-- Executor autoexec kiriada nembak MainUI.php berulang (Hello world + router).
-- Tiap tembakan nunggu ~60s. Skip kalau masih boot / baru selesai.
if G.__AnimeDiceBooting == true then
    warn("[" .. BOOT_NAME .. "] skip: masih loading")
    return G.NodeNeonUI or G.AnimeDiceUI
end
if type(G.__AnimeDiceReadyAt) == "number" and (bootT - G.__AnimeDiceReadyAt) < 45 then
    warn("[" .. BOOT_NAME .. "] skip: sudah load")
    return G.NodeNeonUI or G.AnimeDiceUI
end
G.__AnimeDiceBooting = true
task.delay(90, function()
    if G.__AnimeDiceBooting == true then
        G.__AnimeDiceBooting = false
    end
end)

