local function isFieldGroup(parent)
    return parent and parent.GetAttribute and parent:GetAttribute("FieldGroup") == true
end

local function attachGroupDivider(row, parent)
    if not isFieldGroup(parent) or not row then
        return
    end
    local prior = 0
    for _, ch in ipairs(parent:GetChildren()) do
        if ch ~= row and ch:IsA("GuiObject") and string.sub(ch.Name, 1, 3) == "Row" then
            prior += 1
        end
    end
    if prior < 1 then
        return
    end
    local line = Instance.new("Frame")
    line.Name = "GroupDivider"
    line.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    line.BackgroundTransparency = 0.92
    line.BorderSizePixel = 0
    line.Size = UDim2.new(1, 0, 0, 1)
    line.Position = UDim2.new(0, 0, 0, 0)
    line.ZIndex = 2
    line.Parent = row
end

local function wireCtrlHover(button, stroke)
    if not button or not stroke then
        return
    end
    button.MouseEnter:Connect(function()
        stroke.Color = COLOR_YELLOW
        stroke.Transparency = 0.55
    end)
    button.MouseLeave:Connect(function()
        stroke.Color = COLOR_CTRL_STROKE
        stroke.Transparency = 0.42
    end)
end

local function tweenColor(obj, prop, to, time)
    time = time or 0.12
    TweenService:Create(obj, TweenInfo.new(time, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        [prop] = to
    }):Play()
end



local function makeDraggable(frame, dragHandle)
    dragHandle = dragHandle or frame
    dragHandle.Active = true            -- penting

    local dragging = false
    local dragStart
    local startPos

    dragHandle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging  = true
            dragStart = input.Position
            startPos  = frame.Position
        end
    end)

    dragHandle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging  = false
            dragStart = nil
            startPos  = nil
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end

        if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end

        -- 🔐 Guard biar gak error "attempt to index nil with 'X'"
        if not dragStart or not startPos then
            return
        end

        local delta = input.Position - dragStart
        frame.Position = UDim2.new(
            startPos.X.Scale,
            startPos.X.Offset + delta.X,
            startPos.Y.Scale,
            startPos.Y.Offset + delta.Y
        )
    end)
end

local function saveMiniIconPos(frame)
    if not frame then return end
    local G = (getgenv and getgenv()) or _G
    local ap = frame.AnchorPoint
    local pos = frame.Position
    local saved = {
        ax = ap.X, ay = ap.Y,
        xs = pos.X.Scale, xo = pos.X.Offset,
        ys = pos.Y.Scale, yo = pos.Y.Offset,
    }
    G.__NODEHUB_MINI_ICON_POS = saved
    _G.__NODEHUB_MINI_ICON_POS = saved
end

local function loadMiniIconPos(frame)
    if not frame then return end
    local G = (getgenv and getgenv()) or _G
    local saved = G.__NODEHUB_MINI_ICON_POS or _G.__NODEHUB_MINI_ICON_POS
    if type(saved) ~= "table" then return end
    -- Posisi lama (pojok kiri atas) diganti default tengah layar.
    local oldCorner = (tonumber(saved.ax) or 0) == 0
        and (tonumber(saved.ay) or 0) == 0
        and (tonumber(saved.xs) or 0) == 0
        and (tonumber(saved.xo) or 8) == 8
        and (tonumber(saved.ys) or 0) == 0
        and (tonumber(saved.yo) or 72) == 72
    if oldCorner then
        return
    end
    if saved.ax ~= nil and saved.ay ~= nil then
        frame.AnchorPoint = Vector2.new(tonumber(saved.ax) or 0.5, tonumber(saved.ay) or 0.5)
    end
    frame.Position = UDim2.new(
        tonumber(saved.xs) or 0.5, tonumber(saved.xo) or 0,
        tonumber(saved.ys) or 0.5, tonumber(saved.yo) or 0
    )
end

-- Drag + klik (restore) — geser > threshold = drag, else = click
local function makeDraggableClickable(frame, dragHandle, onClick, dragThreshold)
    dragHandle = dragHandle or frame
    dragHandle.Active = true
    dragThreshold = tonumber(dragThreshold) or 8

    local dragging = false
    local moved = false
    local dragStart
    local startPos

    dragHandle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            moved = false
            dragStart = input.Position
            startPos = frame.Position
        end
    end)

    dragHandle.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
            if dragging and not moved and type(onClick) == "function" then
                onClick()
            end
            if dragging and moved then
                saveMiniIconPos(frame)
            end
            dragging = false
            dragStart = nil
            startPos = nil
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        if not dragging then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        if not dragStart or not startPos then return end

        local delta = input.Position - dragStart
        if not moved and (math.abs(delta.X) > dragThreshold or math.abs(delta.Y) > dragThreshold) then
            moved = true
        end
        if not moved then return end

        frame.Position = UDim2.new(
            startPos.X.Scale,
            startPos.X.Offset + delta.X,
            startPos.Y.Scale,
            startPos.Y.Offset + delta.Y
        )
    end)
end
local MainUI = {}
MainUI.__index = MainUI

local function _isOpts(v)
    return type(v) == "table" and v[1] == nil
end

local function attachVisibility(api, root)
    if type(api) ~= "table" or not root then
        return api
    end
    api.root = root
    if api.row == nil then
        api.row = root
    end
    function api.setVisible(visible)
        local show = visible == true
        root.Visible = show
        if root:GetAttribute("_visH") == nil then
            root:SetAttribute("_visH", root.Size.Y.Offset)
            root:SetAttribute("_visYScale", root.Size.Y.Scale)
        end
        local grouped = isFieldGroup(root.Parent)
        if grouped == true then
            if show then
                local h = tonumber(root:GetAttribute("_visH")) or 0
                local ys = tonumber(root:GetAttribute("_visYScale")) or 0
                if h > 0 or ys > 0 then
                    root.Size = UDim2.new(1, 0, ys, h)
                end
            else
                root.Size = UDim2.new(1, 0, 0, 0)
            end
        end
        return root.Visible
    end
    function api.getVisible()
        return root.Visible ~= false
    end
    return api
end

local function _jsonEncode(value)
    local ok, json = pcall(function()
        return game:GetService("HttpService"):JSONEncode(value)
    end)
    if ok and type(json) == "string" then
        return json
    end
    return nil
end

local function _jsonDecode(src)
    local ok, data = pcall(function()
        return game:GetService("HttpService"):JSONDecode(src)
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end

local function _mirrorSavedConfig(id, value)
    if type(id) ~= "string" or id == "" then
        return
    end
    local G = (getgenv and getgenv()) or _G
    if type(G.__RideAPetSavedConfig) ~= "table" then
        G.__RideAPetSavedConfig = {}
    end
    G.__RideAPetSavedConfig[id] = value
    _G.__RideAPetSavedConfig = G.__RideAPetSavedConfig
end

function MainUI:_bindWidget(id, kind, api, persist, row)
    if type(id) ~= "string" or id == "" or type(api) ~= "table" then
        return api
    end
    persist = persist ~= false
    self._binds = self._binds or {}
    self._config = self._config or {}

    if persist and type(api.set) == "function" and api._cfgWrapped ~= true then
        local origSet = api.set
        local origGet = api.get
        api.set = function(value, silent)
            local result = origSet(value, silent)
            local cur = value
            if type(origGet) == "function" then
                local ok, got = pcall(origGet)
                if ok then
                    cur = got
                end
            end
            if silent then
                self._config[id] = cur
                _mirrorSavedConfig(id, cur)
            else
                self:_touchConfig(id, cur)
            end
            return result
        end
        api._cfgWrapped = true
    end

    self._binds[id] = {
        id = id,
        kind = kind or "widget",
        api = api,
        persist = persist,
    }
    api.id = id

    if persist then
        -- Prefer live config, then boot/file snapshot — jangan timpa save dengan default widget.
        local cfgVal = self._config[id]
        if cfgVal == nil then
            local G = (getgenv and getgenv()) or _G
            local snap = G.__RideAPetSavedConfig
            if type(snap) == "table" and snap[id] ~= nil then
                cfgVal = snap[id]
                self._config[id] = cfgVal
            end
        end
        if cfgVal ~= nil and type(api.set) == "function" then
            pcall(api.set, cfgVal, true)
        elseif type(api.get) == "function" then
            local ok, cur = pcall(api.get)
            if ok and self._config[id] == nil then
                self._config[id] = cur
                _mirrorSavedConfig(id, cur)
            end
        end
    end

    if row then
        row.Destroying:Connect(function()
            local rec = self._binds and self._binds[id]
            if rec and rec.api == api then
                if rec.persist ~= false and type(api.get) == "function" then
                    local ok, cur = pcall(api.get)
                    if ok then
                        -- Snapshot ke memori saja. Jangan autosave di Destroying —
                        -- ganti tab pernah nulis ulang file dengan nilai default/salah.
                        self._config = self._config or {}
                        self._config[id] = cur
                        _mirrorSavedConfig(id, cur)
                    end
                end
                self._binds[id] = nil
            end
        end)
    end
    return api
end

function MainUI:GetValues()
    self._config = self._config or {}
    for id, rec in pairs(self._binds or {}) do
        if rec.persist ~= false and type(rec.api) == "table" and type(rec.api.get) == "function" then
            local ok, value = pcall(rec.api.get)
            if ok then
                self._config[id] = value
            end
        end
    end
    local out = {}
    for id, value in pairs(self._config) do
        out[id] = value
    end
    return out
end

function MainUI:GetConfig()
    return self:GetValues()
end

function MainUI:SetValues(values, silent)
    if type(values) ~= "table" then
        return false
    end
    silent = (silent ~= false)
    self._config = self._config or {}
    for id, value in pairs(values) do
        self._config[id] = value
        _mirrorSavedConfig(id, value)
        local rec = self._binds and self._binds[id]
        if rec and rec.persist ~= false and type(rec.api) == "table" and type(rec.api.set) == "function" then
            pcall(rec.api.set, value, silent)
        end
    end
    return true
end

function MainUI:Save(path)
    path = path or self._savePath or "NodeNeonUI/save.json"
    local values = self:GetValues()
    local json = _jsonEncode(values)
    if not json then
        return false, "json_encode_failed"
    end
    if type(makefolder) == "function" then
        local folder = string.match(path, "^(.*)/[^/]+$")
        if folder and folder ~= "" then
            pcall(makefolder, folder)
        end
    end
    if type(writefile) ~= "function" then
        return false, "writefile_missing"
    end
    local ok, err = pcall(writefile, path, json)
    if not ok then
        return false, tostring(err)
    end
    self._savePath = path
    local G = (getgenv and getgenv()) or _G
    G.__RideAPetSavedConfig = values
    _G.__RideAPetSavedConfig = values
    return true
end

function MainUI:Load(path)
    path = path or self._savePath or "NodeNeonUI/save.json"
    if type(readfile) ~= "function" then
        return false, "readfile_missing"
    end
    if type(isfile) == "function" then
        local okExists, exists = pcall(isfile, path)
        if okExists and exists ~= true then
            return false, "missing"
        end
    end
    local okRead, src = pcall(readfile, path)
    if not okRead or type(src) ~= "string" or src == "" then
        return false, "read_failed"
    end
    local data = _jsonDecode(src)
    if not data then
        return false, "json_decode_failed"
    end
    self._savePath = path
    self._suppressAutosave = true
    self:SetValues(data, true)
    local G = (getgenv and getgenv()) or _G
    G.__RideAPetSavedConfig = data
    _G.__RideAPetSavedConfig = data
    self._suppressAutosave = false
    return true, data
end

function MainUI:_touchConfig(id, value)
    if type(id) ~= "string" or id == "" then
        return
    end
    self._config = self._config or {}
    self._config[id] = value
    _mirrorSavedConfig(id, value)
    self:_scheduleAutosave()
end

function MainUI:_scheduleAutosave()
    if self._autosave ~= true or self._suppressAutosave == true then
        return
    end
    self._autosaveToken = (tonumber(self._autosaveToken) or 0) + 1
    local token = self._autosaveToken
    task.delay(0.45, function()
        if token ~= self._autosaveToken then
            return
        end
        pcall(function()
            self:Save()
        end)
    end)
end

function MainUI:SetAutosave(on)
    self._autosave = on == true
    return self._autosave
end


function MainUI.new(opts)
    opts = opts or {}
