                return
            end
            fpsAcc += dt
            fpsFrames += 1
            local now = os.clock()
            if (now - lastAt) < 0.5 then
                return
            end
            lastAt = now
            local fps = (fpsAcc > 0) and math.floor((fpsFrames / fpsAcc) + 0.5) or 0
            fpsAcc = 0
            fpsFrames = 0
            fpsLbl.Text = tostring(fps) .. " FPS"
        end)
