        local mp   = UIS:GetMouseLocation()
        local pPos = panel.AbsolutePosition
        local pSz  = panel.AbsoluteSize

        local insideX = mp.X >= pPos.X and mp.X <= pPos.X + pSz.X
        local insideY = mp.Y >= pPos.Y and mp.Y <= pPos.Y + pSz.Y
        if not (insideX and insideY) then
            closeOverlay()
        end
    end)

    --------------------------------------------------
    -- HITUNG LEBAR PANEL DARI TEKS TERPANJANG
    --------------------------------------------------
    --------------------------------------------------
-- HITUNG LEBAR PANEL DARI TEKS TERPANJANG
--------------------------------------------------
local function resizePanelWidthFromItems()
    if not TextService or not TextService.GetTextSize then
        panel.Size = UDim2.new(0, 300, 0, 260)
        return
    end

    local maxWidth  = 0
    local font      = Enum.Font.Gotham
    local textSize  = 11

    for _, opt in ipairs(items or {}) do
        local id   = tostring(opt.id)
        local text = opt.label or id
        local full = string.format("  [%s]  %s", id, text)

        local bounds = TextService:GetTextSize(
            full,
            textSize,
            font,
            Vector2.new(10000, 24)
        )

        if bounds.X > maxWidth then
            maxWidth = bounds.X
        end
    end

    -- hitung padding kiri/kanan dari UIPadding panel
    local padLeft  = pad and pad.PaddingLeft and pad.PaddingLeft.Offset or 0
    local padRight = pad and pad.PaddingRight and pad.PaddingRight.Offset or 0

    -- sedikit margin ekstra di kiri/kanan button
    local extraMargin = 15

    local desiredWidth = maxWidth + padLeft + padRight + extraMargin

    -- MIN & MAX LEBAR PANEL
    desiredWidth = math.clamp(desiredWidth, 340, 680)

    -- tinggi tetap 260
    panel.Size = UDim2.new(0, desiredWidth, 0, 290)
end


    resizePanelWidthFromItems()

    --------------------------------------------------
    -- REBUILD LIST
    --------------------------------------------------
    local function rebuildList()
        for _, c in ipairs(list:GetChildren()) do
            if c:IsA("TextButton") then
                c:Destroy()
            end
        end

        local q   = string.lower(search.Text or "")
        local idx = 0
        local cur = tostring(currentId or "")

        for _, opt in ipairs(items or {}) do
            local id   = tostring(opt.id)
            local text = opt.label or id
            local low  = string.lower(text)

            if q == "" or string.find(low, q, 1, true) then
                idx += 1

                local btn = Instance.new("TextButton")
                btn.Name = "Item_" .. id
                btn.AutoButtonColor = false
                btn.BackgroundColor3 = (id == cur)
                    and COLOR_YELLOW
                    or Color3.fromRGB(22,22,22)

                btn.Size = UDim2.new(1, 0, 0, 24)
                btn.Text = string.format("  %s", text)
                btn.Font = Enum.Font.Gotham
                btn.TextXAlignment = Enum.TextXAlignment.Left
                btn.TextSize = 12
                btn.TextColor3 = (id == cur)
                    and COLOR_PANEL
                    or Color3.fromRGB(220,220,220)
                btn.LayoutOrder = idx
                btn.ZIndex = 101

                -- jangan di-"..." (biar full, panel sudah dilebarkan)
                btn.TextTruncate = Enum.TextTruncate.None

                btn.Parent = list
                createCorner(btn, 4)

                btn.MouseButton1Click:Connect(function()
                    currentId = id
                    if onChosen then
                        onChosen(id)
                    end
                    closeOverlay()
                end)
            end
        end
    end

    search:GetPropertyChangedSignal("Text"):Connect(rebuildList)
    search.Text = ""
    rebuildList()
end


----------------------------------------------------------
-- RULE LIST  (search + colored summary + chip + on/off + delete)
-- CreateRuleList(parent, {
--   id, title, searchPlaceholder, emptyText, visibleRows,
--   getItems = function() return { { id, enabled, parts, chips } } end,
--   formatItem = function(rule, index) return view end, -- optional
--   onToggle, onDelete, onPartClick, persist
-- })
-- parts: { { text=, color= or style="kg", kind= } }
-- chips: { { text=, style=, onClick= } }
----------------------------------------------------------
function MainUI:CreateRuleList(parent, opts)
    opts = _isOpts(opts) and opts or {}
    local ROW_H = 26
    local ROW_PAD = 4
    local VISIBLE = math.max(1, tonumber(opts.visibleRows) or 6)
    local items = type(opts.items) == "table" and opts.items or {}

    local function currentItems()
        if type(opts.getItems) == "function" then
            local ok, res = pcall(opts.getItems)
            if ok and type(res) == "table" then
                return res
            end
        end
        return items
    end

    local function partColor(part)
        if type(part) ~= "table" then
            return RULE_PART_COLORS.default
        end
        if typeof(part.color) == "Color3" then
            return part.color
        end
        local key = tostring(part.style or part.kind or "")
        return RULE_PART_COLORS[key]
            or (ROW_LABEL_THEMES[key] and ROW_LABEL_THEMES[key].color)
            or RULE_PART_COLORS.default
    end

    local function viewOf(rule, index)
        if type(opts.formatItem) == "function" then
            local ok, view = pcall(opts.formatItem, rule, index)
            if ok and type(view) == "table" then
                return view
            end
            if ok and type(view) == "string" and view ~= "" then
                return {
                    id = type(rule) == "table" and tostring(rule.id or index) or tostring(index),
                    enabled = not (type(rule) == "table" and rule.enabled == false),
                    parts = { { text = view } },
                }
            end
        end
        if type(rule) ~= "table" then
            return { id = tostring(index), parts = { { text = tostring(rule or "") } }, enabled = true }
        end
        return {
            id = tostring(rule.id or index),
            enabled = rule.enabled ~= false,
            parts = type(rule.parts) == "table" and rule.parts or { { text = tostring(rule.text or rule.id or index) } },
            chips = type(rule.chips) == "table" and rule.chips or nil,
        }
    end

    local root = Instance.new("Frame")
    root.Name = "RowRuleList"
    root.BackgroundTransparency = 1
    root.Size = UDim2.new(1, 0, 0, 0)
    root.AutomaticSize = Enum.AutomaticSize.Y
    root.LayoutOrder = opts.order or (#parent:GetChildren() + 1)
    root.Parent = parent

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 6)
    layout.Parent = root

    local titleLbl = Instance.new("TextLabel")
    titleLbl.Name = "Title"
    titleLbl.BackgroundTransparency = 1
    titleLbl.Size = UDim2.new(1, 0, 0, 16)
    titleLbl.LayoutOrder = 1
    titleLbl.Font = Enum.Font.Gotham
    titleLbl.TextSize = 12
    titleLbl.TextXAlignment = Enum.TextXAlignment.Left
    titleLbl.Text = tostring(opts.title or "Saved Rules")
    titleLbl.Parent = root
    applyRowLabelStyle(titleLbl, "list")

    local searchWrap = Instance.new("Frame")
    searchWrap.Name = "SearchWrap"
    searchWrap.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
    searchWrap.BorderSizePixel = 0
    searchWrap.Size = UDim2.new(1, 0, 0, 24)
    searchWrap.LayoutOrder = 2
    searchWrap.Parent = root
    createCorner(searchWrap, 6)
    createStroke(searchWrap, Color3.fromRGB(50, 50, 50), 1, 0.45)

    local searchBox = Instance.new("TextBox")
    searchBox.Name = "Search"
    searchBox.BackgroundTransparency = 1
    searchBox.Size = UDim2.new(1, -12, 1, 0)
    searchBox.Position = UDim2.new(0, 6, 0, 0)
    searchBox.Font = Enum.Font.Gotham
    searchBox.TextSize = 12
    searchBox.TextColor3 = Color3.fromRGB(230, 230, 230)
    searchBox.PlaceholderText = tostring(opts.searchPlaceholder or "Search rules...")
    searchBox.PlaceholderColor3 = Color3.fromRGB(110, 110, 110)
    searchBox.TextXAlignment = Enum.TextXAlignment.Left
    searchBox.ClearTextOnFocus = false
    searchBox.Text = ""
    searchBox.Parent = searchWrap

    local function listHeight(count)
        local rows = math.clamp(count, 1, VISIBLE)
        return (rows * ROW_H) + ((rows - 1) * ROW_PAD) + 10
    end

    local listScroll = Instance.new("ScrollingFrame")
    listScroll.Name = "Rules"
    listScroll.BackgroundColor3 = Color3.fromRGB(14, 14, 14)
    listScroll.BorderSizePixel = 0
    listScroll.LayoutOrder = 3
    listScroll.Size = UDim2.new(1, 0, 0, listHeight(0))
    listScroll.ScrollBarThickness = 4
    listScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    listScroll.CanvasSize = UDim2.new(0, 0, 0, 0)
    listScroll.ClipsDescendants = true
    listScroll.Parent = root
    createCorner(listScroll, 6)
    createStroke(listScroll, Color3.fromRGB(40, 40, 40), 1, 0.5)

    local listPad = Instance.new("UIPadding")
    listPad.PaddingTop = UDim.new(0, 5)
    listPad.PaddingBottom = UDim.new(0, 5)
    listPad.PaddingLeft = UDim.new(0, 5)
    listPad.PaddingRight = UDim.new(0, 5)
    listPad.Parent = listScroll

    local listLayout = Instance.new("UIListLayout")
    listLayout.FillDirection = Enum.FillDirection.Vertical
    listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    listLayout.Padding = UDim.new(0, ROW_PAD)
    listLayout.Parent = listScroll

    local function clearRows()
        for _, ch in ipairs(listScroll:GetChildren()) do
            if ch:IsA("Frame") or (ch:IsA("TextLabel") and ch.Name == "EmptyHint") then
                ch:Destroy()
            end
        end
    end

    local function mountParts(parentFrame, parts, rule)
        local wrap = Instance.new("Frame")
        wrap.Name = "Parts"
        wrap.BackgroundTransparency = 1
        wrap.Size = UDim2.new(1, 0, 1, 0)
        wrap.ClipsDescendants = true
        wrap.Parent = parentFrame

        local hl = Instance.new("UIListLayout")
        hl.FillDirection = Enum.FillDirection.Horizontal
        hl.VerticalAlignment = Enum.VerticalAlignment.Center
        hl.SortOrder = Enum.SortOrder.LayoutOrder
        hl.Parent = wrap

        for i, part in ipairs(parts or {}) do
            local txt = tostring((type(part) == "table" and part.text) or part or "")
            if txt ~= "" then
            local clickable = type(part) == "table" and part.kind ~= nil and type(opts.onPartClick) == "function"
            local inst
            if clickable then
                inst = Instance.new("TextButton")
                inst.AutoButtonColor = false
                inst.BackgroundTransparency = 1
                inst.MouseButton1Click:Connect(function()
                    pcall(opts.onPartClick, rule, part)
                end)
            else
                inst = Instance.new("TextLabel")
                inst.BackgroundTransparency = 1
            end
            inst.Name = "Part" .. i
            inst.LayoutOrder = i
            inst.AutomaticSize = Enum.AutomaticSize.X
            inst.Size = UDim2.new(0, 0, 1, 0)
            inst.Font = Enum.Font.Gotham
            inst.TextSize = 11
            inst.TextXAlignment = Enum.TextXAlignment.Left
            inst.Text = txt
            inst.TextColor3 = partColor(part)
            inst.Parent = wrap
            end
        end
    end

    local function buildRow(index, rule)
        local view = viewOf(rule, index)
        local enabled = view.enabled ~= false
        local item = Instance.new("Frame")
        item.Name = "Item_" .. tostring(view.id or index)
        item.BackgroundColor3 = enabled and Color3.fromRGB(22, 22, 22) or Color3.fromRGB(16, 16, 16)
        item.Size = UDim2.new(1, 0, 0, ROW_H)
        item.LayoutOrder = index
        item.Parent = listScroll
        createCorner(item, 5)

        local showToggle = opts.showToggle ~= false
        local chips = view.chips or {}
        local chipW = (#chips > 0) and 34 or 0
        local onW = showToggle and 34 or 0
        local delW = 22
        local gap = 4
        local rightW = delW + (onW > 0 and (gap + onW) or 0) + (chipW > 0 and (gap + chipW) or 0)

        local idxLbl = Instance.new("TextLabel")
        idxLbl.BackgroundTransparency = 1
        idxLbl.Size = UDim2.new(0, 20, 1, 0)
        idxLbl.Position = UDim2.new(0, 6, 0, 0)
        idxLbl.Font = Enum.Font.GothamBold
        idxLbl.TextSize = 11
        idxLbl.TextXAlignment = Enum.TextXAlignment.Left
        idxLbl.Text = tostring(index) .. "."
        idxLbl.TextColor3 = enabled and COLOR_YELLOW or Color3.fromRGB(90, 90, 90)
        idxLbl.Parent = item

        local summary = Instance.new("Frame")
        summary.BackgroundTransparency = 1
        summary.Position = UDim2.new(0, 26, 0, 0)
        summary.Size = UDim2.new(1, -rightW - 32, 1, 0)
        summary.Parent = item
        mountParts(summary, view.parts, rule)

        local x = 4
        local del = Instance.new("TextButton")
        del.Name = "Delete"
        del.AutoButtonColor = true
        del.BackgroundColor3 = Color3.fromRGB(150, 40, 40)
        del.Size = UDim2.new(0, delW, 0, 18)
        del.AnchorPoint = Vector2.new(1, 0.5)
        del.Position = UDim2.new(1, -x, 0.5, 0)
        del.Font = Enum.Font.GothamBold
        del.TextSize = 14
        del.TextColor3 = Color3.fromRGB(255, 255, 255)
        del.Text = "-"
        del.Parent = item
        createCorner(del, 4)
        x = x + delW + gap

        del.MouseButton1Click:Connect(function()
            if type(opts.onDelete) == "function" then
                pcall(opts.onDelete, rule, view.id)
            end
        end)

        if showToggle then
            local onBtn = Instance.new("TextButton")
            onBtn.Name = "OnOff"
            onBtn.AutoButtonColor = true
            onBtn.BackgroundColor3 = enabled and COLOR_YELLOW or Color3.fromRGB(48, 48, 48)
            onBtn.Size = UDim2.new(0, onW, 0, 18)
            onBtn.AnchorPoint = Vector2.new(1, 0.5)
            onBtn.Position = UDim2.new(1, -x, 0.5, 0)
            onBtn.Font = Enum.Font.GothamBold
            onBtn.TextSize = 9
            onBtn.TextColor3 = enabled and COLOR_PANEL or Color3.fromRGB(150, 150, 150)
            onBtn.Text = enabled and "ON" or "OFF"
            onBtn.Parent = item
            createCorner(onBtn, 5)
            x = x + onW + gap
            onBtn.MouseButton1Click:Connect(function()
                if type(opts.onToggle) == "function" then
                    pcall(opts.onToggle, rule, not enabled)
                end
            end)
        end

        if #chips > 0 then
            local chip = chips[1]
            local chipBtn = Instance.new("TextButton")
            chipBtn.Name = "Chip"
            chipBtn.AutoButtonColor = true
            chipBtn.BackgroundColor3 = Color3.fromRGB(48, 34, 72)
            chipBtn.Size = UDim2.new(0, chipW, 0, 18)
            chipBtn.AnchorPoint = Vector2.new(1, 0.5)
            chipBtn.Position = UDim2.new(1, -x, 0.5, 0)
            chipBtn.Font = Enum.Font.GothamBold
            chipBtn.TextSize = 10
            chipBtn.TextColor3 = Color3.fromRGB(220, 175, 255)
            chipBtn.Text = tostring(chip.text or "")
            chipBtn.Parent = item
            createCorner(chipBtn, 5)
            chipBtn.MouseButton1Click:Connect(function()
                if type(chip.onClick) == "function" then
                    pcall(chip.onClick, rule)
                elseif type(opts.onChipClick) == "function" then
                    pcall(opts.onChipClick, rule, chip)
                end
            end)
        end
    end

    local function refresh()
        clearRows()
        local q = string.lower(tostring(searchBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", ""))
        local all = currentItems()
        local shown = {}
        for i, rule in ipairs(all) do
            local view = viewOf(rule, i)
            local blob = string.lower(tostring(view.id or ""))
            for _, part in ipairs(view.parts or {}) do
                blob = blob .. " " .. string.lower(tostring(part.text or ""))
            end
            if q == "" or string.find(blob, q, 1, true) then
                shown[#shown + 1] = { index = i, rule = rule }
            end
        end

        listScroll.Size = UDim2.new(1, 0, 0, listHeight(#shown))

        if #shown == 0 then
            local empty = Instance.new("TextLabel")
            empty.Name = "EmptyHint"
            empty.BackgroundTransparency = 1
            empty.Size = UDim2.new(1, 0, 0, ROW_H)
            empty.Font = Enum.Font.Gotham
            empty.TextSize = 11
            empty.TextColor3 = Color3.fromRGB(130, 130, 136)
            empty.Text = (#all == 0)
                and tostring(opts.emptyText or "No rules yet.")
                or "No rules match this search."
            empty.Parent = listScroll
            return
        end

        for _, entry in ipairs(shown) do
            buildRow(entry.index, entry.rule)
        end
    end

    local debounce = 0
    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        debounce += 1
        local token = debounce
        task.delay(0.12, function()
            if token == debounce then
                refresh()
            end
        end)
    end)

    local api = {}
    function api.get()
        return currentItems()
    end
    function api.set(list, _silent)
        if type(list) == "table" then
            items = list
            if type(opts.onLoad) == "function" then
                pcall(opts.onLoad, list)
            end
        end
        refresh()
        return currentItems()
    end
    function api.refresh()
        refresh()
    end

    refresh()
    self:_bindWidget(opts.id, "rules", api, opts.persist, root)
    api.row = root
    attachVisibility(api, root)
    return root, api
end

----------------------------------------------------------
-- RULE FORM  (mode multi dropdown + hide/unhide field rows)
-- CreateRuleForm(parent, {
--   id, label, placeholder, hintText, persist,
--   modes = { { key="zone", name="Zone" }, ... },
--   initial = { zone = true },
--   onChanged = function(selectedMap) end,
-- })
-- api.attach(key, fieldApi, onHide)
-- api.has(key) / api.getModes() / api.apply()
----------------------------------------------------------
function MainUI:CreateRuleForm(parent, opts)
    opts = _isOpts(opts) and opts or {}
    local modes = type(opts.modes) == "table" and opts.modes or {}
    local selected = {}
    if type(opts.initial) == "table" then
        for k, v in pairs(opts.initial) do
            if v == true or v == 1 or v == "true" then
                selected[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil then
                selected[tostring(v)] = true
            end
        end
    end
    local fields = {}

    local api = {}

    local function copySelected()
        local out = {}
        for key, on in pairs(selected) do
            if on == true then
                out[key] = true
            end
        end
        return out
    end

    function api.apply()
        for key, rec in pairs(fields) do
            local show = selected[tostring(key)] == true
            local fieldApi = rec and rec.api
            if type(fieldApi) == "table" and type(fieldApi.setVisible) == "function" then
                pcall(fieldApi.setVisible, show)
            elseif type(fieldApi) == "table" then
                local root = fieldApi.root or fieldApi.row
                if root then
                    root.Visible = show
                end
            end
            if show ~= true and rec.visible == true and type(rec.onHide) == "function" then
                pcall(rec.onHide)
            end
            rec.visible = show == true
        end
    end

    function api.has(key)
        return selected[tostring(key or "")] == true
    end

    function api.getModes()
        return copySelected()
    end

    function api.attach(key, fieldApi, onHide)
        key = tostring(key or "")
        if key == "" or type(fieldApi) ~= "table" then
            return api
        end
        local show = selected[key] == true
        fields[key] = { api = fieldApi, onHide = onHide, visible = show }
        if type(fieldApi.setVisible) == "function" then
            pcall(fieldApi.setVisible, show)
        elseif fieldApi.root or fieldApi.row then
            local root = fieldApi.root or fieldApi.row
            root.Visible = show
        end
        return api
    end

    local _, modeApi = self:CreateRowDropdown(parent, {
        id = opts.id,
        label = opts.label or "Rule Fields",
        placeholder = opts.placeholder or "Pick fields...",
        hintText = opts.hintText or "Pick fields to show inputs.",
        mode = "multi",
        clearable = true,
        persist = opts.persist,
        preserveItemOrder = true,
        initial = selected,
        getItems = function()
            return modes
        end,
        onChanged = function(a, b)
            local map = {}
            if a == "multi" and type(b) == "table" then
                map = b
            elseif type(a) == "table" then
                map = a
            elseif type(b) == "table" then
                map = b
            end
            selected = {}
            for k, v in pairs(map) do
                if v == true or v == 1 or v == "true" then
                    selected[tostring(k)] = true
                elseif type(k) == "number" and v ~= nil then
                    selected[tostring(v)] = true
                end
            end
            api.apply()
            if type(opts.onChanged) == "function" then
                pcall(opts.onChanged, copySelected())
            end
        end,
    })

    if type(modeApi) == "table" and type(modeApi.getSelected) == "function" then
        local ok, cur = pcall(modeApi.getSelected)
        if ok and type(cur) == "table" then
            selected = {}
            for k, v in pairs(cur) do
                if v == true then
                    selected[tostring(k)] = true
                end
            end
        end
    end

    api.modeApi = modeApi
    api.get = function()
        return copySelected()
    end
    api.set = function(value, silent)
        selected = {}
        if type(value) == "table" then
            for k, v in pairs(value) do
                if v == true or v == 1 or v == "true" then
                    selected[tostring(k)] = true
                elseif type(k) == "number" and v ~= nil then
                    selected[tostring(v)] = true
                end
            end
        end
        if type(modeApi) == "table" and type(modeApi.setSelected) == "function" then
            pcall(modeApi.setSelected, copySelected(), silent == true)
        end
        api.apply()
        return copySelected()
    end

    local root = (type(modeApi) == "table" and (modeApi.root or modeApi.row)) or parent
    attachVisibility(api, root)
    api.row = root
    return root, api
end

function MainUI:_noteGuiActivity()
    self._lastGuiActivity = os.clock()
end

function MainUI:_guiHitAt(x, y)
    local sg = self._sg
    if not sg or not sg.Parent then
        return false
    end
    local ok, objs = pcall(function()
        return PlayerGui:GetGuiObjectsAtPosition(x, y)
    end)
    if not ok or type(objs) ~= "table" then
        return false
    end
    local mini = self._miniBtn
    for i = 1, #objs do
        local o = objs[i]
        if o and o:IsDescendantOf(sg) then
            if mini and (o == mini or o:IsDescendantOf(mini)) then
                -- icon minimize: restore sudah handle sendiri
            elseif o:IsA("GuiObject") and o.Visible ~= false then
                -- skip overlay full-screen (Active=false, bukan panel)
                if o.Name ~= "NodeHubOverlay" then
                    return true
                end
            end
        end
    end
    return false
end

function MainUI:_startIdleAutoMinimize()
    if self._idleMinimizeStarted == true then
        return
    end
    self._idleMinimizeStarted = true

    if self._idleInputConn then
        pcall(function()
            self._idleInputConn:Disconnect()
        end)
        self._idleInputConn = nil
    end

    self._idleInputConn = UserInputService.InputBegan:Connect(function(input)
        if self.isMinimized == true or self._autoMinimizeEnabled == false then
            return
        end
        local uit = input.UserInputType
        if uit == Enum.UserInputType.MouseButton1
            or uit == Enum.UserInputType.MouseButton2
            or uit == Enum.UserInputType.Touch then
            local p = input.Position
            if self:_guiHitAt(p.X, p.Y) then
                self:_noteGuiActivity()
            end
            return
        end
        if uit == Enum.UserInputType.Keyboard then
            local focused = UserInputService:GetFocusedTextBox()
            if focused and self.mainFrame and focused:IsDescendantOf(self.mainFrame) then
                self:_noteGuiActivity()
            end
        end
    end)

    task.spawn(function()
        while self._sg and self._sg.Parent do
            task.wait(1)
            if self._autoMinimizeEnabled ~= false
                and self.isMinimized ~= true then
                local idleSec = tonumber(self._autoMinimizeIdleSec) or 30
                if idleSec < 5 then
                    idleSec = 5
                end
                local last = tonumber(self._lastGuiActivity) or 0
                if (os.clock() - last) >= idleSec then
                    self:_setMinimized(true)
                end
            end
        end
        self._idleMinimizeStarted = false
        if self._idleInputConn then
            pcall(function()
                self._idleInputConn:Disconnect()
            end)
            self._idleInputConn = nil
        end
    end)
end

function MainUI:_setMinimized(state)
    state = state and true or false
    self.isMinimized = state

    if state then
        -- MINIMIZE: tutup panel utama, buka icon
        if self.overlay then
            self.overlay.Visible = false
        end
        if self.mainFrame then
            self.mainFrame.Visible = false
        end
        if self._miniBtn then
            self._miniBtn.Visible = true
        end
    else
        -- RESTORE: buka panel utama, tutup icon
        self:_noteGuiActivity()
        if self.overlay then
            self.overlay.Visible = true
            self.overlay.BackgroundTransparency = tonumber(self._overlayTransparency) or DEFAULT_OVERLAY_BG_TRANSPARENCY
        end
        if self.mainFrame then
            self.mainFrame.Visible = true
            self.mainFrame.BackgroundTransparency = tonumber(self._panelTransparency) or DEFAULT_PANEL_BG_TRANSPARENCY
        end
        if self._miniBtn then
            self._miniBtn.Visible = false
        end
        -- refresh scale supaya teks tidak buram setelah restore
        if type(self._updateScale) == "function" then
            pcall(self._updateScale)
            task.defer(function()
                if type(self._updateScale) == "function" then
                    pcall(self._updateScale)
                end
            end)
        end
    end
end

function MainUI:Minimize()
    self:_setMinimized(true)
end

function MainUI:Restore()
    self:_setMinimized(false)
end

function MainUI:SetAutoMinimize(enabled, idleSec)
    self._autoMinimizeEnabled = enabled ~= false
    if idleSec ~= nil then
        local n = tonumber(idleSec)
        if n and n >= 5 then
            self._autoMinimizeIdleSec = n
        end
    end
    if self._autoMinimizeEnabled then
        self:_noteGuiActivity()
        self:_startIdleAutoMinimize()
    end
end

function MainUI:GetTransparency()
    return {
        panel = tonumber(self._panelTransparency) or DEFAULT_PANEL_BG_TRANSPARENCY,
        overlay = tonumber(self._overlayTransparency) or DEFAULT_OVERLAY_BG_TRANSPARENCY,
        section = tonumber(self._sectionTransparency) or DEFAULT_SECTION_BG_TRANSPARENCY,
    }
end

function MainUI:ApplyTransparency(opts)
    opts = type(opts) == "table" and opts or {}
    if opts.panel ~= nil then
        local panel = _clamp01(opts.panel, DEFAULT_PANEL_BG_TRANSPARENCY)
        self._panelTransparency = panel
        -- section selalu ikut panel
        self._sectionTransparency = panel
    elseif opts.section ~= nil then
        local panel = _clamp01(opts.section, DEFAULT_PANEL_BG_TRANSPARENCY)
        self._panelTransparency = panel
        self._sectionTransparency = panel
    end
    -- backdrop fixed full clear
    self._overlayTransparency = DEFAULT_OVERLAY_BG_TRANSPARENCY

    if self.mainFrame then
        self.mainFrame.BackgroundTransparency = self._panelTransparency
    end
    if self.overlay then
        self.overlay.BackgroundTransparency = self._overlayTransparency
    end

    -- update section header yang sudah terbuat
    local content = self.content
    if content then
        for _, ch in ipairs(content:GetDescendants()) do
            if ch:IsA("TextButton") and ch.Name == "Header" then
                ch.BackgroundTransparency = self._sectionTransparency
            end
        end
    end

    return self:GetTransparency()
end

function MainUI:SetTransparency(panelOrOpts, _overlay, _section)
    if type(panelOrOpts) == "table" then
        return self:ApplyTransparency(panelOrOpts)
    end
    return self:ApplyTransparency({
        panel = panelOrOpts,
    })
end

MainUI.RowLabelThemes = ROW_LABEL_THEMES

return MainUI end, required = true },
    { key = "Core", name = "Core", factory = function() -- Anime Dice core
-- Dipakai semua fitur: data, slot, remote, loop, dan pemasangan tab.
-- Fitur tidak menyalin bagian ini.

local Core = {}

local G
local LP
local sections = {}
local syncFns = {}
local remoteCache = {}
local dataMod
local plotCfg
local plotId
local uiMain
local uiSub

local function env()
    return G or (getgenv and getgenv()) or _G
end

function Core.env()
    return env()
end

function Core.potions()
    if type(Core.potionCatalog) == "table" then
        return Core.potionCatalog
    end
    local host = env()
    if type(host.AnimeDicePotionCatalog) == "table" then
        return host.AnimeDicePotionCatalog
    end
    if type(host.AnimeDice) == "table" and type(host.AnimeDice.PotionCatalog) == "table" then
        return host.AnimeDice.PotionCatalog
    end
    return nil
end

function Core.gears()
    if type(Core.gearCatalog) == "table" then
        return Core.gearCatalog
    end
    local host = env()
    if type(host.AnimeDiceGearCatalog) == "table" then
        return host.AnimeDiceGearCatalog
    end
    if type(host.AnimeDice) == "table" and type(host.AnimeDice.GearCatalog) == "table" then
        return host.AnimeDice.GearCatalog
    end
    return nil
end

function Core.player()
    return LP
end

function Core.init(opts)
    opts = type(opts) == "table" and opts or {}
    G = opts.G or env()
    LP = opts.player

    local prev = G.AnimeDice
    if type(prev) == "table" and type(prev.loops) == "table" then
        for _, loop in pairs(prev.loops) do
            if type(loop) == "table" and type(loop.stop) == "function" then
                pcall(loop.stop)
            end
        end
    end

    local maid = G.AnimeDicePerfMaid
    if type(maid) == "table" then
        for _, conn in ipairs(maid) do
            pcall(function()
                conn:Disconnect()
            end)
        end
    end
    G.AnimeDicePerfMaid = nil

    local job = tostring(game.JobId)
    if G.AnimeDiceHookJobId ~= job then
        G.AnimeDiceParticleHook = nil
        G.AnimeDiceFastRollHook = nil
        G.AnimeDiceVisualRollHook = nil
        G.AnimeDiceShowerHook = nil
        G.AnimeDiceDropHook = nil
        G.AnimeDiceVpHook = nil
        G.AnimeDiceHookJobId = job
    end
    G.AnimeDiceVpHook = nil

    G.AnimeDice = {
        loops = {},
        Core = Core,
    }
    sections = {}
    syncFns = {}
    remoteCache = {}
    dataMod = nil
    plotCfg = nil
    plotId = nil
    uiMain = nil
    uiSub = nil
    return Core
end

function Core.data()
    if dataMod ~= nil then
        return dataMod
    end
    local RS = game:GetService("ReplicatedStorage")
    dataMod = require(RS.Framework.Features.Data.DataController)
    return dataMod
end

function Core.pendingTrade()
    local data = Core.data()
    if not data then
        return false
    end
    local row
    pcall(function()
        row = data.PendingTrade()
    end)
    return type(row) == "table" and row.applied ~= true
end

function Core.tradeBusy()
    local host = env()
    local T = host.AnimeDiceAutoTrade
    if type(T) == "table" then
        if T.busy == true then
            return true
        end
        if type(T.busy) == "function" then
            local ok, on = pcall(T.busy)
            if ok and on == true then
                return true
            end
        end
    end
    return Core.pendingTrade()
end

function Core.plotConfig()
    if plotCfg ~= nil then
        return plotCfg
    end
    local RS = game:GetService("ReplicatedStorage")
    plotCfg = require(RS.Framework.Features.Plot.PlotConfig)
    return plotCfg
end

function Core.remote(service, name)
    local key = tostring(service) .. "/" .. tostring(name)
    local cached = remoteCache[key]
    if cached and cached.Parent then
        return cached
    end
    local folder = game:GetService("ReplicatedStorage"):FindFirstChild("Network")
    folder = folder and folder:FindFirstChild(service)
    folder = folder and folder:FindFirstChild("RE")
    local re = folder and folder:FindFirstChild(name)
    remoteCache[key] = re
    return re
end

function Core.plotId()
    if type(plotId) == "string" and plotId ~= "" then
        return plotId
    end
    pcall(function()
        local RS = game:GetService("ReplicatedStorage")
        local id = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "PlotService"):GetProperty("PlotId"):Get()
        if type(id) == "string" and id ~= "" then
            plotId = id
        end
    end)
    if type(plotId) ~= "string" or plotId == "" then
        pcall(function()
            local pc = require(game:GetService("ReplicatedStorage").Framework.Features.Plot.PlotController)
            local plot = pc and pc.plot
            if typeof(plot) == "Instance" and plot.Name ~= "" then
                plotId = plot.Name
            end
        end)
    end
    return plotId
end

function Core.ownPlot()
    local id = Core.plotId()
    if type(id) ~= "string" then
        return nil
    end
    local claimed = workspace:FindFirstChild("Plots")
    claimed = claimed and claimed:FindFirstChild("Claimed")
    return claimed and claimed:FindFirstChild(id)
end

function Core.slots()
    local list = {}
    local seen = {}

    local function add(n)
        n = tonumber(n)
        if not n or n ~= math.floor(n) or n < 1 or n > 32 or seen[n] then
            return
        end
        seen[n] = true
        list[#list + 1] = n
    end

    local ok = pcall(function()
        local Data = Core.data()
        local PlotConfig = Core.plotConfig()
        local rebirth = tonumber(Data.Rebirth()) or 0
        local maxSlots = tonumber(PlotConfig.GetMaxSlots()) or 16
        for i = 1, maxSlots do
            local req = tonumber(PlotConfig.GetSlotRebirthRequirement(i)) or 0
            local hasData = false
            local getter = Data.Slots[tostring(i)]
            if getter ~= nil then
                local okSlot, slot = pcall(getter)
                hasData = okSlot and type(slot) == "table"
            end
            if rebirth >= req or hasData then
                add(i)
            end
        end

        local plot = Core.ownPlot()
        local slotFolder = plot and plot:FindFirstChild("Slots")
        if slotFolder then
            for _, child in ipairs(slotFolder:GetChildren()) do
                if child:IsA("Model") then
                    add(child.Name)
                end
            end
        end
    end)

    if not ok or #list == 0 then
        for i = 1, 16 do
            add(i)
        end
    end

    table.sort(list)
    return list
end

function Core.loop(name, opts)
    opts = type(opts) == "table" and opts or {}
    local host = env()
    host.AnimeDice = host.AnimeDice or {}
    host.AnimeDice.loops = host.AnimeDice.loops or {}

    local prev = host.AnimeDice.loops[name]
    if type(prev) == "table" and type(prev.stop) == "function" then
        pcall(prev.stop)
    end

    local delaySec = tonumber(opts.delay) or 1
    if delaySec < 0.05 then
        delaySec = 0.05
    end

    local state = {
        on = false,
        gen = 0,
    }

    function state.setEnabled(on)
        on = on == true
        state.on = on
        state.gen = state.gen + 1
        if not on then
            return
        end
        local gen = state.gen
        task.spawn(function()
            while gen == state.gen and state.on do
                if type(opts.step) == "function" then
                    pcall(opts.step)
                end
                task.wait(delaySec)
            end
        end)
    end

    function state.enabled()
        return state.on == true
    end

    function state.setDelay(n)
        local v = tonumber(n)
        if not v then
            return delaySec
        end
        if v < 0.05 then
            v = 0.05
        end
        delaySec = v
        return delaySec
    end

    function state.delay()
        return delaySec
    end

    function state.stop()
        state.setEnabled(false)
    end

    host.AnimeDice.loops[name] = state
    return state
end

function Core.section(def)
    if type(def) ~= "table" or type(def.build) ~= "function" then
        return
    end
    sections[#sections + 1] = def
end

function Core.onSync(fn)
    if type(fn) == "function" then
        syncFns[#syncFns + 1] = fn
    end
end

function Core.firstMainKey()
    local best
    local bestOrder
    for _, def in ipairs(sections) do
        local order = def.mainOrder or 1
        if not best or order < bestOrder then
            best = def.main
            bestOrder = order
        end
    end
    return best
end

function Core.uiIs(main, sub)
    local curMain = uiMain or Core.firstMainKey()
    if main and curMain ~= main then
        return false
    end
    if sub then
        if uiSub then
            return uiSub == sub
        end
        return true
    end
    return true
end

function Core.mount(ui)
    local mains = {}
    for _, def in ipairs(sections) do
        local mainKey = def.main or "auto"
        local main = mains[mainKey]
        if not main then
            main = {
                key = mainKey,
                label = def.mainLabel or mainKey,
                order = def.mainOrder or 1,
                subs = {},
            }
            mains[mainKey] = main
        end
        local subKey = def.sub or "main"
        local sub = main.subs[subKey]
        if not sub then
            sub = {
                key = subKey,
                label = def.subLabel or subKey,
                order = def.subOrder or 1,
                icon = def.subIcon,
                builds = {},
            }
            main.subs[subKey] = sub
        end
        if type(def.subIcon) == "string" and def.subIcon ~= "" then
            sub.icon = def.subIcon
        end
        sub.builds[#sub.builds + 1] = def
    end

    local mainList = {}
    for _, main in pairs(mains) do
        mainList[#mainList + 1] = main
    end
    table.sort(mainList, function(a, b)
        return (a.order or 1) < (b.order or 1)
    end)

    for _, main in ipairs(mainList) do
        ui:RegisterMainTab(main.key, main.label, main.order)
        local subList = {}
        for _, sub in pairs(main.subs) do
            subList[#subList + 1] = sub
        end
        table.sort(subList, function(a, b)
            return (a.order or 1) < (b.order or 1)
        end)
        for _, sub in ipairs(subList) do
            table.sort(sub.builds, function(a, b)
                return (a.order or 1) < (b.order or 1)
            end)
            local builds = sub.builds
            ui:RegisterSubTab(main.key, sub.key, sub.label, function()
                uiMain = main.key
                uiSub = sub.key
                ui:ClearSubContent()
                for _, def in ipairs(builds) do
                    pcall(def.build, ui)
                end
            end, sub.order, type(sub.icon) == "string" and sub.icon ~= "" and { icon = sub.icon } or nil)
        end
    end
end

local moneyApi

function Core.money()
    if moneyApi then
        return moneyApi
    end
    local percent = 80
    moneyApi = {}

    function moneyApi.percent()
        return percent
    end

    function moneyApi.setPercent(n)
        n = tonumber(n)
        if not n then
            return percent
        end
        if n < 0 then
            n = 0
        elseif n > 100 then
            n = 100
        end
        percent = n
        return percent
    end

    -- Sisa yang harus masih tertutup, dihitung dari biaya. 80 pada biaya 10 = sisa 8.
    function moneyApi.reserve(cost, pct)
        cost = tonumber(cost) or 0
        pct = tonumber(pct) or percent
        return cost * pct / 100
    end

    -- Uang minimum sebelum fitur boleh memakai biaya itu.
    function moneyApi.required(cost, pct)
        cost = tonumber(cost) or 0
        return cost + moneyApi.reserve(cost, pct)
    end

    function moneyApi.allows(money, cost, pct)
        return (tonumber(money) or 0) >= moneyApi.required(cost, pct)
    end

    env().AnimeDiceMoney = moneyApi
    return moneyApi
end

function Core.compact(n)
    n = tonumber(n)
    if not n then
        return "-"
    end
    local ok, text = pcall(function()
        return require(game:GetService("ReplicatedStorage").Packages.NumberFormatter).FormatCompact(n, 2)
    end)
    if ok and type(text) == "string" and text ~= "" then
        return text
    end
    return tostring(math.floor(n))
end

function Core.grouped(n)
    n = tonumber(n)
    if not n then
        return "-"
    end
    n = math.floor(n + (n >= 0 and 0.5 or -0.5))
    local sign = ""
    if n < 0 then
        sign = "-"
        n = -n
    end
    local s = tostring(n)
    local k
    repeat
        s, k = s:gsub("^(%d+)(%d%d%d)", "%1.%2")
    until k == 0
    return sign .. s
end

function Core.panelStroke(parent, accent)
    if not parent then
        return nil
    end
    local stroke = Instance.new("UIStroke")
    stroke.Color = accent or Color3.fromRGB(232, 232, 236)
    stroke.Thickness = 1
    stroke.Transparency = 0.45
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = parent
    local function kick()
        if not stroke.Parent then
            return
        end
        stroke.Enabled = false
        stroke.Enabled = true
    end
    parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(kick)
    task.defer(kick)
    return stroke
end

function Core.fitY(frame, layout, extra)
    extra = tonumber(extra) or 0
    if not frame then
        return function() end
    end
    local function apply()
        if not frame.Parent then
            return
        end
        local content = extra
        if layout then
            pcall(function()
                content = extra + (tonumber(layout.AbsoluteContentSize.Y) or 0)
            end)
        end
        if content < 48 then
            content = 48
        end
        frame.AutomaticSize = Enum.AutomaticSize.None
        local x = frame.Size
        frame.Size = UDim2.new(x.X.Scale, x.X.Offset, 0, content)
    end
    if layout then
        pcall(function()
            layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(apply)
        end)
    end
    task.defer(apply)
    return apply
end

function Core.kickScroll(scroll)
    if not scroll or not scroll:IsA("ScrollingFrame") then
        return
    end
    local function kick()
        if not scroll.Parent then
            return
        end
        local pos = scroll.CanvasPosition
        scroll.CanvasPosition = Vector2.new(pos.X, pos.Y + 1)
        scroll.CanvasPosition = pos
    end
    task.defer(kick)
    task.delay(0.05, kick)
end

function Core.paintHeader(api, value, style, detail)
    if type(api) ~= "table" then
        return
    end
    if type(api.set) == "function" then
        pcall(api.set, value)
    end
    if type(api.setStyle) == "function" then
        pcall(api.setStyle, style)
    end
    if type(api.setDetail) == "function" then
        pcall(api.setDetail, detail)
    end
end

function Core.bindToggle(ui, parent, opts)
    opts = type(opts) == "table" and opts or {}
    return ui:CreateRowToggle(parent, {
        id = opts.id,
        label = opts.label,
        persist = opts.persist ~= false,
        initial = opts.initial == true,
        onChanged = opts.onChanged,
    })
end

function Core.sync(ui)
    local values = {}
    pcall(function()
        values = ui:GetValues() or {}
    end)
    for _, fn in ipairs(syncFns) do
        pcall(fn, values, ui)
    end
end

return Core
 end, required = true },
    { key = "PotionCatalog", name = "PotionCatalog", factory = function() -- Katalog item Use (Boost potion).
-- Global: Core.potions() / getgenv().AnimeDicePotionCatalog
-- Spin / trait / grade bukan list Auto Item.

local RS = game:GetService("ReplicatedStorage")

local BUFF_ORDER = {
    Luck = 1,
    Income = 2,
    Damage = 3,
    Speed = 4,
    Candy = 5,
    Pumpkins = 6,
    Haunted = 7,
}
local LINE_ORDER = { Normal = 1, Dragon = 2, Cursed = 3, Pirate = 4, Leaf = 5, Slayer = 6, Shadow = 7 }
local LINE_PREFIX = { "Dragon", "Cursed", "Pirate", "Leaf", "Slayer", "Shadow" }

local WHENS = {
    { key = "always", name = "Always" },
    { key = "tower", name = "Tower" },
    { key = "luck_event", name = "Luck Event" },
    { key = "cash_event", name = "Cash Event" },
    { key = "roll_speed_event", name = "Roll Speed Event" },
    { key = "haunted_night", name = "Haunted Night" },
}

local WEATHER_WHEN = {
    ["Luck Event"] = "luck_event",
    ["Cash Event"] = "cash_event",
    ["Roll Speed Event"] = "roll_speed_event",
    ["Haunted Night"] = "haunted_night",
}

local Catalog = {
    BUFFS = { "Luck", "Income", "Damage", "Speed", "Candy", "Pumpkins", "Haunted" },
    LINES = { "Normal", "Dragon", "Cursed", "Pirate", "Leaf", "Slayer", "Shadow" },
    WHENS = WHENS,
}

local itemsCache
local categoriesCache
local weatherProp

local function buffFromConfig(cfg)
    if type(cfg) ~= "table" or type(cfg.buffs) ~= "table" then
        return nil
    end
    if cfg.buffs.Luck then
        return "Luck"
    end
    if cfg.buffs["Money Multiplier"] then
        return "Income"
    end
    if cfg.buffs["Damage Multiplier"] then
        return "Damage"
    end
    if cfg.buffs["Roll Duration"] then
        return "Speed"
    end
    if cfg.buffs["Candy Gain"] then
        return "Candy"
    end
    if cfg.buffs["Pumpkin Gain"] then
        return "Pumpkins"
    end
    if cfg.buffs["Pumpkin Luck"] then
        return "Haunted"
    end
    return nil
end

local BUFF_KEYS = {
    Luck = "Luck",
    Income = "Money Multiplier",
    Damage = "Damage Multiplier",
    Speed = "Roll Duration",
    Candy = "Candy Gain",
    Pumpkins = "Pumpkin Gain",
    Haunted = "Pumpkin Luck",
}

local function amountFromConfig(cfg, buff)
    if type(cfg) ~= "table" or type(cfg.buffs) ~= "table" then
        return 0
    end
    local row = cfg.buffs[BUFF_KEYS[buff] or buff]
    if type(row) ~= "table" then
        return 0
    end
    return tonumber(row.amount) or 0
end

function Catalog.cmpBest(a, b)
    local aa = tonumber(a and a.amount) or 0
    local ba = tonumber(b and b.amount) or 0
    if aa ~= ba then
        return aa > ba
    end
    local ta = tonumber(a and a.tier) or 0
    local tb = tonumber(b and b.tier) or 0
    if ta ~= tb then
        return ta > tb
    end
    local oa = BUFF_ORDER[a and a.buff] or 99
    local ob = BUFF_ORDER[b and b.buff] or 99
    if oa ~= ob then
        return oa < ob
    end
    local la = LINE_ORDER[a and a.line] or 99
    local lb = LINE_ORDER[b and b.line] or 99
    if la ~= lb then
        return la < lb
    end
    return tostring(a and a.name or "") < tostring(b and b.name or "")
end

local function lineFromCategory(category)
    category = tostring(category or "")
    for _, prefix in ipairs(LINE_PREFIX) do
        if category == prefix or category:sub(1, #prefix + 1) == (prefix .. " ") then
            return prefix
        end
    end
    return "Normal"
end

local function categoryLabel(buff, line, category)
    if buff == "Candy" or buff == "Pumpkins" or buff == "Haunted" then
        return tostring(category)
    end
    if line == "Normal" then
        return tostring(buff) .. " · " .. tostring(buff)
    end
    return tostring(buff) .. " · " .. tostring(category)
end

local function cmpItem(a, b)
    local oa = (BUFF_ORDER[a.buff] or 99)
    local ob = (BUFF_ORDER[b.buff] or 99)
    if oa ~= ob then
        return oa < ob
    end
    local la = LINE_ORDER[a.line] or 99
    local lb = LINE_ORDER[b.line] or 99
    if la ~= lb then
        return la < lb
    end
    local ta = tonumber(a.tier) or 0
    local tb = tonumber(b.tier) or 0
    if ta ~= tb then
        return ta < tb
    end
    return tostring(a.name or a.key or "") < tostring(b.name or b.key or "")
end

function Catalog.items()
    if itemsCache then
        return itemsCache
    end
    local out = {}
    pcall(function()
        local boost = require(RS.Framework.Features.Inventory.Kinds.Boost.BoostConfig)
        for name, cfg in pairs(boost.entries or {}) do
            if type(name) == "string" and type(cfg) == "table" then
                local buff = buffFromConfig(cfg)
                if buff then
                    local category = cfg.category or name
                    local line = lineFromCategory(category)
                    local tier = tonumber(cfg.tier) or 1
                    out[#out + 1] = {
                        name = name,
                        kind = "Potion",
                        category = category,
                        line = line,
                        buff = buff,
                        tier = tier,
                        amount = amountFromConfig(cfg, buff),
                        duration = tonumber(cfg.duration) or 0,
                        label = categoryLabel(buff, line, category),
                    }
                end
            end
        end
    end)
    table.sort(out, cmpItem)
    itemsCache = out
    return itemsCache
end

function Catalog.categories()
    if categoriesCache then
        return categoriesCache
    end
    local byKey = {}
    local out = {}
    for _, item in ipairs(Catalog.items()) do
        local cur = byKey[item.category]
        if not cur then
            cur = {
                key = item.category,
                name = item.category,
                label = item.label,
                buff = item.buff,
                line = item.line,
                maxTier = item.tier,
                amount = item.amount,
                duration = item.duration,
            }
            byKey[item.category] = cur
            out[#out + 1] = cur
        else
            if (item.tier or 0) > (cur.maxTier or 0) then
                cur.maxTier = item.tier
                cur.amount = item.amount
                cur.duration = item.duration
            end
        end
    end
    table.sort(out, cmpItem)
    categoriesCache = out
    return categoriesCache
end

function Catalog.dropdownItems()
    local out = {}
    for _, cat in ipairs(Catalog.categories()) do
        out[#out + 1] = {
            key = cat.key,
            name = cat.label,
        }
    end
    return out
end

function Catalog.whenItems()
    return WHENS
end

function Catalog.whenName(key)
    for _, row in ipairs(WHENS) do
        if row.key == key then
            return row.name
        end
    end
    return tostring(key or "")
end

function Catalog.byName(name)
    name = tostring(name or "")
    for _, item in ipairs(Catalog.items()) do
        if item.name == name then
            return item
        end
    end
    return nil
end

function Catalog.byCategory(category)
    category = tostring(category or "")
    for _, cat in ipairs(Catalog.categories()) do
        if cat.key == category then
            return cat
        end
    end
    return nil
end

function Catalog.weatherName()
    if not weatherProp then
        pcall(function()
            weatherProp = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "WeatherService"):GetProperty("ActiveWeather")
        end)
    end
    if not weatherProp then
        return nil
    end
    local ok, cur = pcall(function()
        return weatherProp:Get()
    end)
    if not ok or type(cur) ~= "table" then
        return nil
    end
    return cur.name
end

function Catalog.inTower()
    local ok, result = pcall(function()
        local UIReferences = require(RS.Framework.Features.UI.UIReferences)
        local tower = UIReferences.Root and UIReferences.Root.Tower
        if not tower then
            return false
        end
        local screen = tower:FindFirstChild("Screen")
        local hidden = tower:FindFirstChild("Hidden")
        return (screen and screen.Visible == true) or (hidden and hidden.Visible == true)
    end)
    return ok and result == true
end

local function mapOn(map, key)
    if type(map) ~= "table" then
        return false
    end
    local v = map[key]
    if v == true or v == 1 or v == "true" then
        return true
    end
    return false
end

function Catalog.whenMatches(map)
    if type(map) ~= "table" then
        return false
    end
    local any = false
    for _, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            any = true
            break
        end
    end
    if not any then
        return false
    end
    if mapOn(map, "always") then
        return true
    end
    if mapOn(map, "tower") and Catalog.inTower() then
        return true
    end
    local weather = Catalog.weatherName()
    local weatherKey = weather and WEATHER_WHEN[weather]
    if weatherKey and mapOn(map, weatherKey) then
        return true
    end
    return false
end

function Catalog.install(Core, G)
    G = G or (getgenv and getgenv()) or _G
    G.AnimeDicePotionCatalog = Catalog
    if type(G.AnimeDice) == "table" then
        G.AnimeDice.PotionCatalog = Catalog
    end
    if type(Core) == "table" then
        Core.potionCatalog = Catalog
    end
    return Catalog
end

return Catalog
