function Catalog.goalOf(key)
    key = tostring(key or "")
    if key == "money" then
        key = "income"
    end
    for _, row in ipairs(GOALS) do
        if row.key == key then
            return row
        end
    end
    return GOALS[1]
end

function Catalog.goalItems()
    local out = {}
    for _, row in ipairs(GOALS) do
        out[#out + 1] = { key = row.key, name = row.name }
    end
    return out
