function Catalog.slots()
    if slotsCache then
        return slotsCache
    end
    local cfg = liveConfig()
    local list = {}
    local seen = {}
    if cfg and type(cfg.slots) == "table" then
        for _, slot in ipairs(cfg.slots) do
            slot = tostring(slot or "")
            if slot ~= "" and not seen[slot] then
                seen[slot] = true
                list[#list + 1] = slot
            end
        end
    end
    if #list == 0 then
        for _, slot in ipairs(SLOTS) do
            list[#list + 1] = slot
        end
    end
    slotsCache = list
    return slotsCache
end

local function copyBuffs(src)
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    for name, row in pairs(src) do
        if type(row) == "table" then
            out[name] = {
                bucket = tostring(row.bucket or ""),
                amount = tonumber(row.amount) or 0,
            }
        end
    end
    return out
end

local function makeItem(name, cfg)
    if type(name) ~= "string" or name == "" or type(cfg) ~= "table" then
        return nil
    end
    local slot = tostring(cfg.slot or "")
    if slot == "" then
        return nil
    end
    local rarity = tostring(cfg.rarity or "Rare")
    return {
        name = name,
        slot = slot,
        rarity = rarity,
        rarityRank = RARITY_RANK[rarity] or 0,
        buffs = copyBuffs(cfg.buffs),
    }
end

function Catalog.items()
    if itemsCache then
        return itemsCache
    end
    local byName = {}
    local cfg = liveConfig()
    if cfg then
        for name, row in pairs(cfg.entries) do
            local item = makeItem(name, row)
            if item then
                byName[item.name] = item
            end
        end
    end
    if next(byName) == nil then
        for name, row in pairs(FALLBACK_ENTRIES) do
            local item = makeItem(name, row)
            if item then
                byName[item.name] = item
            end
        end
    end
    local out = {}
    for _, item in pairs(byName) do
        out[#out + 1] = item
    end
    local function slotIndex(slot)
        for i, name in ipairs(Catalog.slots()) do
            if name == slot then
                return i
            end
        end
        return 99
    end
    table.sort(out, function(a, b)
        local sa = slotIndex(a.slot)
        local sb = slotIndex(b.slot)
        if sa ~= sb then
            return sa < sb
        end
        if (a.rarityRank or 0) ~= (b.rarityRank or 0) then
            return (a.rarityRank or 0) > (b.rarityRank or 0)
        end
        return tostring(a.name) < tostring(b.name)
    end)
    itemsCache = out
    byNameCache = byName
    return itemsCache
end

function Catalog.byName(name)
    name = tostring(name or "")
    if name == "" then
        return nil
    end
    Catalog.items()
    return byNameCache and byNameCache[name] or nil
end

function Catalog.score(item, goalKey)
    if type(item) ~= "table" then
        return 0
    end
    local goal = Catalog.goalOf(goalKey)
    local row = item.buffs and item.buffs[goal.buff]
    if type(row) ~= "table" then
        return 0
    end
    return tonumber(row.amount) or 0
end

function Catalog.better(a, b, goalKey)
    if not a then
        return false
    end
    if not b then
        return true
    end
    local sa = Catalog.score(a, goalKey)
    local sb = Catalog.score(b, goalKey)
    if sa ~= sb then
        return sa > sb
    end
    local ra = tonumber(a.rarityRank) or 0
    local rb = tonumber(b.rarityRank) or 0
    if ra ~= rb then
        return ra > rb
    end
    return tostring(a.name or "") < tostring(b.name or "")
end

function Catalog.pickBest(owned, goalKey)
    local picks = {}
    if type(owned) ~= "table" then
        return picks
    end
    for _, item in ipairs(Catalog.items()) do
        local amount = tonumber(owned[item.name]) or 0
        if amount > 0 then
            local cur = picks[item.slot]
            if Catalog.better(item, cur, goalKey) then
                picks[item.slot] = item
            end
        end
    end
    return picks
end

function Catalog.install(Core, G)
    G = G or (getgenv and getgenv()) or _G
    G.AnimeDiceGearCatalog = Catalog
    if type(G.AnimeDice) == "table" then
        G.AnimeDice.GearCatalog = Catalog
    end
    if type(Core) == "table" then
        Core.gearCatalog = Catalog
    end
    return Catalog
end

return Catalog
