    { key = "UnitEarn", name = "UnitEarn", factory = function() -- Rumus earn dari EntryConfig.income (game). Min/max dari SEMUA pilihan.
-- Dipakai Auto Unit. Tidak Fire remote.

local RS = game:GetService("ReplicatedStorage")

local Earn = {}

local SUFFIX = {
    k = 1e3,
    m = 1e6,
    b = 1e9,
    t = 1e12,
    qd = 1e15,
    qi = 1e18,
    sx = 1e21,
    sp = 1e24,
    sc = 1e21,
}

function Earn.readVal(v)
    for _ = 1, 3 do
        if type(v) == "function" then
            local ok, r = pcall(v)
            if not ok then
                return nil
            end
            v = r
        elseif type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if not ok or r == v then
                break
            end
            v = r
        else
            break
        end
    end
    if type(v) == "string" or type(v) == "number" or type(v) == "boolean" then
        return v
    end
    return nil
end

function Earn.name(v)
    v = Earn.readVal(v)
    if type(v) ~= "string" then
        return nil
    end
    v = v:gsub("^%s+", ""):gsub("%s+$", "")
    if v == "" or v == "None" then
        return nil
    end
    return v
end

function Earn.field(source, key)
    if type(source) ~= "table" then
        return nil
    end
    return Earn.readVal(source[key])
end

function Earn.parseCompact(text)
    text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
    if text == "" then
        return 0
    end
    local n = tonumber(text)
    if n then
        return math.max(0, n)
    end
    local ok, value = pcall(function()
        return require(RS.Packages.NumberFormatter).ParseCompact(text)
    end)
    if ok and tonumber(value) then
        return math.max(0, tonumber(value))
    end
    local num, suf = text:lower():match("^([%d%.]+)([a-z]+)$")
    n = tonumber(num)
    local mul = suf and SUFFIX[suf]
    if n and mul then
        return math.max(0, n * mul)
    end
    return 0
end

function Earn.entryConfig(name)
    if type(name) ~= "string" or name == "" then
        return nil
    end
    local ok, cfg = pcall(function()
        return require(RS.Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
    end)
    if ok and type(cfg) == "table" and cfg.kind == "Unit" then
        return cfg
    end
    return nil
end

function Earn.attrs(item)
    if type(item) ~= "table" then
        return {}
    end
    local raw = item.attributes
    if type(raw) == "function" then
        local ok, t = pcall(raw)
        raw = ok and t or nil
    end
    if type(raw) ~= "table" then
        raw = item
    end
    return {
        mutation = Earn.name(raw.mutation) or Earn.field(raw, "mutation"),
        trait = Earn.name(raw.trait),
        grade = Earn.name(raw.grade),
        quirk = Earn.name(raw.quirk),
        level = tonumber(Earn.field(raw, "level")) or 1,
        locked = Earn.field(raw, "locked") == true,
    }
end

function Earn.income(cfg, attrs)
    if type(cfg) ~= "table" or type(cfg.income) ~= "function" then
        return 0
    end
    local ok, n = pcall(cfg.income, attrs)
    return (ok and tonumber(n)) or 0
end

function Earn.mul(mod, name)
    if type(mod) ~= "table" or type(name) ~= "string" or name == "" then
        return 1
    end
    local row = mod[name]
    if type(row) ~= "table" then
        return 1
    end
    return tonumber(row.incomeMultiplier) or 1
end

-- Grade: income saja. Trait: income / damage / health, ambil yang paling tinggi.
function Earn.strength(info)
    if type(info) ~= "table" then
        return nil
    end
    local best = 0
    local inc = tonumber(info.incomeMultiplier)
    local dmg = tonumber(info.damageMultiplier)
    local hp = tonumber(info.healthMultiplier)
    if inc and inc > best then
        best = inc
    end
    if dmg and dmg > best then
        best = dmg
    end
    if hp and hp > best then
        best = hp
    end
    if best <= 0 then
        return nil
    end
    return best
end

function Earn.levelFactor(level)
    level = tonumber(level) or 1
    if level < 1 then
        level = 1
    end
    return 1 + 0.25 * (level - 1)
end

local function selectedKeys(map)
    local keys = {}
    if type(map) ~= "table" then
        return keys
    end
    for k, v in pairs(map) do
        if v == true or v == 1 or v == "true" then
            keys[#keys + 1] = tostring(k)
        elseif type(k) == "number" and type(v) == "string" then
            keys[#keys + 1] = v
        elseif type(v) == "table" then
            keys[#keys + 1] = tostring(v.key or v.id or v.name or k)
        end
    end
    return keys
end

-- Semua yang dicentang. Filter earn pakai income terendah, bukan cuma 3 terkuat.
-- Health/Damage income-nya 1, jadi kalau dicentang, target harus tembus tanpa bonus trait.
function Earn.picked(mod, selectedMap)
    local rows = {}
    for _, key in ipairs(selectedKeys(selectedMap)) do
        local info = type(mod) == "table" and mod[key]
        local mul = Earn.strength(info)
        if mul then
            rows[#rows + 1] = {
                key = key,
                mul = mul,
                income = (type(info) == "table" and tonumber(info.incomeMultiplier)) or 1,
                order = tonumber(info.order) or 0,
            }
        end
    end
    table.sort(rows, function(a, b)
        local ai = tonumber(a.income) or 1
        local bi = tonumber(b.income) or 1
        if ai == bi then
            if a.mul == b.mul then
                return a.order > b.order
            end
            return a.mul > b.mul
        end
        return ai > bi
    end)
    return rows
end

function Earn.best3(list)
    local rows = {}
    if type(list) ~= "table" then
        return rows
    end
    for i = 1, #list do
        rows[i] = list[i]
    end
    table.sort(rows, function(a, b)
        local am = tonumber(a.mul) or 0
        local bm = tonumber(b.mul) or 0
        if am == bm then
            return (tonumber(a.order) or 0) > (tonumber(b.order) or 0)
        end
        return am > bm
    end)
    local out = {}
    for i = 1, math.min(3, #rows) do
        out[i] = rows[i]
    end
    return out
end

function Earn.minStrengthOf(list)
    if type(list) ~= "table" or #list == 0 then
        return nil
    end
    local minRow = list[1]
    local minMul = tonumber(minRow.mul) or 0
    for i = 2, #list do
        local mul = tonumber(list[i].mul) or 0
        if mul < minMul then
            minRow = list[i]
            minMul = mul
        end
    end
    return minRow
end

function Earn.top3(mod, selectedMap)
    return Earn.best3(Earn.picked(mod, selectedMap))
end

function Earn.minIncomeOf(list)
    if type(list) ~= "table" or #list == 0 then
        return nil
    end
    local minRow = list[1]
    local minInc = tonumber(minRow.income) or 1
    for i = 2, #list do
        local inc = tonumber(list[i].income) or 1
        if inc < minInc then
            minRow = list[i]
            minInc = inc
        elseif inc == minInc and (tonumber(list[i].mul) or 0) < (tonumber(minRow.mul) or 0) then
            minRow = list[i]
        end
    end
    return minRow
end

function Earn.maxIncomeOf(list)
    if type(list) ~= "table" or #list == 0 then
        return nil
    end
    local maxRow = list[1]
    local maxInc = tonumber(maxRow.income) or 1
    for i = 2, #list do
        local inc = tonumber(list[i].income) or 1
        if inc > maxInc then
            maxRow = list[i]
            maxInc = inc
        elseif inc == maxInc and (tonumber(list[i].mul) or 0) > (tonumber(maxRow.mul) or 0) then
            maxRow = list[i]
        end
    end
    return maxRow
end

function Earn.minOf(list)
    return Earn.minIncomeOf(list)
end

local function pumpkinChance(name, attrs)
    if type(name) ~= "string" or name == "" then
        return nil
    end
    local ok, PD = pcall(function()
        return require(RS.Framework.Features.Halloween.PumpkinDice)
    end)
    if not ok or type(PD) ~= "table" or type(PD.Get) ~= "function" or type(PD.GetChance) ~= "function" then
        return nil
    end
    local unit = PD.Get(name)
    if type(unit) ~= "table" then
        return nil
    end
    -- Base 1-in (luck=1). Mutation event unit biasanya tidak dipakai di PumpkinDice odds.
    local okc, n = pcall(PD.GetChance, unit, 1)
    n = okc and tonumber(n) or nil
    if not n then
        n = tonumber(unit.chance)
    end
    if n and type(attrs) == "table" and type(attrs.mutation) == "string" and attrs.mutation ~= "" then
        -- EntryRegistry chance kalikan mutation; fallback dekat-dekat kalau ada Mutations.
        pcall(function()
            local Mutations = require(RS.Framework.Features.Inventory.Kinds.Unit.Mutations)
            local row = Mutations[attrs.mutation]
            local mul = row and tonumber(row.chance)
            if mul and mul > 0 then
                n = n * mul
            end
        end)
    end
    return n
end

function Earn.chance(cfg, attrs, name)
    if type(cfg) == "table" and type(cfg.chance) == "function" then
        local ok, n = pcall(cfg.chance, {
            mutation = type(attrs) == "table" and attrs.mutation or nil,
        })
        n = ok and tonumber(n) or nil
        if n then
            return n
        end
    end
    -- Unit Halloween/Pumpkin Dice: game set limited tanpa cfg.chance → ambil dari PumpkinDice.
    return pumpkinChance(name or (type(cfg) == "table" and cfg.id) or nil, attrs)
end

function Earn.maxOf(list)
    return Earn.maxIncomeOf(list)
end

function Earn.inSet(list, name)
    if type(name) ~= "string" or name == "" or type(list) ~= "table" then
        return false
    end
    for _, row in ipairs(list) do
        if row.key == name then
            return true
        end
    end
    return false
end

-- Jangan ngeroll turun. Sudah >= min pilihan = selesai.
-- Grade: income. Trait: strength (income/dmg/hp). Kosong = 0.
function Earn.atLeast(mod, name, minRow, kind)
    if type(minRow) ~= "table" then
        return true
    end
    local info = nil
    if type(name) == "string" and name ~= "" and type(mod) == "table" then
        info = mod[name]
    end
    local have, need
    if kind == "trait" then
        have = Earn.strength(info) or 0
        need = tonumber(minRow.mul) or 0
    else
        have = (type(info) == "table" and tonumber(info.incomeMultiplier)) or 0
        need = tonumber(minRow.income) or tonumber(minRow.mul) or 0
    end
    if need <= 0 then
        return true
    end
    return have + 1e-12 >= need
end

function Earn.snapshot(item, opts)
    opts = type(opts) == "table" and opts or {}
    local name = Earn.field(item, "name") or item and item.name
    local cfg = Earn.entryConfig(name)
    if not cfg then
        return nil
    end
    local attrs = Earn.attrs(item)
    local maxLevel = tonumber(opts.maxLevel) or 60
    local minTrait = opts.minTrait
    local minGrade = opts.minGrade
    local maxTrait = opts.maxTrait
    local maxGrade = opts.maxGrade
    -- Cap filter: base unit di Lv1. Mutation tetap (identitas unit).
    -- Trait/grade sekarang DIBAUNG — kalau dihitung, Eternal×Z+ bikin cap tidak akurat.
    local earnLv1, earnMin, earnMax = 0, 0, 0
