        earnMax = Earn.income(cfg, {
            mutation = attrs.mutation,
            trait = maxTrait or minTrait,
            grade = maxGrade or minGrade,
            level = maxLevel,
        })
    end
    local title = name
    if type(attrs.mutation) == "string" and attrs.mutation ~= "" then
        title = name .. "  " .. attrs.mutation
    end
    return {
        name = name,
        title = title,
        cfg = cfg,
        mutation = attrs.mutation,
        trait = attrs.trait,
        grade = attrs.grade,
        quirk = attrs.quirk,
        level = attrs.level,
        locked = attrs.locked,
        chance = Earn.chance(cfg, attrs, name),
        earnLv1 = earnLv1,
        earnNow = earnNow,
        earnGoal = earnMin,
        earnMin = earnMin,
        earnMax = earnMax,
    }
