 end, required = true },
    { key = "UnitRules", name = "UnitRules", factory = function() -- Rule Make Unit: siapa (nama unit + Earn / 1-in) dan keep apa (grade / trait / quirk / level).
-- Logic murni, dipakai Auto Unit. Tidak ada loop, tidak Fire remote.

local Rules = {}

local DEFAULT_LEVEL = 60

local function copyMap(src)
    local out = {}
    if type(src) ~= "table" then
        return out
    end
    for k, v in pairs(src) do
        if v == true or v == 1 or v == "true" then
            out[tostring(k)] = true
        elseif type(k) == "number" and v ~= nil then
            out[tostring(v)] = true
        end
    end
    return out
end
Rules.copyMap = copyMap

local function mapKeys(map)
    local out = {}
    for k, on in pairs(map or {}) do
        if on == true then
            out[#out + 1] = k
        end
    end
    table.sort(out)
    return out
end
Rules.mapKeys = mapKeys

local function hasAny(map)
    return next(map or {}) ~= nil
end

local function clampLevel(v)
    local n = math.floor(tonumber(v) or DEFAULT_LEVEL)
    return math.clamp(n, 0, 9999)
end

local DEFAULT_MAX_UNITS = 50

local function clampMaxUnits(v)
    local n = math.floor(tonumber(v) or DEFAULT_MAX_UNITS)
    return math.clamp(n, 1, 500)
end
Rules.clampMaxUnits = clampMaxUnits

local idSeq = 0
function Rules.newId()
    idSeq = idSeq + 1
    return string.format("mu%d_%d", math.floor(os.clock() * 1000), idSeq)
end

function Rules.sanitize(rule)
    if type(rule) ~= "table" then
        return nil
    end
    local mode = rule.mode == "onein" and "onein" or "earn"
    return {
        id = tostring(rule.id or Rules.newId()),
        enabled = rule.enabled ~= false,
        units = copyMap(rule.units),
        mode = mode,
        target = tostring(rule.target or "0"),
        earnMax = tostring(rule.earnMax or "0"),
        maxLv1 = tostring(rule.maxLv1 or "0"),
        oneIn = tostring(rule.oneIn or "0"),
        oneInMax = tostring(rule.oneInMax or "0"),
        maxLevel = clampLevel(rule.maxLevel),
        maxUnits = clampMaxUnits(rule.maxUnits),
        grades = copyMap(rule.grades),
        traits = copyMap(rule.traits),
        quirks = copyMap(rule.quirks),
        skipQuirks = copyMap(rule.skipQuirks),
    }
end

function Rules.sanitizeList(list)
    local out = {}
    if type(list) ~= "table" then
        return out
    end
    for _, rule in ipairs(list) do
        local clean = Rules.sanitize(rule)
        if clean then
            out[#out + 1] = clean
        end
    end
    return out
end

local function range(rule, Earn)
    if rule.mode == "onein" then
        local lo = Earn.parseCompact(rule.oneIn) or 0
        local hi = Earn.parseCompact(rule.oneInMax) or 0
        if lo > 0 and hi > 0 and lo > hi then
            lo, hi = hi, lo
        end
        return lo, hi > 0 and hi or math.huge
    end
    local lo = Earn.parseCompact(rule.target) or 0
    local hi = Earn.parseCompact(rule.earnMax) or 0
    if lo > 0 and hi > 0 and lo > hi then
        lo, hi = hi, lo
    end
    return lo, hi > 0 and hi or math.huge
end

local function scopeOverlap(a, b)
    if not hasAny(a.units) or not hasAny(b.units) then
        return true
    end
    for k in pairs(a.units) do
        if b.units[k] then
            return true
        end
    end
    return false
end

-- Filter (Earn / 1-in) sama mode + unit overlap + range overlap = bentrok.
function Rules.overlaps(a, b, Earn)
    if type(a) ~= "table" or type(b) ~= "table" then
        return false
    end
    if a.mode ~= b.mode or not scopeOverlap(a, b) then
        return false
    end
    local aLo, aHi = range(a, Earn)
    local bLo, bHi = range(b, Earn)
    return aLo <= bHi and bLo <= aHi
end

function Rules.findOverlap(rule, list, Earn, skipId)
    for i, other in ipairs(list or {}) do
        if other.enabled ~= false and tostring(other.id) ~= tostring(skipId or "") then
            if Rules.overlaps(rule, other, Earn) then
                return i, other
            end
        end
    end
    return nil
end

local function pickedQuirks(quirksMod, map)
    local rows = {}
    if type(quirksMod) ~= "table" then
        return rows
    end
    for key, on in pairs(map or {}) do
        local info = on == true and quirksMod[key]
        if type(info) == "table" then
            local order = tonumber(info.order) or 0
            rows[#rows + 1] = { key = key, mul = order, income = order, order = order }
        end
    end
    table.sort(rows, function(x, y)
        return (tonumber(x.order) or 0) > (tonumber(y.order) or 0)
    end)
    return rows
end

-- ctx = { Earn, gradesMod, traitsMod, quirksMod }
function Rules.compile(rule, index, ctx)
    local Earn = ctx.Earn
    local gAll = Earn.picked(ctx.gradesMod, rule.grades)
    local tAll = Earn.picked(ctx.traitsMod, rule.traits)
    local g3 = Earn.best3(gAll)
    local t3 = Earn.best3(tAll)
    local q3 = Earn.best3(pickedQuirks(ctx.quirksMod, rule.quirks))
    local oneIn = Earn.parseCompact(rule.oneIn) or 0
    local oneInMax = Earn.parseCompact(rule.oneInMax) or 0
    if oneIn > 0 and oneInMax > 0 and oneIn > oneInMax then
        oneIn, oneInMax = oneInMax, oneIn
    end
    return {
        id = rule.id,
        index = index,
        label = "R" .. tostring(index),
        units = rule.units,
        anyUnit = not hasAny(rule.units),
        mode = rule.mode,
        targetEarn = Earn.parseCompact(rule.target) or 0,
        earnMax = Earn.parseCompact(rule.earnMax) or 0,
        maxEarnLv1 = Earn.parseCompact(rule.maxLv1) or 0,
        oneIn = oneIn,
        oneInMax = oneInMax,
        maxLevel = clampLevel(rule.maxLevel),
        maxUnits = clampMaxUnits(rule.maxUnits),
        grades = rule.grades,
        traits = rule.traits,
        quirks = rule.quirks,
        skipQuirks = rule.skipQuirks or {},
        g3 = g3,
        t3 = t3,
        q3 = q3,
        gmin = Earn.minStrengthOf(g3),
        tmin = Earn.minStrengthOf(t3),
        qmin = Earn.minStrengthOf(q3),
        gFilter = Earn.minIncomeOf(gAll),
        tFilter = Earn.minIncomeOf(tAll),
        gmax = Earn.maxIncomeOf(gAll),
        tmax = Earn.maxIncomeOf(tAll),
    }
end

function Rules.compileAll(list, ctx)
    local out = {}
    for i, rule in ipairs(list or {}) do
        if rule.enabled ~= false then
            out[#out + 1] = Rules.compile(rule, i, ctx)
        end
    end
    return out
end

-- units berisi id unit dari bag; nama unit (rule lama) tetap dihormati.
function Rules.unitIn(c, name, id)
    if c.anyUnit then
        return true
    end
    if type(id) == "string" and c.units[id] == true then
        return true
    end
    return type(name) == "string" and c.units[name] == true
end

-- Unit yang sudah punya quirk blacklist tidak masuk rule ini.
function Rules.blocked(c, quirk)
    return type(quirk) == "string" and quirk ~= "" and type(c.skipQuirks) == "table" and c.skipQuirks[quirk] == true
end

function Rules.snapOpts(c)
    return {
        maxLevel = c.maxLevel,
        minTrait = c.tFilter and c.tFilter.key or nil,
        minGrade = c.gFilter and c.gFilter.key or nil,
        maxTrait = c.tmax and c.tmax.key or nil,
        maxGrade = c.gmax and c.gmax.key or nil,
    }
end

function Rules.pass(snap, c)
    if not snap or not c then
        return false
    end
    if c.mode == "onein" then
        local lo, hi = c.oneIn, c.oneInMax
        local have = tonumber(snap.chance) or 0
        if have <= 0 then
            return false
        end
        if lo > 0 and have < lo then
            return false
        end
        if hi > 0 and have > hi then
            return false
        end
        return lo > 0 or hi > 0
    end
    if c.maxEarnLv1 > 0 and (tonumber(snap.earnLv1) or 0) > c.maxEarnLv1 then
        return false
    end
    local goal = tonumber(snap.earnGoal) or 0
    if c.targetEarn > 0 and goal < c.targetEarn then
        return false
    end
    if c.earnMax > 0 and goal > c.earnMax then
        return false
    end
    return true
end

local function preview(map, empty)
    local keys = mapKeys(map)
    if #keys == 0 then
        return empty
    end
    if #keys <= 2 then
        return table.concat(keys, ", ")
    end
    return keys[1] .. ", " .. keys[2] .. " +" .. tostring(#keys - 2)
end

function Rules.filterText(rule, Earn)
    local function c(v)
        local n = Earn.parseCompact(v) or 0
        return n > 0 and tostring(v) or nil
    end
    if rule.mode == "onein" then
        local lo, hi = c(rule.oneIn), c(rule.oneInMax)
        if lo and hi then
            return "1-in " .. lo .. "-" .. hi
        end
        if lo then
            return "1-in >= " .. lo
        end
        if hi then
            return "1-in <= " .. hi
        end
        return "1-in -"
    end
    local lo, hi = c(rule.target), c(rule.earnMax)
    if lo and hi then
        return "Earn " .. lo .. "-" .. hi
    end
    if lo then
        return "Earn >= " .. lo
    end
    if hi then
        return "Earn <= " .. hi
    end
    return "Earn any"
end

function Rules.format(rule, index, Earn)
    local parts = {}
    local function add(text, style)
        if text == nil or text == "" then
            return
        end
        if #parts > 0 then
            parts[#parts + 1] = { text = " · ", style = "sep" }
        end
        parts[#parts + 1] = { text = text, style = style }
    end
    add("R" .. tostring(index), "rarity")
    local unitN = #mapKeys(rule.units)
    add(unitN == 0 and "All units" or (tostring(unitN) .. (unitN == 1 and " unit" or " units")), "default")
    add(Rules.filterText(rule, Earn), "kg")
    add(preview(rule.grades, nil), "rarity")
    add(preview(rule.traits, nil), "kg")
    add(preview(rule.quirks, nil), "fruit")
    add("Lv " .. tostring(rule.maxLevel), "default")
    add("Max " .. tostring(rule.maxUnits or DEFAULT_MAX_UNITS), "default")
    local skip = preview(rule.skipQuirks, nil)
    if skip then
        add("skip " .. skip, "error")
    end
    return {
        id = rule.id,
        enabled = rule.enabled ~= false,
        parts = parts,
    }
end

return Rules
 end, required = true },
    { key = "Collect", name = "Collect", factory = function() -- AUTO → Main.
-- Roll: nyalakan flag game, tidak menembak RollDice sendiri.
-- Fast roll: skip animasi roll, destroy clone/cutscene, RollDice 0.1s.
-- Dice: satu pembelian dice luck tertinggi yang mampu dibeli.

return function(Core)
    local G = Core.env()
    local old = G.AnimeDiceCollect
    if type(old) == "table" and type(old.setEnabled) == "function" then
        pcall(old.setEnabled, false)
    end
    local oldEquip = G.AnimeDiceEquipBest
    if type(oldEquip) == "table" and type(oldEquip.setEnabled) == "function" then
        pcall(oldEquip.setEnabled, false)
    end
    local oldRoll = G.AnimeDiceAutoRoll
    if type(oldRoll) == "table" and type(oldRoll.setEnabled) == "function" then
        pcall(oldRoll.setEnabled, false)
    end
    local oldDice = G.AnimeDiceBuyDice
    if type(oldDice) == "table" and type(oldDice.setEnabled) == "function" then
        pcall(oldDice.setEnabled, false)
    end
    local oldFast = G.AnimeDiceFastRoll
    if type(oldFast) == "table" and type(oldFast.setEnabled) == "function" then
        pcall(oldFast.setEnabled, false)
    end

    local function diceCatalog()
        local RS = game:GetService("ReplicatedStorage")
        local DiceMod = require(RS.Framework.Features.Rolling.Dice)
        local Data = Core.data()
        local money = tonumber(Data.Money()) or 0
        local current = Data.Dice()
        local currentInfo = type(current) == "string" and DiceMod.Get(current) or nil
        local currentLuck = tonumber(currentInfo and currentInfo.luck) or 0
        local buyName, buyLuck = nil, -1
        local ownName, ownLuck = nil, -1

        local function isOwned(name, info)
            if name == current or info.price == nil then
                return true
            end
            local ok, owned = pcall(function()
                return Data.OwnedDice[name]()
            end)
            return ok and owned == true
        end

        for name, info in pairs(DiceMod.GetAll()) do
            if type(info) == "table" then
                local luck = tonumber(info.luck) or 0
                if isOwned(name, info) and luck > ownLuck then
                    ownLuck = luck
                    ownName = name
                end
                local price = tonumber(info.price)
                if price and (not isOwned(name, info)) and money >= price and luck > buyLuck then
                    buyLuck = luck
                    buyName = name
                end
            end
        end

        return buyName, buyLuck, ownName, ownLuck, currentLuck
    end

    local Roll = {}
    local Fast
    local rollWanted = false
    local fastWanted = false

    local function setGameAutoRoll(on)
        local re = Core.remote("RollService", "SetAutoRoll")
        if re then
            re:FireServer(on == true)
        end
    end

    function Roll.once()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return false
            end
        end
        if not rollWanted or fastWanted then
            return false
        end
        local Data = Core.data()
        if Data.AutoRoll() == true then
            return false
        end
        setGameAutoRoll(true)
        return true
    end

    local rollLoop = Core.loop("autoroll", {
        delay = 2,
        step = Roll.once,
    })

    function Roll.setEnabled(on)
        on = on == true
        rollWanted = on
        rollLoop.setEnabled(on and not fastWanted)
        if not on then
            setGameAutoRoll(false)
            if fastWanted then
                Fast.setEnabled(false)
                pcall(function()
                    local ui = G.AnimeDiceUI or G.NodeNeonUI
                    if ui and type(ui.SetValues) == "function" then
                        ui:SetValues({ ["auto.fastroll"] = false }, true)
                    end
                end)
            end
        end
    end

    function Roll.enabled()
        return rollWanted == true
    end

    G.AnimeDiceAutoRoll = Roll

    Fast = {}
    local fastGen = 0
    local hideConns = {}
    local rollFn = nil
    local rollingFrame = nil
    local rollingDark = nil
    local rollTemplate = nil

    local function resolveRolling()
        if rollingFrame and rollingFrame.Parent then
            return true
        end
        local ok, UI = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.UI.UIReferences)
        end)
        if not ok or type(UI) ~= "table" or type(UI.Root) ~= "table" then
            return false
        end
        local Rolling = UI.Root.Rolling
        if typeof(Rolling) ~= "Instance" then
            return false
        end
        rollingFrame = Rolling:FindFirstChild("Frame")
        rollingDark = Rolling:FindFirstChild("DarkBackground")
        rollTemplate = rollingFrame and rollingFrame:FindFirstChild("RollTemplate")
        return rollingFrame ~= nil
    end

    local function addConn(conn)
        if conn then
            hideConns[#hideConns + 1] = conn
        end
    end

    local function lockHidden(obj)
        if not (obj and obj:IsA("GuiObject")) then
            return
        end
        obj.Visible = false
        addConn(obj:GetPropertyChangedSignal("Visible"):Connect(function()
            if fastWanted and obj.Visible then
                obj.Visible = false
            end
        end))
    end

    local function lockScale(obj)
        if not obj then
            return
        end
        local scale = obj:FindFirstChildOfClass("UIScale")
        if not scale then
            return
        end
        scale.Scale = 0
        addConn(scale:GetPropertyChangedSignal("Scale"):Connect(function()
            if fastWanted and scale.Scale ~= 0 then
                scale.Scale = 0
            end
        end))
    end

    local function destroyFade(inst)
        if inst and inst.Name == "CutsceneBlackFade" then
            pcall(function()
                inst:Destroy()
            end)
        end
    end

    local function destroyClone(inst)
        if inst and inst.Name == "RollTemplate" and inst ~= rollTemplate then
            pcall(function()
                inst:Destroy()
            end)
        end
    end

    local function startHide()
        if not resolveRolling() then
            return
        end
        lockHidden(rollingFrame)
        lockHidden(rollingDark)
        lockScale(rollingFrame)
        if rollingFrame then
            for _, child in ipairs(rollingFrame:GetChildren()) do
                destroyClone(child)
            end
            addConn(rollingFrame.ChildAdded:Connect(destroyClone))
        end

        local UI
        pcall(function()
            UI = require(game:GetService("ReplicatedStorage").Framework.Features.UI.UIReferences)
        end)
        local cutscene = UI and UI.Root and UI.Root.Cutscene
        if typeof(cutscene) == "Instance" then
            lockHidden(cutscene:FindFirstChild("BlackBarTop"))
            lockHidden(cutscene:FindFirstChild("BlackBarBottom"))
            local chance = cutscene:FindFirstChild("Chance")
            lockHidden(chance)
            lockScale(chance)
        end

        local playerGui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
        if playerGui then
            for _, child in ipairs(playerGui:GetChildren()) do
                destroyFade(child)
            end
            addConn(playerGui.ChildAdded:Connect(destroyFade))
        end
    end

    local function stopHide()
        for i = 1, #hideConns do
            pcall(function()
                hideConns[i]:Disconnect()
            end)
            hideConns[i] = nil
        end
        hideConns = {}
        pcall(function()
            game:GetService("RunService"):UnbindFromRenderStep("AnimeDiceHideRoll")
        end)
    end

    local function sweepRollClones()
        if not rollingFrame or not rollingFrame.Parent then
            return
        end
        for _, child in ipairs(rollingFrame:GetChildren()) do
            destroyClone(child)
        end
    end

    local function rollRemote()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return
            end
        end
        if fastWanted ~= true then
            return
        end
        local current = G.AnimeDiceFastRoll
        if current ~= Fast or type(current.enabled) ~= "function" or current.enabled() ~= true then
            return
        end
        if type(rollFn) ~= "function" then
            local ok, fn = pcall(function()
                local RS = game:GetService("ReplicatedStorage")
                return require(RS.Packages.Network).ClientComm.new(RS.Network, false, "RollService"):GetFunction("RollDice")
            end)
            if ok and type(fn) == "function" then
                rollFn = fn
            end
        end
        if type(rollFn) ~= "function" then
            return
        end
        local ok, result = pcall(rollFn)
        if ok and result ~= nil then
            Core.env().AnimeDiceLastRollAt = os.clock()
            return true
        end
        return false
    end

    function Fast.setEnabled(on)
        on = on == true
        fastWanted = on
        fastGen = fastGen + 1
        stopHide()
        if not on then
            if rollWanted then
                setGameAutoRoll(true)
            end
            rollLoop.setEnabled(rollWanted)
            return
        end
        setGameAutoRoll(false)
        rollLoop.setEnabled(false)
        startHide()
        local gen = fastGen
        -- Tunggu Roll Duration - 0.10s, lalu spam sampai hit. Hemat remote, RPM sama.
        task.spawn(function()
            local lastOffAt = 0
            local lastDebrisAt = 0
            local lastDurAt = 0
            local dur = 0.8
            while gen == fastGen and fastWanted do
                local current = G.AnimeDiceFastRoll
                if current ~= Fast or type(current.enabled) ~= "function" or current.enabled() ~= true then
                    break
                end
                local now = os.clock()
                if now - lastOffAt > 2 then
                    setGameAutoRoll(false)
                    lastOffAt = now
                end
                if now - lastDurAt > 2 then
                    lastDurAt = now
                    pcall(function()
                        local BC = require(game:GetService("ReplicatedStorage").Framework.Features.Buffs.BuffController)
                        local v = BC.GetBuff("Roll Duration")
                        if type(v) == "number" and v > 0.05 then
                            dur = v
                        end
                    end)
                end
                if now - lastDebrisAt > 0.25 then
                    lastDebrisAt = now
                    local folder = workspace:FindFirstChild("Debris")
                    if folder then
                        local kids = folder:GetChildren()
                        for i = 1, #kids do
                            pcall(function()
                                kids[i]:Destroy()
                            end)
                        end
                    end
                end
                local hit = rollRemote()
                sweepRollClones()
                if gen ~= fastGen or not fastWanted then
                    break
                end
                if hit then
                    local wake = os.clock() + math.max(0.05, dur - 0.10)
                    while os.clock() < wake and gen == fastGen and fastWanted do
                        task.wait()
                    end
                else
                    task.wait()
                end
            end
        end)
    end

    function Fast.enabled()
        return fastWanted == true
    end

    local function skipRollFx()
        local F = G.AnimeDiceFastRoll
        if type(F) == "table" and type(F.enabled) == "function" then
            local ok, on = pcall(F.enabled)
            if ok and on == true then
                return true
            end
        end
        local P = G.AnimeDicePerf
        if type(P) == "table" then
            if type(P.vfx) == "function" then
                local ok, on = pcall(P.vfx)
                if ok and on == true then
                    return true
                end
            end
            if type(P.boost) == "function" then
                local ok, on = pcall(P.boost)
                if ok and on == true then
                    return true
                end
            end
        end
        return false
    end

    G.AnimeDiceFastRoll = Fast
    if G.AnimeDiceFastRollHook ~= true and type(hookfunction) == "function" then
        pcall(function()
            local cutscene = require(game:GetService("ReplicatedStorage").Framework.Features.Rolling.RollCutscene)
            if type(cutscene) ~= "function" then
                return
            end
            local original
            original = hookfunction(cutscene, function(...)
                if skipRollFx() then
                    return
                end
                return original(...)
            end)
            G.AnimeDiceFastRollHook = true
        end)
    end
    if G.AnimeDiceVisualRollHook ~= true and type(hookfunction) == "function" and type(getgc) == "function" then
        task.spawn(function()
            if G.AnimeDiceVisualRollHook == true then
                return
            end
            pcall(function()
                require(game:GetService("ReplicatedStorage").Framework.Features.Rolling.RollController)
            end)
            local found
            pcall(function()
                local isl = islclosure or is_l_closure
                local list = getgc(false)
                for i = 1, #list do
                    local fn = list[i]
                    if type(fn) == "function" and (not isl or isl(fn)) then
                        local ok, consts = pcall(debug.getconstants, fn)
                        if ok and type(consts) == "table" then
                            local hasDuration, hasShower
                            for _, c in pairs(consts) do
                                if c == "Roll Duration" then
                                    hasDuration = true
                                elseif c == "PlayShower" then
                                    hasShower = true
                                end
                            end
                            if hasDuration and hasShower then
                                found = fn
                                break
                            end
                        end
                    end
                end
            end)
            if type(found) ~= "function" then
                return
            end
            pcall(function()
                local original
                original = hookfunction(found, function(...)
                    local current = G.AnimeDiceFastRoll
                    if type(current) == "table" and type(current.enabled) == "function" and current.enabled() then
                        return
                    end
                    return original(...)
                end)
                G.AnimeDiceVisualRollHook = true
            end)
        end)
    end
    if G.AnimeDiceShowerHook ~= true and type(hookfunction) == "function" then
        pcall(function()
            local spin = require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.Kinds.Spin.SpinController)
            if type(spin) ~= "table" or type(spin.PlayShower) ~= "function" then
                return
            end
            local original
            original = hookfunction(spin.PlayShower, function(...)
                if skipRollFx() then
                    return
                end
                return original(...)
            end)
            G.AnimeDiceShowerHook = true
        end)
    end
    if G.AnimeDiceDropHook ~= true and type(hookfunction) == "function" then
        pcall(function()
            local drop = require(game:GetService("ReplicatedStorage").Framework.Features.Notifications.EntryDropController)
            if type(drop) ~= "table" or type(drop.Play) ~= "function" then
                return
            end
            local original
            original = hookfunction(drop.Play, function(...)
                if skipRollFx() then
                    return
                end
                return original(...)
            end)
            G.AnimeDiceDropHook = true
        end)
    end
    if type(G.AnimeDice) == "table" and type(G.AnimeDice.loops) == "table" then
        G.AnimeDice.loops.fastroll = {
            stop = function()
                Fast.setEnabled(false)
            end,
        }
    end

    local DiceBuy = {}

    function DiceBuy.once()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return
            end
        end
        local buyName, buyLuck, ownName, ownLuck, currentLuck = diceCatalog()
        if buyName and buyLuck > currentLuck and buyLuck >= ownLuck then
            local re = Core.remote("DiceShopService", "BuyDice")
            if re then
                re:FireServer(buyName)
                return buyName
            end
        elseif ownName and ownLuck > currentLuck then
            local re = Core.remote("DiceShopService", "EquipDice")
            if re then
                re:FireServer(ownName)
                return ownName
            end
        end
        return nil
    end

    local diceLoop = Core.loop("buydice", {
        delay = 2,
        step = DiceBuy.once,
    })

    DiceBuy.setEnabled = diceLoop.setEnabled
    G.AnimeDiceBuyDice = DiceBuy

    local Collect = {}

    function Collect.once()
        local re = Core.remote("PlotService", "CollectBalance")
        if not re then
            return 0
        end
        local slots = Core.slots()
        for _, slot in ipairs(slots) do
            re:FireServer(slot)
        end
        return #slots
    end

    local collectLoop = Core.loop("collect", {
        delay = 5,
        step = Collect.once,
    })

    Collect.setEnabled = collectLoop.setEnabled
    G.AnimeDiceCollect = Collect

    local Equip = {}
    local equipBusy = false
    local equipLoop
    local equipMode = "lv1"
    local rankedCache = {}
    local rankedAt = 0
    local rankedN = -1
    local EQUIP_CACHE_SEC = 8
    local EQUIP_MODES = {
        { key = "lv1", name = "Earn at lvl 1" },
        { key = "total", name = "Earn total lvl" },
    }
    local priorityUnits = {}

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true then
                out[tostring(k)] = true
            elseif type(k) == "number" and type(v) == "string" then
                out[v] = true
            end
        end
        return out
    end

    local function invalidateEquipRank()
        rankedCache = {}
        rankedAt = 0
        rankedN = -1
    end

    local function clampEquipMode(v)
        v = tostring(v or "")
        if v == "total" or v == "lv1" then
            return v
        end
        return "lv1"
    end

    local function dropdownValue(a, b)
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function unitIncome(item, full)
        if type(item) ~= "table" then
            return 0
        end
        local name = readVal(item.name)
        if type(name) ~= "string" or name == "" then
            return 0
        end
        local ok, cfg = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
        end)
        if not ok or type(cfg) ~= "table" or cfg.kind ~= "Unit" or type(cfg.income) ~= "function" then
            return 0
        end
        local attrs = readVal(item.attributes)
        if type(attrs) ~= "table" then
            attrs = item
        end
        local mutation = readVal(attrs.mutation)
        if type(mutation) ~= "string" or mutation == "" then
            mutation = nil
        end
        -- lv1 = unit polos: mutation saja, tanpa trait/grade/level.
        local opts = {
            mutation = mutation,
            level = 1,
        }
        if full or equipMode == "total" then
            opts.trait = readVal(attrs.trait)
            opts.grade = readVal(attrs.grade)
            opts.level = tonumber(readVal(attrs.level)) or 1
        end
        local okInc, value = pcall(cfg.income, opts)
        return okInc and tonumber(value) or 0
    end

    local function unitQuirk(item)
        if type(item) ~= "table" then
            return nil
        end
        local attrs = readVal(item.attributes)
        if type(attrs) ~= "table" then
            attrs = item
        end
        local q = readVal(attrs.quirk)
        if type(q) == "string" and q ~= "" and q ~= "None" then
            return q
        end
        return nil
    end

    local function unitChance(item)
        local name = readVal(item.name)
        local ok, cfg = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
        end)
        if not ok or type(cfg) ~= "table" or cfg.kind ~= "Unit" then
            return 0
        end
        local attrs = readVal(item.attributes)
        if type(attrs) ~= "table" then
            attrs = item
        end
        local opts = { mutation = readVal(attrs.mutation) }
        if type(cfg.chance) == "function" then
            local okC, v = pcall(cfg.chance, opts)
            return okC and tonumber(v) or 0
        end
        local okI, inc = pcall(cfg.income, opts)
        return okI and tonumber(inc) and tonumber(inc) ^ 1.3793103448275863 or 0
    end

    local unitItemsCache, unitItemsAt = nil, 0
    local function unitItems()
        if unitItemsCache and os.clock() - unitItemsAt < 5 then
            return unitItemsCache
        end
        local out = {}
        local data = Core.data()
        local okInv, inv = pcall(function()
            return data.Inventory()
        end)
        if not okInv or type(inv) ~= "table" then
            return out
        end
        for id, item in pairs(inv) do
            if type(id) == "string" and type(item) == "table" then
                local earn = unitIncome(item, true)
                if earn > 0 then
                    local quirk = unitQuirk(item)
                    out[#out + 1] = {
                        key = id,
                        label = string.format(
                            "1-in %s · %s/s · %s",
                            Core.compact(unitChance(item)),
                            Core.compact(earn),
                            quirk or "no quirk"
                        ),
                        earn = earn,
                    }
                end
            end
        end
        table.sort(out, function(a, b)
            if a.earn ~= b.earn then
                return a.earn > b.earn
            end
            return a.key < b.key
        end)
        unitItemsCache, unitItemsAt = out, os.clock()
        return out
    end

    local function slotUnitId(data, slot)
        local getter = data.Slots and data.Slots[tostring(slot)]
        if getter == nil then
            return nil
        end
        local ok, row = pcall(getter)
        if not ok or type(row) ~= "table" then
            return nil
        end
        local id = readVal(row.unitId)
        if type(id) == "string" and id ~= "" then
            return id
        end
        return nil
    end

    local function waitUntil(pred, timeout)
        local untilAt = os.clock() + (tonumber(timeout) or 1.2)
        while os.clock() < untilAt do
            if pred() then
                return true
            end
            task.wait(0.08)
        end
        return pred()
    end

    local function findSlotOf(data, slots, id)
        for _, slot in ipairs(slots) do
            if slotUnitId(data, slot) == id then
                return slot
            end
        end
        return nil
    end

    local function holdingId()
        local ok, uc = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.Kinds.Unit.UnitController)
        end)
        if not ok or type(uc) ~= "table" then
            return nil
        end
        local eq = uc.EquippedUnit
        if type(eq) == "function" then
            local id = eq()
            if type(id) == "string" and id ~= "" then
                return id
            end
        end
        return nil
    end

    local function plotNet()
        local RS = game:GetService("ReplicatedStorage")
        local Net = require(RS.Packages.Network)
        local unit = Net.ClientComm.new(RS.Network, false, "UnitService")
        local plot = Net.ClientComm.new(RS.Network, false, "PlotService")
        return unit:GetFunction("Equip"), unit:GetFunction("Unequip"), plot:GetSignal("InteractSlot")
    end

    function Equip.once()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return false
            end
        end
        local au = G.AnimeDiceAutoUnit
        local blocked = type(au) == "table" and au.blockEquipBest == true
        local reserved = {}
        if type(au) == "table" and type(au.reservedIds) == "function" then
            local okBag, bag = pcall(au.reservedIds)
            if okBag and type(bag) == "table" then
                reserved = bag
            end
        end
        if equipMode == "total" and not blocked and next(priorityUnits) == nil then
            local re = Core.remote("PlotService", "EquipBest")
            if not re then
                return false
            end
            re:FireServer()
            return true
        end
        if equipBusy then
            return false
        end
        local Data = Core.data()
        if not Data then
            return false
        end
        local slots = Core.slots()
        if type(slots) ~= "table" or #slots == 0 then
            return false
        end
        local inv = Data.Inventory()
        if type(inv) ~= "table" then
            return false
        end
        local n = 0
        for _ in pairs(inv) do
            n = n + 1
        end
        local ranked = rankedCache
        if rankedN ~= n or (os.clock() - rankedAt) >= EQUIP_CACHE_SEC or type(ranked) ~= "table" or #ranked == 0 then
            ranked = {}
            for key, row in pairs(inv) do
                if type(key) == "string" and type(row) == "table" then
                    ranked[#ranked + 1] = {
                        key = key,
                        income = unitIncome(row),
                    }
                end
            end
            table.sort(ranked, function(a, b)
                if a.income == b.income then
                    return a.key < b.key
                end
                return a.income > b.income
            end)
            rankedCache = ranked
            rankedAt = os.clock()
            rankedN = n
        end
        local pool = {}
        local rest = {}
        for _, row in ipairs(ranked) do
            if row.income > 0 and reserved[row.key] ~= true then
                if priorityUnits[row.key] then
                    pool[#pool + 1] = row
                else
                    rest[#rest + 1] = row
                end
            end
        end
        for _, row in ipairs(rest) do
            pool[#pool + 1] = row
        end
        local want = {}
        local used = {}
        if blocked then
            for i, slot in ipairs(slots) do
                local id = slotUnitId(Data, slot)
                if id and reserved[id] then
                    want[i] = id
                    used[id] = true
                end
            end
            local ri = 1
            for i in ipairs(slots) do
                if not want[i] then
                    while ri <= #pool do
                        local key = pool[ri].key
                        ri = ri + 1
                        if not used[key] then
                            want[i] = key
                            used[key] = true
                            break
                        end
                    end
                end
            end
        else
            local take = math.min(#pool, #slots)
            for i = 1, take do
                want[i] = pool[i].key
            end
        end
        local ordered = true
        for i, slot in ipairs(slots) do
            local id = slotUnitId(Data, slot)
            if want[i] then
                if id ~= want[i] then
                    ordered = false
                    break
                end
            elseif id then
                ordered = false
                break
            end
        end
        if ordered then
            return true
        end
        local okNet, equipFn, unequipFn, interact = pcall(plotNet)
        if not okNet or equipFn == nil or unequipFn == nil or interact == nil then
            return false
        end

        local function clearHand()
            if holdingId() then
                unequipFn()
                task.wait(0.55)
            end
        end

        local function placeOn(slot, id)
            if slotUnitId(Data, slot) == id then
                return true
            end
            local from = findSlotOf(Data, slots, id)
            if from == slot then
                return true
            end
            if from then
                clearHand()
                interact:Fire(from)
                waitUntil(function()
                    return slotUnitId(Data, from) == nil
                end, 1.2)
                task.wait(0.55)
                interact:Fire(slot)
            else
                clearHand()
                equipFn(id)
                waitUntil(function()
                    return holdingId() == id
                end, 1.2)
                interact:Fire(slot)
            end
            local ok = waitUntil(function()
                return slotUnitId(Data, slot) == id
            end, 1.2)
            task.wait(0.55)
            return ok
        end

        equipBusy = true
        local ok = pcall(function()
            for i, slot in ipairs(slots) do
                if not equipLoop.enabled() then
                    return
                end
                local id = want[i]
                if not id then
                    continue
                end
                if slotUnitId(Data, slot) ~= id then
                    placeOn(slot, id)
                end
            end
            clearHand()
        end)
        equipBusy = false
        return ok
    end

    equipLoop = Core.loop("equipbest", {
        delay = 5,
        step = Equip.once,
    })

    Equip.setEnabled = equipLoop.setEnabled
    function Equip.isPriority(id)
        return type(id) == "string" and priorityUnits[id] == true
    end
    G.AnimeDiceEquipBest = Equip

    local REBIRTH_CAP = 14
    local maxRebirth = 0

    local function clampRebirthMax(n)
        n = tonumber(n) or 0
        if n < 0 then
            n = 0
        elseif n > REBIRTH_CAP then
            n = REBIRTH_CAP
        end
        return math.floor(n + 0.5)
    end

    local function tryRebirth()
        local Data = Core.data()
        local current, money = 0, 0
        local okRead = pcall(function()
            current = tonumber(Data.Rebirth()) or 0
            money = tonumber(Data.Money()) or 0
        end)
        if not okRead then
            return
        end
        if maxRebirth > 0 and current >= maxRebirth then
            return
        end
        local okNext, nxt = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Rebirth.Rebirths).GetNext(current)
        end)
        if not okNext or type(nxt) ~= "table" then
            return
        end
        if money < (tonumber(nxt.cost) or 0) then
            return
        end
        local re = Core.remote("RebirthService", "Rebirth")
        if re then
            re:FireServer()
        end
    end

    local rebirthLoop = Core.loop("rebirth", {
        delay = 1,
        step = tryRebirth,
    })

    local farmHeader
    local function farmOn()
        return rollWanted == true
            or fastWanted == true
            or diceLoop.enabled()
            or collectLoop.enabled()
            or equipLoop.enabled()
            or rebirthLoop.enabled()
    end

    local function paintFarmHeader()
        local current = 0
        pcall(function()
            current = tonumber(Core.data().Rebirth()) or 0
        end)
        local detail = "R" .. tostring(math.floor(current))
        local okNext, nxt = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Rebirth.Rebirths).GetNext(current)
        end)
        if okNext and type(nxt) == "table" and tonumber(nxt.cost) then
            detail = detail .. " · next " .. Core.compact(nxt.cost)
        else
            detail = detail .. " · max"
        end
        if farmOn() then
            Core.paintHeader(farmHeader, "On", "success", detail)
        else
            Core.paintHeader(farmHeader, "Off", "muted", detail)
        end
    end

    local farmStatusLoop = Core.loop("farm_header", {
        delay = 5,
        step = function()
            if Core.uiIs("auto", "main") then
                paintFarmHeader()
            end
        end,
    })
    farmStatusLoop.setEnabled(true)

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 1,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Farm",
                expanded = false,
                status = {
                    id = "auto.farm.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "Rebirth · next cost",
                },
            })
            farmHeader = api
            paintFarmHeader()
            local group = ui:CreateGroup(body)
            Core.bindToggle(ui, group, {
                id = "auto.roll",
                label = "Auto Roll",
                initial = rollWanted == true,
                onChanged = function(on)
                    Roll.setEnabled(on == true)
                    paintFarmHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.fastroll",
                label = "Auto Hide Animation & Fast Roll",
                initial = fastWanted == true,
                onChanged = function(on)
                    Fast.setEnabled(on == true)
                    paintFarmHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.buydice",
                label = "Auto Buy Best Dice & Equip",
                initial = diceLoop.enabled(),
                onChanged = function(on)
                    diceLoop.setEnabled(on == true)
                    paintFarmHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.collect",
                label = "Auto Collect (2s)",
                initial = collectLoop.enabled(),
                onChanged = function(on)
                    collectLoop.setEnabled(on == true)
                    paintFarmHeader()
                end,
            })
            ui:CreateRowDropdown(group, {
                id = "auto.equipbest.mode",
                label = "Equip Mode",
                placeholder = "Mode",
                clearable = false,
                persist = true,
                preserveItemOrder = true,
                initial = equipMode,
                getItems = function()
                    return EQUIP_MODES
                end,
                hintText = "Lvl 1 = plain unit (mutation only). Total = current earn with trait / grade / level.",
                onChanged = function(a, b)
                    local nextMode = clampEquipMode(dropdownValue(a, b))
                    if nextMode ~= equipMode then
                        invalidateEquipRank()
                    end
                    equipMode = nextMode
                end,
            })
            local priorityApi
            local function paintPriorityLabel()
                if priorityApi then
                    local n = 0
                    for _ in pairs(priorityUnits) do
                        n = n + 1
                    end
                    pcall(priorityApi.setLabel, n > 0 and ("Priority Units (" .. n .. ")") or "Priority Units")
                end
            end
            local _
            _, priorityApi = ui:CreateRowDropdown(group, {
                id = "auto.equipbest.units",
                label = "Priority Units",
                mode = "multi",
                placeholder = "None",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = unitItems,
                hintText = "Picked units go on the plot first (highest earn/s), then the rest fill by Equip Mode. Label: 1-in · earn/s · quirk.",
                onChanged = function(a, b)
                    priorityUnits = copyMap(type(a) == "table" and a or b)
                    invalidateEquipRank()
                    paintPriorityLabel()
                end,
            })
            paintPriorityLabel()
            Core.bindToggle(ui, group, {
                id = "auto.equipbest",
                label = "Auto Equip Best Unit",
                initial = equipLoop.enabled(),
                onChanged = function(on)
                    equipLoop.setEnabled(on == true)
                    paintFarmHeader()
                end,
            })
            ui:CreateRowInput(group, {
                id = "auto.rebirthMax",
                label = "Max rebirth",
                initial = tostring(maxRebirth),
                onChanged = function(text)
                    maxRebirth = clampRebirthMax(text)
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.rebirth",
                label = "Auto Rebirth",
                initial = rebirthLoop.enabled(),
                onChanged = function(on)
                    rebirthLoop.setEnabled(on == true)
                    paintFarmHeader()
                end,
            })
        end,
    })

    Core.onSync(function(values)
        Roll.setEnabled(values["auto.roll"] == true)
        Fast.setEnabled(values["auto.fastroll"] == true)
        diceLoop.setEnabled(values["auto.buydice"] == true)
        collectLoop.setEnabled(values["auto.collect"] == true)
        equipLoop.setEnabled(values["auto.equipbest"] == true)
        local nextMode = clampEquipMode(values["auto.equipbest.mode"])
        if nextMode ~= equipMode then
            invalidateEquipRank()
        end
        equipMode = nextMode
        if values["auto.equipbest.units"] ~= nil then
            priorityUnits = copyMap(values["auto.equipbest.units"])
        end
        local n = tonumber(values["auto.rebirthMax"])
        if n ~= nil then
            maxRebirth = clampRebirthMax(n)
        end
        rebirthLoop.setEnabled(values["auto.rebirth"] == true)
        paintFarmHeader()
    end)
end
 end, required = true, feature = true },
    { key = "FastTower", name = "Fast Tower", factory = function() -- AUTO → Auto Tower.
-- Multi-select towers, rotate after win or lose. Equip best team before each run.
-- Fast Tower skips fight playback but waits the server floor cooldown (or the game cancels).

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local TS = game:GetService("TweenService")
    local oldFast = G.AnimeDiceFastTower
    if type(oldFast) == "table" and type(oldFast.setEnabled) == "function" then
        pcall(oldFast.setEnabled, false)
    end
    local oldAuto = G.AnimeDiceAutoTower
    if type(oldAuto) == "table" and type(oldAuto.setEnabled) == "function" then
        pcall(oldAuto.setEnabled, false)
    end

    local fastOn = false
    local autoOn = false
    local selected = {}
    local towerIndex = 1
    local wasIn = false
    local running = false
    local lastStartAt = 0
    local pendingEquip = false
    local equipAt = 0
    local pendingName = nil
    local runFloor = nil
    local towerRoot
    local floorLabel
    local hiddenFrame
    local hiddenLabel
    local headerApi
    local completeRf
    local towerComm
    local realStart
    local resolveStart
    local setTowerHiddenFn
    local towerStartedFn
    local floorWaitInitial = 0.76
    local floorWaitTransition = 0.38
    local actionWait = {
        damagePlayer = 0.62,
        damageEnemy = 0.62,
        floorCompleted = 0.24,
        memberDefeated = 0.32,
        ended = 0,
    }

    pcall(function()
        local refs = require(RS.Framework.Features.Towers.TowerRefs)
        if type(refs) == "table" then
            if type(refs.FloorStartedWaitTime) == "table" then
                floorWaitInitial = tonumber(refs.FloorStartedWaitTime.initial) or floorWaitInitial
                floorWaitTransition = tonumber(refs.FloorStartedWaitTime.transition) or floorWaitTransition
            end
            if type(refs.ActionWaitTime) == "table" then
                actionWait.damagePlayer = tonumber(refs.ActionWaitTime.damagePlayer) or actionWait.damagePlayer
                actionWait.damageEnemy = tonumber(refs.ActionWaitTime.damageEnemy) or actionWait.damageEnemy
                actionWait.floorCompleted = tonumber(refs.ActionWaitTime.floorCompleted) or actionWait.floorCompleted
                actionWait.memberDefeated = tonumber(refs.ActionWaitTime.memberDefeated) or actionWait.memberDefeated
                actionWait.ended = tonumber(refs.ActionWaitTime.ended) or 0
            end
        end
    end)

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if type(a) == "table" then
            return a
        end
        if type(b) == "table" then
            return b
        end
        return a
    end

    local function cacheTowerGui()
        pcall(function()
            local root = require(RS.Framework.Features.UI.UIReferences).Root.Tower
            towerRoot = root
            local screen = root:FindFirstChild("Screen")
            floorLabel = screen and screen:FindFirstChild("Floor")
            hiddenFrame = root:FindFirstChild("Hidden")
            hiddenLabel = hiddenFrame and hiddenFrame:FindFirstChild("Label")
            completeRf = RS.Network.Towers.RF.CompleteTowerFloor
        end)
        return towerRoot
    end

    local function getTowerRoot()
        if towerRoot and towerRoot.Parent then
            return towerRoot
        end
        return cacheTowerGui()
    end

    local function isCompleteRemote(inst)
        if typeof(inst) ~= "Instance" or inst.ClassName ~= "RemoteFunction" then
            return false
        end
        if inst.Name ~= "CompleteTowerFloor" then
            return false
        end
        local rf = completeRf
        if not (rf and rf.Parent) then
            pcall(function()
                completeRf = RS.Network.Towers.RF.CompleteTowerFloor
                rf = completeRf
            end)
        end
        return inst == rf
    end

    local function getComm()
        if towerComm then
            return towerComm
        end
        pcall(function()
            towerComm = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "Towers")
        end)
        return towerComm
    end

    local function towerMod()
        local mod
        pcall(function()
            mod = require(RS.Framework.Features.Towers.Towers)
        end)
        return mod
    end

    local function towerItems()
        local mod = towerMod()
        local all = mod and type(mod.GetAll) == "function" and mod.GetAll()
        local list = {}
        if type(all) ~= "table" then
            return list
        end
        for name, cfg in pairs(all) do
            if type(name) == "string" then
                list[#list + 1] = {
                    key = name,
                    name = name,
                    order = type(cfg) == "table" and tonumber(cfg.order) or 99,
                }
            end
        end
        table.sort(list, function(a, b)
            if a.order == b.order then
                return a.name < b.name
            end
            return a.order < b.order
        end)
        return list
    end

    local function selectedList()
        local items = towerItems()
        local out = {}
        for _, item in ipairs(items) do
            if selected[item.key] then
                out[#out + 1] = item.key
            end
        end
        return out
    end

    local function isTowerInst(inst)
        local root = getTowerRoot()
        if not root or typeof(inst) ~= "Instance" then
            return false
        end
        return inst == root or inst:IsDescendantOf(root)
    end

    local function inTower()
        local root = getTowerRoot()
        if not root then
            return false
        end
        local screen = root:FindFirstChild("Screen")
        local hidden = root:FindFirstChild("Hidden")
        return (screen and screen.Visible == true) or (hidden and hidden.Visible == true)
    end

    local function isFast()
        local current = G.AnimeDiceFastTower
        return type(current) == "table" and type(current.enabled) == "function" and current.enabled() == true
    end

    local function setFloorText(n)
        n = tonumber(n)
        if not n then
            return
        end
        local text = "Floor " .. tostring(n)
        runFloor = n
        if floorLabel and floorLabel.Parent then
            floorLabel.Text = text
        end
        if hiddenFrame and hiddenFrame.Visible and hiddenLabel and hiddenLabel.Parent then
            hiddenLabel.Text = text
        end
    end

    local function currentFloor()
        if hiddenFrame and hiddenFrame.Visible and hiddenLabel then
            local n = tostring(hiddenLabel.Text or ""):match("(%d+)")
            return n and tonumber(n) or nil
        end
        if floorLabel then
            local n = tostring(floorLabel.Text or ""):match("(%d+)")
            return n and tonumber(n) or nil
        end
        return nil
    end

    local function zeroInfo(info)
        if typeof(info) ~= "TweenInfo" then
            return info
        end
        return TweenInfo.new(0, info.EasingStyle, info.EasingDirection, info.RepeatCount, info.Reverses, 0)
    end

    local exclusiveSaved = nil
    local exclusiveFastSaved = nil

    local function hauntTurbo()
        return exclusiveSaved ~= nil
    end

    local function seqWait(seq)
        if type(seq) ~= "table" then
            return 0
        end
        local t = 0
        for i, row in ipairs(seq) do
            if type(row) == "table" then
                if row.action == "floorStarted" then
                    if i == 1 then
                        if row.floor == 1 then
                            t = t + floorWaitInitial
                        else
                            t = t + floorWaitTransition
                        end
                    else
                        local prev = seq[i - 1]
                        if type(prev) == "table" and prev.action == "memberDefeated" then
                            t = t + floorWaitTransition
                        end
                    end
                else
                    t = t + (actionWait[row.action] or 0)
                end
            end
        end
        -- Halloween exclusive: potong playback wait (server tetap debounce CompleteTowerFloor).
        if hauntTurbo() and t > 0 then
            t = math.max(0.04, t * 0.18)
        end
        return t
    end

    local function readUp(fn, i)
        local a, b
        local ok = pcall(function()
            a, b = debug.getupvalue(fn, i)
        end)
        if not ok then
            return nil
        end
        if type(a) == "string" then
            return b
        end
        return a
    end

    local function srcOf(fn)
        local ok, src = pcall(debug.info, fn, "s")
        if ok then
            return src
        end
        return nil
    end

    if G.AnimeDiceFastTowerNamecallV3 ~= true and type(hookmetamethod) == "function" then
        pcall(function()
            local old
            old = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
                local method = getnamecallmethod()
                if method == "InvokeServer" and isCompleteRemote(self) and isFast() then
                    local result = old(self, ...)
                    if type(result) == "table" and #result > 0 then
                        return result
                    end
                    local t0 = os.clock()
                    local maxT = hauntTurbo() and 1.35 or 2.5
                    local step = hauntTurbo() and 0.012 or 0.03
                    while os.clock() - t0 < maxT do
                        task.wait(step)
                        result = old(self, ...)
                        if type(result) == "table" and #result > 0 then
                            return result
                        end
                    end
                    return result
                end
                if checkcaller() then
                    return old(self, ...)
                end
                if method == "Create" and typeof(self) == "Instance" and self.ClassName == "TweenService" then
                    local inst, info, props = ...
                    if isFast() and isTowerInst(inst) then
                        info = zeroInfo(info)
                    end
                    return TS.Create(self, inst, info, props)
                end
                return old(self, ...)
            end))
            G.AnimeDiceFastTowerNamecallV3 = true
        end)
    end

    if G.AnimeDiceFastTowerCreateV2 ~= true and type(hookfunction) == "function" then
        pcall(function()
            local original
            original = hookfunction(TS.Create, newcclosure(function(self, inst, info, props)
                if isFast() and isTowerInst(inst) then
                    info = zeroInfo(info)
                end
                return original(self, inst, info, props)
            end))
            G.AnimeDiceFastTowerCreateV2 = true
        end)
    end

    local function playSeqMatch(fn)
        if type(fn) ~= "function" then
            return false
        end
        local ok, consts = pcall(debug.getconstants, fn)
        if not (ok and type(consts) == "table") then
            return false
        end
        local hasFloor, hasDamage, hasFailed, hasEnded = false, false, false, false
        for _, c in pairs(consts) do
            if c == "floorStarted" then
                hasFloor = true
            elseif c == "damageEnemy" then
                hasDamage = true
            elseif c == "Tower sequence playback failed:" then
                hasFailed = true
            elseif c == "ended" then
                hasEnded = true
            end
        end
        if hasFailed then
            return false
        end
        if hasFloor and hasDamage then
            return true
        end
        return hasEnded == true
    end

    local function findPlaySeq()
        local playSeq
        pcall(function()
            local startFn = resolveStart()
            if type(startFn) ~= "function" then
                return
            end
            local towerStarted
            for i = 1, 24 do
                local val = readUp(startFn, i)
                if type(val) == "function" then
                    local ok, consts = pcall(debug.getconstants, val)
                    if ok and type(consts) == "table" then
                        for _, c in pairs(consts) do
                            if c == "Tower sequence playback failed:" then
                                towerStarted = val
                                break
                            end
                        end
                    end
                end
                if towerStarted then
                    break
                end
            end
            if type(towerStarted) == "function" then
                for i = 1, 32 do
                    local val = readUp(towerStarted, i)
                    if playSeqMatch(val) then
                        playSeq = val
                        break
                    end
                end
            end
        end)
        if type(playSeq) == "function" then
            return playSeq
        end
        local isl = islclosure
        local okList, list = pcall(getgc, false)
        if not okList or type(list) ~= "table" then
            return nil
        end
        for _, fn in ipairs(list) do
            if type(fn) == "function" and (not isl or isl(fn)) and playSeqMatch(fn) then
                local src = srcOf(fn)
                if type(src) == "string" and src:find("TowerController", 1, true) then
                    return fn
                end
            end
        end
        return nil
    end

    if G.AnimeDiceFastTowerPlaySeqV3 ~= true and type(hookfunction) == "function" then
        task.spawn(function()
            if G.AnimeDiceFastTowerPlaySeqV3 == true then
                return
            end
            cacheTowerGui()
            local playSeq = findPlaySeq()
            if type(playSeq) ~= "function" then
                return
            end
            local original
            original = hookfunction(playSeq, newcclosure(function(seq, gen)
                if not isFast() then
                    return original(seq, gen)
                end
                local ended = false
                if type(seq) == "table" then
                    for _, row in ipairs(seq) do
                        if type(row) == "table" then
                            if row.floor then
                                setFloorText(row.floor)
                            end
                            if row.action == "ended" then
                                ended = true
                            end
                        end
                    end
                    local waitFor = seqWait(seq)
                    if waitFor > 0 then
                        task.wait(waitFor)
                    end
                else
                    ended = true
                end
                return ended
            end))
            G.AnimeDiceFastTowerPlaySeqV3 = true
        end)
    end

    if G.AnimeDiceFastTowerPlaySeqV5 ~= true and type(hookfunction) == "function" then
        task.spawn(function()
            if G.AnimeDiceFastTowerPlaySeqV5 == true then
                return
            end
            cacheTowerGui()
            local playSeq = findPlaySeq()
            if type(playSeq) ~= "function" then
                return
            end
            local original
            original = hookfunction(playSeq, newcclosure(function(seq, gen)
                if not fastOn then
                    return original(seq, gen)
                end
                local ended = false
                if type(seq) == "table" then
                    for _, row in ipairs(seq) do
                        if type(row) == "table" then
                            if row.floor then
                                setFloorText(row.floor)
                            end
                            if row.action == "ended" then
                                ended = true
                            end
                        end
                    end
                    local waitFor = seqWait(seq)
                    if waitFor > 0 then
                        task.wait(waitFor)
                    end
                else
                    ended = true
                end
                return ended
            end))
            G.AnimeDiceFastTowerPlaySeqV5 = true
        end)
    end

    local function setGameAuto(name)
        local comm = getComm()
        if type(comm) ~= "table" or type(comm.GetSignal) ~= "function" then
            return
        end
        pcall(function()
            local sig = comm:GetSignal("SetAutoTower")
            if name then
                sig:Fire(name)
            else
                sig:Fire(false)
            end
        end)
    end

    local function equipBest()
        local comm = getComm()
        if type(comm) ~= "table" or type(comm.GetSignal) ~= "function" then
            return false
        end
        local ok = pcall(function()
            comm:GetSignal("EquipBestTowerTeam"):Fire()
        end)
        return ok == true
    end

    function resolveStart()
        if type(realStart) == "function" then
            return realStart
        end
        local tc
        pcall(function()
            tc = require(RS.Framework.Features.Towers.TowerController)
        end)
        if type(tc) ~= "table" or type(tc.startTower) ~= "function" then
            return nil
        end
        local fn = tc.startTower
        for _ = 1, 5 do
            local src = srcOf(fn)
            if type(src) == "string" and src:find("TowerController", 1, true) then
                break
            end
            local inner
            for i = 1, 16 do
                local val = readUp(fn, i)
                if type(val) == "function" then
                    local src2 = srcOf(val)
                    if type(src2) == "string" and src2:find("TowerController", 1, true) then
                        inner = val
                        break
                    end
                end
            end
            if not inner then
                break
            end
            fn = inner
        end
        realStart = fn
        pcall(function()
            tc.startTower = fn
        end)
        return fn
    end

    local function cacheHideApi()
        if type(setTowerHiddenFn) == "function" and type(towerStartedFn) == "function" then
            return
        end
        pcall(function()
            local startFn = resolveStart()
            if type(startFn) == "function" and type(towerStartedFn) ~= "function" then
                for i = 1, 24 do
                    local val = readUp(startFn, i)
                    if type(val) == "function" then
                        local ok, consts = pcall(debug.getconstants, val)
                        if ok and type(consts) == "table" then
                            for _, c in pairs(consts) do
                                if c == "Tower sequence playback failed:" then
                                    towerStartedFn = val
                                    break
                                end
                            end
                        end
                    end
                    if towerStartedFn then
                        break
                    end
                end
            end
            if type(towerStartedFn) == "function" and type(setTowerHiddenFn) ~= "function" then
                for i = 1, 32 do
                    local val = readUp(towerStartedFn, i)
                    if type(val) == "function" then
                        local ok, consts = pcall(debug.getconstants, val)
                        if ok and type(consts) == "table" then
                            local hasHide, hasFloor = false, false
                            for _, c in pairs(consts) do
                                if c == "Hide" then
                                    hasHide = true
                                elseif c == "Floor " then
                                    hasFloor = true
                                end
                            end
                            if hasHide and hasFloor then
                                setTowerHiddenFn = val
                                break
                            end
                        end
                    end
                end
            end
        end)
        if type(setTowerHiddenFn) == "function" then
            return
        end
        pcall(function()
            local root = getTowerRoot()
            local hidden = root and root:FindFirstChild("Hidden")
            if not (hidden and hidden.Activated and getconnections) then
                return
            end
            for _, conn in ipairs(getconnections(hidden.Activated)) do
                local fn = conn.Function
                if type(fn) == "function" then
                    for i = 1, 8 do
                        local val = readUp(fn, i)
                        if type(val) == "function" then
                            local ok, consts = pcall(debug.getconstants, val)
                            if ok and type(consts) == "table" then
                                for _, c in pairs(consts) do
                                    if c == "Hide" then
                                        setTowerHiddenFn = val
                                        return
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)
    end

    local function hideTowerUi()
        cacheHideApi()
        local root = getTowerRoot()
        local screen = root and root:FindFirstChild("Screen")
        if not (screen and screen.Visible == true) then
            return
        end
        if type(setTowerHiddenFn) == "function" then
            pcall(setTowerHiddenFn, true)
            return
        end
        pcall(function()
            local hidden = root:FindFirstChild("Hidden")
            for _, conn in ipairs(getconnections(hidden.Activated)) do
                if conn.Fire then
                    conn:Fire()
                    break
                end
            end
        end)
    end

    local function markNextStartHidden()
        cacheHideApi()
        if type(towerStartedFn) == "function" and type(debug.setupvalue) == "function" then
            pcall(debug.setupvalue, towerStartedFn, 1, true)
        end
    end

    local function startNamed(name)
        local started = false
        pcall(function()
            local fn = resolveStart()
            if type(fn) == "function" then
                markNextStartHidden()
                started = fn(name) == true
            end
        end)
        if started then
            task.defer(hideTowerUi)
        end
        return started
    end

    local function paintHeader()
        if not headerApi then
            return
        end
        local list = selectedList()
        if not autoOn then
            Core.paintHeader(headerApi, "Off", "muted", #list == 0 and "pick towers" or (tostring(#list) .. " towers"))
            return
        end
        if #list == 0 then
            Core.paintHeader(headerApi, "Idle", "muted", "pick towers")
            return
        end
        local name = list[((towerIndex - 1) % #list) + 1]
        if inTower() or running then
            local floor = currentFloor()
            local extra = floor and (" · Floor " .. tostring(floor)) or ""
            Core.paintHeader(headerApi, "On", "success", name .. extra)
            return
        end
        if pendingEquip then
            Core.paintHeader(headerApi, "Wait", "muted", "equip best · " .. tostring(pendingName or name))
            return
        end
        Core.paintHeader(headerApi, "On", "success", "next " .. name)
    end

    local loop = Core.loop("auto_tower", {
        delay = 1,
        step = function()
            if not autoOn then
                return
            end
            paintHeader()
            local list = selectedList()
            if #list == 0 then
                return
            end
            if towerIndex > #list then
                towerIndex = 1
            end
            local nowIn = inTower()
            if nowIn then
                wasIn = true
                running = true
                pendingEquip = false
                hideTowerUi()
                return
            end
            if running then
                if os.clock() - lastStartAt < 1.6 then
                    return
                end
                running = false
                wasIn = true
            end
            if wasIn then
                wasIn = false
                towerIndex = towerIndex + 1
                if towerIndex > #list then
                    towerIndex = 1
                end
                pendingEquip = false
            end
            if os.clock() - lastStartAt < 3.2 then
                return
            end
            local name = list[towerIndex]
            if not name then
                return
            end
            if not pendingEquip then
                setGameAuto(false)
                equipBest()
                pendingEquip = true
                equipAt = os.clock()
                pendingName = name
                paintHeader()
                return
            end
            if os.clock() - equipAt < 1.05 then
                return
            end
            lastStartAt = os.clock()
            pendingEquip = false
            local started = startNamed(pendingName or name)
            if started then
                running = true
                wasIn = true
            end
            paintHeader()
        end,
    })

    local Fast = {}
    function Fast.setEnabled(on)
        fastOn = on == true
        paintHeader()
    end
    -- Old namecall V3 retries CompleteTowerFloor with task.wait inside __namecall (200-800ms spikes).
    -- Keep skip via fastOn; lie to the old hook so it never waits.
    function Fast.enabled()
        return false
    end
    function Fast.skipEnabled()
        return fastOn == true
    end

    local Auto = {}
    function Auto.setEnabled(on)
        autoOn = on == true
        if not autoOn then
            wasIn = false
            running = false
            pendingEquip = false
            setGameAuto(false)
        end
        loop.setEnabled(autoOn)
        paintHeader()
    end
    function Auto.enabled()
        return autoOn == true
    end
    function Auto.busy()
        return autoOn == true and (running == true or pendingEquip == true or inTower())
    end
    function Auto.inside()
        return inTower() == true
    end
    function Auto.progress()
        local list = selectedList()
        local idx = 1
        if #list > 0 then
            idx = ((towerIndex - 1) % #list) + 1
        end
        local tower = pendingName
        if type(tower) ~= "string" or tower == "" then
            tower = list[idx]
        end
        local floor = currentFloor() or runFloor
        if not inTower() then
            floor = nil
        end
        return {
            tower = tower,
            floor = floor,
            inside = inTower() == true,
            equipping = pendingEquip == true,
        }
    end
    function Auto.hauntTurbo()
        return hauntTurbo()
    end
    -- Halloween Haunted House: 1 wing + paksa Fast Tower + turbo wait.
    function Auto.beginExclusive(map)
        if exclusiveSaved == nil then
            exclusiveSaved = copyMap(selected)
        end
        if exclusiveFastSaved == nil then
            exclusiveFastSaved = fastOn == true
        end
        selected = copyMap(map)
        towerIndex = 1
        pendingEquip = false
        Fast.setEnabled(true)
        Auto.setEnabled(true)
    end
    -- Halloween direct-drive: tahan loop controller (driver panggil remote sendiri).
    -- Pilihan user disimpan; endExclusive memulihkan seperti biasa.
    function Auto.hauntHold()
        if exclusiveSaved == nil then
            exclusiveSaved = copyMap(selected)
        end
        if exclusiveFastSaved == nil then
            exclusiveFastSaved = fastOn == true
        end
        selected = {}
        towerIndex = 1
        pendingEquip = false
        Auto.setEnabled(false)
    end
    function Auto.endExclusive()
        if exclusiveSaved ~= nil then
            selected = exclusiveSaved
            exclusiveSaved = nil
        end
        if exclusiveFastSaved ~= nil then
            Fast.setEnabled(exclusiveFastSaved == true)
            exclusiveFastSaved = nil
        end
        towerIndex = 1
        pendingEquip = false
        Auto.setEnabled(false)
    end

    cacheTowerGui()
    G.AnimeDiceFastTower = Fast
    G.AnimeDiceAutoTower = Auto

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 1.5,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Tower",
                expanded = false,
                status = {
                    id = "auto.tower.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "pick towers",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            ui:CreateRowDropdown(group, {
                id = "auto.tower.list",
                label = "Towers",
                mode = "multi",
                placeholder = "Pick towers...",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 22,
                getItems = towerItems,
                onChanged = function(a, b)
                    selected = copyMap(dropdownValue(a, b))
                    towerIndex = 1
                    pendingEquip = false
                    paintHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.fasttower",
                label = "Fast Tower",
                initial = fastOn == true,
                onChanged = function(on)
                    Fast.setEnabled(on == true)
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.tower",
                label = "Enable Auto Tower",
                initial = autoOn == true,
                onChanged = function(on)
                    Auto.setEnabled(on == true)
                end,
            })
            local note = ui:CreateRowLabel(group, {
                text = "Equips best units, then runs selected towers in order. Next tower starts after a win or a loss. Fast Tower skips fight playback (~1.3s per floor).",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if values["auto.tower.list"] ~= nil then
            selected = copyMap(values["auto.tower.list"])
        end
        Fast.setEnabled(values["auto.fasttower"] == true)
        Auto.setEnabled(values["auto.tower"] == true)
    end)
end
 end, required = true, feature = true },
    { key = "Info", name = "Info", factory = function() -- INFO, tab utama di atas AUTO.
-- Angka sesi dihitung sejak script ini hidup di server yang sama.

return function(Core)
    local G = Core.env()
    local labels = {}
    local heads = {}

    local function compact(n)
        n = tonumber(n)
        if not n then
            return "-"
        end
        local ok, text = pcall(function()
            return require(game:GetService("ReplicatedStorage").Packages.NumberFormatter).FormatCompact(n, 2)
        end)
        if ok and type(text) == "string" and text ~= "" then
            return text
        end
        return tostring(math.floor(n))
    end

    local function signed(n)
        n = tonumber(n) or 0
        local text = compact(math.abs(n))
        if n > 0 then
            return "+" .. text
        end
        if n < 0 then
            return "-" .. text
        end
        return "0"
    end

    local function clockText(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        local h = math.floor(sec / 3600)
        local m = math.floor((sec % 3600) / 60)
        local s = sec % 60
        if h > 0 then
            return string.format("%d:%02d:%02d", h, m, s)
        end
        return string.format("%d:%02d", m, s)
    end

    local session = G.AnimeDiceSession
    local jobId = tostring(game.JobId or "")
    if type(session) ~= "table" or session.job ~= jobId then
        session = {
            job = jobId,
            t0 = os.clock(),
            money0 = nil,
            rolls0 = nil,
            bestChance = -1,
            bestText = "-",
            seen = {},
            seeded = false,
            fuseBest = nil,
            fuseHistory = {},
            fuseCount = 0,
        }
        G.AnimeDiceSession = session
    end
    if session.rollOnly ~= true then
        session.best = nil
        session.bestChance = -1
        session.rollOnly = true
    end
    if type(session.fuseHistory) ~= "table" then
        session.fuseHistory = {}
    end
    if type(session.topRolls) ~= "table" then
        session.topRolls = {}
    end
    if session.topDeduped ~= true then
        local src = session.topRolls
        local cleaned = {}
        for i = 1, #src do
            local row = src[i]
            local prev = cleaned[#cleaned]
            if type(row) == "table" then
                local same = prev
                    and prev.name == row.name
                    and prev.mutation == row.mutation
                    and tonumber(prev.chance) == tonumber(row.chance)
                if not same then
                    cleaned[#cleaned + 1] = row
                end
            end
        end
        session.topRolls = cleaned
        session.topDeduped = true
    end
    session.fuseCount = tonumber(session.fuseCount) or 0
    session.pumpkinRolls = tonumber(session.pumpkinRolls) or 0
    session.topGen = (tonumber(session.topGen) or 0) + 1

    local chanceCache = {}
    local function entryChance(name, mutation)
        if type(name) ~= "string" or name == "" then
            return nil
        end
        local key = name .. "\0" .. tostring(mutation or "")
        local cached = chanceCache[key]
        if cached ~= nil then
            if cached == false then
                return nil
            end
            return cached
        end
        local ok, cfg = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
        end)
        if not ok or type(cfg) ~= "table" or cfg.kind ~= "Unit" or type(cfg.chance) ~= "function" then
            chanceCache[key] = false
            return nil
        end
        local okChance, chance = pcall(cfg.chance, {
            mutation = mutation,
        })
        chance = okChance and tonumber(chance) or nil
        if not chance then
            chanceCache[key] = false
            return nil
        end
        chanceCache[key] = chance
        return chance
    end

    local function readValue(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function field(source, key)
        if type(source) ~= "table" then
            return nil
        end
        return readValue(source[key])
    end

    local function profileUnit(name, mutation, extra)
        name = readValue(name)
        if type(name) ~= "string" or name == "" then
            return nil
        end
        extra = type(extra) == "table" and extra or {}
        local attrs = extra
        if type(extra.attributes) == "table" then
            attrs = extra.attributes
        end
        mutation = readValue(mutation)
        if type(mutation) ~= "string" or mutation == "" then
            mutation = field(attrs, "mutation")
        end
        if type(mutation) ~= "string" or mutation == "" then
            mutation = nil
        end
        local ok, cfg = pcall(function()
            return require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
        end)
        if not ok or type(cfg) ~= "table" or cfg.kind ~= "Unit" then
            return nil
        end
        local opts = {
            mutation = mutation,
            trait = field(attrs, "trait"),
            grade = field(attrs, "grade"),
            level = field(attrs, "level"),
        }
        local chance = entryChance(name, mutation)
        if not chance then
            return nil
        end
        local income
        if type(cfg.income) == "function" then
            local okIncome, value = pcall(cfg.income, opts)
            income = okIncome and tonumber(value) or nil
        end
        local rarity
        if type(cfg.getRarity) == "function" then
            local okRarity, value = pcall(cfg.getRarity, opts)
            if okRarity and value ~= nil then
                rarity = tostring(value)
            end
        end
        local gradient
        if rarity then
            local okInfo, info = pcall(function()
                return require(game:GetService("ReplicatedStorage").Framework.Other.Rarities).Get(rarity)
            end)
            if okInfo and type(info) == "table" then
                gradient = info.gradient
            end
        end
        return {
            name = name,
            mutation = mutation,
            trait = extra.trait,
            grade = extra.grade,
            level = extra.level,
            chance = chance,
            income = income,
            rarity = rarity,
            gradient = gradient,
        }
    end

    local function detailLine(unit)
        local bits = {}
        if unit.rarity and unit.rarity ~= "" then
            bits[#bits + 1] = unit.rarity
        end
        if unit.chance then
            bits[#bits + 1] = "1 in " .. compact(unit.chance)
        end
        if unit.income then
            bits[#bits + 1] = compact(unit.income) .. "/s"
        end
        if type(unit.mutation) == "string" and unit.mutation ~= "" then
            bits[#bits + 1] = unit.mutation
        end
        if type(unit.trait) == "string" and unit.trait ~= "" then
            bits[#bits + 1] = unit.trait
        end
        if unit.grade ~= nil and tostring(unit.grade) ~= "" then
            bits[#bits + 1] = tostring(unit.grade)
        end
        if tonumber(unit.level) then
            bits[#bits + 1] = "Lv " .. tostring(unit.level)
        end
        if #bits == 0 then
            return "-"
        end
        return table.concat(bits, "  ·  ")
    end

    local function paintBestRoll(unit)
        if type(unit) ~= "table" then
            return nil
        end
        if unit._ready == true then
            return unit
        end
        local full = profileUnit(unit.name, unit.mutation, unit)
        if type(full) ~= "table" then
            return unit
        end
        full._ready = true
        session.best = full
        session.bestChance = full.chance
        return full
    end

    local function pushTop(name, mutation, chance)
        local list = session.topRolls
        if type(list) ~= "table" then
            list = {}
            session.topRolls = list
        end
        local n = #list
        if n >= 100 then
            local worst = tonumber(list[n] and list[n].chance) or 0
            if chance <= worst then
                return
            end
        end
        local i = n
        while i >= 1 and chance > (tonumber(list[i].chance) or 0) do
            i = i - 1
        end
        table.insert(list, i + 1, {
            name = name,
            mutation = mutation,
            chance = chance,
        })
        while #list > 100 do
            table.remove(list)
        end
        session.topGen = (tonumber(session.topGen) or 0) + 1
    end

    local lastNoteAt = 0
    local lastNoteName
    local lastNoteMut
    local lastNoteChance = 0

    local function fastRolling()
        local F = G.AnimeDiceFastRoll
        if type(F) ~= "table" or type(F.enabled) ~= "function" then
            return false
        end
        local ok, on = pcall(F.enabled)
        return ok and on == true
    end

    local Info = {}
    function Info.noteRoll(row)
        if type(row) ~= "table" then
            return
        end
        local name = readValue(row.result or row.name)
        if type(name) ~= "string" or name == "" then
            return
        end
        local mutation = readValue(row.mutation)
        if type(mutation) ~= "string" or mutation == "" then
            mutation = nil
        end
        local chance = tonumber(row.chance) or entryChance(name, mutation)
        if not chance then
            return
        end
        local now = os.clock()
        if name == lastNoteName and mutation == lastNoteMut and chance == lastNoteChance and (now - lastNoteAt) < 0.05 then
            return
        end
        -- Fast Roll: skip roll yang tidak bisa masuk Top 100 / best baru.
        if fastRolling() then
            local best = tonumber(session.bestChance) or -1
            local list = session.topRolls
            local n = type(list) == "table" and #list or 0
            if chance <= best and n >= 100 then
                local worst = tonumber(list[n] and list[n].chance) or 0
                if chance <= worst then
                    return
                end
            end
        end
        lastNoteAt = now
        lastNoteName = name
        lastNoteMut = mutation
        lastNoteChance = chance
        if chance > (tonumber(session.bestChance) or -1) then
            session.bestChance = chance
            session.best = {
                name = name,
                mutation = mutation,
                chance = chance,
            }
        end
        pushTop(name, mutation, chance)
    end
    function Info.noteFuse(row)
        if type(row) ~= "table" then
            return
        end
        local unit = profileUnit(row.name or row.result, row.mutation, row)
        if not unit then
            return
        end
        session.fuseCount = (tonumber(session.fuseCount) or 0) + 1
        local pending = G.AnimeDicePendingFuse
        if type(pending) == "table" and (os.clock() - (tonumber(pending.at) or 0)) < 8 then
            unit.inputs = pending.units
            G.AnimeDicePendingFuse = nil
        end
        local best = session.fuseBest
        if type(best) ~= "table" or unit.chance > (tonumber(best.chance) or -1) then
            session.fuseBest = unit
        end
        local hist = session.fuseHistory
        table.insert(hist, 1, unit)
        while #hist > 30 do
            table.remove(hist)
        end
    end
    G.AnimeDiceInfo = Info

    pcall(function()
        local Client = require(game:GetService("ReplicatedStorage").Packages.Network.Client)
        if type(Client) ~= "table" or type(Client.GetFunction) ~= "function" then
            return
        end
        if type(G.AnimeDiceInfoGetOriginal) ~= "function" then
            G.AnimeDiceInfoGetOriginal = Client.GetFunction
        end
        local original = G.AnimeDiceInfoGetOriginal
        local function notePumpkinRollResult(result, current)
            if type(result) ~= "table" or type(current) ~= "table" or type(current.noteRoll) ~= "function" then
                return
            end
            if result.ok == false then
                return
            end
            local list = result.results
            if type(list) ~= "table" then
                return
            end
            session.pumpkinRolls = (tonumber(session.pumpkinRolls) or 0) + #list
            local PD
            pcall(function()
                PD = require(game:GetService("ReplicatedStorage").Framework.Features.Halloween.PumpkinDice)
            end)
            for _, row in ipairs(list) do
                if type(row) == "table" and type(row.name) == "string" then
                    local chance
                    if type(PD) == "table" and type(PD.Get) == "function" and type(PD.GetChance) == "function" then
                        local unit = PD.Get(row.name)
                        if type(unit) == "table" then
                            local okc, c = pcall(PD.GetChance, unit, 1)
                            chance = okc and tonumber(c) or nil
                        end
                    end
                    pcall(current.noteRoll, {
                        name = row.name,
                        chance = chance,
                    })
                end
            end
        end

        Client.GetFunction = function(folder, name, ...)
            local fn = original(folder, name, ...)
            if type(fn) ~= "function" then
                return fn
            end
            local folderName = typeof(folder) == "Instance" and folder.Name or ""
            local isDice = name == "RollDice"
            local isPumpkin = name == "Roll" and folderName == "PumpkinDiceService"
            if not isDice and not isPumpkin then
                return fn
            end
            return function(...)
                local packed = table.pack(fn(...))
                local result = packed[1]
                local current = G.AnimeDiceInfo
                if type(result) == "table" and type(current) == "table" and type(current.noteRoll) == "function" then
                    if isPumpkin then
                        notePumpkinRollResult(result, current)
                    elseif result.result or result.name then
                        pcall(current.noteRoll, result)
                    else
                        for _, row in ipairs(result) do
                            pcall(current.noteRoll, row)
                        end
                    end
                end
                return table.unpack(packed, 1, packed.n)
            end
        end
        G.AnimeDiceInfoGetHook = true
    end)

    if G.AnimeDiceFuseHook ~= true then
        pcall(function()
            local RS = game:GetService("ReplicatedStorage")
            local sig = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "FusingService"):GetSignal("Result")
            if not sig or type(sig.Connect) ~= "function" then
                return
            end
            sig:Connect(function(unit)
                local current = G.AnimeDiceInfo
                if type(unit) == "table" and type(current) == "table" and type(current.noteFuse) == "function" then
                    pcall(current.noteFuse, unit)
                end
            end)
            G.AnimeDiceFuseHook = true
        end)
    end

    local cards = {}

    local function gradientColor(gradient)
        if typeof(gradient) == "ColorSequence" and gradient.Keypoints[1] then
            return gradient.Keypoints[1].Value
        end
        return Color3.fromRGB(232, 232, 236)
    end

    local function applyGradient(label, gradient)
        local old = label:FindFirstChild("RarityGrad")
        if old then
            old:Destroy()
        end
        if typeof(gradient) ~= "ColorSequence" then
            label.TextColor3 = Color3.fromRGB(232, 232, 236)
            return
        end
        label.TextColor3 = Color3.new(1, 1, 1)
        local grad = Instance.new("UIGradient")
        grad.Name = "RarityGrad"
        grad.Color = gradient
        grad.Rotation = 0
        grad.Parent = label
    end

    local function rgbHex(color)
        if typeof(color) ~= "Color3" then
            return "#E8E8EC"
        end
        local r = math.clamp(math.floor(color.R * 255 + 0.5), 0, 255)
        local g = math.clamp(math.floor(color.G * 255 + 0.5), 0, 255)
        local b = math.clamp(math.floor(color.B * 255 + 0.5), 0, 255)
        return string.format("#%02X%02X%02X", r, g, b)
    end

    local function escRich(text)
        text = tostring(text or "")
        text = text:gsub("&", "&amp;")
        text = text:gsub("<", "&lt;")
        text = text:gsub(">", "&gt;")
        return text
    end

    local function resolveFuseUnit(row)
        if type(row) ~= "table" then
            return nil
        end
        local unit = profileUnit(row.name or row.result, row.mutation, row)
        if not unit then
            unit = {
                name = tostring(row.name or row.result or "?"),
                mutation = row.mutation,
                chance = tonumber(row.chance),
                income = tonumber(row.income) or tonumber(row.earn),
            }
        end
        if tonumber(row.chance) then
            unit.chance = tonumber(row.chance)
        end
        if tonumber(row.earn) then
            unit.income = tonumber(row.earn)
        elseif tonumber(row.income) then
            unit.income = tonumber(row.income)
        end
        return unit
    end

    local function richChance(unit, hex)
        unit = resolveFuseUnit(unit)
        if not unit then
            return ""
        end
        local text = unit.chance and compact(unit.chance) or (unit.name or "?")
        return string.format('<font color="%s">%s</font>', hex or rgbHex(gradientColor(unit.gradient)), escRich(text))
    end

    local function richResultDetail(unit)
        unit = resolveFuseUnit(unit)
        if not unit then
            return "?"
        end
        local name = unit.name or "?"
        if type(unit.mutation) == "string" and unit.mutation ~= "" then
            name = name .. " " .. unit.mutation
        end
        local extra = {}
        if unit.chance then
            extra[#extra + 1] = compact(unit.chance)
        end
        if unit.income then
            extra[#extra + 1] = compact(unit.income) .. "/s"
        end
        if type(unit.trait) == "string" and unit.trait ~= "" then
            extra[#extra + 1] = unit.trait
        end
        if unit.grade ~= nil and tostring(unit.grade) ~= "" then
            extra[#extra + 1] = tostring(unit.grade)
        end
        if unit.rarity and unit.rarity ~= "" then
            table.insert(extra, 1, unit.rarity)
        end
        local nameHex = rgbHex(gradientColor(unit.gradient))
        local body = escRich(name)
        if #extra > 0 then
            body = body .. '<font color="#FFD45A"> · ' .. escRich(table.concat(extra, " · ")) .. "</font>"
        end
        return string.format('<font color="%s">%s</font>', nameHex, body)
    end

    local function fuseHistRich(unit)
        if type(unit) ~= "table" then
            return ""
        end
        local resultBit = string.format(
            '<font size="10" color="#C4A0FF">( </font><font size="10">%s</font><font size="10" color="#C4A0FF"> )</font>',
            richResultDetail(unit)
        )
        local inputs = type(unit.inputs) == "table" and unit.inputs or nil
        if type(inputs) ~= "table" or #inputs == 0 then
            return resultBit
        end
        local parts = {}
        for i = 1, 3 do
            local bit = richChance(inputs[i])
            if bit ~= "" then
                parts[#parts + 1] = bit
            end
        end
        if #parts == 0 then
            return resultBit
        end
        return '<font color="#9AA0A8">1 IN </font>'
            .. table.concat(parts, '<font color="#6A6E78"> + </font>')
            .. '<font color="#C4A0FF"> → </font>'
            .. resultBit
    end

    local function fuseInputsRich(unit)
        if type(unit) ~= "table" or type(unit.inputs) ~= "table" then
            return ""
        end
        local parts = {}
        for i = 1, 3 do
            local row = resolveFuseUnit(unit.inputs[i])
            if row then
                local label = tostring(row.name or "?")
                if type(row.mutation) == "string" and row.mutation ~= "" then
                    label = label .. " " .. row.mutation
                end
                parts[#parts + 1] = richChance(row) .. '<font color="#9AA0A8"> ' .. escRich(label) .. "</font>"
            end
        end
        if #parts == 0 then
            return ""
        end
        return '<font color="#9AA0A8">1 IN </font>'
            .. table.concat(parts, '<font color="#6A6E78"> + </font>')
    end

    local function paintCard(key, unit)
        local card = cards[key]
        if not card or not card.title or not card.title.Parent then
            return
        end
        local detail = card.detail
        if type(unit) ~= "table" then
            card.title.Text = "-"
            if detail then
                detail.RichText = false
                detail.TextColor3 = Color3.fromRGB(186, 190, 198)
                detail.Text = "rarity  ·  1 in  ·  earn/s"
            end
            applyGradient(card.title, nil)
            card.bar.BackgroundColor3 = Color3.fromRGB(90, 90, 90)
            return
        end
        card.title.Text = unit.name
        applyGradient(card.title, unit.gradient)
        card.bar.BackgroundColor3 = gradientColor(unit.gradient)
        if not detail then
            return
        end
        local stats = detailLine(unit)
        local inputs = key == "fbest" and fuseInputsRich(unit) or ""
        if inputs ~= "" then
            detail.RichText = true
            detail.TextColor3 = Color3.new(1, 1, 1)
            detail.Text = inputs .. '\n<font color="#BABEC6">' .. escRich(stats) .. "</font>"
        else
            detail.RichText = false
            detail.TextColor3 = Color3.fromRGB(186, 190, 198)
            detail.Text = stats
        end
    end

    local function setText(key, text, color)
        local label = labels[key]
        if label and label.Parent then
            label.Text = tostring(text or "-")
            if color then
                label.TextColor3 = color
            end
        end
    end

    local liveWeathers = {}
    pcall(function()
        local RS = game:GetService("ReplicatedStorage")
        local prop = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "WeatherService"):GetProperty("ActiveWeather")
        local function applyWeather(value)
            liveWeathers = {}
            if type(value) == "table" then
                if type(value.name) == "string" then
                    liveWeathers[1] = value
                else
                    for _, row in ipairs(value) do
                        if type(row) == "table" and type(row.name) == "string" then
                            liveWeathers[#liveWeathers + 1] = row
                        end
                    end
                    if #liveWeathers == 0 then
                        for _, row in pairs(value) do
                            if type(row) == "table" and type(row.name) == "string" then
                                liveWeathers[#liveWeathers + 1] = row
                            end
                        end
                    end
                end
            end
        end
        if prop.IsReady and prop:IsReady() then
            applyWeather(prop:Get())
        end
        if type(prop.Observe) == "function" then
            prop:Observe(applyWeather)
        end
    end)

    local weatherNames = {}
    pcall(function()
        local folder = game:GetService("ReplicatedStorage"):FindFirstChild("Weather Events")
        if folder then
            for _, child in ipairs(folder:GetChildren()) do
                weatherNames[child.Name] = true
            end
        end
    end)

    local function remainText(row)
        local remain = tonumber(row.duration) or 0
        local started = tonumber(row.startedAt)
        if started then
            remain = remain - (workspace:GetServerTimeNow() - started)
        end
        remain = math.max(0, math.floor(remain))
        return string.format("%d:%02d", math.floor(remain / 60), remain % 60)
    end

    local function eventLine()
        local listed = {}
        local seen = {}
        local function add(name, timeText)
            if type(name) ~= "string" or name == "" or seen[name] then
                return
            end
            seen[name] = true
            if timeText and timeText ~= "" then
                listed[#listed + 1] = name .. "  ·  " .. timeText
            else
                listed[#listed + 1] = name
            end
        end
        for _, row in ipairs(liveWeathers) do
            add(row.name, remainText(row))
        end
        pcall(function()
            for _, child in ipairs(workspace:GetChildren()) do
                if weatherNames[child.Name] then
                    local timeText
                    for _, row in ipairs(liveWeathers) do
                        if row.name == child.Name then
                            timeText = remainText(row)
                            break
                        end
                    end
                    add(child.Name, timeText)
                end
            end
        end)
        pcall(function()
            local bar = game:GetService("Players").LocalPlayer.PlayerGui.Root.HUD.BuffBar
            for _, child in ipairs(bar:GetChildren()) do
                if child:IsA("GuiObject") and child.Visible and child.Name ~= "Template" and child.Name ~= "Expand" then
                    local label = child:FindFirstChild("TextLabel")
                    local txt = label and label.Text or ""
                    if child.Name == "__WeatherEvent" or weatherNames[child.Name] then
                        local name = child.Name
                        if name == "__WeatherEvent" then
                            name = liveWeathers[1] and liveWeathers[1].name
                            if not name then
                                for wname in pairs(weatherNames) do
                                    if workspace:FindFirstChild(wname) then
                                        name = wname
                                        break
                                    end
                                end
                            end
                        end
                        add(name or "Event", txt)
                    end
                end
            end
        end)
        if #listed == 0 then
            return "None"
        end
        return table.concat(listed, "  ·  ")
    end

    local lastInvScan = 0
    local cachedBestOwned
    local cachedUnitCount = 0

    local function paint()
        if not Core.uiIs("info", "info") then
            return
        end
        if not (labels.time and labels.time.Parent) then
            return
        end
        local Data = Core.data()
        local moneyNow, rollsNow = nil, nil
        pcall(function()
            moneyNow = tonumber(Data.Money())
        end)
        pcall(function()
            rollsNow = tonumber(Data.Rolls())
        end)
        if session.money0 == nil and moneyNow then
            session.money0 = moneyNow
        end
        if session.rolls0 == nil and rollsNow then
            session.rolls0 = rollsNow
        end

        local bestOwned = cachedBestOwned
        local unitCount = cachedUnitCount
        local nowClock = os.clock()
        if (nowClock - lastInvScan) >= 5 then
            lastInvScan = nowClock
            bestOwned = nil
            unitCount = 0
            pcall(function()
                local inv = Data.Inventory()
                if type(inv) ~= "table" then
                    return
                end
                local registry = require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryRegistry)
                for _, item in pairs(inv) do
                    if type(item) == "table" then
                        local cfg
                        pcall(function()
                            cfg = registry.getEntryConfig(item.name)
                        end)
                        if type(cfg) == "table" and cfg.kind == "Unit" then
                            unitCount = unitCount + 1
                        end
                        local unit = profileUnit(item.name, item.mutation, item)
                        if unit and (not bestOwned or unit.chance > bestOwned.chance) then
                            bestOwned = unit
                        end
                    end
                end
            end)
            cachedBestOwned = bestOwned
            cachedUnitCount = unitCount
        end

        local elapsed = os.clock() - (tonumber(session.t0) or os.clock())
        local sessionRolls = 0
        if rollsNow and session.rolls0 then
            sessionRolls = math.max(0, rollsNow - session.rolls0)
        end
        local perMin = "-"
        if elapsed >= 8 then
            perMin = string.format("%.1f", sessionRolls / (elapsed / 60))
        end
        local moneyDelta = 0
        if moneyNow and session.money0 then
            moneyDelta = moneyNow - session.money0
        end

        local moneyColor = Color3.fromRGB(120, 220, 150)
        if moneyDelta < 0 then
            moneyColor = Color3.fromRGB(255, 120, 120)
        end
        setText("time", clockText(elapsed), Color3.fromRGB(255, 214, 90))
        setText("srolls", compact(sessionRolls), Color3.fromRGB(120, 190, 255))
        setText("prolls", compact(session.pumpkinRolls or 0), Color3.fromRGB(255, 140, 200))
        setText("permin", perMin, Color3.fromRGB(255, 170, 90))
        setText("smoney", signed(moneyDelta), moneyColor)
        paintCard("sbest", paintBestRoll(session.best))
        paintCard("obest", bestOwned)
        paintCard("fbest", session.fuseBest)
        local hist = type(session.fuseHistory) == "table" and session.fuseHistory or {}
        for i = 1, 5 do
            local label = labels["fh" .. tostring(i)]
            local unit = hist[i]
            if label and label.Parent then
                if type(unit) == "table" then
                    label.RichText = true
                    label.TextColor3 = Color3.new(1, 1, 1)
                    label.Text = fuseHistRich(unit)
                else
                    label.RichText = false
                    label.TextColor3 = Color3.fromRGB(150, 154, 162)
                    label.Text = i == 1 and "None yet" or "-"
                end
            end
        end
        if heads.fuse then
            local n = tonumber(session.fuseCount) or 0
            heads.fuse.Text = n > 0 and (tostring(n) .. " this session") or "this session"
        end
        setText("trolls", rollsNow and compact(rollsNow) or "-", Color3.fromRGB(120, 190, 255))
        setText("money", moneyNow and compact(moneyNow) or "-", Color3.fromRGB(120, 220, 150))
        pcall(function()
            local dice = Data.Dice()
            local luck = ""
            if type(dice) == "string" and dice ~= "" then
                local info = require(game:GetService("ReplicatedStorage").Framework.Features.Rolling.Dice).Get(dice)
                if type(info) == "table" and info.luck then
                    luck = "  ·  " .. compact(info.luck)
                end
                setText("dice", tostring(dice) .. luck)
            end
        end)
        pcall(function()
            setText("rebirth", compact(Data.Rebirth()))
        end)
        local packText = "-"
        pcall(function()
            local cap = require(game:GetService("ReplicatedStorage").Framework.Features.Buffs.BuffController).GetBuff("Unit Storage")
            cap = tonumber(cap) or 0
            packText = tostring(unitCount) .. " / " .. tostring(math.floor(cap))
        end)
        local plotEarn = 0
        pcall(function()
            local inv = Data.Inventory()
            if type(inv) ~= "table" then
                return
            end
            local seen = {}
            for _, slot in ipairs(Core.slots()) do
                local getter = Data.Slots and Data.Slots[tostring(slot)]
                if getter ~= nil then
                    local okSlot, row = pcall(getter)
                    if okSlot and type(row) == "table" then
                        local id = field(row, "unitId")
                        if type(id) ~= "string" or id == "" then
                            id = readValue(row.unitId)
                        end
                        if type(id) == "string" and id ~= "" and not seen[id] then
                            seen[id] = true
                            local item = inv[id] or inv[tostring(id)]
                            local unit = profileUnit(item and (item.name or field(item, "name")), nil, item)
                            local earn = unit and tonumber(unit.income) or 0
                            plotEarn = plotEarn + earn
                        end
                    end
                end
            end
            local mul = 1
            pcall(function()
                local v = require(game:GetService("ReplicatedStorage").Framework.Features.Buffs.BuffController).GetBuff("Money Multiplier")
                v = tonumber(v)
                if v and v > 0 then
                    mul = v
                end
            end)
            plotEarn = plotEarn * mul
        end)
        setText("plot", compact(plotEarn) .. "/s", Color3.fromRGB(120, 220, 150))
        local eventText = "-"
        pcall(function()
            eventText = eventLine()
            setText("event", eventText)
        end)
        if heads.session then
            local ev = tostring(eventText or "")
            if ev == "" or ev == "-" or ev == "None" then
                heads.session.Text = clockText(elapsed)
            else
                heads.session.Text = ev
            end
        end
        if heads.owned then
            heads.owned.Text = packText
        end
    end

    local loop = Core.loop("info", {
        delay = 4,
        step = paint,
    })
    loop.setEnabled(true)

    local function corner(inst, radius)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius or 8)
        c.Parent = inst
    end

    local function addLine(parent, order, key, caption, valueColor)
        local row = Instance.new("Frame")
        row.Name = "InfoLine"
        row.BackgroundTransparency = 1
        row.BorderSizePixel = 0
        row.Size = UDim2.new(1, 0, 0, 16)
        row.LayoutOrder = order
        row.Parent = parent

        local cap = Instance.new("TextLabel")
        cap.BackgroundTransparency = 1
        cap.Size = UDim2.new(0.42, 0, 1, 0)
        cap.Font = Enum.Font.Gotham
        cap.TextSize = 12
        cap.TextXAlignment = Enum.TextXAlignment.Left
        cap.TextYAlignment = Enum.TextYAlignment.Center
        cap.TextColor3 = Color3.fromRGB(150, 154, 162)
        cap.TextTruncate = Enum.TextTruncate.AtEnd
        cap.Text = caption
        cap.Parent = row

        local value = Instance.new("TextLabel")
        value.BackgroundTransparency = 1
        value.Position = UDim2.new(0.42, 0, 0, 0)
        value.Size = UDim2.new(0.58, 0, 1, 0)
        value.Font = Enum.Font.GothamMedium
        value.TextSize = 12
        value.TextXAlignment = Enum.TextXAlignment.Right
        value.TextYAlignment = Enum.TextYAlignment.Center
        value.TextColor3 = valueColor or Color3.fromRGB(232, 232, 236)
        value.TextTruncate = Enum.TextTruncate.AtEnd
        value.Text = "-"
        value.Parent = row
        labels[key] = value
    end

    local function addFuseHist(parent, order, key, caption)
        local row = Instance.new("Frame")
        row.Name = "FuseHist"
        row.BackgroundTransparency = 1
        row.BorderSizePixel = 0
        row.Size = UDim2.new(1, 0, 0, 0)
        row.AutomaticSize = Enum.AutomaticSize.Y
        row.LayoutOrder = order
        row.Parent = parent

        local cap = Instance.new("TextLabel")
        cap.BackgroundTransparency = 1
        cap.Size = UDim2.new(0, 38, 0, 16)
        cap.Font = Enum.Font.Gotham
        cap.TextSize = 12
        cap.TextXAlignment = Enum.TextXAlignment.Left
        cap.TextYAlignment = Enum.TextYAlignment.Top
        cap.TextColor3 = Color3.fromRGB(150, 154, 162)
