            row.Parent = board

            local sessionCol, sessionHead = column(board, 1, "SESSION", Color3.fromRGB(255, 196, 64))
            heads.session = sessionHead
            addBest(sessionCol, 1, "sbest", "BEST ROLL")
            addLine(sessionCol, 2, "time", "Time", Color3.fromRGB(255, 214, 90))
