            addLine(sessionCol, 6, "event", "Event", Color3.fromRGB(255, 140, 200))
            addLine(sessionCol, 7, "prolls", "Event rolls", Color3.fromRGB(255, 140, 200))

            local ownedCol, ownedHead = column(board, 2, "OWNED", Color3.fromRGB(120, 190, 255))
