            addLine(ownedCol, 2, "plot", "Plot earn/s", Color3.fromRGB(120, 220, 150))
            addLine(ownedCol, 3, "trolls", "Total rolls", Color3.fromRGB(120, 190, 255))
            addLine(ownedCol, 4, "money", "Money", Color3.fromRGB(120, 220, 150))
            addLine(ownedCol, 5, "dice", "Dice", Color3.fromRGB(196, 160, 255))
            addLine(ownedCol, 6, "rebirth", "Rebirth", Color3.fromRGB(255, 150, 190))

            local fuseBoard = Instance.new("Frame")
            fuseBoard.Name = "FuseBoard"
