            local fuseCol, fuseHead = column(fuseBoard, 1, "FUSE", Color3.fromRGB(196, 160, 255), true)
            heads.fuse = fuseHead
            addBest(fuseCol, 1, "fbest", "BEST FUSE", true)
            addFuseHist(fuseCol, 2, "fh1", "Last")
            addFuseHist(fuseCol, 3, "fh2", "2")
            addFuseHist(fuseCol, 4, "fh3", "3")
            addFuseHist(fuseCol, 5, "fh4", "4")
            addFuseHist(fuseCol, 6, "fh5", "5")
            paint()
            Core.kickScroll(ui.content)
        end,
    })
end
 end, required = true, feature = true },
    { key = "Webhook", name = "Webhook", factory = function() -- MISC → Webhook.
-- Discord: roll JP/LS/biasa, Fuse, Trade, Account. Luck total + /s. NODE + GAG panel.

return function(Core)
    local Players = game:GetService("Players")
    local HttpService = game:GetService("HttpService")
    local LP = Core.player() or Players.LocalPlayer
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")

    local old = G.AnimeDiceWebhook
    if type(old) == "table" then
        pcall(function()
            if old._fuseConn then
                old._fuseConn:Disconnect()
            end
            if old._tradeConn then
                old._tradeConn:Disconnect()
            end
        end)
        if type(old.Stop) == "function" then
            pcall(old.Stop)
        end
    end

    G.__AnimeDiceWebhookGen = (tonumber(G.__AnimeDiceWebhookGen) or 0) + 1
    local GEN = G.__AnimeDiceWebhookGen

    local COLOR_LINE = 16766720
    local NODE_ICON = "https://tr.rbxcdn.com/180DAY-87ec5b4684a1c087d9eea8067fc5a76e/150/150/Image/Png/noFilter"
    local GAME_NAME = "Anime Dice"
    local POST_GAP = 1.25
    local DELAY_MIN = 1
    local DELAY_MAX = 180
    local DELAY_DEFAULT = 5
    local JP = "Jackpot Spin"
    local LS = "Lucky Spin"
    local IMG_WAIT = 1.2

    local W = {
        url = "",
        tradeUrl = "",
        jp = false,
        ls = false,
        roll = false,
        fuse = false,
        trade = false,
        account = false,
        rollMin = 0,
        fuseMin = 0,
        delayMin = DELAY_DEFAULT,
        _token = 0,
        _lastPost = 0,
        _status = { text = "Off", style = "muted", detail = "—" },
        _onStatus = nil,
        _fuseConn = nil,
        _fuseSnap = nil,
        _tradeConn = nil,
        _tradeSnap = nil,
        _loopOn = false,
    }
    G.AnimeDiceWebhook = W

    local _imgCache = {}
    local _postQ = {}
    local _postOn = false
    local statusApi
    local accountLoop
    local rollMinApi
    local fuseMinApi

    local function emit(text, style, detail)
        W._status = {
            text = tostring(text or "Off"),
            style = style or "muted",
            detail = tostring(detail or "—"),
        }
        local fn = W._onStatus
        if type(fn) == "function" then
            pcall(fn, W._status)
        end
        if type(statusApi) == "table" then
            pcall(function()
                statusApi.set(W._status.text)
                if statusApi.setStyle then
                    statusApi.setStyle(W._status.style)
                end
                if statusApi.setDetail then
                    statusApi.setDetail(W._status.detail)
                end
            end)
        end
    end

    local function flagOn(v)
        return v == true or v == 1 or v == "true" or v == "1"
    end

    local function webhookUrl(raw)
        raw = tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if raw == "" then
            return ""
        end
        if not string.find(raw, "discord.com/api/webhooks/", 1, true)
            and not string.find(raw, "discordapp.com/api/webhooks/", 1, true) then
            return ""
        end
        return raw
    end

    local function httpRequest()
        return (syn and syn.request)
            or (http and http.request)
            or http_request
            or request
            or (fluxus and fluxus.request)
    end

    local function anyOn()
        return W.jp == true
            or W.ls == true
            or W.roll == true
            or W.fuse == true
            or W.trade == true
            or W.account == true
    end

    local function paintIdle()
        if not anyOn() then
            emit("Off", "muted", "—")
            return
        end
        local main = webhookUrl(W.url)
        local trade = webhookUrl(W.tradeUrl)
        if trade == "" then
            trade = main
        end
        local needMain = W.jp or W.ls or W.roll or W.fuse or W.account
        if needMain and main == "" then
            emit("No URL", "warn", "set webhook url")
            return
        end
        if W.trade and trade == "" then
            emit("No URL", "warn", "set trade webhook url")
            return
        end
        local bits = {}
        if W.jp then
            bits[#bits + 1] = "JP"
        end
        if W.ls then
            bits[#bits + 1] = "LS"
        end
        if W.roll then
            bits[#bits + 1] = "Roll"
        end
        if W.fuse then
            bits[#bits + 1] = "Fuse"
        end
        if W.trade then
            bits[#bits + 1] = "Trade"
        end
        if W.account then
            bits[#bits + 1] = "Account"
        end
        emit("On", "success", table.concat(bits, " · "))
    end

    local SUFFIX = {
        k = 1e3,
        m = 1e6,
        b = 1e9,
        t = 1e12,
        qd = 1e15,
        qa = 1e15,
        qi = 1e18,
    }

    local function parseMin(text)
        if type(text) == "number" then
            if text < 0 then
                return 0
            end
            return math.floor(text)
        end
        text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
        if text == "" then
            return 0
        end
        local n = tonumber(text)
        if n then
            if n < 0 then
                return 0
            end
            return math.floor(n)
        end
        local ok, value = pcall(function()
            return require(RS.Packages.NumberFormatter).ParseCompact(text)
        end)
        if ok and tonumber(value) then
            n = tonumber(value)
            if n < 0 then
                return 0
            end
            return math.floor(n)
        end
        local num, suf = text:lower():match("^([%d%.]+)([a-z]+)$")
        n = tonumber(num)
        local mul = suf and SUFFIX[suf]
        if n and mul then
            return math.floor(math.max(0, n * mul))
        end
        return 0
    end

    local function shortNum(n)
        n = tonumber(n)
        if not n then
            return "-"
        end
        local ok, text = pcall(function()
            return require(RS.Packages.NumberFormatter).FormatCompact(n, 2)
        end)
        if ok and type(text) == "string" and text ~= "" and #text <= 10 then
            return text
        end
        local abs = math.abs(n)
        local units = {
            { 1e15, "Qa" },
            { 1e12, "T" },
            { 1e9, "B" },
            { 1e6, "M" },
            { 1e3, "K" },
        }
        for _, u in ipairs(units) do
            if abs >= u[1] then
                local s = string.format("%.1f%s", n / u[1], u[2])
                return (s:gsub("%.0(%a)", "%1"))
            end
        end
        if abs >= 10 or n == math.floor(n) then
            return tostring(math.floor(n + 0.5))
        end
        return string.format("%.1f", n)
    end

    local function fmtMin(n)
        n = parseMin(n)
        if n <= 0 then
            return "0"
        end
        return shortNum(n)
    end

    local function clampDelay(n)
        n = math.floor(tonumber(n) or DELAY_DEFAULT)
        if n < DELAY_MIN then
            n = DELAY_MIN
        end
        if n > DELAY_MAX then
            n = DELAY_MAX
        end
        return n
    end

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function code(v)
        return "`" .. tostring(v or ""):gsub("`", "'") .. "`"
    end

    local function field(name, value, inline)
        value = tostring(value or "")
        if value == "" then
            value = "—"
        end
        if #value > 1020 then
            value = value:sub(1, 1017) .. "..."
        end
        return {
            name = name,
            value = value,
            inline = inline ~= false,
        }
    end

    local function whoTag()
        if not LP then
            return "Account"
        end
        local display = tostring(LP.DisplayName or LP.Name or "Account")
        local name = tostring(LP.Name or "")
        if name ~= "" and name ~= display then
            return display .. "  @" .. name
        end
        return display
    end

    local function firstImageUrl(data)
        local row = type(data) == "table" and data.data and data.data[1]
        if type(row) ~= "table" then
            return nil
        end
        local url = row.imageUrl
        if type(url) ~= "string" or not string.find(url, "^https://") then
            return nil
        end
        return url
    end

    local function httpGetJson(url)
        local req = httpRequest()
        if type(req) ~= "function" then
            return nil
        end
        local ok, res = pcall(req, {
            Url = url,
            Method = "GET",
        })
        if not ok then
            return nil
        end
        local body = res and (res.Body or res.body)
        if type(body) ~= "string" or body == "" then
            return nil
        end
        local okj, data = pcall(HttpService.JSONDecode, HttpService, body)
        if okj and type(data) == "table" then
            return data
        end
        return nil
    end

    local function playerAvatar()
        local id = tonumber(LP and LP.UserId) or 0
        if id <= 0 then
            return NODE_ICON
        end
        local key = "u" .. tostring(id)
        if type(_imgCache[key]) == "string" then
            return _imgCache[key]
        end
        if _imgCache[key] == false then
            return NODE_ICON
        end
        local box = { data = nil, done = false }
        task.spawn(function()
            box.data = httpGetJson(
                "https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds="
                    .. tostring(id)
                    .. "&size=150x150&format=Png&isCircular=false"
            )
            box.done = true
        end)
        local t0 = os.clock()
        while box.done ~= true and os.clock() - t0 < IMG_WAIT do
            task.wait(0.05)
        end
        local url = firstImageUrl(box.data)
        _imgCache[key] = url or false
        return url or NODE_ICON
    end

    local function authorBlock()
        return {
            name = whoTag(),
            icon_url = NODE_ICON,
        }
    end

    local function footerBlock()
        return {
            text = "NODE  ·  " .. GAME_NAME .. "  ·  " .. os.date("%H:%M:%S"),
            icon_url = NODE_ICON,
        }
    end

    local function panelSection(title, rows)
        local out = { "**" .. tostring(title) .. "**" }
        for _, r in ipairs(rows or {}) do
            local label = tostring(r.label or "")
            local value = tostring(r.value or "")
            if label ~= "" then
                if value == "" then
                    value = "-"
                end
                out[#out + 1] = "│ " .. label .. " : " .. value
            end
        end
        return table.concat(out, "\n")
    end

    local function panelBlock(sections)
        return table.concat(sections or {}, "\n\n")
    end

    local function fmtOneIn(n)
        n = tonumber(n)
        if not n then
            return "-"
        end
        return "1/" .. shortNum(n)
    end

    local function fmtLuck(n)
        n = tonumber(n)
        if not n then
            return "-"
        end
        if n == math.floor(n) then
            return "x" .. tostring(math.floor(n))
        end
        local text = string.format("x%.2f", n):gsub("0+$", ""):gsub("%.$", "")
        return text
    end

    local function fmtIncome(n)
        n = tonumber(n)
        if not n or n <= 0 then
            return "-"
        end
        return shortNum(n) .. "/s"
    end

    local function fmtTotalLuck(n)
        n = tonumber(n)
        if not n or n <= 0 then
            return "-"
        end
        return shortNum(n)
    end

    local function entryCfg(name)
        if type(name) ~= "string" or name == "" then
            return nil
        end
        local ok, cfg = pcall(function()
            return require(RS.Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
        end)
        if ok and type(cfg) == "table" then
            return cfg
        end
        return nil
    end

    local function profileUnit(row)
        if type(row) ~= "table" then
            return nil
        end
        local attrs = row
        if type(row.attributes) == "table" then
            attrs = row.attributes
        end
        local name = readVal(row.result or row.name)
        if type(name) ~= "string" or name == "" then
            return nil
        end
        local mutation = readVal(row.mutation)
        if type(mutation) ~= "string" or mutation == "" then
            mutation = readVal(attrs.mutation)
        end
        if type(mutation) ~= "string" or mutation == "" then
            mutation = nil
        end
        local trait = readVal(row.trait) or readVal(attrs.trait)
        local grade = readVal(row.grade) or readVal(attrs.grade)
        if type(trait) ~= "string" or trait == "" then
            trait = nil
        end
        local cfg = entryCfg(name)
        local chance = tonumber(row.chance)
        if not chance and type(cfg) == "table" and type(cfg.chance) == "function" then
            local ok, n = pcall(cfg.chance, { mutation = mutation })
            chance = ok and tonumber(n) or nil
        end
        local income = 0
        if type(cfg) == "table" then
            local Earn = Core.unitEarn or G.AnimeDiceUnitEarn
            if type(Earn) == "table" and type(Earn.income) == "function" then
                income = tonumber(Earn.income(cfg, {
                    mutation = mutation,
                    trait = trait,
                    grade = grade,
                })) or 0
            elseif type(cfg.income) == "function" then
                local okInc, n = pcall(cfg.income, {
                    mutation = mutation,
                    trait = trait,
                    grade = grade,
                })
                income = okInc and tonumber(n) or 0
            end
        end
        local rarity
        if type(cfg) == "table" and type(cfg.getRarity) == "function" then
            local ok, value = pcall(cfg.getRarity, {
                mutation = mutation,
                trait = trait,
                grade = grade,
            })
            if ok and value ~= nil then
                rarity = tostring(value)
            end
        elseif type(cfg) == "table" and cfg.rarity ~= nil then
            rarity = tostring(cfg.rarity)
        end
        return {
            name = name,
            mutation = mutation,
            trait = trait,
            grade = grade,
            chance = chance,
            income = income,
            rarity = rarity,
        }
    end

    local function unitRows(unit)
        local rows = {
            { label = "Name", value = unit and unit.name or "-" },
            { label = "Mutation", value = (unit and unit.mutation) or "Normal" },
            { label = "Rarity", value = (unit and unit.rarity) or "-" },
            { label = "1-in", value = fmtOneIn(unit and unit.chance) },
            { label = "/s", value = fmtIncome(unit and unit.income) },
        }
        if unit and type(unit.trait) == "string" then
            rows[#rows + 1] = { label = "Trait", value = unit.trait }
        end
        if unit and unit.grade ~= nil and tostring(unit.grade) ~= "" then
            rows[#rows + 1] = { label = "Grade", value = tostring(unit.grade) }
        end
        return rows
    end

    local function stockOf(name)
        local n = 0
        pcall(function()
            local data = Core.data()
            local inv = data and data.Inventory()
            if type(inv) ~= "table" then
                return
            end
            for _, row in pairs(inv) do
                if type(row) == "table" and readVal(row.name) == name then
                    n = n + (tonumber(readVal(row.amount)) or 0)
                end
            end
        end)
        return n
    end

    local function unitBag()
        local count, cap = 0, 0
        pcall(function()
            local buffs = require(RS.Framework.Features.Buffs.BuffController)
            cap = tonumber(buffs.GetBuff("Unit Storage")) or 0
        end)
        pcall(function()
            local data = Core.data()
            local inv = data and data.Inventory()
            if type(inv) ~= "table" then
                return
            end
            for _, row in pairs(inv) do
                if type(row) == "table" then
                    local cfg = entryCfg(readVal(row.name))
                    if type(cfg) == "table" and cfg.kind == "Unit" then
                        count = count + 1
                    end
                end
            end
        end)
        if cap > 0 then
            return tostring(count) .. "/" .. tostring(cap)
        end
        return tostring(count)
    end

    local function moneyNow()
        local n = 0
        pcall(function()
            n = tonumber(Core.data().Money()) or 0
        end)
        return n
    end

    local function rollsNow()
        local n = 0
        pcall(function()
            n = tonumber(Core.data().Rolls()) or 0
        end)
        return n
    end

    local function buffOf(name)
        local n = 1
        pcall(function()
            n = tonumber(require(RS.Framework.Features.Buffs.BuffController).GetBuff(name)) or 1
        end)
        return n
    end

    local function snapFields(kind, extra)
        extra = type(extra) == "table" and extra or {}
        local money = code(Core.compact(moneyNow()))
        if kind == "account" then
            local jp = code(tostring(stockOf(JP)))
            local ls = code(tostring(stockOf(LS)))
            return {
                field("$", money, true),
                field("Rolls", code(Core.compact(rollsNow())), true),
                field("JP", jp, true),
                field("LS", ls, true),
                field("Units", code(unitBag()), true),
                field("Trait Luck", code(fmtLuck(buffOf("Trait Luck"))), true),
                field("Grade Luck", code(fmtLuck(buffOf("Grade Luck"))), true),
            }
        end
        if kind == "roll" then
            return {
                field("$", money, true),
                field("Luck", code(fmtTotalLuck(extra.luck)), true),
                field("/s", code(fmtIncome(extra.income)), true),
            }
        end
        if kind == "trade" then
            return {
                field("$", money, true),
                field("Units", code(unitBag()), true),
            }
        end
        return {
            field("$", money, true),
            field("/s", code(fmtIncome(extra.income)), true),
        }
    end

    local function postNow(payload, url)
        url = webhookUrl(url or W.url)
        if url == "" then
            return false, "no url"
        end
        local req = httpRequest()
        if type(req) ~= "function" then
            return false, "no request"
        end
        local waitFor = POST_GAP - (os.clock() - (W._lastPost or 0))
        if waitFor > 0 then
            task.wait(waitFor)
        end
        local body = HttpService:JSONEncode(payload)
        local ok, res = pcall(req, {
            Url = url,
            Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = body,
        })
        W._lastPost = os.clock()
        local codeN = ok and tonumber(res and (res.StatusCode or res.status_code)) or 0
        if codeN == 204 or codeN == 200 then
            return true, nil
        end
        return false, "http " .. tostring(codeN)
    end

    local function postPayload(payload, onDone, url)
        while #_postQ >= 30 do
            table.remove(_postQ, 1)
        end
        _postQ[#_postQ + 1] = { payload = payload, onDone = onDone, url = url }
        if _postOn == true then
            return
        end
        _postOn = true
        task.spawn(function()
            while #_postQ > 0 do
                local job = table.remove(_postQ, 1)
                local embed = job.payload and job.payload.embeds and job.payload.embeds[1]
                if type(embed) == "table" and type(embed.author) == "table" then
                    embed.author.icon_url = playerAvatar()
                end
                local ok, err = postNow(job.payload, job.url)
                if type(job.onDone) == "function" then
                    pcall(job.onDone, ok, err)
                end
            end
            _postOn = false
        end)
    end

    local function sendEmbed(title, description, fields, detail, url)
        url = webhookUrl(url or W.url)
        if url == "" then
            emit("No URL", "warn", "set webhook url")
            return
        end
        local embed = {
            author = authorBlock(),
            title = title,
            color = COLOR_LINE,
            fields = fields,
            footer = footerBlock(),
        }
        if type(description) == "string" and description ~= "" then
            embed.description = description
        end
        postPayload({
            username = "NODE",
            avatar_url = NODE_ICON,
            embeds = { embed },
        }, function(ok, err)
            if ok then
                emit("Sent", "success", detail or title)
            else
                emit("Fail", "error", tostring(err or title))
            end
        end, url)
    end

    local function firstRow(result)
        if type(result) ~= "table" then
            return nil
        end
        if result.result or result.name then
            return result
        end
        for _, row in ipairs(result) do
            if type(row) == "table" then
                return row
            end
        end
        return nil
    end

    local function spinQueued(data)
        local found = {}
        if not data then
            return found
        end
        local snap
        pcall(function()
            snap = data.ActiveEntries()
        end)
        if type(snap) ~= "table" then
            return found
        end
        for _, v in pairs(snap) do
            if type(v) == "table" then
                local name = readVal(v.name)
                if name == JP or name == LS then
                    local amt = tonumber(readVal(v.amount)) or 1
                    if amt > 0 then
                        found[name] = amt
                    end
                end
            end
        end
        return found
    end

    local function passesMin(chance, minN)
        minN = parseMin(minN)
        if minN <= 0 then
            return true
        end
        chance = tonumber(chance)
        if not chance then
            return false
        end
        return chance >= minN
    end

    local function diceLuck()
        local n = 1
        pcall(function()
            local data = Core.data()
            local name = readVal(data and data.Dice)
            if type(name) ~= "string" or name == "" then
                return
            end
            local row = require(RS.Framework.Features.Rolling.Dice).Get(name)
            n = tonumber(row and row.luck) or 1
        end)
        if n <= 0 then
            n = 1
        end
        return n
    end

    local function rollLuck(spin, packedLuck)
        local n = tonumber(packedLuck)
        if n and n > 0 then
            return n
        end
        local spinMul = 1
        if spin == JP or spin == LS then
            spinMul = spin == JP and 1000 or 100
            pcall(function()
                local row = require(RS.Framework.Features.Inventory.Kinds.Spin.SpinConfig).entries[spin]
                local n = row and tonumber(row.luckMultiplier)
                if n and n > 0 then
                    spinMul = n
                end
            end)
        end
        return buffOf("Luck") * diceLuck() * spinMul
    end

    local function spinTitle(spin)
        if spin == JP then
            return "Jackpot Spin"
        end
        if spin == LS then
            return "Lucky Spin"
        end
        return "Roll"
    end

    local function onSpinRoll(result, spin, packedLuck)
        if GEN ~= G.__AnimeDiceWebhookGen then
            return
        end
        if spin == JP then
            if W.jp ~= true then
                return
            end
        elseif spin == LS then
            if W.ls ~= true then
                return
            end
        else
            if W.roll ~= true then
                return
            end
            spin = nil
        end
        local unit = profileUnit(firstRow(result))
        if not unit then
            return
        end
        if not passesMin(unit.chance, W.rollMin) then
            return
        end
        local luck = rollLuck(spin, packedLuck)
        local title = spinTitle(spin)
        local desc = panelBlock({
            panelSection("Roll", {
                { label = "Type", value = title },
                { label = "Luck", value = fmtTotalLuck(luck) },
                { label = "/s", value = fmtIncome(unit.income) },
            }),
            panelSection("Unit", unitRows(unit)),
        })
        sendEmbed(title, desc, snapFields("roll", { luck = luck, income = unit.income }), unit.name)
    end

    local function onFuse(unitRow)
        if GEN ~= G.__AnimeDiceWebhookGen then
            return
        end
        if W.fuse ~= true then
            return
        end
        local unit = profileUnit(unitRow)
        if not unit then
            return
        end
        if not passesMin(unit.chance, W.fuseMin) then
            return
        end
        local desc = panelSection("Result", unitRows(unit))
        local mats = W._fuseSnap and W._fuseSnap.units
        W._fuseSnap = nil
        if (not mats or #mats == 0) then
            local pending = G.AnimeDicePendingFuse
            if type(pending) == "table"
                and type(pending.units) == "table"
                and (os.clock() - (tonumber(pending.at) or 0)) < 8
            then
                mats = pending.units
            end
        end
        if type(mats) == "table" and #mats > 0 then
            local rows = {}
            for i = 1, #mats do
                local m = mats[i]
                if type(m) == "table" then
                    local bits = { tostring(m.name or "?") }
                    if type(m.mutation) == "string" and m.mutation ~= "" then
                        bits[#bits + 1] = m.mutation
                    end
                    if m.rarity then
                        bits[#bits + 1] = tostring(m.rarity)
                    end
                    bits[#bits + 1] = fmtOneIn(m.chance)
                    bits[#bits + 1] = fmtIncome(m.income)
                    if type(m.trait) == "string" and m.trait ~= "" then
                        bits[#bits + 1] = m.trait
                    end
                    if m.grade ~= nil and tostring(m.grade) ~= "" then
                        bits[#bits + 1] = tostring(m.grade)
                    end
                    rows[#rows + 1] = { label = tostring(i), value = table.concat(bits, " · ") }
                end
            end
            if #rows > 0 then
                desc = panelBlock({ desc, panelSection("From", rows) })
            end
        end
        sendEmbed("Fuse", desc, snapFields("fuse", { income = unit.income }), unit.name)
    end

    local function invById(id)
        local row
        pcall(function()
            local inv = Core.data().Inventory
            local node = inv[id]
            if node == nil then
                node = inv[tostring(id)]
            end
            row = readVal(node)
        end)
        if type(row) ~= "table" then
            pcall(function()
                local snap = Core.data().Inventory()
                if type(snap) == "table" then
                    row = snap[id] or snap[tostring(id)]
                end
            end)
        end
        return type(row) == "table" and row or nil
    end

    local function cacheFuseMats(a, b, c)
        local mats = {}
        local ids = { a, b, c }
        for i = 1, 3 do
            local row = invById(ids[i])
            if type(row) == "table" then
                local unit = profileUnit(row)
                if unit then
                    mats[#mats + 1] = unit
                end
            end
        end
        if #mats > 0 then
            W._fuseSnap = { at = os.clock(), units = mats }
        end
    end

    local function tradeItem(name, amount, attrs)
        name = readVal(name)
        if type(name) ~= "string" or name == "" then
            return nil
        end
        attrs = type(attrs) == "table" and attrs or {}
        local item = {
            name = name,
            amount = tonumber(amount) or 1,
        }
        if item.amount <= 0 then
            item.amount = 1
        end
        local mutation = readVal(attrs.mutation)
        if type(mutation) == "string" and mutation ~= "" then
            item.mutation = mutation
        end
        local cfg = entryCfg(name)
        if type(cfg) == "table" and cfg.kind == "Unit" and type(cfg.chance) == "function" then
            local ok, n = pcall(cfg.chance, { mutation = item.mutation })
            item.chance = ok and tonumber(n) or nil
        end
        return item
    end

    local function collectOffer(src, own)
        local list = {}
        if type(src) ~= "table" then
            return list
        end
        local function push(name, amount, attrs)
            local item = tradeItem(name, amount, attrs)
            if item then
                list[#list + 1] = item
            end
        end
        if src[1] ~= nil then
            for i = 1, #src do
                local row = src[i]
                if type(row) == "table" then
                    push(row.name, row.amount, row.attributes)
                end
            end
            return list
        end
        for id, v in pairs(src) do
            if type(v) == "table" then
                local amt = v.amount or v
                push(v.name, amt, v.attributes)
            elseif own then
                local row = invById(id)
                if row then
                    push(row.name, v, row.attributes)
                end
            end
        end
        return list
    end

    local function offerBlock(title, items)
        local out = { "**" .. tostring(title) .. "**" }
        if type(items) ~= "table" or #items == 0 then
            out[#out + 1] = "│ -"
            return table.concat(out, "\n")
        end
        local maxN = 16
        local n = #items
        if n > maxN then
            n = maxN
        end
        for i = 1, n do
            local item = items[i]
            local line = tostring(item.amount) .. "x " .. tostring(item.name)
            if item.mutation then
                line = line .. " · " .. tostring(item.mutation)
            end
            if item.chance then
                line = line .. " · " .. fmtOneIn(item.chance)
            end
            out[#out + 1] = "│ " .. line
        end
        if #items > maxN then
            out[#out + 1] = "│ +" .. tostring(#items - maxN) .. " more"
        end
        return table.concat(out, "\n")
    end

    local function partnerTag(player)
        if typeof(player) == "Instance" then
            local name = player.DisplayName or player.Name or "?"
            local id = tonumber(player.UserId)
            if id then
                return name, tostring(id)
            end
            return name, "-"
        end
        return "?", "-"
    end

    local function cacheTrade(payload)
        if type(payload) ~= "table" then
            return
        end
        local name, uid = partnerTag(payload.partner)
        W._tradeSnap = {
            partner = name,
            userId = uid,
            gave = collectOffer(payload.ownOffer, true),
            got = collectOffer(payload.otherOffer, false),
        }
    end

    local function onTradeEnded(payload)
        if GEN ~= G.__AnimeDiceWebhookGen then
            return
        end
        local reason = type(payload) == "table" and tostring(payload.reason or "") or tostring(payload or "")
        if reason ~= "Completed" then
            W._tradeSnap = nil
            return
        end
        if W.trade ~= true then
            W._tradeSnap = nil
            return
        end
        local snap = W._tradeSnap
        W._tradeSnap = nil
        if type(snap) ~= "table" then
            return
        end
        if #(snap.gave or {}) == 0 and #(snap.got or {}) == 0 then
            return
        end
        local desc = panelBlock({
            panelSection("Partner", {
                { label = "Name", value = snap.partner or "?" },
                { label = "UserId", value = snap.userId or "-" },
            }),
            offerBlock("Gave", snap.gave),
            offerBlock("Got", snap.got),
        })
        sendEmbed("Trade", desc, snapFields("trade"), snap.partner or "Trade", webhookUrl(W.tradeUrl) ~= "" and W.tradeUrl or W.url)
    end

    local function sendAccount()
        if GEN ~= G.__AnimeDiceWebhookGen then
            return
        end
        if W.account ~= true then
            return
        end
        if webhookUrl(W.url) == "" then
            return
        end
        sendEmbed("Account", nil, snapFields("account"), "account")
    end

    local function ensureAccountLoop()
        if not accountLoop then
            accountLoop = Core.loop("webhook-account", {
                delay = clampDelay(W.delayMin) * 60,
                step = function()
                    if GEN ~= G.__AnimeDiceWebhookGen or W.account ~= true then
                        return
                    end
                    sendAccount()
                end,
            })
        else
            accountLoop.setDelay(clampDelay(W.delayMin) * 60)
        end
        local want = W.account == true and webhookUrl(W.url) ~= ""
        local on = accountLoop.enabled() == true
        if want and not on then
            accountLoop.setEnabled(true)
        elseif not want and on then
            accountLoop.setEnabled(false)
        end
    end

    function W.setUrl(text)
        W.url = tostring(text or "")
        paintIdle()
        ensureAccountLoop()
        return W.url
    end

    function W.setTradeUrl(text)
        W.tradeUrl = tostring(text or "")
        paintIdle()
        return W.tradeUrl
    end

    function W.setJp(on)
        W.jp = on == true
        paintIdle()
    end

    function W.setLs(on)
        W.ls = on == true
        paintIdle()
    end

    function W.setRoll(on)
        W.roll = on == true
        paintIdle()
    end

    function W.setFuse(on)
        W.fuse = on == true
        paintIdle()
    end

    function W.setTrade(on)
        W.trade = on == true
        paintIdle()
    end

    function W.setAccount(on)
        W.account = on == true
        paintIdle()
        ensureAccountLoop()
    end

    function W.setRollMin(text)
        W.rollMin = parseMin(text)
        return fmtMin(W.rollMin)
    end

    function W.setFuseMin(text)
        W.fuseMin = parseMin(text)
        return fmtMin(W.fuseMin)
    end

    function W.setDelay(n)
        W.delayMin = clampDelay(n)
        ensureAccountLoop()
        return W.delayMin
    end

    function W.Stop()
        W.jp = false
        W.ls = false
        W.roll = false
        W.fuse = false
        W.trade = false
        W.account = false
        W._fuseSnap = nil
        W._tradeSnap = nil
        W._token = (tonumber(W._token) or 0) + 1
        if accountLoop then
            accountLoop.setEnabled(false)
        end
        emit("Off", "muted", "off")
    end

    pcall(function()
        local Client = require(RS.Packages.Network.Client)
        if type(Client) ~= "table" or type(Client.GetFunction) ~= "function" then
            return
        end
        local current = Client.GetFunction
        Client.GetFunction = function(folder, name, ...)
            local fn = current(folder, name, ...)
            if name ~= "RollDice" or type(fn) ~= "function" then
                return fn
            end
            return function(...)
                local needSpin = W.jp == true or W.ls == true
                local before = needSpin and spinQueued(Core.data()) or nil
                local packed = table.pack(fn(...))
                if GEN == G.__AnimeDiceWebhookGen then
                    local spin = packed[5]
                    if needSpin and spin ~= JP and spin ~= LS and type(before) == "table" then
                        local after = spinQueued(Core.data())
                        if (tonumber(before[JP]) or 0) > (tonumber(after[JP]) or 0) then
                            spin = JP
                        elseif (tonumber(before[LS]) or 0) > (tonumber(after[LS]) or 0) then
                            spin = LS
                        end
                    end
                    pcall(onSpinRoll, packed[1], spin, packed[2])
                end
                return table.unpack(packed, 1, packed.n)
            end
        end
    end)

    pcall(function()
        local sig = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "FusingService"):GetSignal("Result")
        if not sig or type(sig.Connect) ~= "function" then
            return
        end
        W._fuseConn = sig:Connect(function(unit)
            if type(unit) == "table" then
                pcall(onFuse, unit)
            end
        end)
    end)

    pcall(function()
        local sig = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "FusingService"):GetSignal("Fuse")
        if type(sig) ~= "table" or type(sig.Fire) ~= "function" then
            return
        end
        if type(G.AnimeDiceWebhookFuseOrig) ~= "function" then
            G.AnimeDiceWebhookFuseOrig = sig.Fire
        end
        local orig = G.AnimeDiceWebhookFuseOrig
        sig.Fire = function(...)
            if GEN == G.__AnimeDiceWebhookGen then
                local a, b, c, d = ...
                if type(a) == "string" then
                    pcall(cacheFuseMats, a, b, c)
                else
                    pcall(cacheFuseMats, b, c, d)
                end
            end
            return orig(...)
        end
    end)

    pcall(function()
        local re = RS.Network.FusingService.RE.Fuse
        if not re or type(hookfunction) ~= "function" then
            return
        end
        if type(restorefunction) == "function" then
            pcall(restorefunction, re.FireServer)
        end
        local original
        original = hookfunction(re.FireServer, function(...)
            if GEN == G.__AnimeDiceWebhookGen then
                local a, b, c, d = ...
                if typeof(a) == "Instance" then
                    pcall(cacheFuseMats, b, c, d)
                else
                    pcall(cacheFuseMats, a, b, c)
                end
            end
            return original(...)
        end)
    end)

    pcall(function()
        local sig = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "TradeService"):GetSignal("TradeEvent")
        if not sig or type(sig.Connect) ~= "function" then
            return
        end
        W._tradeConn = sig:Connect(function(kind, payload)
            if GEN ~= G.__AnimeDiceWebhookGen then
                return
            end
            if kind == "Updated" then
                pcall(cacheTrade, payload)
            elseif kind == "Ended" then
                pcall(onTradeEnded, payload)
            end
        end)
    end)

    Core.section({
        main = "misc",
        mainLabel = "MISC",
        mainOrder = 2,
        sub = "webhook",
        subLabel = "Webhook",
        subOrder = 8,
        order = 1,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Discord Webhook",
                expanded = false,
                status = {
                    id = "misc.webhook.status",
                    persist = false,
                    value = W._status.text,
                    style = W._status.style,
                    detail = W._status.detail,
                },
            })
            statusApi = api
            local group = ui:CreateGroup(body)
            ui:CreateRowInput(group, {
                id = "misc.webhook.url",
                label = "Webhook URL",
                persist = true,
                initial = W.url,
                clearOnFocus = false,
                placeholder = "https://discord.com/api/webhooks/...",
                hintText = "Discord channel webhook. Do not share.",
                onChanged = function(text)
                    W.setUrl(text)
                end,
            })
            ui:CreateRowToggle(group, {
                id = "misc.webhook.jp",
                label = "Jackpot Spin",
                persist = true,
                initial = W.jp == true,
                onChanged = function(on)
                    W.setJp(on == true)
                end,
            })
            ui:CreateRowToggle(group, {
                id = "misc.webhook.ls",
                label = "Lucky Spin",
                persist = true,
                initial = W.ls == true,
                onChanged = function(on)
                    W.setLs(on == true)
                end,
            })
            _, _, _, rollMinApi = ui:CreateRowInput(group, {
                id = "misc.webhook.rollMin",
                label = "Min 1-in roll",
                persist = true,
                initial = fmtMin(W.rollMin),
                clearOnFocus = false,
                placeholder = "0",
                hintText = "1k / 1m / 1b. 0 = all matching rolls.",
                onChanged = function(text)
                    local shown = W.setRollMin(text)
                    if rollMinApi and type(rollMinApi.set) == "function" then
                        pcall(rollMinApi.set, shown, true)
                    end
                end,
            })
            ui:CreateRowToggle(group, {
                id = "misc.webhook.roll",
                label = "Roll",
                persist = true,
                initial = W.roll == true,
                onChanged = function(on)
                    W.setRoll(on == true)
                end,
            })
            _, _, _, fuseMinApi = ui:CreateRowInput(group, {
                id = "misc.webhook.fuseMin",
                label = "Min 1-in fuse",
                persist = true,
                initial = fmtMin(W.fuseMin),
                clearOnFocus = false,
                placeholder = "0",
                hintText = "1k / 1m / 1b. 0 = all fuse.",
                onChanged = function(text)
                    local shown = W.setFuseMin(text)
                    if fuseMinApi and type(fuseMinApi.set) == "function" then
                        pcall(fuseMinApi.set, shown, true)
                    end
                end,
            })
            ui:CreateRowToggle(group, {
                id = "misc.webhook.fuse",
                label = "Fuse",
                persist = true,
                initial = W.fuse == true,
                onChanged = function(on)
                    W.setFuse(on == true)
                end,
            })
            ui:CreateRowInput(group, {
                id = "misc.webhook.tradeUrl",
                label = "Trade webhook",
                persist = true,
                initial = W.tradeUrl,
                clearOnFocus = false,
                placeholder = "https://discord.com/api/webhooks/...",
                hintText = "Trade channel only. Empty = use Webhook URL above.",
                onChanged = function(text)
                    W.setTradeUrl(text)
                end,
            })
            ui:CreateRowToggle(group, {
                id = "misc.webhook.trade",
                label = "Trade",
                persist = true,
                initial = W.trade == true,
                onChanged = function(on)
                    W.setTrade(on == true)
                end,
            })
            ui:CreateRowSlider(group, {
                id = "misc.webhook.account.delay",
                label = "Account delay",
                min = DELAY_MIN,
                max = DELAY_MAX,
                step = 1,
                initial = W.delayMin,
                suffix = "m",
                persist = true,
                onChanged = function(n)
                    W.setDelay(n)
                end,
            })
            ui:CreateRowToggle(group, {
                id = "misc.webhook.account",
                label = "Account",
                persist = true,
                initial = W.account == true,
                onChanged = function(on)
                    W.setAccount(on == true)
                end,
            })
        end,
    })

    Core.onSync(function(values)
        if values["misc.webhook.url"] ~= nil then
            W.setUrl(values["misc.webhook.url"])
        end
        if values["misc.webhook.tradeUrl"] ~= nil then
            W.setTradeUrl(values["misc.webhook.tradeUrl"])
        end
        if values["misc.webhook.rollMin"] ~= nil then
            local shown = W.setRollMin(values["misc.webhook.rollMin"])
            if rollMinApi and type(rollMinApi.set) == "function" then
                pcall(rollMinApi.set, shown, true)
            end
        end
        if values["misc.webhook.fuseMin"] ~= nil then
            local shown = W.setFuseMin(values["misc.webhook.fuseMin"])
            if fuseMinApi and type(fuseMinApi.set) == "function" then
                pcall(fuseMinApi.set, shown, true)
            end
        end
        if values["misc.webhook.account.delay"] ~= nil then
            W.setDelay(values["misc.webhook.account.delay"])
        end
        W.setJp(flagOn(values["misc.webhook.jp"]))
        W.setLs(flagOn(values["misc.webhook.ls"]))
        W.setRoll(flagOn(values["misc.webhook.roll"]))
        W.setFuse(flagOn(values["misc.webhook.fuse"]))
        W.setTrade(flagOn(values["misc.webhook.trade"]))
        W.setAccount(flagOn(values["misc.webhook.account"]))
    end)
end
 end, required = true, feature = true },
    { key = "InfoTopRolls", name = "Info Top 100", factory = function() -- INFO → Top 100.
-- 100 hasil roll paling langka sesi ini. Insert cek bawah list. Tanpa scan tas.

return function(Core)
    local G = Core.env()
    local listBody
    local headDetail
    local emptyLabel
    local cards = {}
    local lastGen = -1

    local function compact(n)
        return Core.compact(n)
    end

    local function corner(inst, radius)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius or 8)
        c.Parent = inst
    end

    local function applyGradient(label, gradient)
        local old = label:FindFirstChild("RarityGrad")
        if old then
            old:Destroy()
        end
        if typeof(gradient) ~= "ColorSequence" then
            label.TextColor3 = Color3.fromRGB(232, 232, 236)
            return
        end
        label.TextColor3 = Color3.new(1, 1, 1)
        local grad = Instance.new("UIGradient")
        grad.Name = "RarityGrad"
        grad.Color = gradient
        grad.Rotation = 0
        grad.Parent = label
    end

    local function unitTitle(unit)
        local name = tostring(unit and unit.name or "-")
        local mutation = unit and unit.mutation
        if type(mutation) == "string" and mutation ~= "" then
            return name .. "  " .. mutation
        end
        return name
    end

    local function fillGradient(unit)
        if type(unit) ~= "table" or unit.gradient ~= nil then
            return unit and unit.gradient
        end
        pcall(function()
            local cfg = require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryRegistry).getEntryConfig(unit.name)
            if type(cfg) ~= "table" then
                return
            end
            if typeof(cfg.gradient) == "ColorSequence" then
                unit.gradient = cfg.gradient
                return
            end
            local rarity = cfg.rarity
            if type(cfg.getRarity) == "function" then
                local ok, value = pcall(cfg.getRarity, { mutation = unit.mutation })
                if ok and value ~= nil then
                    rarity = value
                end
            end
            if rarity then
                local info = require(game:GetService("ReplicatedStorage").Framework.Other.Rarities).Get(rarity)
                if type(info) == "table" then
                    unit.gradient = info.gradient
                end
            end
        end)
        if unit.gradient == nil then
            unit.gradient = false
        end
        return unit.gradient
    end

    local function makeRow(parent, order)
        local row = Instance.new("Frame")
        row.Name = "TopRoll"
        row.BackgroundTransparency = 1
        row.BorderSizePixel = 0
        row.Size = UDim2.new(1, 0, 0, 18)
        row.LayoutOrder = order
        row.Parent = parent

        local rank = Instance.new("TextLabel")
        rank.Name = "Rank"
        rank.BackgroundTransparency = 1
        rank.Size = UDim2.new(0, 28, 1, 0)
        rank.Font = Enum.Font.Gotham
        rank.TextSize = 12
        rank.TextXAlignment = Enum.TextXAlignment.Left
        rank.TextColor3 = Color3.fromRGB(150, 154, 162)
        rank.Parent = row

        local name = Instance.new("TextLabel")
        name.Name = "Title"
        name.BackgroundTransparency = 1
        name.Position = UDim2.new(0, 32, 0, 0)
        name.Size = UDim2.new(1, -110, 1, 0)
        name.Font = Enum.Font.GothamMedium
        name.TextSize = 12
        name.TextXAlignment = Enum.TextXAlignment.Left
        name.TextTruncate = Enum.TextTruncate.AtEnd
        name.Parent = row

        local chance = Instance.new("TextLabel")
        chance.Name = "Chance"
        chance.BackgroundTransparency = 1
        chance.Position = UDim2.new(1, -74, 0, 0)
        chance.Size = UDim2.new(0, 74, 1, 0)
        chance.Font = Enum.Font.Gotham
        chance.TextSize = 12
        chance.TextXAlignment = Enum.TextXAlignment.Right
        chance.TextColor3 = Color3.fromRGB(186, 190, 198)
        chance.TextTruncate = Enum.TextTruncate.AtEnd
        chance.Parent = row

        return { frame = row, rank = rank, name = name, chance = chance }
    end

    local function paintRow(card, unit, order)
        card.frame.Visible = true
        card.frame.LayoutOrder = order
        card.rank.Text = tostring(order)
        card.name.Text = unitTitle(unit)
        applyGradient(card.name, fillGradient(unit))
        card.chance.Text = unit.chance and ("1/" .. compact(unit.chance)) or "-"
    end

    local function paint()
        if not Core.uiIs("info", "top") then
            return
        end
        if not listBody or not listBody.Parent then
            return
        end
        local session = G.AnimeDiceSession
        local rows = type(session) == "table" and session.topRolls or nil
        if type(rows) ~= "table" then
            rows = {}
        end
        local gen = type(session) == "table" and tonumber(session.topGen) or 0
        if gen == lastGen and #cards > 0 then
            return
        end
        lastGen = gen
        local count = #rows
        if headDetail and headDetail.Parent then
            headDetail.Text = tostring(count) .. " / 100"
        end
        if emptyLabel and emptyLabel.Parent then
            emptyLabel.Visible = count == 0
        end
        for i = 1, count do
            local card = cards[i]
            if not card or not card.frame or not card.frame.Parent then
                card = makeRow(listBody, i)
                cards[i] = card
            end
            paintRow(card, rows[i], i)
        end
        for i = count + 1, #cards do
            local card = cards[i]
            if card and card.frame and card.frame.Parent then
                card.frame.Visible = false
            end
        end
    end

    local loop = Core.loop("info_top_rolls", {
        delay = 5,
        step = paint,
    })
    loop.setEnabled(true)

    Core.section({
        main = "info",
        mainLabel = "INFO",
        mainOrder = 0,
        sub = "top",
        subLabel = "Top 100",
        subOrder = 2,
        order = 1,
        build = function(ui)
            cards = {}
            lastGen = -1
            listBody = nil
            headDetail = nil
            emptyLabel = nil

            local stack = Instance.new("Frame")
            stack.Name = "TopRollStack"
            stack.BackgroundTransparency = 1
            stack.BorderSizePixel = 0
            stack.Size = UDim2.new(1, 0, 0, 0)
            stack.AutomaticSize = Enum.AutomaticSize.Y
            stack.LayoutOrder = 1
            stack.Parent = ui.content

            local col = Instance.new("Frame")
            col.Name = "TopRollColumn"
            col.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
            col.BackgroundTransparency = 0.2
            col.BorderSizePixel = 0
            col.Size = UDim2.new(1, 0, 0, 44)
            col.AutomaticSize = Enum.AutomaticSize.Y
            col.Parent = stack
            corner(col, 10)
            Core.panelStroke(col, Color3.fromRGB(255, 170, 90))

            local head = Instance.new("TextLabel")
            head.Name = "Head"
            head.BackgroundTransparency = 1
            head.Size = UDim2.new(0.52, -8, 0, 18)
            head.Position = UDim2.new(0, 8, 0, 6)
            head.Font = Enum.Font.GothamBold
            head.TextSize = 12
            head.TextXAlignment = Enum.TextXAlignment.Left
            head.TextColor3 = Color3.fromRGB(255, 170, 90)
            head.Text = "TOP 100 ROLL"
            head.Parent = col

            headDetail = Instance.new("TextLabel")
            headDetail.Name = "HeadDetail"
            headDetail.BackgroundTransparency = 1
            headDetail.Size = UDim2.new(0.48, -8, 0, 18)
            headDetail.Position = UDim2.new(0.52, 0, 0, 6)
            headDetail.Font = Enum.Font.Gotham
            headDetail.TextSize = 11
            headDetail.TextXAlignment = Enum.TextXAlignment.Right
            headDetail.TextColor3 = Color3.fromRGB(150, 154, 162)
            headDetail.Text = "0 / 100"
            headDetail.Parent = col

            local body = Instance.new("Frame")
            body.Name = "Body"
            body.BackgroundTransparency = 1
            body.Position = UDim2.new(0, 8, 0, 26)
            body.Size = UDim2.new(1, -16, 0, 0)
            body.AutomaticSize = Enum.AutomaticSize.Y
            body.Parent = col
            local list = Instance.new("UIListLayout")
            list.FillDirection = Enum.FillDirection.Vertical
            list.SortOrder = Enum.SortOrder.LayoutOrder
            list.Padding = UDim.new(0, 1)
            list.Parent = body
            local pad = Instance.new("UIPadding")
            pad.PaddingBottom = UDim.new(0, 8)
            pad.Parent = body

            emptyLabel = Instance.new("TextLabel")
            emptyLabel.Name = "Empty"
            emptyLabel.BackgroundTransparency = 1
            emptyLabel.Size = UDim2.new(1, 0, 0, 18)
            emptyLabel.LayoutOrder = 0
            emptyLabel.Font = Enum.Font.Gotham
            emptyLabel.TextSize = 12
            emptyLabel.TextXAlignment = Enum.TextXAlignment.Left
            emptyLabel.TextColor3 = Color3.fromRGB(150, 154, 162)
            emptyLabel.Text = "No rolls yet"
            emptyLabel.Parent = body

            listBody = body
            paint()
            Core.kickScroll(ui.content)
        end,
    })
end
 end, required = true, feature = true },
    { key = "InfoUnits", name = "Info Units", factory = function() -- INFO → Units.
-- All owned unit details, same card theme as Info. Refresh every 5s.

return function(Core)
    local RS = game:GetService("ReplicatedStorage")
    local G = Core.env()
    local Earn = Core.unitEarn or G.AnimeDiceUnitEarn
    local listBody
    local headDetail
    local cards = {}
    local emptyLabel
    local earnFilter = 0
    local shownUnits = {}

    local function compact(n)
        return Core.compact(n)
    end

    local function parseEarn(text)
        if type(Earn) == "table" and type(Earn.parseCompact) == "function" then
            return tonumber(Earn.parseCompact(text)) or 0
        end
        text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
        if text == "" then
            return 0
        end
        local n = tonumber(text)
        if n then
            return math.max(0, n)
        end
        local ok, value = pcall(function()
            return require(RS.Packages.NumberFormatter).ParseCompact(text)
        end)
        return ok and tonumber(value) or 0
    end

    local function readValue(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function field(source, key)
        if type(source) ~= "table" then
            return nil
        end
        return readValue(source[key])
    end

    local function gradientColor(gradient)
        if typeof(gradient) == "ColorSequence" and gradient.Keypoints[1] then
            return gradient.Keypoints[1].Value
        end
        return Color3.fromRGB(232, 232, 236)
    end

    local function applyGradient(label, gradient)
        local old = label:FindFirstChild("RarityGrad")
        if old then
            old:Destroy()
        end
        if typeof(gradient) ~= "ColorSequence" then
            label.TextColor3 = Color3.fromRGB(232, 232, 236)
            return
        end
        label.TextColor3 = Color3.new(1, 1, 1)
        local grad = Instance.new("UIGradient")
        grad.Name = "RarityGrad"
        grad.Color = gradient
        grad.Rotation = 0
        grad.Parent = label
    end

    local function corner(inst, radius)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius or 8)
        c.Parent = inst
    end

    local function plottedIds(data)
        local out = {}
        for _, slot in ipairs(Core.slots()) do
            local getter = data.Slots and data.Slots[tostring(slot)]
            if getter ~= nil then
                local ok, row = pcall(getter)
                if ok and type(row) == "table" then
                    local id = field(row, "unitId")
                    if type(id) == "string" and id ~= "" then
                        out[id] = true
                    end
                end
            end
        end
        return out
    end

    local function towerIds(data)
        local out = {}
        pcall(function()
            local team = data.TowerTeam
            if type(team) ~= "table" then
                return
            end
            for i = 1, 4 do
                local getter = team[i]
                local id
                if type(getter) == "function" then
                    id = getter()
                else
                    id = readValue(getter)
                end
                if type(id) == "string" and id ~= "" then
                    out[id] = true
                end
            end
        end)
        return out
    end

    local function profileUnit(item, key)
        if type(item) ~= "table" then
            return nil
        end
        local name = readValue(item.name)
        if type(name) ~= "string" or name == "" then
            return nil
        end
        local ok, cfg = pcall(function()
            return require(RS.Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
        end)
        if not ok or type(cfg) ~= "table" or cfg.kind ~= "Unit" then
            return nil
        end
        local attrs = readValue(item.attributes)
        if type(attrs) ~= "table" then
            attrs = item
        end
        local opts = {
            mutation = field(attrs, "mutation"),
            trait = field(attrs, "trait"),
            grade = field(attrs, "grade"),
            level = field(attrs, "level"),
        }
        if type(opts.mutation) ~= "string" or opts.mutation == "" then
            opts.mutation = nil
        end
        local chance
        if type(cfg.chance) == "function" then
            local okChance, value = pcall(cfg.chance, opts)
            chance = okChance and tonumber(value) or nil
        end
        local income
        if type(cfg.income) == "function" then
            local okIncome, value = pcall(cfg.income, opts)
            income = okIncome and tonumber(value) or nil
        end
        local damage
        if type(cfg.damage) == "function" then
            local okDmg, value = pcall(cfg.damage, opts)
            damage = okDmg and tonumber(value) or nil
        end
        local health
        if type(cfg.health) == "function" then
            local okHp, value = pcall(cfg.health, opts)
            health = okHp and tonumber(value) or nil
        end
        local rarity
        if type(cfg.getRarity) == "function" then
            local okRarity, value = pcall(cfg.getRarity, opts)
            if okRarity and value ~= nil then
                rarity = tostring(value)
            end
        end
        local gradient
        if rarity then
            local okInfo, info = pcall(function()
                return require(RS.Framework.Other.Rarities).Get(rarity)
            end)
            if okInfo and type(info) == "table" then
                gradient = info.gradient
            end
        end
        local title = name
        if type(opts.mutation) == "string" and opts.mutation ~= "" then
            title = name .. "  " .. opts.mutation
        end
        return {
            key = tostring(key or ""),
            name = name,
            title = title,
            mutation = opts.mutation,
            trait = opts.trait,
            grade = opts.grade,
            quirk = field(attrs, "quirk"),
            level = opts.level,
            chance = chance,
            income = income,
            damage = damage,
            health = health,
            rarity = rarity,
            gradient = gradient,
            locked = field(attrs, "locked") == true,
            amount = tonumber(readValue(item.amount)) or 1,
        }
    end

    local function collectUnits()
        local data = Core.data()
        local inv
        local okInv = pcall(function()
            inv = data.Inventory()
        end)
        if not okInv or type(inv) ~= "table" then
            return {}, 0
        end
        local plotted = plottedIds(data)
        local tower = towerIds(data)
        local list = {}
        for id, item in pairs(inv) do
            local unit = profileUnit(item, id)
            if unit then
                local key = unit.key
                unit.plot = plotted[key] == true or plotted[id] == true
                unit.tower = tower[key] == true or tower[id] == true
                list[#list + 1] = unit
            end
        end
        table.sort(list, function(a, b)
            local ac = tonumber(a.chance) or -1
            local bc = tonumber(b.chance) or -1
            if ac == bc then
                if a.name == b.name then
                    return a.key < b.key
                end
                return a.name < b.name
            end
            return ac > bc
        end)
        return list, #list
    end

    local function storageCap()
        local cap = 0
        pcall(function()
            cap = tonumber(require(RS.Framework.Features.Buffs.BuffController).GetBuff("Unit Storage")) or 0
        end)
        return cap
    end

    local function detailText(unit)
        local top = {}
        if unit.rarity and unit.rarity ~= "" then
            top[#top + 1] = unit.rarity
        end
        if unit.chance then
            top[#top + 1] = "1 in " .. compact(unit.chance)
        end
        if unit.income then
            top[#top + 1] = compact(unit.income) .. "/s"
        end
        if type(unit.trait) == "string" and unit.trait ~= "" then
            top[#top + 1] = unit.trait
        end
        if unit.grade ~= nil and tostring(unit.grade) ~= "" then
            top[#top + 1] = tostring(unit.grade)
        end
        if type(unit.quirk) == "string" and unit.quirk ~= "" and unit.quirk ~= "None" then
            top[#top + 1] = unit.quirk
        end
        if tonumber(unit.level) then
            top[#top + 1] = "Lv " .. tostring(unit.level)
        end
        local bottom = {}
        if unit.damage then
            bottom[#bottom + 1] = "DMG " .. compact(unit.damage)
        end
        if unit.health then
            bottom[#bottom + 1] = "HP " .. compact(unit.health)
        end
        if unit.plot then
            bottom[#bottom + 1] = "Plot"
        end
        if unit.tower then
            bottom[#bottom + 1] = "Tower"
        end
        if unit.locked then
            bottom[#bottom + 1] = "Lock"
        end
        if (tonumber(unit.amount) or 1) > 1 then
            bottom[#bottom + 1] = "x" .. tostring(unit.amount)
        end
        local line = #top > 0 and table.concat(top, "  ·  ") or "-"
        if #bottom > 0 then
            line = line .. "\n" .. table.concat(bottom, "  ·  ")
        end
        return line
    end

    local function makeCard(parent, order)
        local card = Instance.new("Frame")
        card.Name = "UnitCard"
        card.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        card.BackgroundTransparency = 0.94
        card.BorderSizePixel = 0
        card.Size = UDim2.new(1, 0, 0, 0)
        card.AutomaticSize = Enum.AutomaticSize.Y
        card.LayoutOrder = order
        card.Parent = parent
        corner(card, 8)
        local pad = Instance.new("UIPadding")
        pad.PaddingBottom = UDim.new(0, 8)
        pad.Parent = card

        local bar = Instance.new("Frame")
        bar.Name = "Bar"
        bar.BackgroundColor3 = Color3.fromRGB(90, 90, 90)
        bar.BorderSizePixel = 0
        bar.Size = UDim2.new(0, 3, 1, -8)
        bar.Position = UDim2.new(0, 6, 0, 4)
        bar.Parent = card
        corner(bar, 2)

        local title = Instance.new("TextLabel")
        title.Name = "Title"
        title.BackgroundTransparency = 1
        title.Position = UDim2.new(0, 16, 0, 6)
        title.Size = UDim2.new(1, -22, 0, 16)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 14
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.TextTruncate = Enum.TextTruncate.AtEnd
        title.Text = "-"
        title.Parent = card

        local detail = Instance.new("TextLabel")
        detail.Name = "Detail"
        detail.BackgroundTransparency = 1
        detail.Position = UDim2.new(0, 16, 0, 24)
        detail.Size = UDim2.new(1, -22, 0, 0)
        detail.AutomaticSize = Enum.AutomaticSize.Y
        detail.Font = Enum.Font.Gotham
        detail.TextSize = 12
        detail.TextXAlignment = Enum.TextXAlignment.Left
        detail.TextYAlignment = Enum.TextYAlignment.Top
        detail.TextColor3 = Color3.fromRGB(186, 190, 198)
        detail.TextWrapped = true
        detail.Text = ""
        detail.Parent = card

        return {
            frame = card,
            title = title,
            detail = detail,
            bar = bar,
        }
    end

    local function paintCard(card, unit, order)
        card.frame.Visible = true
        card.frame.LayoutOrder = order
        card.title.Text = unit.title or unit.name or "-"
        applyGradient(card.title, unit.gradient)
        card.bar.BackgroundColor3 = gradientColor(unit.gradient)
        card.detail.Text = detailText(unit)
    end

    local function paint()
        if not Core.uiIs("info", "units") then
            return
        end
        if not listBody or not listBody.Parent then
            return
        end
        local units, total = collectUnits()
        local shown = {}
        for i = 1, #units do
            local unit = units[i]
            local earn = tonumber(unit.income) or 0
            if earnFilter <= 0 or earn + 1e-9 >= earnFilter then
                shown[#shown + 1] = unit
            end
        end
        local count = #shown
        shownUnits = shown
        if headDetail and headDetail.Parent then
            local cap = storageCap()
            if earnFilter > 0 then
