                        lines[#lines + 1] = (unit.title or unit.name or "-") .. "\n" .. detailText(unit)
                    end
                    local label = "Copy"
                    if #lines == 0 then
                        label = "Empty"
                    elseif copyText(table.concat(lines, "\n\n")) then
                        label = "Copied"
                    else
                        label = "Failed"
                    end
                    if copyApi then
                        copyApi.set(label)
                        task.delay(1.2, function()
                            if copyApi then
                                copyApi.set("Copy")
