 end, required = true, feature = true },
    { key = "Rejoin", name = "Rejoin", factory = function() -- MISC -> Rejoin.
-- Anti AFK, Auto Reconnect, Rejoin Now. Pola Ride A Pet.

return function(Core)
    local G = Core.env()
    local old = G.AnimeDiceRejoin
    if type(old) == "table" then
        if type(old.setAntiAfk) == "function" then
            pcall(old.setAntiAfk, false)
        end
        if type(old.setReconnect) == "function" then
            pcall(old.setReconnect, false)
        end
        if type(old.setEvery) == "function" then
            pcall(old.setEvery, false)
        end
        if type(old.setEnabled) == "function" then
            pcall(old.setEnabled, false)
        end
    end

    local Players = game:GetService("Players")
    local TeleportService = game:GetService("TeleportService")
    local GuiService = game:GetService("GuiService")
    local LP = Core.player() or Players.LocalPlayer

    local EVERY_MIN = 10
    local EVERY_MAX = 126000

    local Rejoin = {
        antiAfk = true,
        reconnect = false,
        every = false,
        everyDelay = EVERY_MIN,
    }
    local busy = false
    local afkGen = 0
    local reconnectGen = 0
    local everyGen = 0
    local afkIdleConn
    local afkWatch
    local statusApi
    Rejoin.allowTeleport = false

    local function jobLabel()
        local jobId = tostring(game.JobId or "")
        if jobId == "" then
            return "no job"
        end
        if #jobId > 8 then
            return string.sub(jobId, 1, 8)
        end
        return jobId
    end

    local function setStatus(value, style, detail)
        local api = statusApi
        if type(api) ~= "table" then
            return
        end
        pcall(function()
            api.set(value)
            if api.setStyle then
                api.setStyle(style or "muted")
            end
            if api.setDetail then
                api.setDetail(detail or "")
            end
        end)
    end

    local function paintStatus(value, style)
        local bits = {}
        if Rejoin.antiAfk then
            bits[#bits + 1] = "AFK"
        end
        if Rejoin.reconnect then
            bits[#bits + 1] = "reconnect"
        end
        if Rejoin.every then
            bits[#bits + 1] = "every " .. tostring(Rejoin.everyDelay) .. "s"
        end
        setStatus(value or (Rejoin.antiAfk and "Armed" or "Idle"), style or (Rejoin.antiAfk and "success" or "muted"), table.concat(bits, " · "))
    end

    local function nudgeCamera()
        pcall(function()
            local cam = workspace.CurrentCamera
            if cam then
                cam.CFrame = cam.CFrame * CFrame.Angles(0, 0.00015, 0)
            end
        end)
    end

    local function silenceIdleKick()
        if typeof(getconnections) ~= "function" or not LP then
            return false
        end
        local ok, conns = pcall(getconnections, LP.Idled)
        if not ok or type(conns) ~= "table" then
            return false
        end
        local n = 0
        for _, conn in pairs(conns) do
            if conn ~= nil then
                local disabled = pcall(function()
                    conn.Enabled = false
                end)
                disabled = pcall(function()
                    conn:Disable()
                end) or disabled
                if not disabled then
                    disabled = pcall(function()
                        conn:Disconnect()
                    end)
                end
                if disabled then
                    n = n + 1
                end
            end
        end
        return n > 0
    end

    local function killGameAfkHop()
        pcall(function()
            local ps = LP and LP:FindFirstChild("PlayerScripts")
            if not ps then
                return
            end
            local s = ps:FindFirstChild("AFK")
            if s and s:IsA("LocalScript") then
                s.Disabled = true
            end
        end)
    end

    if G.AnimeDiceBlockAfkTeleport ~= true then
        pcall(function()
            if typeof(hookfunction) ~= "function" then
                return
            end
            local ts = TeleportService
            local oldTeleport = ts.Teleport
            hookfunction(oldTeleport, function(...)
                local current = ((getgenv and getgenv()) or _G).AnimeDiceRejoin
                if type(current) == "table" and current.antiAfk == true and current.allowTeleport ~= true then
                    return
                end
                return oldTeleport(...)
            end)
            G.AnimeDiceBlockAfkTeleport = true
        end)
    end

    function Rejoin.setAntiAfk(on)
        on = on == true
        Rejoin.antiAfk = on
        afkGen = afkGen + 1
        if afkIdleConn then
            pcall(function()
                afkIdleConn:Disconnect()
            end)
            afkIdleConn = nil
        end
        if afkWatch then
            pcall(function()
                afkWatch:Disconnect()
            end)
            afkWatch = nil
        end
        if not on then
            paintStatus()
            return
        end
        killGameAfkHop()
        silenceIdleKick()
        local gen = afkGen
        pcall(function()
            local ps = LP and LP:FindFirstChild("PlayerScripts")
            if ps then
                afkWatch = ps.ChildAdded:Connect(function(child)
                    if Rejoin.antiAfk == true and tostring(child.Name) == "AFK" then
                        pcall(function()
