                if Rejoin.antiAfk == true and afkGen == gen then
                    silenceIdleKick()
                    nudgeCamera()
                end
            end)
        end)
        task.spawn(function()
            while Rejoin.antiAfk and afkGen == gen do
                killGameAfkHop()
                silenceIdleKick()
                nudgeCamera()
                task.wait(60)
            end
        end)
        paintStatus()
    end

    local vipServer = false
    pcall(function()
        local id = game.PrivateServerId
        vipServer = type(id) == "string" and id ~= ""
    end)

    local function isPrivateServer()
        return vipServer
    end

    local function teleportPlace(placeId)
        return pcall(function()
            TeleportService:Teleport(placeId, LP)
        end)
    end

    local function teleportSame(placeId, jobId)
        return pcall(function()
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
        end)
    end

    function Rejoin.now(anyServer)
        if busy then
            return false, "busy"
        end
        local placeId = tonumber(game.PlaceId)
        if not placeId or placeId <= 0 or not LP then
            return false, "place id invalid"
        end
        busy = true
        Rejoin.allowTeleport = true
        local jobId = tostring(game.JobId or "")
        local ps = isPrivateServer()
        -- VIP/PS: JobId / TeleportToPlaceInstance = Unauthorized. PlaceId saja yang lolos.
        local usePlaceOnly = anyServer == true or ps or jobId == ""
        local ok, err
        if usePlaceOnly then
            ok, err = teleportPlace(placeId)
        else
            ok, err = teleportSame(placeId, jobId)
            if not ok then
                ok, err = teleportPlace(placeId)
            end
        end
        task.spawn(function()
            local failConn
            pcall(function()
                failConn = TeleportService.TeleportInitFailed:Connect(function(player)
                    if player ~= LP or not busy then
                        return
                    end
                    Rejoin.allowTeleport = true
                    teleportPlace(placeId)
                end)
            end)
            for _ = 1, 10 do
                if not LP or not LP.Parent then
                    break
                end
                task.wait(0.55)
                if not LP or not LP.Parent then
                    break
                end
                Rejoin.allowTeleport = true
                if usePlaceOnly then
                    teleportPlace(placeId)
                else
                    local sameOk = teleportSame(placeId, jobId)
                    if not sameOk then
                        teleportPlace(placeId)
                    end
                end
            end
            if failConn then
                pcall(function()
                    failConn:Disconnect()
                end)
            end
            busy = false
            Rejoin.allowTeleport = false
        end)
        if ok then
            return true, ps and "private server" or jobLabel()
        end
        return false, tostring(err)
    end

    local function clampEveryDelay(n)
        n = tonumber(n) or EVERY_MIN
        if n < EVERY_MIN then
            n = EVERY_MIN
        elseif n > EVERY_MAX then
            n = EVERY_MAX
        end
        return math.floor(n + 0.5)
    end

    function Rejoin.setEveryDelay(n)
        Rejoin.everyDelay = clampEveryDelay(n)
        paintStatus()
        return Rejoin.everyDelay
    end

    function Rejoin.setEvery(on)
        on = on == true
        Rejoin.every = on
        everyGen = everyGen + 1
        paintStatus()
        if not on then
            return
        end
        local gen = everyGen
        task.spawn(function()
            while Rejoin.every and everyGen == gen do
                local waitSec = Rejoin.everyDelay
                local elapsed = 0
                while elapsed < waitSec and Rejoin.every and everyGen == gen do
                    local slice = math.min(1, waitSec - elapsed)
                    task.wait(slice)
                    elapsed = elapsed + slice
                    waitSec = Rejoin.everyDelay
                end
                if Rejoin.every and everyGen == gen then
                    setStatus("Teleporting", "live", "every " .. tostring(Rejoin.everyDelay) .. "s")
                    Rejoin.now()
                end
            end
        end)
    end

    local function looksLikeDc(msg)
        msg = string.lower(tostring(msg or ""))
        if msg == "" then
            return false
        end
        return msg:find("reconnect", 1, true)
            or msg:find("disconnect", 1, true)
            or msg:find("lost connection", 1, true)
            or msg:find("please rejoin", 1, true)
            or msg:find("idle", 1, true)
            or msg:find("inactive", 1, true)
            or msg:find("kicked", 1, true)
            or msg:find("timed out", 1, true)
            or msg:find("timeout", 1, true)
            or msg:find("277", 1, true)
            or msg:find("278", 1, true)
            or msg:find("279", 1, true)
            or msg:find("280", 1, true)
    end

    local function promptIsIdle(msg)
        msg = string.lower(tostring(msg or ""))
        return msg:find("idle", 1, true) or msg:find("inactive", 1, true) or msg:find("279", 1, true)
    end

    local function tryReconnect(reason)
        if Rejoin.reconnect ~= true then
            return
        end
        local anyServer = reason == "idle" or reason == "teleport_failed"
        task.delay(1.2, function()
            if Rejoin.reconnect ~= true then
                return
            end
            setStatus("Reconnecting", "live", anyServer and "new server" or "same server")
            Rejoin.now(anyServer)
        end)
    end

    function Rejoin.setReconnect(on)
        on = on == true
        Rejoin.reconnect = on
        reconnectGen = reconnectGen + 1
        paintStatus()
        if not on then
            return
        end
        local gen = reconnectGen
        task.spawn(function()
            while Rejoin.reconnect and reconnectGen == gen do
                local hit = false
                local idle = false
                local function inspect(msg)
                    if looksLikeDc(msg) then
                        hit = true
                        if promptIsIdle(msg) then
                            idle = true
                        end
                    end
                end
                pcall(function()
                    inspect(GuiService.ErrorMessage)
                end)
                pcall(function()
                    if typeof(GuiService.GetErrorMessage) == "function" then
                        inspect(GuiService:GetErrorMessage())
                    end
                end)
                if not hit then
                    pcall(function()
                        local prompt = game:GetService("CoreGui"):FindFirstChild("RobloxPromptGui")
                        if not prompt then
                            return
                        end
                        for _, d in ipairs(prompt:GetDescendants()) do
                            if d:IsA("TextLabel") or d:IsA("TextButton") then
                                inspect(d.Text)
                                if hit then
                                    break
                                end
                            end
                        end
                    end)
                end
                if hit then
                    tryReconnect(idle and "idle" or "prompt")
                    task.wait(6)
                else
                    task.wait(1.5)
                end
            end
        end)
    end

    pcall(function()
        TeleportService.TeleportInitFailed:Connect(function()
            if Rejoin.reconnect == true then
                tryReconnect("teleport_failed")
            end
        end)
    end)
    pcall(function()
        if typeof(GuiService.ErrorMessageChanged) == "RBXScriptSignal" then
            GuiService.ErrorMessageChanged:Connect(function(msg)
                if Rejoin.reconnect == true and looksLikeDc(msg) then
                    tryReconnect(promptIsIdle(msg) and "idle" or "error_message")
                end
            end)
        end
    end)

    G.AnimeDiceRejoin = Rejoin
    Rejoin.setAntiAfk(true)

    Core.section({
        main = "misc",
        mainLabel = "MISC",
        mainOrder = 2,
        sub = "rejoin",
        subLabel = "Rejoin",
        subOrder = 1,
        order = 1,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Rejoin",
                expanded = false,
                status = {
                    id = "misc.rejoin.status",
                    persist = false,
                    value = "Armed",
                    style = "success",
                    detail = "AFK",
                },
            })
            statusApi = api
            local group = ui:CreateGroup(body)
            Core.bindToggle(ui, group, {
                id = "misc.rejoin.antiafk",
                label = "Anti AFK",
                initial = Rejoin.antiAfk ~= false,
                onChanged = function(on)
                    Rejoin.setAntiAfk(on == true)
                end,
            })
            Core.bindToggle(ui, group, {
                id = "misc.rejoin.reconnect",
                label = "Auto Reconnect",
                initial = Rejoin.reconnect == true,
                onChanged = function(on)
                    Rejoin.setReconnect(on == true)
                end,
            })
            ui:CreateRowSlider(group, {
                id = "misc.rejoin.every.delay",
                label = "Auto rejoin delay",
                min = EVERY_MIN,
                max = EVERY_MAX,
                step = 1,
                initial = Rejoin.everyDelay,
                suffix = "s",
                persist = true,
                onChanged = function(n)
