                end,
            })
            Core.bindToggle(ui, group, {
                id = "misc.rejoin.every",
                label = "Enable Auto Rejoin Every",
                initial = Rejoin.every == true,
                onChanged = function(on)
                    Rejoin.setEvery(on == true)
                end,
            })
            local note = ui:CreateRowLabel(group, {
                text = "Game hops to a new server after 18 min with no click. Anti AFK blocks that hop and the Roblox 20 min idle kick.",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            ui:CreateRowButton(group, {
                text = "Rejoin Now",
                kind = "primary",
                onClick = function()
                    setStatus("Teleporting", "live", "same server")
                    local ok, detail = Rejoin.now()
                    if ok then
                        setStatus("Sent", "success", detail or jobLabel())
                    else
                        setStatus("Failed", "error", detail or "teleport failed")
                    end
