        Rejoin.setReconnect(values["misc.rejoin.reconnect"] == true)
        if values["misc.rejoin.every.delay"] ~= nil then
            Rejoin.setEveryDelay(values["misc.rejoin.every.delay"])
        end
        Rejoin.setEvery(values["misc.rejoin.every"] == true)
    end)
end
 end, required = true, feature = true },
    { key = "Hop", name = "Hop", factory = function() -- MISC -> Hop.
-- List public JobId min-max, TeleportToPlaceInstance. Event hunt dari dropdown cuaca.
-- Fuse in-flight: nunggu Result dulu. Trade berjalan: pause hop sampai selesai.

return function(Core)
    local G = Core.env()
    local old = G.AnimeDiceHop
    if type(old) == "table" and type(old.setEnabled) == "function" then
        pcall(old.setEnabled, false)
    end

    local Players = game:GetService("Players")
    local TeleportService = game:GetService("TeleportService")
    local HttpService = game:GetService("HttpService")
    local RS = game:GetService("ReplicatedStorage")
    local LP = Core.player() or Players.LocalPlayer

    local capPlayers = tonumber(Players.MaxPlayers) or 50
    if capPlayers < 1 then
        capPlayers = 50
    elseif capPlayers > 50 then
        capPlayers = 50
    end

    local CACHE_TTL = 30
    local CACHE_LIMIT = 100
    local FETCH_COOLDOWN = 20
    local FUSE_WAIT_CAP = 6
    local VISIT_TTL = 45 * 60

    local Hop = {
        enabled = false,
        minPlayers = 1,
        maxPlayers = math.min(8, capPlayers),
        preferEmpty = true,
        skipVisited = true,
        events = {},
        interval = 10,
    }
    local headerApi
    local busy = false
    local gen = 0
    local visited = {}
    local visitedAt = {}
    local failNext = {}
    local weatherProp
    local listCache = { at = 0, placeId = 0, rows = {}, failAt = 0 }
    local visitPath = "nodeanimedice/hop_visited_" .. tostring((LP and LP.Name) or "player") .. ".json"

    local EVENT_FALLBACK = {
        "Luck Event",
        "Cash Event",
        "Roll Speed Event",
        "Trait Event",
        "Grade Event",
    }

    local function setStatus(value, style, detail)
        Core.paintHeader(headerApi, value, style, detail)
    end

    local function eventOkName(name)
        if type(name) ~= "string" then
            return nil
        end
        name = name:gsub("^%s+", ""):gsub("%s+$", "")
        local low = string.lower(name)
        if name == "" or low == "none" or low == "null" or low == "off" or low == "false" then
            return nil
        end
        return name
    end

    local function copyEventMap(src)
        local out = {}
        if type(src) == "string" then
            local name = eventOkName(src)
            if name then
                out[name] = true
            end
            return out
        end
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            local name
            if v == true or v == 1 or v == "true" then
                name = eventOkName(tostring(k))
            elseif type(k) == "number" and type(v) == "string" then
                name = eventOkName(v)
            elseif type(v) == "table" then
                name = eventOkName(v.key or v.id or v.name)
            end
            if name then
                out[name] = true
            end
        end
        return out
    end

    local function huntCount()
        local n = 0
        for _ in pairs(Hop.events) do
            n = n + 1
        end
        return n
    end

    local function hunting()
        return huntCount() > 0
    end

    local function huntLabel()
        local names = {}
        for name in pairs(Hop.events) do
            names[#names + 1] = name
        end
        table.sort(names)
        if #names == 0 then
            return nil
        end
        if #names == 1 then
            return names[1]
        end
        return tostring(#names) .. " events"
    end

    local function weatherSnap()
        local cur
        pcall(function()
            if not weatherProp then
                weatherProp = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "WeatherService"):GetProperty("ActiveWeather")
            end
            cur = weatherProp and weatherProp:Get()
        end)
        if type(cur) ~= "table" or type(cur.name) ~= "string" then
            return false, 0, nil
        end
        local remain = (tonumber(cur.duration) or 300) - (workspace:GetServerTimeNow() - (tonumber(cur.startedAt) or 0))
        if remain < 0 then
            remain = 0
        end
        local want = hunting()
        local on = remain > 0.5 and ((want and Hop.events[cur.name] == true) or not want)
        return on, remain, cur.name
    end

    local function fmtRemain(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
    end

    local function visitedCount()
        local n = 0
        for _ in pairs(visited) do
            n = n + 1
        end
        return n
    end

    local function pruneVisited()
        local now = os.time()
        for id, at in pairs(visitedAt) do
            if type(at) ~= "number" or now - at > VISIT_TTL then
                visitedAt[id] = nil
                visited[id] = nil
            end
        end
    end

    local function saveVisited()
        pruneVisited()
        if type(writefile) ~= "function" then
            return
        end
        local ok, json = pcall(function()
            return HttpService:JSONEncode(visitedAt)
        end)
        if ok and type(json) == "string" then
            pcall(writefile, visitPath, json)
        end
    end

    local function loadVisited()
        visited = {}
        visitedAt = {}
        if type(readfile) ~= "function" then
            return
        end
        local ok, body = pcall(readfile, visitPath)
        if not ok or type(body) ~= "string" or body == "" then
            return
        end
        local okJson, decoded = pcall(function()
            return HttpService:JSONDecode(body)
        end)
        if not okJson or type(decoded) ~= "table" then
            return
        end
        local now = os.time()
        for id, at in pairs(decoded) do
            id = tostring(id or "")
            at = tonumber(at)
            if id ~= "" and at and now - at <= VISIT_TTL then
                visited[id] = true
                visitedAt[id] = at
            end
        end
    end

    local function markVisited(jobId)
        jobId = tostring(jobId or "")
        if jobId == "" then
            return
        end
        visited[jobId] = true
        visitedAt[jobId] = os.time()
        saveVisited()
    end

    local function clearVisited()
        visited = {}
        visitedAt = {}
        if type(writefile) == "function" then
            pcall(writefile, visitPath, "{}")
        elseif type(delfile) == "function" then
            pcall(delfile, visitPath)
        end
    end

    local function clearFails()
        failNext = {}
    end

    pcall(loadVisited)
    do
        local here = tostring(game.JobId or "")
        if here ~= "" then
            markVisited(here)
        end
    end

    local function paint()
        if not Hop.enabled then
            setStatus("Off", "muted", "off")
            return
        end
        local here = #Players:GetPlayers()
        if busy then
            setStatus("Teleport", "live", here .. "p")
            return
        end
        local tradeOn = false
        if type(Core.tradeBusy) == "function" then
            local ok, on = pcall(Core.tradeBusy)
            tradeOn = ok and on == true
        end
        if tradeOn then
            setStatus("Wait trade", "muted", "pause")
            return
        end
        local _, remain, name = weatherSnap()
        if hunting() then
            if name and Hop.events[name] == true and remain > 0.5 then
                setStatus(name, "success", fmtRemain(remain) .. " | " .. here .. "p")
                return
            end
            setStatus("Seek " .. (huntLabel() or "event"), "live", (name or "no event") .. " | skip " .. tostring(visitedCount()))
            return
        end
        setStatus("On", "success", here .. "p | " .. tostring(Hop.minPlayers) .. "-" .. tostring(Hop.maxPlayers) .. "p")
    end

    local function allowTeleport(on)
        local rj = G.AnimeDiceRejoin
        if type(rj) == "table" then
            rj.allowTeleport = on == true
        end
    end

    local function takeBody(res)
        if type(res) == "string" then
            return res, 200
        end
        if type(res) == "table" then
            return res.Body or res.body, tonumber(res.StatusCode or res.Status) or 0
        end
        return nil, 0
    end

    local function rawGet(url, timeout)
        timeout = tonumber(timeout) or 4
        local box = { done = false }
        task.spawn(function()
            pcall(function()
                if type(request) == "function" then
                    box.body, box.code = takeBody(request({
                        Url = url,
                        Method = "GET",
                    }))
                end
            end)
            if type(box.body) ~= "string" or box.body == "" then
                pcall(function()
                    if type(http_request) == "function" then
                        box.body, box.code = takeBody(http_request({
                            Url = url,
                            Method = "GET",
                        }))
                    end
                end)
            end
            if type(box.body) ~= "string" or box.body == "" then
                pcall(function()
                    box.body = game:HttpGet(url)
                    box.code = 200
                end)
            end
            box.done = true
        end)
        local elapsed = 0
        while box.done ~= true and elapsed < timeout do
            task.wait(0.1)
            elapsed = elapsed + 0.1
        end
        if box.done ~= true then
            return nil, 0
        end
        return box.body, box.code
    end

    local function clamp(n, lo, hi, fallback)
        n = tonumber(n)
        if not n then
            n = fallback
        end
        if n < lo then
            n = lo
        elseif n > hi then
            n = hi
        end
        return math.floor(n + 0.5)
    end

    local function decodeServers(body)
        if type(body) ~= "string" or body == "" then
            return nil
        end
        local ok, decoded = pcall(function()
            return HttpService:JSONDecode(body)
        end)
        if not ok or type(decoded) ~= "table" or type(decoded.data) ~= "table" then
            return nil
        end
        return decoded
    end

    local function cacheRows(placeId)
        if listCache.placeId ~= placeId then
            return nil
        end
        if type(listCache.rows) == "table" and #listCache.rows > 0 then
            return listCache.rows
        end
        return nil
    end

    local function cacheFresh(placeId)
        return cacheRows(placeId) ~= nil and (os.clock() - (listCache.at or 0)) < CACHE_TTL
    end

    local function fetchBlocked()
        return (os.clock() - (listCache.failAt or 0)) < FETCH_COOLDOWN
    end

    local function fetchServers(force)
        local placeId = tonumber(game.PlaceId)
        if not placeId or placeId <= 0 then
            return nil, "place id invalid"
        end
        local cached = cacheRows(placeId)
        if cached and not force then
            if cacheFresh(placeId) or fetchBlocked() then
                return cached
            end
        end
        if cached and force and fetchBlocked() then
            return cached
        end
        if fetchBlocked() and not cached then
            return nil, "http failed"
        end
        local url = "https://games.roblox.com/v1/games/"
            .. tostring(placeId)
            .. "/servers/Public?sortOrder=Asc&excludeFullGames=true&limit="
            .. tostring(CACHE_LIMIT)
        local decoded = decodeServers(rawGet(url, 4))
        if not decoded then
            listCache.failAt = os.clock()
            if cached then
                return cached
            end
            return nil, "http failed"
        end
        local here = tostring(game.JobId or "")
        local out = {}
        for i = 1, #decoded.data do
            local row = decoded.data[i]
            if type(row) == "table" then
                local id = tostring(row.id or "")
                local playing = tonumber(row.playing) or 0
                local maxP = tonumber(row.maxPlayers) or capPlayers
                if id ~= "" and id ~= here then
                    out[#out + 1] = {
                        id = id,
                        playing = playing,
                        maxPlayers = maxP,
                    }
                end
            end
        end
        listCache = {
            at = os.clock(),
            placeId = placeId,
            rows = out,
            failAt = 0,
        }
        return out
    end

    local function filterPool(list, force)
        local minP = Hop.minPlayers
        local maxP = Hop.maxPlayers
        if minP > maxP then
            minP = maxP
        end
        local here = tostring(game.JobId or "")
        local pool = {}
        for i = 1, #list do
            local s = list[i]
            local skipHere = here ~= "" and s.id == here
            local skipVisit = Hop.skipVisited and visited[s.id] == true
            local skipFail = failNext[s.id] == true
            local full = s.playing >= s.maxPlayers
            if not skipHere and s.playing >= minP and s.playing <= maxP and not full and not skipVisit and not skipFail then
                pool[#pool + 1] = s
            end
        end
        if #pool == 0 and force then
            for i = 1, #list do
                local s = list[i]
                local skipHere = here ~= "" and s.id == here
                if not skipHere and failNext[s.id] ~= true and visited[s.id] ~= true and s.playing <= maxP and s.playing < s.maxPlayers then
                    pool[#pool + 1] = s
                end
            end
        end
        return pool, minP, maxP
    end

    local function pickFrom(pool)
        if #pool == 0 then
            return nil
        end
        if Hop.preferEmpty then
            table.sort(pool, function(a, b)
                if a.playing == b.playing then
                    return a.id < b.id
                end
                return a.playing < b.playing
            end)
            -- Banyak server 1p: jangan selalu JobId terkecil — acak di tier tersepi.
            local best = pool[1].playing
            local ties = { pool[1] }
            for i = 2, #pool do
                if pool[i].playing == best then
                    ties[#ties + 1] = pool[i]
                else
                    break
                end
            end
            return ties[math.random(1, #ties)]
        end
        return pool[math.random(1, #pool)]
    end

    local function pickServer(force)
        local list, err = fetchServers(false)
        if type(list) ~= "table" then
            return nil, tostring(err)
        end
        local pool, minP, maxP = filterPool(list, force)
        if #pool == 0 and Hop.skipVisited then
            clearVisited()
            pool = filterPool(list, force)
        end
        if #pool == 0 then
            if cacheFresh(tonumber(game.PlaceId) or 0) then
                return nil, "no server " .. tostring(minP) .. "-" .. tostring(maxP) .. "p"
            end
            list, err = fetchServers(true)
            if type(list) ~= "table" then
                return nil, tostring(err)
            end
            clearVisited()
            clearFails()
            pool = filterPool(list, true)
        end
        if #pool == 0 then
            return nil, "no server " .. tostring(minP) .. "-" .. tostring(maxP) .. "p"
        end
        return pickFrom(pool)
    end

    local function stillHere()
        return LP ~= nil and LP.Parent ~= nil
    end

    pcall(function()
        local sig = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "FusingService"):GetSignal("Result")
        if sig and type(sig.Connect) == "function" then
            sig:Connect(function()
                G.AnimeDiceLastFuseAt = os.clock()
            end)
        end
    end)

    local function tradeBusy()
        if type(Core.tradeBusy) == "function" then
            local ok, on = pcall(Core.tradeBusy)
            if ok and on == true then
                return true
            end
        end
        return false
    end

    local function tradeWait(force)
        while stillHere() and tradeBusy() do
            if force ~= true and Hop.enabled ~= true then
                break
            end
            setStatus("Wait trade", "muted", "pause")
            task.wait(0.25)
        end
    end

    local function fuseSaveWait()
        local capAt = os.clock() + FUSE_WAIT_CAP
        while stillHere() and os.clock() < capAt do
            local pending = G.AnimeDicePendingFuse
            local pendingAt = type(pending) == "table" and tonumber(pending.at) or 0
            local last = tonumber(G.AnimeDiceLastFuseAt) or 0
            if pendingAt > last and os.clock() - pendingAt < FUSE_WAIT_CAP then
                setStatus("Wait fuse", "muted", "result")
                task.wait(0.15)
            else
                break
            end
        end
    end

    local function fireJob(placeId, jobId)
        pcall(function()
            local P = G.AnimeDicePerf
            if type(P) == "table" and type(P.purge) == "function" then
                P.purge()
            end
        end)
        pcall(function()
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
        end)
        if stillHere() then
            pcall(function()
                TeleportService:TeleportToPlaceInstance(placeId, jobId)
            end)
        end
    end

    local function teleportJob(jobId)
        local placeId = tonumber(game.PlaceId)
        jobId = tostring(jobId or "")
        local here = tostring(game.JobId or "")
        if not placeId or placeId <= 0 or jobId == "" or not LP then
            return false, "job invalid"
        end
        if here ~= "" and jobId == here then
            failNext[jobId] = true
            return false, "same job"
        end
        allowTeleport(true)
        markVisited(jobId)
        fireJob(placeId, jobId)
        task.spawn(function()
            for _ = 1, 6 do
                if not stillHere() then
                    break
                end
                task.wait(0.7)
                if not stillHere() then
                    break
                end
                allowTeleport(true)
                fireJob(placeId, jobId)
            end
            task.wait(0.2)
            busy = false
            allowTeleport(false)
        end)
        return true, string.sub(jobId, 1, 8)
    end

    function Hop.go(force)
        if busy then
            return false, "busy"
        end
        busy = true
        tradeWait(force == true)
        if not stillHere() then
            busy = false
            return false, "left"
        end
        if tradeBusy() then
            busy = false
            return false, "trade"
        end
        fuseSaveWait()
        if not stillHere() then
            busy = false
            return false, "left"
        end
        if tradeBusy() then
            busy = false
            return false, "trade"
        end
        local server, err = pickServer(force == true)
        if not server then
            busy = false
            return false, tostring(err)
        end
        local ok, detail = teleportJob(server.id)
        if not ok then
            busy = false
            failNext[server.id] = true
            return false, tostring(detail)
        end
        local waited = 0
        while waited < 5 and stillHere() do
            task.wait(0.5)
            waited = waited + 0.5
        end
        if stillHere() then
            busy = false
            failNext[server.id] = true
            allowTeleport(false)
            return false, "job " .. tostring(detail) .. " no-op"
        end
        return true, tostring(server.playing) .. "p | " .. tostring(detail)
    end

    local function onTargetEvent()
        if not hunting() then
            return false
        end
        local _, remain, name = weatherSnap()
        return type(name) == "string" and Hop.events[name] == true and remain > 0.5
    end

    local function needsHop()
        if hunting() then
            return not onTargetEvent()
        end
        return #Players:GetPlayers() > Hop.maxPlayers
    end

    local function waitHopDelay(my)
        local sec = clamp(Hop.interval, 5, 120, 10)
        local elapsed = 0
        while elapsed < sec and Hop.enabled and gen == my do
            if hunting() and onTargetEvent() then
                return false
            end
            setStatus("Wait hop", "muted", tostring(sec - elapsed) .. "s")
            task.wait(1)
            elapsed = elapsed + 1
        end
        return Hop.enabled == true and gen == my
    end

    function Hop.setEnabled(on)
        on = on == true
        Hop.enabled = on
        gen = gen + 1
        if not on then
            busy = false
            allowTeleport(false)
            paint()
            return
        end
        paint()
        local my = gen
        task.spawn(function()
            while Hop.enabled and gen == my do
                if busy then
                    paint()
                    task.wait(1)
                elseif tradeBusy() then
                    setStatus("Wait trade", "muted", "pause")
                    task.wait(0.5)
                elseif needsHop() then
                    if not waitHopDelay(my) then
                        paint()
                    elseif needsHop() and not busy then
                        setStatus("Hopping", "live", huntLabel() or (#Players:GetPlayers() .. "p"))
                        local ok, detail = Hop.go(false)
                        if not ok and tostring(detail) == "busy" then
                            task.wait(1)
                        elseif not ok then
                            setStatus("No server", "warn", detail)
                        else
                            setStatus("Hop", "success", detail)
                        end
                    end
                else
                    if hunting() and onTargetEvent() then
                        clearVisited()
                    end
                    paint()
                    task.wait(1)
                end
            end
        end)
    end

    local function eventItems()
        local out = {}
        local seen = {}
        pcall(function()
            local folder = RS:FindFirstChild("Weather Events")
            if folder then
                for _, child in ipairs(folder:GetChildren()) do
                    local name = child.Name
                    if type(name) == "string" and name ~= "" and not seen[name] then
                        seen[name] = true
                        out[#out + 1] = { key = name, name = name }
                    end
                end
            end
        end)
        if #out == 0 then
            for i = 1, #EVENT_FALLBACK do
                local name = EVENT_FALLBACK[i]
                out[#out + 1] = { key = name, name = name }
            end
        end
        table.sort(out, function(a, b)
            return a.name < b.name
        end)
        return out
    end

    pcall(function()
        TeleportService.TeleportInitFailed:Connect(function(player, result, reason)
            if player ~= LP then
                return
            end
            local job = tostring(game.JobId or "")
            if job ~= "" then
                failNext[job] = true
            end
            busy = false
            allowTeleport(false)
            if Hop.enabled == true then
                setStatus("Hop fail", "error", tostring(result or reason or "init"))
            end
        end)
    end)

    G.AnimeDiceHop = Hop

    Core.section({
        main = "misc",
        mainLabel = "MISC",
        mainOrder = 2,
        sub = "hop",
        subLabel = "Hop",
        subOrder = 2,
        order = 1,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Hop",
                expanded = false,
                status = {
                    id = "misc.hop.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "off",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            ui:CreateRowSlider(group, {
                id = "misc.hop.min",
                label = "Min players",
                min = 0,
                max = capPlayers,
                step = 1,
                initial = Hop.minPlayers,
                suffix = "p",
                persist = true,
                onChanged = function(n)
                    Hop.minPlayers = clamp(n, 0, capPlayers, 1)
                    paint()
                end,
            })
            ui:CreateRowSlider(group, {
                id = "misc.hop.max",
                label = "Max players",
                min = 1,
                max = capPlayers,
                step = 1,
                initial = Hop.maxPlayers,
                suffix = "p",
                persist = true,
                onChanged = function(n)
                    Hop.maxPlayers = clamp(n, 1, capPlayers, 8)
                    paint()
                end,
            })
            ui:CreateRowSlider(group, {
                id = "misc.hop.interval",
                label = "Hop interval",
                min = 5,
                max = 120,
                step = 1,
                initial = Hop.interval,
                suffix = "s",
                persist = true,
                onChanged = function(n)
                    Hop.interval = clamp(n, 5, 120, 10)
                end,
            })
            ui:CreateRowDropdown(group, {
                id = "misc.hop.event",
                label = "Event",
                mode = "multi",
                placeholder = "None",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                getItems = eventItems,
                onChanged = function(a, b)
                    if a == "multi" then
                        Hop.events = copyEventMap(b)
                    elseif a == "single" then
                        Hop.events = copyEventMap(b)
                    else
                        Hop.events = copyEventMap(b or a)
                    end
                    paint()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "misc.hop.preferEmpty",
                label = "Prefer emptiest",
                persist = true,
                initial = true,
                onChanged = function(on)
                    Hop.preferEmpty = on ~= false
                end,
            })
            Core.bindToggle(ui, group, {
                id = "misc.hop.skipVisited",
                label = "Skip visited",
                persist = true,
                initial = true,
                onChanged = function(on)
                    Hop.skipVisited = on ~= false
                end,
            })
            Core.bindToggle(ui, group, {
                id = "misc.hop.enabled",
                label = "Enable Auto Hop",
                persist = true,
                initial = false,
                onChanged = function(on)
                    Hop.setEnabled(on == true)
                end,
            })
            local note = ui:CreateRowLabel(group, {
                text = "Auto Hop waits Hop interval then hops. Trade in progress pauses hop until the trade ends. Fuse in flight: wait Result then hop. Multi-select events: stay if weather matches any pick. Empty = hop only if over max players. Skip visited blacklists JobId. List cached 100 jobs / 30s. Default off.",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            ui:CreateRowButton(group, {
                text = "Hop Now",
                kind = "primary",
                onClick = function()
                    setStatus("Hopping", "live", "job")
                    local ok, detail = Hop.go(true)
                    if ok then
                        setStatus("Hop", "success", detail)
                    else
                        setStatus("Hop fail", "error", detail or "no server")
                    end
                end,
            })
            paint()
        end,
    })

    Core.onSync(function(values)
        if values["misc.hop.min"] ~= nil then
            Hop.minPlayers = clamp(values["misc.hop.min"], 0, capPlayers, 1)
        end
        if values["misc.hop.max"] ~= nil then
            Hop.maxPlayers = clamp(values["misc.hop.max"], 1, capPlayers, 8)
        end
        if values["misc.hop.interval"] ~= nil then
            Hop.interval = clamp(values["misc.hop.interval"], 5, 120, 10)
        end
        if values["misc.hop.preferEmpty"] == nil then
            Hop.preferEmpty = true
        else
            Hop.preferEmpty = values["misc.hop.preferEmpty"] ~= false
        end
        if values["misc.hop.skipVisited"] == nil then
            Hop.skipVisited = true
        else
            Hop.skipVisited = values["misc.hop.skipVisited"] ~= false
        end
        Hop.events = copyEventMap(values["misc.hop.event"])
        Hop.setEnabled(values["misc.hop.enabled"] == true)
    end)
end
 end, required = true, feature = true },
    { key = "Config", name = "Config", factory = function() -- MISC → gear tab: copy / paste hub config. Save always stays on this account.

return function(Core)
    local HttpService = game:GetService("HttpService")
    local Players = game:GetService("Players")
    local G = Core.env()
    local LP = Core.player() or Players.LocalPlayer
    local GEAR_ICON = "rbxasset://textures/ui/Settings/MenuBarIcons/GameSettingsTab.png"
    local SKIP = {
        ["misc.config.paste"] = true,
        ["misc.config.status"] = true,
        ["misc.config.account"] = true,
    }

    local function saveDir()
        local dir = G.__AnimeDiceSaveDir
        if type(dir) ~= "string" or dir == "" then
            dir = "nodeanimedice"
        end
        return dir
    end

    local function safeName(name)
        local s = tostring(name or "player")
        s = s:gsub("[^%w%-_.]", "_")
        s = s:gsub("_+", "_")
        if s == "" or s == "_" then
            s = "player"
        end
        return s:sub(1, 48)
    end

    local function ownFileName()
        return safeName(LP and LP.Name) .. ".json"
    end

    local function fileName(path)
        path = tostring(path or ""):gsub("\\", "/")
        return path:match("([^/]+)$") or path
    end

    local function trim(s)
        return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
    end

    local function encodeJson(value)
        local ok, json = pcall(function()
            return HttpService:JSONEncode(value)
        end)
        if ok and type(json) == "string" and json ~= "" then
            return json
        end
        return nil
    end

    local function decodeJson(src)
        src = trim(src)
        if src == "" then
            return nil
        end
        local ok, data = pcall(function()
            return HttpService:JSONDecode(src)
        end)
        if ok and type(data) == "table" then
            return data
        end
        return nil
    end

    local function copyText(text)
        if type(setclipboard) == "function" and pcall(setclipboard, text) then
            return true
        end
        if type(toclipboard) == "function" and pcall(toclipboard, text) then
            return true
        end
        if type(set_clipboard) == "function" and pcall(set_clipboard, text) then
            return true
        end
        return false
    end

    local function sharePath()
        return saveDir() .. "/config_share.json"
    end

    local function writeShare(json)
        local dir = saveDir()
        if type(makefolder) == "function" then
            pcall(makefolder, dir)
        end
        if type(writefile) ~= "function" then
            return false
        end
        return pcall(writefile, sharePath(), json) == true
    end

    local function readShare()
        if type(readfile) ~= "function" then
            return nil
        end
        local ok, src = pcall(readfile, sharePath())
        if ok and type(src) == "string" and src ~= "" then
            return src
        end
        return nil
    end

    local function snapshotConfig(ui)
        local values = ui:GetValues() or {}
        local out = {}
        for id, value in pairs(values) do
            if not SKIP[id] then
                out[id] = value
            end
        end
        return out
    end

    local function applyLive(ui, data)
        if type(data) ~= "table" then
            return false
        end
        for id in pairs(SKIP) do
            data[id] = nil
        end
        ui:SetValues(data, true)
        pcall(function()
            Core.sync(ui)
        end)
        pcall(function()
            ui:Save()
        end)
        return true
    end

    local accountFiles = {}

    local function dropdownKey(a, b)
        if a == "single" or a == "multi" then
            a = b
        end
        if type(a) == "table" then
            for k, v in pairs(a) do
                if v == true or v == 1 or v == "true" then
                    return tostring(k)
                end
            end
            return nil
        end
        local key = tostring(a or "")
        if key == "" or key == "nil" then
            return nil
        end
        return key
    end

    local function listAccountSaves()
        local dir = saveDir()
        local own = ownFileName()
        local out = {}
        accountFiles = {}
        local files
        if type(listfiles) == "function" then
            local ok, res = pcall(listfiles, dir)
            if ok and type(res) == "table" then
                files = res
            end
        end
        if type(files) ~= "table" then
            return out
        end
        for _, path in ipairs(files) do
            local name = fileName(path)
            if type(name) == "string" and name:sub(-5) == ".json" and name ~= own and name ~= "config_share.json" then
                local account = name:sub(1, #name - 5)
                if account ~= "" then
                    accountFiles[account] = tostring(path)
                    accountFiles[safeName(account)] = tostring(path)
                    out[#out + 1] = {
                        key = account,
                        label = account,
                    }
                end
            end
        end
        table.sort(out, function(a, b)
            return tostring(a.label) < tostring(b.label)
        end)
        return out
    end

    local function readAccount(account)
        account = tostring(account or "")
        if account == "" then
            return nil, "pick an account"
        end
        if safeName(account) == safeName(LP and LP.Name) then
            return nil, "own"
        end
        local name = safeName(account) .. ".json"
        local dir = saveDir()
        local candidates = {
            accountFiles[account],
            accountFiles[safeName(account)],
            dir .. "/" .. name,
            dir .. "\\" .. name,
            dir .. "/" .. account .. ".json",
            dir .. "\\" .. account .. ".json",
        }
        if type(readfile) ~= "function" then
            return nil, "no readfile"
        end
        for _, path in ipairs(candidates) do
            if type(path) == "string" and path ~= "" then
                local ok, src = pcall(readfile, path)
                if ok and type(src) == "string" and src ~= "" then
                    local data = decodeJson(src)
                    if type(data) == "table" then
                        return data, path
                    end
                    return nil, "invalid"
                end
            end
        end
        return nil, "missing"
    end

    Core.section({
        main = "misc",
        mainLabel = "MISC",
        mainOrder = 2,
        sub = "config",
        subLabel = "",
        subIcon = GEAR_ICON,
        subOrder = 9,
        order = 1,
        build = function(ui)
            local body, _, statusApi = ui:CreateSection({
                title = "Config",
                expanded = false,
                status = {
                    id = "misc.config.status",
                    persist = false,
                    value = "Idle",
                    style = "muted",
                    detail = saveDir() .. "/" .. ownFileName(),
                },
            })
            local group = ui:CreateGroup(body)
            local pickedAccount

            local function setStatus(text, style, detail)
                if type(statusApi) ~= "table" then
                    return
                end
                pcall(statusApi.set, text)
                if type(statusApi.setStyle) == "function" then
                    pcall(statusApi.setStyle, style or "muted")
                end
                if type(statusApi.setDetail) == "function" then
                    pcall(statusApi.setDetail, detail or "")
                end
            end

            ui:CreateRowLabel(group, {
                text = "Copy this account, or load another save from " .. saveDir() .. "/. Apply writes to your own file.",
                wrap = true,
                style = "detail",
                order = 1,
            })

            local pasteWrap = Instance.new("Frame")
            pasteWrap.Name = "ConfigPaste"
            pasteWrap.BackgroundTransparency = 1
            pasteWrap.Size = UDim2.new(1, 0, 0, 78)
            pasteWrap.LayoutOrder = 10
            pasteWrap.Parent = group

            local pasteBox = Instance.new("TextBox")
            pasteBox.Name = "Input"
            pasteBox.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            pasteBox.Size = UDim2.new(1, 0, 1, 0)
            pasteBox.Font = Enum.Font.Gotham
            pasteBox.TextSize = 11
            pasteBox.TextColor3 = Color3.fromRGB(220, 220, 220)
            pasteBox.PlaceholderColor3 = Color3.fromRGB(110, 110, 110)
            pasteBox.PlaceholderText = "Paste save config"
            pasteBox.Text = ""
            pasteBox.ClearTextOnFocus = false
            pasteBox.MultiLine = true
            pasteBox.TextWrapped = true
            pasteBox.TextXAlignment = Enum.TextXAlignment.Left
            pasteBox.TextYAlignment = Enum.TextYAlignment.Top
            pasteBox.ClipsDescendants = true
            pasteBox.Parent = pasteWrap
            pcall(function()
                pasteBox.TextTruncate = Enum.TextTruncate.None
            end)
            local boxPad = Instance.new("UIPadding")
            boxPad.PaddingLeft = UDim.new(0, 8)
            boxPad.PaddingRight = UDim.new(0, 8)
            boxPad.PaddingTop = UDim.new(0, 6)
            boxPad.PaddingBottom = UDim.new(0, 6)
            boxPad.Parent = pasteBox
            local boxCorner = Instance.new("UICorner")
            boxCorner.CornerRadius = UDim.new(0, 8)
            boxCorner.Parent = pasteBox
            local boxStroke = Instance.new("UIStroke")
            boxStroke.Color = Color3.fromRGB(70, 70, 70)
            boxStroke.Thickness = 1
            boxStroke.Transparency = 0.35
            boxStroke.Parent = pasteBox

            ui:CreateRowButton(group, {
                text = "Copy",
                kind = "primary",
                order = 20,
                onClick = function()
                    local json = encodeJson(snapshotConfig(ui))
                    if not json then
                        setStatus("Failed", "error", "encode")
                        return
                    end
                    local clip = copyText(json)
                    local fileOk = writeShare(json)
                    if clip then
                        setStatus("Copied", "success", fileOk and "clipboard + share file" or "clipboard")
                    elseif fileOk then
                        setStatus("Copied", "warn", "share file only")
                    else
                        setStatus("Failed", "error", "clipboard")
                    end
                end,
            })

            ui:CreateRowButton(group, {
                text = "Paste / Apply",
                order = 21,
                onClick = function()
                    local raw = trim(pasteBox.Text)
                    local fromFile = false
                    if raw == "" then
                        raw = trim(readShare() or "")
                        fromFile = raw ~= ""
                    end
                    local data = decodeJson(raw)
                    if type(data) ~= "table" then
                        if raw == "" then
                            setStatus("Failed", "error", "empty")
                        else
                            setStatus("Failed", "error", "invalid JSON")
                        end
                        return
                    end
                    if applyLive(ui, data) then
                        pasteBox.Text = ""
                        setStatus("Applied", "success", fromFile and "share file → " .. ownFileName() or "paste → " .. ownFileName())
                    else
                        setStatus("Failed", "error", "apply")
                    end
                end,
            })

            ui:CreateRowDropdown(group, {
                id = "misc.config.account",
                label = "Other account",
                placeholder = "Pick save in " .. saveDir() .. "/",
                persist = false,
                clearable = true,
                getItems = listAccountSaves,
                hintText = "JSON files in " .. saveDir() .. " except this account.",
                order = 30,
                onChanged = function(a, b)
                    pickedAccount = dropdownKey(a, b)
                end,
            })

            ui:CreateRowButton(group, {
                text = "Load account config",
                order = 31,
                onClick = function()
                    if type(pickedAccount) ~= "string" or pickedAccount == "" then
                        setStatus("Failed", "error", "pick an account")
                        return
                    end
                    local data, err = readAccount(pickedAccount)
                    if type(data) ~= "table" then
                        setStatus("Failed", "error", tostring(err or "missing"))
                        return
                    end
                    if applyLive(ui, data) then
                        setStatus("Applied", "success", pickedAccount .. " → " .. ownFileName())
                    else
                        setStatus("Failed", "error", "apply")
                    end
                end,
            })
        end,
    })
end
 end, required = true, feature = true },
    { key = "AutoUpgradeUnits", name = "Auto Upgrade Unit", factory = function() -- AUTO → Auto Upgrade Unit.
-- Naik level unit yang terpasang di slot plot. Harga dari UnitUtil.GetLevelPrice.

return function(Core)
    local RS = game:GetService("ReplicatedStorage")
    local keepPercent = 80
    local maxLevel = 25

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function clampLevel(n)
        n = tonumber(n) or 0
        if n < 0 then
            n = 0
        elseif n > 9999 then
            n = 9999
        end
        return math.floor(n + 0.5)
    end

    local function slotData(data, slot)
        local getter = data.Slots and data.Slots[tostring(slot)]
        if getter == nil then
            return nil
        end
        local ok, row = pcall(getter)
        if not ok or type(row) ~= "table" then
            return nil
        end
        return row
    end

    local function inventoryItem(data, unitId)
        if type(unitId) ~= "string" or unitId == "" then
            return nil
        end
        local getter = data.Inventory and data.Inventory[unitId]
        if getter == nil then
            return nil
        end
        local ok, item = pcall(getter)
        if not ok or type(item) ~= "table" then
            return nil
        end
        return item
    end

    local util
    local function unitUtil()
        if type(util) == "table" and type(util.GetLevelPrice) == "function" then
            return util
        end
        pcall(function()
            util = require(RS.Framework.Features.Inventory.Kinds.Unit.UnitUtil)
        end)
        return util
    end

    local function fireSlot(slot)
        local re = Core.remote("PlotService", "LevelUpSlot")
        if not re then
            return false
        end
        if pcall(function()
            re:FireServer(slot)
        end) then
            return true
        end
        return pcall(function()
            re:Fire(slot)
        end)
    end

    -- Replica level sering telat. Tanpa prediksi, loop 0.12s menembak 2-3x
    -- sebelum data capai max, jadi 25 bisa jadi 27.
    local pending = {}
    local pendingAt = {}

    local function liveLevel(unitId, dataLevel)
        dataLevel = tonumber(dataLevel) or 1
        local pred = pending[unitId]
        if not pred then
            return dataLevel
        end
        if dataLevel >= pred or (os.clock() - (pendingAt[unitId] or 0)) > 1.5 then
            pending[unitId] = nil
            pendingAt[unitId] = nil
            return dataLevel
        end
        if dataLevel > pred then
            return dataLevel
        end
        return pred
    end

    local function markFired(unitId, fromLevel)
        if type(unitId) ~= "string" or unitId == "" then
            return
        end
        pending[unitId] = (tonumber(fromLevel) or 1) + 1
        pendingAt[unitId] = os.clock()
    end

    local slotCache, slotCacheAt = nil, 0
    local function slotsNow()
        if slotCache and (os.clock() - slotCacheAt) < 2 then
            return slotCache
        end
        slotCache = Core.slots()
        slotCacheAt = os.clock()
        return slotCache
    end

    local priceCache = {}
    local function levelPrice(priceFn, name, level, mutation)
        local key = tostring(name) .. "\0" .. tostring(level) .. "\0" .. tostring(mutation)
        local cached = priceCache[key]
        if cached ~= nil then
            return cached
        end
        local okPrice, value = pcall(priceFn.GetLevelPrice, name, {
            level = level,
            mutation = mutation,
        })
        local price = okPrice and tonumber(value) or false
        priceCache[key] = price
        return price
    end

    local lastReady, lastNext, lastMoney, lastScanAt = nil, nil, 0, 0

    local function scanLevel()
        local data = Core.data()
        local money = 0
        local okMoney = pcall(function()
            money = tonumber(data.Money()) or 0
        end)
        if not okMoney then
            lastReady, lastNext, lastMoney, lastScanAt = nil, nil, money, os.clock()
            return nil, nil, money
        end
        local priceFn = unitUtil()
        if type(priceFn) ~= "table" or type(priceFn.GetLevelPrice) ~= "function" then
            lastReady, lastNext, lastMoney, lastScanAt = nil, nil, money, os.clock()
            return nil, nil, money
        end
        local ready, nextUp
        local seen = {}
        for _, slot in ipairs(slotsNow()) do
            local row = slotData(data, slot)
            if row then
                local unitId = readVal(row.unitId)
                local item = inventoryItem(data, unitId)
                if item then
                    seen[unitId] = true
                    local attrs = type(item.attributes) == "table" and item.attributes or item
                    local level = liveLevel(unitId, readVal(attrs.level))
                    if maxLevel <= 0 or level < maxLevel then
                        local price = levelPrice(priceFn, readVal(item.name), level, readVal(attrs.mutation))
                        if type(price) == "number" then
                            local rowInfo = {
                                slot = slot,
                                unitId = unitId,
                                price = price,
                                level = level,
                                name = readVal(item.name),
                            }
                            if not nextUp or price < nextUp.price then
                                nextUp = rowInfo
                            end
                            if Core.money().allows(money, price, keepPercent) then
                                if not ready or price < ready.price then
                                    ready = rowInfo
                                end
                            end
                        end
                    end
                end
            end
        end
        for id in pairs(pending) do
            if not seen[id] then
                pending[id] = nil
                pendingAt[id] = nil
            end
        end
        lastReady, lastNext, lastMoney, lastScanAt = ready, nextUp, money, os.clock()
        return ready, nextUp, money
    end

    local levelLoop
    local unitHeader
    local function paintUnitHeader()
        local cap = maxLevel <= 0 and "no cap" or ("max " .. tostring(maxLevel))
        if not (levelLoop and levelLoop.enabled()) then
            Core.paintHeader(unitHeader, "Off", "muted", cap)
            return
        end
        local ready, nextUp, money = lastReady, lastNext, lastMoney
        if (os.clock() - lastScanAt) > 1.25 then
            ready, nextUp, money = scanLevel()
        end
        if ready then
            Core.paintHeader(unitHeader, "On", "success", "Lv " .. tostring(ready.level) .. " · " .. Core.compact(ready.price))
            return
        end
        if nextUp then
            local need = Core.money().required(nextUp.price, keepPercent)
            Core.paintHeader(unitHeader, "Wait", "muted", Core.compact(money) .. " / " .. Core.compact(need))
            return
        end
        Core.paintHeader(unitHeader, "On", "muted", "no unit on plot")
    end

    local function tryLevel()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return
            end
        end
        local au = Core.env().AnimeDiceAutoUnit
        if type(au) == "table" and au.upgradeOn == true then
            return
        end
        local ready = scanLevel()
        if ready and (maxLevel <= 0 or ready.level < maxLevel) then
            if fireSlot(ready.slot) then
                markFired(ready.unitId, ready.level)
            end
        end
    end

    levelLoop = Core.loop("auto_upgrade_units", {
        delay = 0.5,
        step = tryLevel,
    })

    local unitStatusLoop = Core.loop("auto_upgrade_units_header", {
        delay = 5,
        step = function()
            if Core.uiIs("auto", "main") then
                paintUnitHeader()
            end
        end,
    })
    unitStatusLoop.setEnabled(true)

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 2,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Upgrade Unit",
                expanded = false,
                status = {
                    id = "auto.unitLevel.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "max " .. tostring(maxLevel),
                },
            })
            unitHeader = api
            paintUnitHeader()
            local group = ui:CreateGroup(body)
            ui:CreateRowSlider(group, {
                id = "auto.unitLevel.keepPercent",
                label = "Money left",
                min = 0,
                max = 100,
                step = 1,
                initial = keepPercent,
                suffix = "%",
                onChanged = function(n)
                    keepPercent = tonumber(n) or keepPercent
                    paintUnitHeader()
                end,
            })
            local note = ui:CreateRowLabel(group, {
                text = "Level up waits until money covers the price plus this percent. 80 on a 10B price starts at 18B.",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            ui:CreateRowInput(group, {
                id = "auto.unitLevel.max",
                label = "Max upgrade level",
                initial = tostring(maxLevel),
                onChanged = function(text)
                    maxLevel = clampLevel(text)
                    paintUnitHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.unitLevel",
                label = "Auto Upgrade Unit",
                initial = levelLoop.enabled(),
                onChanged = function(on)
                    levelLoop.setEnabled(on == true)
                    paintUnitHeader()
                end,
            })
        end,
    })

    Core.onSync(function(values)
        local keep = tonumber(values["auto.unitLevel.keepPercent"])
        if keep ~= nil then
            keepPercent = keep
        end
        local cap = tonumber(values["auto.unitLevel.max"])
        if cap ~= nil then
            maxLevel = clampLevel(cap)
        end
        levelLoop.setEnabled(values["auto.unitLevel"] == true)
        paintUnitHeader()
    end)
end
 end, required = true, feature = true },
    { key = "AutoBuyTreeUpgrades", name = "Auto Buy Tree Upgrades", factory = function() -- AUTO → Buy Tree Upgrades.
-- Cabang dan harga dibaca dari modul Upgrades + TreeStructure, bukan daftar tulis tangan.

return function(Core)
    local RS = game:GetService("ReplicatedStorage")
    local okMods, Upgrades, Tree = pcall(function()
        local framework = RS:WaitForChild("Framework", 8)
        local features = framework and framework:WaitForChild("Features", 8)
        local folder = features and features:WaitForChild("Upgrades", 8)
        return require(folder:WaitForChild("Upgrades", 2)), require(folder:WaitForChild("TreeStructure", 2))
    end)
    if not okMods or type(Upgrades) ~= "table" or type(Tree) ~= "table" then
        return
    end

    local PREFER = {
        Money = true,
        Sell = true,
        Luck = true,
        ["Roll Speed"] = true,
        Fortune = true,
        ["Grade Luck"] = true,
        ["Unit Storage"] = true,
    }

    local function familyOf(name)
        local base = tostring(name):match("^(.-)%s+[IVXLCDM]+$")
        if base and base ~= "" then
            return base
        end
        return tostring(name)
    end

    local nodes = {}
    local families = {}
    local seenFamily = {}
    local seenNode = {}

    local function walk(name)
        if seenNode[name] then
            return
        end
        seenNode[name] = true
        local children = Tree.GetChildren(name)
        if type(children) ~= "table" then
            return
        end
        for _, child in ipairs(children) do
            local cfg = Upgrades[child]
            if type(cfg) == "table" and child ~= "Start" then
                local family = familyOf(child)
                if not seenFamily[family] then
                    seenFamily[family] = true
                    families[#families + 1] = {
                        key = family,
                        label = family,
                        order = #families + 1,
                    }
                end
                nodes[#nodes + 1] = {
                    name = child,
                    family = family,
                    price = tonumber(cfg.price) or 0,
                    parent = Tree.GetParent(child),
                }
            end
            walk(child)
        end
    end
    walk("Start")

    local selected = {}
    for _, item in ipairs(families) do
        if PREFER[item.key] then
            selected[item.key] = true
        end
    end

    local function owns(data, name)
        local ok, owned = pcall(function()
            return data.Upgrades[name]() == true
        end)
        return ok and owned == true
    end

    local function allowedFamily(family)
        local any = false
        for _, on in pairs(selected) do
            if on then
                any = true
                break
            end
        end
        if not any then
            return true
        end
        return selected[family] == true
    end

    local signal
    local function buySignal()
        if signal then
            return signal
        end
        local ok, got = pcall(function()
            return require(RS.Packages.Network).Client.GetSignal(RS.Network, "BuyUpgrade")
        end)
        if ok then
            signal = got
        end
        return signal
    end

    local function scanBuy()
        local data = Core.data()
        local money = 0
        local okMoney = pcall(function()
            money = tonumber(data.Money()) or 0
        end)
        if not okMoney then
            return nil, nil, money
        end
        local ready, nextUp
        for _, node in ipairs(nodes) do
            if allowedFamily(node.family) and not owns(data, node.name) then
                local parent = node.parent
                local parentOk = parent == nil or parent == "Start" or owns(data, parent)
                if parentOk then
                    if not nextUp or node.price < nextUp.price then
                        nextUp = node
                    end
                    if Core.money().allows(money, node.price) then
                        if not ready or node.price < ready.price then
                            ready = node
                        end
                    end
                end
            end
        end
        return ready, nextUp, money
    end

    local buyLoop
    local treeHeader
    local function paintTreeHeader()
        local ready, nextUp, money = scanBuy()
        if not (buyLoop and buyLoop.enabled()) then
            local detail = nextUp and (nextUp.name .. " · " .. Core.compact(nextUp.price)) or "all owned"
            Core.paintHeader(treeHeader, "Off", "muted", detail)
            return
        end
        if ready then
            Core.paintHeader(treeHeader, "On", "success", ready.name .. " · " .. Core.compact(ready.price))
            return
        end
        if nextUp then
            local need = Core.money().required(nextUp.price)
            Core.paintHeader(treeHeader, "Wait", "muted", nextUp.name .. " · " .. Core.compact(need))
            return
        end
        Core.paintHeader(treeHeader, "On", "muted", "all owned")
    end

    local function tryBuy()
        local ready = scanBuy()
        if ready then
            local remote = buySignal()
            if remote then
                remote:Fire(ready.name)
            end
        end
        paintTreeHeader()
    end

    buyLoop = Core.loop("auto_buy_tree_upgrades", {
        delay = 1,
        step = tryBuy,
    })

    local treeStatusLoop = Core.loop("auto_buy_tree_upgrades_header", {
        delay = 5,
        step = function()
            if Core.uiIs("auto", "main") then
                paintTreeHeader()
            end
        end,
    })
    treeStatusLoop.setEnabled(true)

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 3,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Upgrade Tree",
                expanded = false,
                status = {
                    id = "auto.upgrade.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "next node · price",
                },
            })
            treeHeader = api
            paintTreeHeader()
            local group = ui:CreateGroup(body)
            ui:CreateRowSlider(group, {
                id = "money.keepPercent",
                label = "Money left",
                min = 0,
                max = 100,
                step = 1,
                initial = Core.money().percent(),
                suffix = "%",
                onChanged = function(n)
                    Core.money().setPercent(n)
                    paintTreeHeader()
                end,
            })
            local moneyNote = ui:CreateRowLabel(group, {
                text = "Buy waits until money covers the upgrade price plus this percent. 80 on a 10B price starts at 18B.",
                wrap = true,
                style = "detail",
            })
            local moneyPad = Instance.new("UIPadding")
            moneyPad.PaddingTop = UDim.new(0, 2)
            moneyPad.PaddingBottom = UDim.new(0, 4)
            moneyPad.Parent = moneyNote

            ui:CreateRowDropdown(group, {
                id = "auto.upgradeBranches",
                label = "Upgrade branches",
                mode = "multi",
                placeholder = "All",
                getItems = function()
                    return families
                end,
                initial = selected,
                preserveItemOrder = true,
                controlWidth = 176,
                onChanged = function(_, value)
                    if type(value) == "table" then
                        selected = value
                    end
                    paintTreeHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.upgrade",
                label = "Auto Buy Upgrades",
                initial = buyLoop.enabled(),
                onChanged = function(on)
                    buyLoop.setEnabled(on == true)
                    paintTreeHeader()
                end,
            })
        end,
    })

    Core.onSync(function(values)
        local keep = tonumber(values["money.keepPercent"])
        if keep ~= nil then
            Core.money().setPercent(keep)
        end
        if type(values["auto.upgradeBranches"]) == "table" then
            selected = values["auto.upgradeBranches"]
        end
        buyLoop.setEnabled(values["auto.upgrade"] == true)
        paintTreeHeader()
    end)
end
 end, required = true, feature = true },
    { key = "AutoSellUnits", name = "Auto Sell Unit", factory = function() -- AUTO → Auto Sell Unit.
-- Rule list pola Ride A Pet. Jual backpack lewat SellInventory.
-- Plot, locked, dan pending trade tidak dijual. NodeHubNeonUI tidak diubah.

return function(Core)
    local RS = game:GetService("ReplicatedStorage")
    local NONE = "None"
    local COMPARE = {
        { key = "below", name = "Below" },
        { key = "above", name = "Above" },
    }

    local rules = {}
    local draft = {
        rarities = {},
        mutations = {},
        traits = {},
        grades = {},
        earnRule = "0",
        earnMode = "below",
    }

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function mapPreview(map)
        if mapSize(map) == 0 then
            return "any"
        end
        local first
        local extra = 0
        for k in pairs(map) do
            if not first then
                first = k
            else
                extra = extra + 1
            end
        end
        if extra > 0 then
            return first .. ", +" .. tostring(extra)
        end
        return first
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local SUFFIX = {
        k = 1e3,
        m = 1e6,
        b = 1e9,
        t = 1e12,
        qd = 1e15,
        qi = 1e18,
        sx = 1e21,
        sp = 1e24,
    }

    local function parseEarn(text)
        text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
        if text == "" then
            return 0
        end
        local n = tonumber(text)
        if n then
            return math.max(0, n)
        end
        local ok, value = pcall(function()
            return require(RS.Packages.NumberFormatter).ParseCompact(text)
        end)
        if ok and tonumber(value) then
            return math.max(0, tonumber(value))
        end
        local num, suf = text:lower():match("^([%d%.]+)([a-z]+)$")
        n = tonumber(num)
        local mul = suf and SUFFIX[suf]
        if n and mul then
            return math.max(0, n * mul)
        end
        return 0
    end

    local function clampMode(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "below"))
        if mode == "above" or mode == "over" or mode == ">=" then
            return "above"
        end
        return "below"
    end

    local function earnLabel(rule)
        local word = clampMode(rule and rule.earnMode) == "above" and "Above" or "Below"
        local n = parseEarn(rule and rule.earnRule)
        if n > 0 then
            return word .. " " .. Core.compact(n) .. "/s"
        end
        return word .. " any/s"
    end

    local function matchesEarn(earn, n, mode)
        n = tonumber(n) or 0
        if n <= 0 then
            return true
        end
        earn = tonumber(earn) or 0
        if clampMode(mode) == "above" then
            return earn >= n
        end
        return earn <= n
    end

    local function newRuleId()
        return tostring(os.clock()) .. "-" .. tostring(math.random(1000, 9999))
    end

    local function sanitizeRule(rule)
        if type(rule) ~= "table" then
            return nil
        end
        local fields = {}
        local src = type(rule.fields) == "table" and rule.fields or nil
        if src then
            for _, key in ipairs({ "rarity", "mutation", "trait", "grade", "earn" }) do
                if src[key] == true or src[key] == 1 or src[key] == "true" then
                    fields[key] = true
                end
            end
        end
        return {
            id = tostring(rule.id or newRuleId()),
            enabled = rule.enabled ~= false,
            fields = fields,
            rarities = copyMap(rule.rarities),
            mutations = copyMap(rule.mutations),
            traits = copyMap(rule.traits),
            grades = copyMap(rule.grades),
            earnRule = tostring(rule.earnRule or "0"),
            earnMode = clampMode(rule.earnMode),
        }
    end

    local function setRules(list)
        local out = {}
        if type(list) == "table" then
            for _, rule in ipairs(list) do
                local clean = sanitizeRule(rule)
                if clean then
                    out[#out + 1] = clean
                end
            end
        end
        rules = out
        return rules
    end

    local function enabledRules()
        local out = {}
        for _, rule in ipairs(rules) do
            if rule.enabled ~= false then
                out[#out + 1] = rule
            end
        end
        return out
    end

    local function fieldOn(rule, key)
        local fields = type(rule) == "table" and rule.fields or nil
        if type(fields) ~= "table" or mapSize(fields) == 0 then
            return true
        end
        return fields[key] == true
    end

    local function inMap(map, value)
        if mapSize(map) == 0 then
            return false
        end
        return map[tostring(value or NONE)] == true
    end

    local function ruleMatches(rule, info)
        if type(rule) ~= "table" or type(info) ~= "table" then
            return false
        end
        if fieldOn(rule, "rarity") and not inMap(rule.rarities, info.rarity) then
            return false
        end
        if fieldOn(rule, "mutation") and not inMap(rule.mutations, info.mutation or NONE) then
            return false
        end
        if fieldOn(rule, "trait") and not inMap(rule.traits, info.trait or NONE) then
            return false
        end
        if fieldOn(rule, "grade") and not inMap(rule.grades, info.grade or NONE) then
            return false
        end
        if fieldOn(rule, "earn") and not matchesEarn(info.earn, parseEarn(rule.earnRule), rule.earnMode) then
            return false
        end
        return true
    end

    local function unitAllowed(info)
        local enabled = enabledRules()
        if #enabled == 0 then
            return false
        end
        for _, rule in ipairs(enabled) do
            if ruleMatches(rule, info) then
                return true
            end
        end
        return false
    end

    local function formatRule(rule)
        rule = sanitizeRule(rule) or {}
        local parts = {}
        local function add(text, style)
            text = tostring(text or "")
            if text == "" then
                return
            end
            if #parts > 0 then
                parts[#parts + 1] = { text = " · ", style = "sep" }
            end
            parts[#parts + 1] = { text = text, style = style }
        end
        if fieldOn(rule, "rarity") then
            add(mapPreview(rule.rarities), "rarity")
        end
        if fieldOn(rule, "mutation") then
            add(mapPreview(rule.mutations), "fruit")
        end
        if fieldOn(rule, "trait") then
            add(mapPreview(rule.traits), "kg")
        end
        if fieldOn(rule, "grade") then
            add(mapPreview(rule.grades), "rarity")
        end
        if fieldOn(rule, "earn") then
            add(earnLabel(rule), "rarity")
        end
        if #parts == 0 then
            add("Any unit", "default")
        end
        return {
            id = rule.id,
            enabled = rule.enabled ~= false,
            parts = parts,
        }
    end

    local function sortedItems(mod, extra)
        local out = {}
        if extra then
            out[#out + 1] = extra
        end
        if type(mod) ~= "table" then
            return out
        end
        local rows = {}
        for key, info in pairs(mod) do
            if type(key) == "string" and type(info) == "table" then
                rows[#rows + 1] = {
                    key = key,
                    label = key,
                    order = tonumber(info.order or info.sortOrder) or 99,
                }
            end
        end
        table.sort(rows, function(a, b)
            if a.order == b.order then
                return a.label < b.label
            end
            return a.order < b.order
        end)
        for _, row in ipairs(rows) do
            out[#out + 1] = row
        end
        return out
    end

    local rarityItemsCache
    local function rarityItems()
        if rarityItemsCache then
            return rarityItemsCache
        end
        local out = {}
        pcall(function()
            local Rarities = require(RS.Framework.Other.Rarities)
            local refs = Rarities.Refs
            for _, name in pairs(refs) do
                local info = Rarities.Get(name)
                out[#out + 1] = {
                    key = name,
                    label = name,
                    order = type(info) == "table" and tonumber(info.sortOrder) or 99,
                }
            end
        end)
        table.sort(out, function(a, b)
            if a.order == b.order then
                return tostring(a.label) < tostring(b.label)
            end
            return a.order < b.order
        end)
        rarityItemsCache = out
        return out
    end

    local mutItems, traitItems, gradeItems
    local function mutationItems()
        if mutItems then
            return mutItems
        end
        local ok, mod = pcall(function()
            return require(RS.Framework.Features.Inventory.Kinds.Unit.Mutations)
        end)
        mutItems = sortedItems(ok and mod, { key = NONE, label = NONE, order = 0 })
        return mutItems
    end

    local function traitItemList()
        if traitItems then
            return traitItems
        end
        local ok, mod = pcall(function()
            return require(RS.Framework.Features.Traits.Traits)
        end)
        traitItems = sortedItems(ok and mod, { key = NONE, label = NONE, order = 0 })
        return traitItems
    end

    local function gradeItemList()
        if gradeItems then
            return gradeItems
        end
        local ok, mod = pcall(function()
            return require(RS.Framework.Features.Grades.Grades)
        end)
        gradeItems = sortedItems(ok and mod, { key = NONE, label = NONE, order = 0 })
        return gradeItems
    end

    local function wrapFieldStack(parent)
        local wrap = Instance.new("Frame")
        wrap.Name = "FieldStack"
        wrap.BackgroundTransparency = 1
        wrap.BorderSizePixel = 0
        wrap.Size = UDim2.new(1, 0, 0, 0)
        wrap.AutomaticSize = Enum.AutomaticSize.Y
        wrap.LayoutOrder = #parent:GetChildren() + 1
        wrap.Parent = parent
        local list = Instance.new("UIListLayout")
        list.FillDirection = Enum.FillDirection.Vertical
        list.SortOrder = Enum.SortOrder.LayoutOrder
        list.Padding = UDim.new(0, 0)
        list.Parent = wrap
        return wrap
    end

    local registry
    local function entryConfig(name)
        if type(registry) ~= "table" then
            pcall(function()
                registry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
        end
        if type(registry) ~= "table" or type(registry.getEntryConfig) ~= "function" then
            return nil
        end
        local ok, cfg = pcall(registry.getEntryConfig, name)
        if ok and type(cfg) == "table" and cfg.kind == "Unit" then
            return cfg
        end
        return nil
    end

    local function profile(item, unitId)
        if type(item) ~= "table" then
            return nil
        end
        local name = readVal(item.name)
        local cfg = entryConfig(name)
        if not cfg then
            return nil
        end
        local attrs = type(item.attributes) == "table" and item.attributes or item
        local opts = {
            mutation = readVal(attrs.mutation),
            trait = readVal(attrs.trait),
            grade = readVal(attrs.grade),
            level = readVal(attrs.level),
        }
        if type(opts.mutation) ~= "string" or opts.mutation == "" then
            opts.mutation = nil
        end
        local rarity
        if type(cfg.getRarity) == "function" then
            local ok, value = pcall(cfg.getRarity, opts)
            if ok and value ~= nil then
                rarity = tostring(value)
            end
        end
        local earn = 0
        if type(cfg.income) == "function" then
            local ok, value = pcall(cfg.income, opts)
            earn = ok and tonumber(value) or 0
        end
        return {
            key = unitId,
            name = name,
            rarity = rarity,
            mutation = opts.mutation,
            trait = opts.trait,
            grade = opts.grade,
            earn = earn,
            locked = readVal(attrs.locked) == true,
            amount = tonumber(readVal(item.amount)) or 1,
        }
    end

    local function plottedIds(data)
        local out = {}
        for _, slot in ipairs(Core.slots()) do
            local getter = data.Slots and data.Slots[tostring(slot)]
            if getter ~= nil then
                local ok, row = pcall(getter)
                if ok and type(row) == "table" then
                    local id = readVal(row.unitId)
                    if type(id) == "string" and id ~= "" then
                        out[id] = true
                    end
                end
            end
        end
        return out
    end

    local function pendingTrade()
        if type(Core.tradeBusy) == "function" then
            local ok, on = pcall(Core.tradeBusy)
            if ok then
                return on == true
            end
        end
        local row
        pcall(function()
            row = Core.data().PendingTrade()
        end)
        return type(row) == "table" and row.applied ~= true
    end

    local sellFn
    local function sellRemote()
        if type(sellFn) == "function" then
            return sellFn
        end
        pcall(function()
            sellFn = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "SellService"):GetFunction("SellInventory")
        end)
        return sellFn
    end

    local lastReady = 0
    local lastSold = 0
    local lastBag = 0
    local lastCap = 0
    local scanCache
    local scanAt = 0
    local scanN = -1
    local delaySec = 1
    local keepPercent = 90
    local almostFull = true
    local DEFAULT_ALMOST_MIN = "100t"
    local almostMinEarn = parseEarn(DEFAULT_ALMOST_MIN)
    if almostMinEarn <= 0 then
        almostMinEarn = 100 * 1e12
    end
    local sellHeader
    local sellLoop

    local function almostMinLabel()
        if almostMinEarn <= 0 then
            return nil
        end
        return "below " .. Core.compact(almostMinEarn)
    end

    local function clampDelay(n)
        n = tonumber(n) or delaySec
        if n < 0.1 then
            n = 0.1
        elseif n > 10 then
            n = 10
        end
        return n
    end

    local function clampKeep(n)
        n = tonumber(n) or keepPercent
        if n < 1 then
            n = 1
        elseif n > 100 then
            n = 100
        end
        return math.floor(n + 0.5)
    end

    local function unitCap()
        local n
        pcall(function()
            n = require(RS.Framework.Features.Buffs.BuffController).GetBuff("Unit Storage")
        end)
        n = tonumber(n) or 0
        if n < 1 then
            n = 1
        end
        return n
    end

    local function keepCount(cap)
        cap = tonumber(cap) or 1
        local n = math.floor(cap * keepPercent / 100)
        if n < 0 then
            n = 0
        elseif n > cap then
            n = cap
        end
        return n
    end

    local function paintHeader()
        local n = #enabledRules()
        local bag = tostring(lastBag) .. "/" .. tostring(lastCap > 0 and lastCap or "-")
        if not sellLoop or not sellLoop.enabled() then
            if almostFull then
                local offHint = "keep " .. tostring(keepPercent) .. "%"
                local minHint = almostMinLabel()
                Core.paintHeader(sellHeader, "Off", "muted", minHint and (offHint .. " · " .. minHint) or offHint)
            else
                Core.paintHeader(sellHeader, "Off", "muted", n == 0 and "add a rule" or (tostring(n) .. " rules"))
            end
            return
        end
        if almostFull then
            local keep = keepCount(lastCap > 0 and lastCap or unitCap())
            local minHint = almostMinLabel()
            if lastSold > 0 then
                Core.paintHeader(sellHeader, "Sold", "success", tostring(lastSold) .. " · " .. bag .. " keep " .. tostring(keep))
                return
            end
            if lastReady > 0 then
                Core.paintHeader(sellHeader, "On", "success", "sell " .. tostring(lastReady) .. " · " .. bag)
                return
            end
            if lastBag > keep and minHint then
                Core.paintHeader(sellHeader, "Idle", "muted", bag .. " · none " .. minHint)
                return
            end
            Core.paintHeader(sellHeader, "Idle", "muted", bag .. " · keep " .. tostring(keepPercent) .. "%")
            return
        end
        if n == 0 then
            Core.paintHeader(sellHeader, "Idle", "muted", "add a sell rule first")
            return
        end
        local hint
        for _, rule in ipairs(enabledRules()) do
            if fieldOn(rule, "earn") then
                hint = earnLabel(rule)
                break
            end
        end
        if lastSold > 0 then
            Core.paintHeader(sellHeader, "Sold", "success", tostring(lastSold) .. " · ready " .. tostring(lastReady))
            return
        end
        if lastReady <= 0 then
            Core.paintHeader(sellHeader, "On", "muted", hint and ("0 match · " .. hint) or "0 match")
            return
        end
        Core.paintHeader(sellHeader, "On", "success", tostring(lastReady) .. " ready" .. (hint and (" · " .. hint) or ""))
    end

    local function scanInventory()
        local data = Core.data()
        local inv
        local okInv = pcall(function()
            inv = data.Inventory()
        end)
        local cap = unitCap()
        lastCap = cap
        if not okInv or type(inv) ~= "table" then
            lastBag = 0
            return {
                count = 0,
                cap = cap,
                sellable = {},
            }
        end
        local n = 0
        for _ in pairs(inv) do
            n = n + 1
        end
        if type(scanCache) == "table" and scanN == n and (os.clock() - scanAt) < 3 then
            lastBag = scanCache.count
            return scanCache
        end
        local plotted = plottedIds(data)
        local count = 0
        local sellable = {}
        for id, item in pairs(inv) do
            local key = tostring(id or "")
            if key ~= "" then
                local info = profile(item, key)
                if info then
                    count = count + 1
                    if info.amount > 0 and not info.locked and not plotted[key] then
                        sellable[#sellable + 1] = info
                    end
                end
            end
        end
        lastBag = count
        scanCache = {
            count = count,
            cap = cap,
            sellable = sellable,
        }
        scanAt = os.clock()
        scanN = n
        return scanCache
    end

    local function collectOverflowIds()
        local bag = scanInventory()
        local extra = bag.count - keepCount(bag.cap)
        if extra <= 0 then
            return {}
        end
        local pool = bag.sellable
        if almostMinEarn > 0 then
            pool = {}
            for _, info in ipairs(bag.sellable) do
                if matchesEarn(info.earn, almostMinEarn, "below") then
                    pool[#pool + 1] = info
                end
            end
        end
        table.sort(pool, function(a, b)
            local ea = tonumber(a.earn) or 0
            local eb = tonumber(b.earn) or 0
            if ea == eb then
                return tostring(a.key) < tostring(b.key)
            end
            return ea < eb
        end)
        local ids = {}
        local n = math.min(extra, #pool)
        for i = 1, n do
            ids[i] = pool[i].key
        end
        return ids
    end

    local function collectRuleIds()
        local bag = scanInventory()
        local ids = {}
        for _, info in ipairs(bag.sellable) do
            if unitAllowed(info) then
                ids[#ids + 1] = info.key
            end
        end
        return ids
    end

    local function trySell()
        lastSold = 0
        if pendingTrade() then
            lastReady = 0
            paintHeader()
            return
        end
        local ids
        if almostFull then
            ids = collectOverflowIds()
        else
            if #enabledRules() == 0 then
                lastReady = 0
                paintHeader()
                return
            end
            ids = collectRuleIds()
        end
        lastReady = #ids
        if #ids == 0 then
            paintHeader()
            return
        end
        local fn = sellRemote()
        if type(fn) ~= "function" then
            paintHeader()
            return
        end
        local ok, money, count = pcall(fn, ids)
        if ok then
            lastSold = tonumber(count) or #ids
            if lastSold <= 0 and type(money) == "number" and money > 0 then
                lastSold = #ids
            end
        end
        paintHeader()
    end

    sellLoop = Core.loop("auto_sell_units", {
        delay = delaySec,
        step = trySell,
    })

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 4,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Sell Unit",
                expanded = false,
                status = {
                    id = "auto.sell.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "add a rule",
                },
            })
            sellHeader = api
            local group = ui:CreateGroup(body)

            local ruleApi
            local function persistRules()
                if ruleApi and type(ruleApi.set) == "function" then
                    pcall(ruleApi.set, rules)
                end
                paintHeader()
            end

            local _, bindRules = ui:CreateRuleList(group, {
                id = "auto.sell.rules",
                title = "Saved Rules",
                searchPlaceholder = "Search rules...",
                emptyText = "No rules yet. Empty = sell none.",
                visibleRows = 5,
                persist = true,
                getItems = function()
                    return rules
                end,
                formatItem = formatRule,
                onLoad = function(list)
                    setRules(list)
                end,
                onToggle = function(rule, enabled)
                    local id = type(rule) == "table" and tostring(rule.id or "") or ""
                    for _, item in ipairs(rules) do
                        if tostring(item.id) == id then
                            item.enabled = enabled == true
                            break
                        end
                    end
                    persistRules()
                end,
                onDelete = function(rule)
                    local id = type(rule) == "table" and tostring(rule.id or "") or ""
                    local nextList = {}
                    for _, item in ipairs(rules) do
                        if tostring(item.id) ~= id then
                            nextList[#nextList + 1] = item
                        end
                    end
                    rules = nextList
                    persistRules()
                end,
            })
            ruleApi = bindRules

            local _, formApi = ui:CreateRuleForm(group, {
                id = "auto.sell.draft.modes",
                label = "Rule Fields",
                placeholder = "Pick fields...",
                hintText = "Pick rarity, mutation, trait, grade, and/or earn/s. Plot and locked units are never sold.",
                persist = true,
                modes = {
                    { key = "rarity", name = "Rarity" },
                    { key = "mutation", name = "Mutation" },
                    { key = "trait", name = "Trait" },
                    { key = "grade", name = "Grade" },
                    { key = "earn", name = "Earn/s" },
                },
            })

            local _, rarityApi = ui:CreateRowDropdown(group, {
                id = "auto.sell.draft.rarities",
                label = "Rarity",
                mode = "multi",
                placeholder = "Any rarity",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = rarityItems,
                onChanged = function(a, b)
                    draft.rarities = copyMap(dropdownValue(a, b))
                end,
            })

            local _, mutationApi = ui:CreateRowDropdown(group, {
                id = "auto.sell.draft.mutations",
                label = "Mutation",
                mode = "multi",
                placeholder = "Any mutation",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = mutationItems,
                onChanged = function(a, b)
                    draft.mutations = copyMap(dropdownValue(a, b))
                end,
            })

            local _, traitApi = ui:CreateRowDropdown(group, {
                id = "auto.sell.draft.traits",
                label = "Trait",
                mode = "multi",
                placeholder = "Any trait",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = traitItemList,
                onChanged = function(a, b)
                    draft.traits = copyMap(dropdownValue(a, b))
                end,
            })

            local _, gradeApi = ui:CreateRowDropdown(group, {
                id = "auto.sell.draft.grades",
                label = "Grade",
                mode = "multi",
                placeholder = "Any grade",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = gradeItemList,
                onChanged = function(a, b)
                    draft.grades = copyMap(dropdownValue(a, b))
                end,
            })

            local earnWrap = wrapFieldStack(group)
            local _, earnModeApi = ui:CreateRowDropdown(earnWrap, {
                id = "auto.sell.draft.earnMode",
                label = "Earn/s mode",
                placeholder = "Mode",
                clearable = false,
                persist = true,
                preserveItemOrder = true,
                initial = "below",
                getItems = function()
                    return COMPARE
                end,
                onChanged = function(a, b)
                    draft.earnMode = clampMode(dropdownValue(a, b))
                end,
            })
            local _, _, commitEarn, earnApi = ui:CreateRowInput(earnWrap, {
                id = "auto.sell.draft.earnRule",
                label = "Earn/s",
                initial = "0",
                hintText = "Example 1000, 10k, 1m. 0 = any.",
                clearOnFocus = false,
                persist = true,
                onChanged = function(text)
                    draft.earnRule = tostring(text or "0")
                end,
            })

            if formApi and type(formApi.attach) == "function" then
                formApi.attach("rarity", rarityApi, function()
                    draft.rarities = {}
                    if rarityApi and type(rarityApi.clear) == "function" then
                        pcall(rarityApi.clear, true)
                    end
                end)
                formApi.attach("mutation", mutationApi, function()
                    draft.mutations = {}
                    if mutationApi and type(mutationApi.clear) == "function" then
                        pcall(mutationApi.clear, true)
                    end
                end)
                formApi.attach("trait", traitApi, function()
                    draft.traits = {}
                    if traitApi and type(traitApi.clear) == "function" then
                        pcall(traitApi.clear, true)
                    end
                end)
                formApi.attach("grade", gradeApi, function()
                    draft.grades = {}
                    if gradeApi and type(gradeApi.clear) == "function" then
                        pcall(gradeApi.clear, true)
                    end
                end)
                formApi.attach("earn", { root = earnWrap }, function()
                    draft.earnRule = "0"
                    draft.earnMode = "below"
                    if earnApi and type(earnApi.set) == "function" then
                        pcall(earnApi.set, "0", true)
                    end
                    if earnModeApi and type(earnModeApi.setSelected) == "function" then
                        pcall(earnModeApi.setSelected, "below", true)
                    end
                end)
                pcall(formApi.apply)
            end

            ui:CreateRowButton(group, {
                text = "APPLY → Add Rule",
                kind = "primary",
                onClick = function()
                    local modes = formApi and formApi.getModes and formApi.getModes() or {}
                    local hasMode = false
                    for _, on in pairs(modes) do
                        if on == true then
                            hasMode = true
                            break
                        end
                    end
                    if not hasMode then
                        return
                    end
                    if type(commitEarn) == "function" then
                        pcall(commitEarn)
                    end
                    if earnApi and type(earnApi.get) == "function" then
                        draft.earnRule = tostring(earnApi.get() or "0")
                    end
                    if earnModeApi and type(earnModeApi.getSelected) == "function" then
                        draft.earnMode = clampMode(earnModeApi.getSelected())
                    end
                    rules[#rules + 1] = sanitizeRule({
                        enabled = true,
                        fields = modes,
                        rarities = modes.rarity and draft.rarities or {},
                        mutations = modes.mutation and draft.mutations or {},
                        traits = modes.trait and draft.traits or {},
                        grades = modes.grade and draft.grades or {},
                        earnRule = modes.earn and draft.earnRule or "0",
                        earnMode = modes.earn and draft.earnMode or "below",
                    })
                    persistRules()
                end,
            })

            ui:CreateRowSlider(group, {
                id = "auto.sell.delay",
                label = "Delay",
                min = 0.1,
                max = 10,
                step = 0.1,
                initial = delaySec,
                suffix = "s",
                onChanged = function(n)
                    delaySec = clampDelay(n)
                    sellLoop.setDelay(delaySec)
                end,
            })

            local enableGroup = ui:CreateGroup(body)
            ui:CreateRowSlider(enableGroup, {
                id = "auto.sell.keepPercent",
                label = "Keep backpack",
                min = 1,
                max = 100,
                step = 1,
                initial = keepPercent,
                suffix = "%",
                onChanged = function(n)
                    keepPercent = clampKeep(n)
                    paintHeader()
                end,
            })
            local note = ui:CreateRowLabel(enableGroup, {
                text = "When on, rules are ignored. Only overflow above Keep backpack % is sold, lowest earn/s first. Sell only below earn/s skips units at or above that earn. If none are below, backpack stays full. 0 = no earn cap. Plot and locked are never sold.",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            ui:CreateRowInput(enableGroup, {
                id = "auto.sell.almostMinEarn",
                label = "Sell only below earn/s",
                hintText = "Example 100t. 0 = no earn cap (old overflow).",
                initial = DEFAULT_ALMOST_MIN,
                persist = true,
                clearOnFocus = false,
                onChanged = function(text)
                    almostMinEarn = parseEarn(text)
                    paintHeader()
                end,
            })
            Core.bindToggle(ui, enableGroup, {
                id = "auto.sell.almostFull",
                label = "Autosell when Backpack Almost Full",
                initial = almostFull,
                onChanged = function(on)
                    almostFull = on == true
                    paintHeader()
                end,
            })
            Core.bindToggle(ui, enableGroup, {
                id = "auto.sell",
                label = "Enable Auto Sell",
                initial = sellLoop.enabled(),
                onChanged = function(on)
                    sellLoop.setEnabled(on == true)
                    paintHeader()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if type(values["auto.sell.rules"]) == "table" then
            setRules(values["auto.sell.rules"])
        end
        if values["auto.sell.delay"] ~= nil then
            delaySec = clampDelay(values["auto.sell.delay"])
            sellLoop.setDelay(delaySec)
        end
        if values["auto.sell.keepPercent"] ~= nil then
            keepPercent = clampKeep(values["auto.sell.keepPercent"])
        end
        if values["auto.sell.almostMinEarn"] ~= nil then
            almostMinEarn = parseEarn(values["auto.sell.almostMinEarn"])
        else
            almostMinEarn = parseEarn(DEFAULT_ALMOST_MIN)
            if almostMinEarn <= 0 then
                almostMinEarn = 100 * 1e12
            end
        end
        if values["auto.sell.almostFull"] == nil then
            almostFull = true
        else
            almostFull = values["auto.sell.almostFull"] == true
        end
        sellLoop.setEnabled(values["auto.sell"] == true)
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "AutoLockUnits", name = "Auto Lock Unit", factory = function() -- AUTO → Auto Lock Unit.
-- Dua list: Lock / Unlock. Field: rarity, earn/s, level, 1-in.
-- Lock menang kalau match keduanya. Plot ikut di-scan. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local Earn = Core.unitEarn or G.AnimeDiceUnitEarn
    local COMPARE = {
        { key = "above", name = "Above" },
        { key = "below", name = "Below" },
    }
    local TARGETS = {
        { key = "lock", name = "Lock list" },
        { key = "unlock", name = "Unlock list" },
    }

    local old = G.AnimeDiceAutoLock
    if type(old) == "table" then
        if type(old.setEnabled) == "function" then
            pcall(old.setEnabled, false)
        end
        if type(old.stop) == "function" then
            pcall(old.stop)
        end
    end

    local lockRules = {}
    local unlockRules = {}
    local addTarget = "lock"
    local draft = {
        rarities = {},
        earnRule = "0",
        earnMode = "above",
        levelRule = "0",
        levelMode = "above",
        chanceRule = "0",
        chanceMode = "above",
        quirks = {},
    }
    local delaySec = 1
    local lastLock = 0
    local lastUnlock = 0
    local headerApi
    local lockLoop

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
            return nil
        end
        if type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if ok and r ~= v then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function mapPreview(map)
        if mapSize(map) == 0 then
            return "any"
        end
        local first
        local extra = 0
        for k in pairs(map) do
            if not first then
                first = k
            else
                extra = extra + 1
            end
        end
        if extra > 0 then
            return first .. ", +" .. tostring(extra)
        end
        return first
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local SUFFIX = {
        k = 1e3,
        m = 1e6,
        b = 1e9,
        t = 1e12,
        qd = 1e15,
        qi = 1e18,
        sx = 1e21,
        sp = 1e24,
    }

    local function parseEarn(text)
        text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
        if text == "" then
            return 0
        end
        local n = tonumber(text)
        if n then
            return math.max(0, n)
        end
        local ok, value = pcall(function()
            return require(RS.Packages.NumberFormatter).ParseCompact(text)
        end)
        if ok and tonumber(value) then
            return math.max(0, tonumber(value))
        end
        local num, suf = text:lower():match("^([%d%.]+)([a-z]+)$")
        n = tonumber(num)
        local mul = suf and SUFFIX[suf]
        if n and mul then
            return math.max(0, n * mul)
        end
        return 0
    end

    local function clampMode(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "above"))
        if mode == "below" or mode == "under" or mode == "<=" then
            return "below"
        end
        return "above"
    end

    local function clampTarget(v)
        v = tostring(dropdownValue(v, nil) or v or "lock")
        if v == "unlock" then
            return "unlock"
        end
        return "lock"
    end

    local function clampDelay(n)
        n = tonumber(n) or 1
        if n < 0.2 then
            n = 0.2
        elseif n > 10 then
            n = 10
        end
        return math.floor(n * 10 + 0.5) / 10
    end

    local function parseLevel(text)
        local n = tonumber(tostring(text or "0"):gsub(",", ""):gsub("%s", ""))
        if not n or n ~= n then
            return 0
        end
        n = math.floor(n)
        if n < 0 then
            n = 0
        elseif n > 999 then
            n = 999
        end
        return n
    end

    local function newRuleId()
        return tostring(os.clock()) .. "-" .. tostring(math.random(1000, 9999))
    end

    local function sanitizeRule(rule)
        if type(rule) ~= "table" then
            return nil
        end
        local fields = {}
        local src = type(rule.fields) == "table" and rule.fields or nil
        if src then
            for _, key in ipairs({ "rarity", "earn", "level", "chance", "quirk" }) do
                if src[key] == true or src[key] == 1 or src[key] == "true" then
                    fields[key] = true
                end
            end
        end
        return {
            id = tostring(rule.id or newRuleId()),
            enabled = rule.enabled ~= false,
            fields = fields,
            rarities = copyMap(rule.rarities),
            earnRule = tostring(rule.earnRule or "0"),
            earnMode = clampMode(rule.earnMode),
            levelRule = tostring(rule.levelRule or "0"),
            levelMode = clampMode(rule.levelMode),
            chanceRule = tostring(rule.chanceRule or "0"),
            chanceMode = clampMode(rule.chanceMode),
            quirks = copyMap(rule.quirks),
        }
    end

    local function setList(which, list)
        local out = {}
        if type(list) == "table" then
            for _, rule in ipairs(list) do
                local clean = sanitizeRule(rule)
                if clean then
                    out[#out + 1] = clean
                end
            end
        end
        if which == "unlock" then
            unlockRules = out
        else
            lockRules = out
        end
        return out
    end

    local function enabledRules(list)
        local out = {}
        if type(list) ~= "table" then
            return out
        end
        for _, rule in ipairs(list) do
            if rule.enabled ~= false then
                out[#out + 1] = rule
            end
        end
        return out
    end

    local function fieldOn(rule, key)
        local fields = type(rule) == "table" and rule.fields or nil
        if type(fields) ~= "table" or mapSize(fields) == 0 then
            return true
        end
        return fields[key] == true
    end

    local function inMap(map, value)
        if mapSize(map) == 0 then
            return false
        end
        return map[tostring(value or "")] == true
    end

    local function matchesNum(have, want, mode)
        want = tonumber(want) or 0
        if want <= 0 then
            return true
        end
        have = tonumber(have) or 0
        if clampMode(mode) == "below" then
            return have <= want
        end
        return have >= want
    end

    local function ruleMatches(rule, info)
        if type(rule) ~= "table" or type(info) ~= "table" then
            return false
        end
        if type(rule.fields) ~= "table" or mapSize(rule.fields) == 0 then
            return false
        end
        if fieldOn(rule, "rarity") and not inMap(rule.rarities, info.rarity) then
            return false
        end
        if fieldOn(rule, "earn") and not matchesNum(info.earn, parseEarn(rule.earnRule), rule.earnMode) then
            return false
        end
        if fieldOn(rule, "level") and not matchesNum(info.level, parseLevel(rule.levelRule), rule.levelMode) then
            return false
        end
        if fieldOn(rule, "chance") then
            if not tonumber(info.chance) then
                return false
            end
            if not matchesNum(info.chance, parseEarn(rule.chanceRule), rule.chanceMode) then
                return false
            end
        end
        if fieldOn(rule, "quirk") and not inMap(rule.quirks, info.quirk) then
            return false
        end
        return true
    end

    local function anyMatch(list, info)
        for _, rule in ipairs(enabledRules(list)) do
            if ruleMatches(rule, info) then
                return true
            end
        end
        return false
    end

    local function numLabel(kind, rule)
        local modeKey = kind == "level" and rule.levelMode or (kind == "chance" and rule.chanceMode or rule.earnMode)
        local mode = clampMode(modeKey)
        local word = mode == "below" and "Below" or "Above"
        if kind == "level" then
            local n = parseLevel(rule.levelRule)
            if n > 0 then
                return word .. " Lv " .. tostring(n)
            end
            return word .. " any Lv"
        end
        if kind == "chance" then
            local n = parseEarn(rule.chanceRule)
            if n > 0 then
                return "1-in " .. word .. " " .. Core.compact(n)
            end
            return "1-in any"
        end
        local n = parseEarn(rule.earnRule)
        if n > 0 then
            return word .. " " .. Core.compact(n) .. "/s"
        end
        return word .. " any/s"
    end

    local function formatRule(rule)
        rule = sanitizeRule(rule) or {}
        local parts = {}
        local function add(text, style)
            text = tostring(text or "")
            if text == "" then
                return
            end
            if #parts > 0 then
                parts[#parts + 1] = { text = " · ", style = "sep" }
            end
            parts[#parts + 1] = { text = text, style = style }
        end
        if fieldOn(rule, "rarity") then
            add(mapPreview(rule.rarities), "rarity")
        end
        if fieldOn(rule, "earn") then
            add(numLabel("earn", rule), "rarity")
        end
        if fieldOn(rule, "level") then
            add(numLabel("level", rule), "kg")
        end
        if fieldOn(rule, "chance") then
            add(numLabel("chance", rule), "rarity")
        end
        if fieldOn(rule, "quirk") then
            add(mapPreview(rule.quirks), "fruit")
        end
        if #parts == 0 then
            add("Any unit", "default")
        end
        return {
            id = rule.id,
            enabled = rule.enabled ~= false,
            parts = parts,
        }
    end

    local rarityItemsCache
    local function rarityItems()
        if rarityItemsCache then
            return rarityItemsCache
        end
        local out = {}
        pcall(function()
            local Rarities = require(RS.Framework.Other.Rarities)
            local refs = Rarities.Refs
            for _, name in pairs(refs) do
                local info = Rarities.Get(name)
                out[#out + 1] = {
                    key = name,
                    label = name,
                    order = type(info) == "table" and tonumber(info.sortOrder) or 99,
                }
            end
        end)
        table.sort(out, function(a, b)
            if a.order == b.order then
                return tostring(a.label) < tostring(b.label)
            end
            return a.order < b.order
        end)
        rarityItemsCache = out
        return out
    end

    local quirkItemsCache
    local function quirkItems()
        if quirkItemsCache then
            return quirkItemsCache
        end
        local out = {}
        pcall(function()
            local Quirks = require(RS.Framework.Features.Quirks.Quirks)
            for key, info in pairs(Quirks) do
                if type(key) == "string" and type(info) == "table" then
                    local bits = {}
                    for buff, row in pairs(info.buffs or {}) do
                        local amt = type(row) == "table" and tonumber(row.amount)
                        if amt then
                            bits[#bits + 1] = string.format("%g%% %s", amt * 100, buff == "Money Multiplier" and "$" or tostring(buff))
                        end
                    end
                    table.sort(bits)
                    out[#out + 1] = {
                        key = key,
                        label = #bits > 0 and (key .. "  " .. table.concat(bits, " ")) or key,
                        order = -(tonumber(info.order) or 0),
                    }
                end
            end
        end)
        table.sort(out, function(a, b)
            if a.order ~= b.order then
                return a.order < b.order
            end
            return a.key < b.key
        end)
        if #out > 0 then
            quirkItemsCache = out
        end
        return out
    end

    local function wrapFieldStack(parent)
        local wrap = Instance.new("Frame")
        wrap.Name = "FieldStack"
        wrap.BackgroundTransparency = 1
        wrap.BorderSizePixel = 0
        wrap.Size = UDim2.new(1, 0, 0, 0)
        wrap.AutomaticSize = Enum.AutomaticSize.Y
        wrap.LayoutOrder = #parent:GetChildren() + 1
        wrap.Parent = parent
        local list = Instance.new("UIListLayout")
        list.FillDirection = Enum.FillDirection.Vertical
        list.SortOrder = Enum.SortOrder.LayoutOrder
        list.Padding = UDim.new(0, 0)
        list.Parent = wrap
        return wrap
    end

    local registry
    local function entryConfig(name)
        if type(registry) ~= "table" then
            pcall(function()
                registry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
        end
        if type(registry) ~= "table" or type(registry.getEntryConfig) ~= "function" then
            return nil
        end
        local ok, cfg = pcall(registry.getEntryConfig, name)
        if ok and type(cfg) == "table" and cfg.kind == "Unit" then
            return cfg
        end
        return nil
    end

    local function profile(item, unitId)
        if type(item) ~= "table" then
            return nil
        end
        local name = readVal(item.name)
        local cfg = entryConfig(name)
        if not cfg then
            return nil
        end
        local attrs
        if type(Earn) == "table" and type(Earn.attrs) == "function" then
            attrs = Earn.attrs(item)
        else
            local raw = type(item.attributes) == "table" and item.attributes or item
            attrs = {
                mutation = readVal(raw.mutation),
                trait = readVal(raw.trait),
                grade = readVal(raw.grade),
                level = tonumber(readVal(raw.level)) or 1,
                locked = readVal(raw.locked) == true,
                quirk = readVal(raw.quirk),
            }
        end
        if type(attrs.mutation) ~= "string" or attrs.mutation == "" then
            attrs.mutation = nil
        end
        local rarity
        if type(cfg.getRarity) == "function" then
            local ok, value = pcall(cfg.getRarity, attrs)
            if ok and value ~= nil then
                rarity = tostring(value)
            end
        end
        local earn = 0
        if type(Earn) == "table" and type(Earn.income) == "function" then
            earn = tonumber(Earn.income(cfg, attrs)) or 0
        elseif type(cfg.income) == "function" then
            local ok, value = pcall(cfg.income, attrs)
            earn = ok and tonumber(value) or 0
        end
        local chance
        if type(Earn) == "table" and type(Earn.chance) == "function" then
            chance = tonumber(Earn.chance(cfg, attrs, name))
        elseif type(cfg.chance) == "function" then
            local ok, value = pcall(cfg.chance, {
                mutation = attrs.mutation,
            })
            chance = ok and tonumber(value) or nil
        end
        return {
            key = unitId,
            name = name,
            rarity = rarity,
            earn = earn,
            chance = chance,
            level = tonumber(attrs.level) or 1,
            locked = attrs.locked == true,
            quirk = attrs.quirk,
        }
    end

    local function pendingTrade()
        if type(Core.tradeBusy) == "function" then
            local ok, on = pcall(Core.tradeBusy)
            if ok and on == true then
                return true
            end
        end
        local row
        pcall(function()
            row = Core.data().PendingTrade()
        end)
        return type(row) == "table" and row.applied ~= true
    end

    local lockRemote
    local function getLockRemote()
        if lockRemote then
            return lockRemote
        end
        pcall(function()
            lockRemote = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "UnitService"):GetSignal("SetLocked")
        end)
        return lockRemote
    end

    local function paintHeader()
        if type(headerApi) ~= "table" then
            return
        end
        local nLock = #enabledRules(lockRules)
        local nUnlock = #enabledRules(unlockRules)
        local detail = "lock " .. tostring(nLock) .. " · unlock " .. tostring(nUnlock)
        local on = lockLoop and lockLoop.enabled()
        if not on then
            Core.paintHeader(headerApi, "Off", "muted", (nLock + nUnlock) == 0 and "add a rule" or detail)
            return
        end
        if pendingTrade() then
            Core.paintHeader(headerApi, "Pause", "muted", "trade")
            return
        end
        if lastLock > 0 or lastUnlock > 0 then
            Core.paintHeader(headerApi, "On", "success", "set lock " .. tostring(lastLock) .. " · unlock " .. tostring(lastUnlock))
            return
        end
        Core.paintHeader(headerApi, "On", "success", detail)
    end

    local function tryLock()
        lastLock = 0
        lastUnlock = 0
        if not lockLoop or not lockLoop.enabled() then
            paintHeader()
            return
        end
        if pendingTrade() then
            paintHeader()
            return
        end
        if #enabledRules(lockRules) == 0 and #enabledRules(unlockRules) == 0 then
            paintHeader()
            return
        end
        local data = Core.data()
        local inv
        local okInv = pcall(function()
            inv = data.Inventory()
        end)
        if not okInv or type(inv) ~= "table" then
            paintHeader()
            return
        end
        local batch = {}
        local nLock = 0
        local nUnlock = 0
        for id, item in pairs(inv) do
            local key = tostring(id or "")
            if key ~= "" then
                local info = profile(item, key)
                if info then
                    local wantLock = anyMatch(lockRules, info)
                    local wantUnlock = anyMatch(unlockRules, info)
                    local want
                    if wantLock then
                        want = true
                    elseif wantUnlock then
                        want = false
                    end
                    if want ~= nil and info.locked ~= want then
                        batch[key] = want
                        if want then
                            nLock = nLock + 1
                        else
                            nUnlock = nUnlock + 1
                        end
                    end
                end
            end
        end
        if nLock == 0 and nUnlock == 0 then
            paintHeader()
            return
        end
        local remote = getLockRemote()
        if not remote then
            paintHeader()
            return
        end
        local ok = pcall(function()
            remote:Fire(batch)
        end)
        if ok then
            lastLock = nLock
            lastUnlock = nUnlock
        end
        paintHeader()
    end

    lockLoop = Core.loop("auto_lock_units", {
        delay = delaySec,
        step = tryLock,
    })

    G.AnimeDiceAutoLock = {
        setEnabled = function(on)
            lockLoop.setEnabled(on == true)
            paintHeader()
        end,
        stop = function()
            lockLoop.stop()
        end,
    }

    local function makeRuleList(ui, group, which, title, empty, persistId)
        local api
        local function persist()
            if api and type(api.set) == "function" then
                pcall(api.set, which == "unlock" and unlockRules or lockRules)
            end
            paintHeader()
        end
        local _, bind = ui:CreateRuleList(group, {
            id = persistId,
            title = title,
            searchPlaceholder = "Search rules...",
            emptyText = empty,
            visibleRows = 4,
            persist = true,
            getItems = function()
                return which == "unlock" and unlockRules or lockRules
            end,
            formatItem = formatRule,
            onLoad = function(list)
                setList(which, list)
            end,
            onToggle = function(rule, enabled)
                local id = type(rule) == "table" and tostring(rule.id or "") or ""
                local rows = which == "unlock" and unlockRules or lockRules
                for _, item in ipairs(rows) do
                    if tostring(item.id) == id then
                        item.enabled = enabled == true
                        break
                    end
                end
                persist()
            end,
            onDelete = function(rule)
                local id = type(rule) == "table" and tostring(rule.id or "") or ""
                local rows = which == "unlock" and unlockRules or lockRules
                local nextList = {}
                for _, item in ipairs(rows) do
                    if tostring(item.id) ~= id then
                        nextList[#nextList + 1] = item
                    end
                end
                setList(which, nextList)
                persist()
            end,
        })
        api = bind
        return {
            persist = persist,
            api = api,
        }
    end

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 4.5,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Lock Unit",
                expanded = false,
                status = {
                    id = "auto.lock.status",
