            headerApi = api
            local group = ui:CreateGroup(body)

            local lockList = makeRuleList(ui, group, "lock", "Saved Lock Rules", "No lock rules. Empty = lock none.", "auto.lock.rules")
            local unlockList = makeRuleList(ui, group, "unlock", "Saved Unlock Rules", "No unlock rules. Empty = unlock none.", "auto.unlock.rules")

            ui:CreateRowDropdown(group, {
                id = "auto.lock.addTo",
