                clearOnFocus = false,
                persist = true,
                onChanged = function(text)
                    draft.chanceRule = tostring(text or "0")
                end,
            })

            if formApi and type(formApi.attach) == "function" then
                formApi.attach("rarity", rarityApi, function()
                    draft.rarities = {}
                    if rarityApi and type(rarityApi.clear) == "function" then
                        pcall(rarityApi.clear, true)
                    end
                end)
                formApi.attach("earn", { root = earnWrap }, function()
                    draft.earnRule = "0"
                    draft.earnMode = "above"
                    if earnApi and type(earnApi.set) == "function" then
                        pcall(earnApi.set, "0", true)
                    end
                    if earnModeApi and type(earnModeApi.setSelected) == "function" then
                        pcall(earnModeApi.setSelected, "above", true)
                    end
                end)
                formApi.attach("level", { root = levelWrap }, function()
                    draft.levelRule = "0"
                    draft.levelMode = "above"
                    if levelApi and type(levelApi.set) == "function" then
                        pcall(levelApi.set, "0", true)
                    end
                    if levelModeApi and type(levelModeApi.setSelected) == "function" then
                        pcall(levelModeApi.setSelected, "above", true)
                    end
                end)
                formApi.attach("chance", { root = chanceWrap }, function()
                    draft.chanceRule = "0"
                    draft.chanceMode = "above"
                    if chanceApi and type(chanceApi.set) == "function" then
                        pcall(chanceApi.set, "0", true)
                    end
                    if chanceModeApi and type(chanceModeApi.setSelected) == "function" then
                        pcall(chanceModeApi.setSelected, "above", true)
                    end
                end)
                formApi.attach("quirk", quirkApi, function()
                    draft.quirks = {}
                    if quirkApi and type(quirkApi.clear) == "function" then
                        pcall(quirkApi.clear, true)
                    end
                end)
                pcall(formApi.apply)
            end

            ui:CreateRowButton(group, {
                text = "APPLY → Add Rule",
                kind = "primary",
                onClick = function()
                    local modes = formApi and formApi.getModes and formApi.getModes() or {}
                    local hasMode = false
                    for _, on in pairs(modes) do
                        if on == true then
                            hasMode = true
                            break
                        end
                    end
                    if not hasMode then
                        return
                    end
                    if type(commitEarn) == "function" then
                        pcall(commitEarn)
                    end
                    if type(commitLevel) == "function" then
                        pcall(commitLevel)
                    end
                    if type(commitChance) == "function" then
                        pcall(commitChance)
                    end
                    if earnApi and type(earnApi.get) == "function" then
                        draft.earnRule = tostring(earnApi.get() or "0")
                    end
                    if earnModeApi and type(earnModeApi.getSelected) == "function" then
                        draft.earnMode = clampMode(earnModeApi.getSelected())
                    end
                    if levelApi and type(levelApi.get) == "function" then
                        draft.levelRule = tostring(levelApi.get() or "0")
                    end
                    if levelModeApi and type(levelModeApi.getSelected) == "function" then
                        draft.levelMode = clampMode(levelModeApi.getSelected())
                    end
                    if chanceApi and type(chanceApi.get) == "function" then
                        draft.chanceRule = tostring(chanceApi.get() or "0")
                    end
                    if chanceModeApi and type(chanceModeApi.getSelected) == "function" then
                        draft.chanceMode = clampMode(chanceModeApi.getSelected())
                    end
                    local row = sanitizeRule({
                        enabled = true,
                        fields = modes,
                        rarities = modes.rarity and draft.rarities or {},
                        earnRule = modes.earn and draft.earnRule or "0",
                        earnMode = modes.earn and draft.earnMode or "above",
                        levelRule = modes.level and draft.levelRule or "0",
                        levelMode = modes.level and draft.levelMode or "above",
                        chanceRule = modes.chance and draft.chanceRule or "0",
                        chanceMode = modes.chance and draft.chanceMode or "above",
                        quirks = modes.quirk and draft.quirks or {},
                    })
                    if addTarget == "unlock" then
                        unlockRules[#unlockRules + 1] = row
                        unlockList.persist()
                    else
                        lockRules[#lockRules + 1] = row
                        lockList.persist()
                    end
                end,
            })

            ui:CreateRowSlider(group, {
                id = "auto.lock.delay",
                label = "Delay",
                min = 0.2,
                max = 10,
                step = 0.1,
                initial = delaySec,
                suffix = "s",
                onChanged = function(n)
                    delaySec = clampDelay(n)
                    lockLoop.setDelay(delaySec)
                end,
            })

            local enableGroup = ui:CreateGroup(body)
            local note = ui:CreateRowLabel(enableGroup, {
                text = "Lock list locks matching units. Unlock list unlocks matching units. If both match, lock wins. Already-correct units are skipped. Trade pauses. Plot units are included.",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            Core.bindToggle(ui, enableGroup, {
                id = "auto.lock",
                label = "Enable Auto Lock",
                initial = false,
                onChanged = function(on)
                    lockLoop.setEnabled(on == true)
                    paintHeader()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if type(values["auto.lock.rules"]) == "table" then
            setList("lock", values["auto.lock.rules"])
        end
        if type(values["auto.unlock.rules"]) == "table" then
            setList("unlock", values["auto.unlock.rules"])
        end
        if values["auto.lock.addTo"] ~= nil then
            addTarget = clampTarget(values["auto.lock.addTo"])
        end
        if values["auto.lock.delay"] ~= nil then
            delaySec = clampDelay(values["auto.lock.delay"])
            lockLoop.setDelay(delaySec)
        end
        lockLoop.setEnabled(values["auto.lock"] == true)
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "AutoFuseUnits", name = "Auto Fuse", factory = function() -- AUTO → Auto Fuse.
-- Rule = unit yang boleh dibakar. Hanya Safe: 3 1-in dekat, tidak fuse kalau hasil tipikal di bawah bahan terbaik.
-- Locked, limited, amount ~= 1 tidak di-fuse. Plot hanya kalau Skip if On plot. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    G.AnimeDiceOnFuseResult = nil
    local RS = game:GetService("ReplicatedStorage")
    local NONE = "None"
    local COMPARE = {
        { key = "below", name = "Below" },
        { key = "above", name = "Above" },
    }
    local PICK_ORDERS = {
        { key = "lowest", name = "Lowest 1-in" },
        { key = "highest", name = "Highest 1-in" },
    }

    local rules = {}
    local draft = {
        rarities = {},
        mutations = {},
        traits = {},
        grades = {},
        earnMin = "0",
        earnMax = "0",
        chanceMin = "0",
        chanceMax = "0",
    }
    local pickOrder = "lowest"
    local safeMaxGap = 2
    local skipMap = {
        hasGrade = true,
        hasTrait = true,
        levelAbove1 = true,
        onPlot = true,
    }
    local fuseSkipApi
    local skipQuirks = {}
    local quirksMod
    pcall(function()
        quirksMod = require(RS.Framework.Features.Quirks.Quirks)
    end)

    local function quirkItems()
        local out = {}
        if type(quirksMod) ~= "table" then
            return out
        end
        for key, info in pairs(quirksMod) do
            if type(key) == "string" and type(info) == "table" then
                local bits = {}
                for buff, row in pairs(info.buffs or {}) do
                    local amt = type(row) == "table" and tonumber(row.amount)
                    if amt then
                        bits[#bits + 1] = string.format("%g%% %s", amt * 100, buff == "Money Multiplier" and "$" or tostring(buff))
                    end
                end
                table.sort(bits)
                out[#out + 1] = {
                    key = key,
                    label = #bits > 0 and (key .. "  " .. table.concat(bits, " ")) or key,
                    order = -(tonumber(info.order) or 0),
                }
            end
        end
        table.sort(out, function(a, b)
            if a.order ~= b.order then
                return a.order < b.order
            end
            return a.key < b.key
        end)
        return out
    end

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function mapPreview(map)
        if mapSize(map) == 0 then
            return ""
        end
        local first
        local extra = 0
        for k in pairs(map) do
            if not first then
                first = k
            else
                extra = extra + 1
            end
        end
        if extra > 0 then
            return first .. ", +" .. tostring(extra)
        end
        return first
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local function parseEarn(text)
        text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
        if text == "" then
            return 0
        end
        local n = tonumber(text)
        if n then
            return math.max(0, n)
        end
        local ok, value = pcall(function()
            return require(RS.Packages.NumberFormatter).ParseCompact(text)
        end)
        return ok and tonumber(value) or 0
    end

    local function clampEarnMode(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "below"))
        if mode == "above" or mode == "over" or mode == ">=" then
            return "above"
        end
        return "below"
    end

    local function clampPickOrder(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "lowest"))
        if mode == "highest" or mode == "high" or mode == "top" then
            return "highest"
        end
        return "lowest"
    end

    local function clampSafeGap(n)
        n = tonumber(n) or 2
        if n < 1.01 then
            n = 1.01
        elseif n > 4 then
            n = 4
        end
        return n
    end

    local function earnLabel(rule)
        local lo = parseEarn(rule and rule.earnMin)
        local hi = parseEarn(rule and rule.earnMax)
        if lo > 0 and hi > 0 then
            if lo > hi then
                lo, hi = hi, lo
            end
            return Core.compact(lo) .. "-" .. Core.compact(hi) .. "/s"
        end
        if lo > 0 then
            return "≥ " .. Core.compact(lo) .. "/s"
        end
        if hi > 0 then
            return "≤ " .. Core.compact(hi) .. "/s"
        end
        return ""
    end

    local function chanceLabel(rule)
        local lo = parseEarn(rule and rule.chanceMin)
        local hi = parseEarn(rule and rule.chanceMax)
        if lo > 0 and hi > 0 then
            if lo > hi then
                lo, hi = hi, lo
            end
            return "1-in " .. Core.compact(lo) .. "-" .. Core.compact(hi)
        end
        if lo > 0 then
            return "1-in ≥ " .. Core.compact(lo)
        end
        if hi > 0 then
            return "1-in ≤ " .. Core.compact(hi)
        end
        return ""
    end

    local function matchesEarn(value, lo, hi)
        lo = tonumber(lo) or 0
        hi = tonumber(hi) or 0
        if lo > 0 and hi > 0 and lo > hi then
            lo, hi = hi, lo
        end
        if lo <= 0 and hi <= 0 then
            return false
        end
        value = tonumber(value)
        if not value then
            return false
        end
        if lo > 0 and value < lo then
            return false
        end
        if hi > 0 and value > hi then
            return false
        end
        return true
    end

    local function newRuleId()
        return tostring(os.clock()) .. "-" .. tostring(math.random(1000, 9999))
    end

    local function sanitizeRule(rule)
        if type(rule) ~= "table" then
            return nil
        end
        local fields = {}
        local src = type(rule.fields) == "table" and rule.fields or nil
        if src then
            for _, key in ipairs({ "rarity", "mutation", "trait", "grade", "earn", "chance" }) do
                if src[key] == true or src[key] == 1 or src[key] == "true" then
                    fields[key] = true
                end
            end
        end
        local earnMin = tostring(rule.earnMin or "")
        local earnMax = tostring(rule.earnMax or "")
        if earnMin == "" and earnMax == "" then
            local n = tostring(rule.earnRule or "0")
            if clampEarnMode(rule.earnMode) == "above" then
                earnMin = n
                earnMax = "0"
            else
                earnMin = "0"
                earnMax = n
            end
        end
        if earnMin == "" then
            earnMin = "0"
        end
        if earnMax == "" then
            earnMax = "0"
        end
        local chanceMin = tostring(rule.chanceMin or "")
        local chanceMax = tostring(rule.chanceMax or "")
        if chanceMin == "" and chanceMax == "" then
            local n = tostring(rule.chanceRule or "0")
            if clampEarnMode(rule.chanceMode) == "above" then
                chanceMin = n
                chanceMax = "0"
            else
                chanceMin = "0"
                chanceMax = n
            end
        end
        if chanceMin == "" then
            chanceMin = "0"
        end
        if chanceMax == "" then
            chanceMax = "0"
        end
        return {
            id = tostring(rule.id or newRuleId()),
            enabled = rule.enabled ~= false,
            fields = fields,
            rarities = copyMap(rule.rarities),
            mutations = copyMap(rule.mutations),
            traits = copyMap(rule.traits),
            grades = copyMap(rule.grades),
            earnMin = earnMin,
            earnMax = earnMax,
            chanceMin = chanceMin,
            chanceMax = chanceMax,
        }
    end

    local function setRules(list)
        local out = {}
        if type(list) == "table" then
            for _, rule in ipairs(list) do
                local clean = sanitizeRule(rule)
                if clean then
                    out[#out + 1] = clean
                end
            end
        end
        rules = out
        return rules
    end

    local function enabledRules()
        local out = {}
        for _, rule in ipairs(rules) do
            if rule.enabled ~= false then
                out[#out + 1] = rule
            end
        end
        return out
    end

    local function fieldOn(rule, key)
        local fields = type(rule) == "table" and rule.fields or nil
        if type(fields) ~= "table" then
            return false
        end
        return fields[key] == true
    end

    local function fieldReady(rule, key)
        if not fieldOn(rule, key) then
            return false
        end
        if key == "earn" then
            return parseEarn(rule.earnMin) > 0 or parseEarn(rule.earnMax) > 0
        end
        if key == "chance" then
            return parseEarn(rule.chanceMin) > 0 or parseEarn(rule.chanceMax) > 0
        end
        local map = key == "rarity" and rule.rarities
            or key == "mutation" and rule.mutations
            or key == "trait" and rule.traits
            or key == "grade" and rule.grades
        return mapSize(map) > 0
    end

    local function ruleReady(rule)
        if type(rule) ~= "table" or rule.enabled == false then
            return false
        end
        return fieldReady(rule, "rarity")
            or fieldReady(rule, "mutation")
            or fieldReady(rule, "trait")
            or fieldReady(rule, "grade")
            or fieldReady(rule, "earn")
            or fieldReady(rule, "chance")
    end

    local function readyRules()
        local out = {}
        for _, rule in ipairs(enabledRules()) do
            if ruleReady(rule) then
                out[#out + 1] = rule
            end
        end
        return out
    end

    local function inMap(map, value)
        if mapSize(map) == 0 then
            return false
        end
        return map[tostring(value or NONE)] == true
    end

    local function ruleMatches(rule, info)
        if type(rule) ~= "table" or type(info) ~= "table" then
            return false
        end
        if not ruleReady(rule) then
            return false
        end
        if fieldOn(rule, "rarity") then
            if not fieldReady(rule, "rarity") or not inMap(rule.rarities, info.rarity) then
                return false
            end
        end
        if fieldOn(rule, "mutation") then
            if not fieldReady(rule, "mutation") or not inMap(rule.mutations, info.mutation or NONE) then
                return false
            end
        end
        if fieldOn(rule, "trait") then
            if not fieldReady(rule, "trait") or not inMap(rule.traits, info.trait or NONE) then
                return false
            end
        end
        if fieldOn(rule, "grade") then
            if not fieldReady(rule, "grade") or not inMap(rule.grades, info.grade or NONE) then
                return false
            end
        end
        if fieldOn(rule, "earn") then
            if not fieldReady(rule, "earn") or not matchesEarn(info.earn, parseEarn(rule.earnMin), parseEarn(rule.earnMax)) then
                return false
            end
        end
        if fieldOn(rule, "chance") then
            if not fieldReady(rule, "chance") or not matchesEarn(info.chance, parseEarn(rule.chanceMin), parseEarn(rule.chanceMax)) then
                return false
            end
        end
        return true
    end

    local function unitAllowed(info)
        local enabled = readyRules()
        if #enabled == 0 then
            return false
        end
        for _, rule in ipairs(enabled) do
            if ruleMatches(rule, info) then
                return true
            end
        end
        return false
    end

    local function formatRule(rule)
        rule = sanitizeRule(rule) or {}
        local parts = {}
        local function add(text, style)
            text = tostring(text or "")
            if text == "" then
                return
            end
            if #parts > 0 then
                parts[#parts + 1] = { text = " · ", style = "sep" }
            end
            parts[#parts + 1] = { text = text, style = style }
        end
        if fieldReady(rule, "rarity") then
            add(mapPreview(rule.rarities), "rarity")
        end
        if fieldReady(rule, "mutation") then
            add(mapPreview(rule.mutations), "fruit")
        end
        if fieldReady(rule, "trait") then
            add(mapPreview(rule.traits), "kg")
        end
        if fieldReady(rule, "grade") then
            add(mapPreview(rule.grades), "rarity")
        end
        if fieldReady(rule, "earn") then
            add(earnLabel(rule), "rarity")
        end
        if fieldReady(rule, "chance") then
            add(chanceLabel(rule), "rarity")
        end
        if #parts == 0 then
            add("Incomplete", "default")
        end
        return {
            id = rule.id,
            enabled = rule.enabled ~= false,
            parts = parts,
        }
    end

    local function sortedItems(mod, extra)
        local out = {}
        if extra then
            out[#out + 1] = extra
        end
        if type(mod) ~= "table" then
            return out
        end
        local rows = {}
        for key, info in pairs(mod) do
            if type(key) == "string" and type(info) == "table" then
                rows[#rows + 1] = {
                    key = key,
                    label = key,
                    order = tonumber(info.order or info.sortOrder) or 99,
                }
            end
        end
        table.sort(rows, function(a, b)
            if a.order == b.order then
                return a.label < b.label
            end
            return a.order < b.order
        end)
        for _, row in ipairs(rows) do
            out[#out + 1] = row
        end
        return out
    end

    local rarityItemsCache
    local function rarityItems()
        if rarityItemsCache then
            return rarityItemsCache
        end
        local out = {}
        pcall(function()
            local Rarities = require(RS.Framework.Other.Rarities)
            local refs = Rarities.Refs
            for _, name in pairs(refs) do
                local info = Rarities.Get(name)
                out[#out + 1] = {
                    key = name,
                    label = name,
                    order = type(info) == "table" and tonumber(info.sortOrder) or 99,
                }
            end
        end)
        table.sort(out, function(a, b)
            if a.order == b.order then
                return tostring(a.label) < tostring(b.label)
            end
            return a.order < b.order
        end)
        rarityItemsCache = out
        return out
    end

    local mutItems, traitItems, gradeItems
