        return traitItems
    end

    local function gradeItemList()
        if gradeItems then
            return gradeItems
        end
        local ok, mod = pcall(function()
            return require(RS.Framework.Features.Grades.Grades)
        end)
        gradeItems = sortedItems(ok and mod, { key = NONE, label = NONE, order = 0 })
        return gradeItems
    end

    local function wrapFieldStack(parent)
        local wrap = Instance.new("Frame")
        wrap.Name = "FieldStack"
        wrap.BackgroundTransparency = 1
        wrap.BorderSizePixel = 0
        wrap.Size = UDim2.new(1, 0, 0, 0)
        wrap.AutomaticSize = Enum.AutomaticSize.Y
        wrap.LayoutOrder = #parent:GetChildren() + 1
        wrap.Parent = parent
        local list = Instance.new("UIListLayout")
        list.FillDirection = Enum.FillDirection.Vertical
        list.SortOrder = Enum.SortOrder.LayoutOrder
        list.Padding = UDim.new(0, 0)
        list.Parent = wrap
        return wrap
    end

    local registry
    local function entryConfig(name)
        if type(registry) ~= "table" then
            pcall(function()
                registry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
        end
        if type(registry) ~= "table" or type(registry.getEntryConfig) ~= "function" then
            return nil
        end
        local ok, cfg = pcall(registry.getEntryConfig, name)
        if ok and type(cfg) == "table" and cfg.kind == "Unit" then
            return cfg
        end
        return nil
    end

    local fuseUtil, fuseCfg
    local function fuseMods()
        if type(fuseUtil) == "table" and type(fuseCfg) == "table" then
            return fuseUtil, fuseCfg
        end
        pcall(function()
            local folder = RS.Framework.Features.Fusing
            fuseUtil = require(folder.FusingUtil)
            fuseCfg = require(folder.FusingConfig)
        end)
        return fuseUtil, fuseCfg
    end

    local function fmtNum(n, digits)
        n = tonumber(n)
        if not n then
            return "?"
        end
        local t = string.format("%." .. tostring(digits or 3) .. "f", n)
        t = t:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
        return t
    end

    local function fuseStats()
        local _, cfg = fuseMods()
        local avg = 2 / 3
        local floorMin = 0.375
        local floorMax = 0.625
        local floorW = 60
        local capMax = 20
        local totalW = 0
        if type(cfg) == "table" then
            if type(cfg.AverageMultiplier) == "number" then
                avg = cfg.AverageMultiplier
            end
            local pools = cfg.Pools
            if type(pools) == "table" then
                for _, pool in ipairs(pools) do
                    if type(pool) == "table" then
                        totalW = totalW + (tonumber(pool.weight) or 0)
                        if type(pool.max) == "number" and pool.max > capMax then
                            capMax = pool.max
                        end
                    end
                end
                local first = pools[1]
                if type(first) == "table" then
                    if type(first.min) == "number" then
                        floorMin = first.min
                    end
                    if type(first.max) == "number" then
                        floorMax = first.max
                    end
                    if type(first.weight) == "number" then
                        floorW = first.weight
                    end
                end
            end
        end
        local function gapEqual(mul)
            mul = tonumber(mul)
            if not mul or mul <= 0 or mul >= 1 then
                return 4
            end
            return (2 * mul) / (1 - mul)
        end
        local function gapTied(mul)
            mul = tonumber(mul)
            if not mul or mul <= 0 then
                return 4
            end
            local t = (1 / mul) - 2
            if t <= 0 then
                return 4
            end
            return 1 / t
        end
        local floorPct = floorW
        if totalW > 0 then
            floorPct = (floorW / totalW) * 100
        end
        if floorW >= 1 then
            floorPct = floorW
        end
        return {
            avg = avg,
            floorMin = floorMin,
            floorMax = floorMax,
            capMax = capMax,
            floorPct = floorPct,
            minSumMul = (1 / floorMin) - 1,
            gapGreen = gapEqual(floorMin),
            gapYellow = gapTied(floorMin),
        }
    end

    local gapInfoApi
    local gapSliderRow
    local GAP_SLIDER_COLORS = {
        green = Color3.fromRGB(184, 245, 212),
        yellow = Color3.fromRGB(255, 233, 163),
        red = Color3.fromRGB(255, 196, 200),
    }

    local function gapZone(gap)
        local st = fuseStats()
        gap = clampSafeGap(gap)
        if gap <= st.gapGreen + 0.05 then
            return "green", st
        end
        if gap <= st.gapYellow + 0.05 then
            return "yellow", st
        end
        return "red", st
    end

    local function fmtIn(n)
        n = tonumber(n)
        if not n then
            return "?"
        end
        if n >= 1000 then
            return Core.compact(n)
        end
        if n >= 10 then
            return tostring(math.floor(n + 0.5))
        end
        return fmtNum(n, 2)
    end

    local function buildGapInfo()
        local gap = clampSafeGap(safeMaxGap)
        local zone, st = gapZone(gap)
        local H = 300
        local eq = math.max(1, math.ceil((H / gap) - 1e-9))
        local sum = H + eq + eq
        local resMin = st.floorMin * sum
        local resMax = (st.capMax or 20) * sum
        local example = string.format(
            "Example: 300 + %s + %s at %s× → %s–%s",
            tostring(eq),
            tostring(eq),
            fmtNum(gap, 2),
            fmtIn(resMin),
            fmtIn(resMax)
        )
        local floorTxt = fmtNum(st.floorMin, 3)
        if resMin + 1e-9 < H then
            local style = zone == "red" and "error" or "warn"
            return string.format(
                "! %s\nWorst %s× = %s, below 300. High unit can drop.",
                example,
                floorTxt,
                fmtIn(resMin)
            ), style
        end
        return string.format(
            "%s\nSafe vs %s× floor: worst still ≥ 300.",
            example,
            floorTxt
        ), "detail"
    end

    local function paintGapSlider()
        local zone = gapZone(safeMaxGap)
        local color = GAP_SLIDER_COLORS[zone] or GAP_SLIDER_COLORS.green
        local row = gapSliderRow
        if not row then
            return
        end
        local fill = row:FindFirstChild("Fill", true)
        local knob = row:FindFirstChild("Knob", true)
        local label = row:FindFirstChild("Label")
        if fill then
            fill.BackgroundColor3 = color
        end
        if knob then
            knob.BackgroundColor3 = color
        end
        if label then
            label.TextColor3 = color
            if zone == "green" then
                label.Text = "Max 1-in gap"
            else
                label.Text = "! Max 1-in gap"
            end
        end
    end

    local function paintGapInfo()
        paintGapSlider()
        local text, style = buildGapInfo()
        if type(gapInfoApi) == "table" then
            if type(gapInfoApi.set) == "function" then
                pcall(gapInfoApi.set, text)
            end
            if type(gapInfoApi.setStyle) == "function" then
                pcall(gapInfoApi.setStyle, style or "detail")
            end
        end
    end

    local function profile(item, unitId)
        if type(item) ~= "table" then
            return nil
        end
        local name = readVal(item.name)
        local cfg = entryConfig(name)
        if not cfg then
            return nil
        end
        local rawAttrs = readVal(item.attributes)
        if type(rawAttrs) ~= "table" then
            rawAttrs = item
        end
        local opts = {
            mutation = readVal(rawAttrs.mutation),
            trait = readVal(rawAttrs.trait),
            grade = readVal(rawAttrs.grade),
            level = readVal(rawAttrs.level),
        }
        if type(opts.mutation) ~= "string" or opts.mutation == "" then
            opts.mutation = nil
        end
        local rarity
        if type(cfg.getRarity) == "function" then
            local ok, value = pcall(cfg.getRarity, opts)
            if ok and value ~= nil then
                rarity = tostring(value)
            end
        end
        local earn = 0
        if type(cfg.income) == "function" then
            local ok, value = pcall(cfg.income, opts)
            earn = ok and tonumber(value) or 0
        end
        local amount = tonumber(readVal(item.amount)) or 1
        local locked = readVal(rawAttrs.locked) == true
        local util = fuseMods()
        local chance
        if type(util) == "table" and type(util.GetChance) == "function" then
            local okItem, fromItem = pcall(util.GetChance, item)
            chance = okItem and tonumber(fromItem) or nil
            if not chance then
                local ok, value = pcall(util.GetChance, {
                    amount = 1,
                    name = name,
                    attributes = {
                        mutation = opts.mutation,
                        locked = locked,
                        level = opts.level,
                        trait = opts.trait,
                        grade = opts.grade,
                    },
                })
                chance = ok and tonumber(value) or nil
            end
        end
        return {
            key = unitId,
            name = name,
            rarity = rarity,
            mutation = opts.mutation,
            trait = opts.trait,
            grade = opts.grade,
            earn = earn,
            chance = chance,
            locked = locked,
            amount = amount,
            level = tonumber(opts.level) or 1,
            quirk = readVal(rawAttrs.quirk),
        }
    end

    local function plottedIds(data)
        local out = {}
        for _, slot in ipairs(Core.slots()) do
            local getter = data.Slots and data.Slots[tostring(slot)]
            if getter ~= nil then
                local ok, row = pcall(getter)
                if ok and type(row) == "table" then
                    local id = readVal(row.unitId)
                    if type(id) == "string" and id ~= "" then
                        out[id] = true
                    end
                end
            end
        end
        return out
    end

    local function pendingTrade()
        if type(Core.tradeBusy) == "function" then
            local ok, on = pcall(Core.tradeBusy)
            if ok then
                return on == true
            end
        end
        local row
        pcall(function()
            row = Core.data().PendingTrade()
        end)
        return type(row) == "table" and row.applied ~= true
    end

    local fuseRemote
    local function getFuseRemote()
        if fuseRemote then
            return fuseRemote
        end
        pcall(function()
            fuseRemote = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "FusingService"):GetSignal("Fuse")
        end)
        return fuseRemote
    end

    local lastCost = 0
    local lastNeed = 0
    local lastNames = ""
    local lastWait = ""
    local delaySec = 30
    local keepPercent = 80
    local fuseWhileRolling = true
    local lastFire = 0
    local lastRolls = 0
    local lastRollAt = 0
    local rollsSeeded = false
    local readyPick
    local readyAt = 0
    local readySum = 0
    local readyCost = 0
    local poolCache = {}
    local poolCacheN = 0
    local fuseHeader
    local fuseLoop

    local function clampDelay(n)
        n = tonumber(n) or delaySec
        if n < 3.2 then
            n = 3.2
        elseif n > 200 then
            n = 200
        end
        return n
    end

    local function clampKeep(n)
        n = tonumber(n) or keepPercent
        if n < 0 then
            n = 0
        elseif n > 100 then
            n = 100
        end
        return n
    end

    local function paintHeader()
        local n = #enabledRules()
        local ready = #readyRules()
        if not fuseLoop or not fuseLoop.enabled() then
            Core.paintHeader(fuseHeader, "Off", "muted", n == 0 and "add a rule" or (tostring(n) .. " rules"))
            return
        end
        if n == 0 then
            Core.paintHeader(fuseHeader, "Idle", "muted", "add a fuse rule first")
            return
        end
        if ready == 0 then
            Core.paintHeader(fuseHeader, "Idle", "muted", "rule incomplete")
            return
        end
        if lastWait ~= "" then
            Core.paintHeader(fuseHeader, "Wait", "muted", lastWait)
            return
        end
        if lastNames ~= "" then
            Core.paintHeader(fuseHeader, "On", "success", lastNames .. " · " .. Core.compact(lastCost))
            return
        end
        Core.paintHeader(fuseHeader, "Idle", "muted", "need 3 close units")
    end

    local function isRolling()
        local env = Core.env()
        local fast = env.AnimeDiceFastRoll
        if type(fast) == "table" and type(fast.enabled) == "function" and fast.enabled() then
            return true
        end
        local auto = env.AnimeDiceAutoRoll
        if type(auto) == "table" and type(auto.enabled) == "function" and auto.enabled() then
            return true
        end
        local on = false
        pcall(function()
            on = Core.data().AutoRoll() == true
        end)
        return on == true
    end

    local function noteRollTick()
        local n
        pcall(function()
            n = tonumber(Core.data().Rolls())
        end)
        if not n then
            return
        end
        if not rollsSeeded then
            lastRolls = n
            rollsSeeded = true
            return
        end
        if n > lastRolls then
            lastRollAt = os.clock()
        end
        lastRolls = n
    end

    local function rollLock()
        local d = 1
        pcall(function()
            d = tonumber(require(game:GetService("ReplicatedStorage").Framework.Features.Buffs.BuffController).GetBuff("Roll Duration")) or 1
        end)
        if d < 0.25 then
            d = 0.25
        elseif d > 8 then
            d = 8
        end
        return d
    end

    local function lastRollClock()
        noteRollTick()
        local stamped = 0
        pcall(function()
            stamped = tonumber(Core.env().AnimeDiceLastRollAt) or 0
        end)
        if lastRollAt > stamped then
            return lastRollAt
        end
        return stamped
    end

    local function inRollWindow()
        local t = lastRollClock()
        if t <= 0 then
            return false
        end
        local age = os.clock() - t
        local lock = rollLock()
        return age >= 0.02 and age <= math.max(0.2, lock - 0.05)
    end

    local function useDelay(n)
        if fuseLoop and type(fuseLoop.setDelay) == "function" then
            fuseLoop.setDelay(n)
        end
    end

    local function poolsOk(a, b, c)
        local util = fuseMods()
        if type(util) ~= "table" or type(util.BuildPools) ~= "function" then
            return false, 0
        end
        local s = (tonumber(a.chance) or 0) + (tonumber(b.chance) or 0) + (tonumber(c.chance) or 0)
        if s <= 0 then
            return false, 0
        end
        local cached = poolCache[s]
        if cached ~= nil then
            return cached, s
        end
        local ok, pools = pcall(util.BuildPools, s)
        local valid = ok and type(pools) == "table" and #pools > 0
        if poolCacheN > 400 then
            poolCache = {}
            poolCacheN = 0
        end
        poolCache[s] = valid
        poolCacheN = poolCacheN + 1
        return valid, s
    end

    local function chanceSpread(a, b, c)
        local lo = math.min(a.chance, b.chance, c.chance)
        local hi = math.max(a.chance, b.chance, c.chance)
        if not lo or lo <= 0 then
            return math.huge
        end
        return hi / lo
    end

    local function safeNoLoss(a, b, c, sum)
        local hi = math.max(a.chance, b.chance, c.chance)
        sum = tonumber(sum) or ((tonumber(a.chance) or 0) + (tonumber(b.chance) or 0) + (tonumber(c.chance) or 0))
        if sum <= 0 or hi <= 0 then
            return false
        end
        local st = fuseStats()
        if st.avg * sum < hi then
            return false
        end
        if st.floorMin * sum < hi then
            return false
        end
        return true
    end

    local function tripletCost(sum)
        local _, cfg = fuseMods()
        local cost = 0
        if type(cfg) == "table" and type(cfg.GetCost) == "function" then
            pcall(function()
                cost = tonumber(cfg.GetCost(sum)) or 0
            end)
        end
        return cost
    end

    -- List is already sorted by Pick from (highest / lowest 1-in).
    -- Gap is only a cap. Take the first consecutive window that is Safe + payable.
    -- Do not score "tightest cluster" — that burns cheap 1-in packs while high 1-in sits in bag.
    local function pickTriplet(list, money)
        if type(list) ~= "table" or #list < 3 then
            return nil
        end
        local cap = clampSafeGap(safeMaxGap)
        local wait, waitSum, waitCost
        for i = 1, #list - 2 do
            local a, b, c = list[i], list[i + 1], list[i + 2]
            if chanceSpread(a, b, c) <= cap then
                local ok, s = poolsOk(a, b, c)
                if ok and safeNoLoss(a, b, c, s) then
                    local cost = tripletCost(s)
                    if Core.money().allows(money, cost, keepPercent) then
                        return { a, b, c }, s, cost, true
                    end
                    if not wait then
                        wait = { a, b, c }
                        waitSum = s
                        waitCost = cost
                    end
                end
            end
        end
        if wait then
            return wait, waitSum, waitCost, false
        end
        return nil
    end

    local function hasNamed(v)
        return type(v) == "string" and v ~= "" and v ~= NONE
    end

    local function skipUnit(info, plotted)
        if type(info) ~= "table" then
            return true
        end
        if skipMap.onPlot and type(plotted) == "table" then
            local key = tostring(info.key or "")
            if key ~= "" and plotted[key] then
                return true
            end
        end
        if skipMap.hasGrade and hasNamed(info.grade) then
            return true
        end
        if skipMap.hasTrait and hasNamed(info.trait) then
            return true
        end
        if skipMap.levelAbove1 and (tonumber(info.level) or 1) > 1 then
            return true
        end
        if hasNamed(info.quirk) and skipQuirks[info.quirk] then
            return true
        end
        local au = Core.env().AnimeDiceAutoUnit
        if type(au) == "table" then
            if type(au.isReserved) == "function" and au.isReserved(info.key) then
                return true
            end
            if type(au.reservedIds) == "function" then
                local bag = au.reservedIds()
                if type(bag) == "table" and bag[tostring(info.key or "")] then
                    return true
                end
            end
        end
        return false
    end

    local candCache = {}
    local candAt = 0
    local candN = -1
    local candTag = ""

    local function candSig()
        return table.concat({
            clampPickOrder(pickOrder),
            skipMap.hasGrade and "1" or "0",
            skipMap.hasTrait and "1" or "0",
            skipMap.levelAbove1 and "1" or "0",
            skipMap.onPlot and "1" or "0",
            (function()
                local keys = {}
                for k in pairs(skipQuirks) do
                    keys[#keys + 1] = k
                end
                table.sort(keys)
                return table.concat(keys, ",")
            end)(),
        }, "|")
    end

    local function bustCands()
        candCache = {}
        candN = -1
        candTag = ""
    end

    local function collectCandidates()
        local data = Core.data()
        local inv
        local okInv = pcall(function()
            inv = data.Inventory()
        end)
        if not okInv or type(inv) ~= "table" then
            return {}
        end
        local n = 0
        for _ in pairs(inv) do
            n = n + 1
        end
        local tag = candSig()
        if type(candCache) == "table" and candN == n and candTag == tag and (os.clock() - candAt) < 4 then
            return candCache
        end
        local plotted = plottedIds(data)
        local out = {}
        for id, item in pairs(inv) do
            local key = tostring(id or "")
            if key ~= "" then
                local info = profile(item, key)
                if info and info.chance and info.amount == 1 and not info.locked and not skipUnit(info, plotted) and unitAllowed(info) then
                    out[#out + 1] = info
                end
            end
        end
        table.sort(out, function(a, b)
            if a.chance == b.chance then
                return tostring(a.key) < tostring(b.key)
            end
            if clampPickOrder(pickOrder) == "highest" then
                return a.chance > b.chance
            end
            return a.chance < b.chance
        end)
        candCache = out
        candAt = os.clock()
        candN = n
        candTag = tag
        return out
    end

    local function bumpFail(err)
        lastFire = 0
        readyPick = nil
        bustCands()
        lastWait = tostring(err or "fuse rejected")
        useDelay(0.45)
        paintHeader()
    end

    pcall(function()
        local old = G.AnimeDiceFuseRetryConn
        if old and type(old.Disconnect) == "function" then
            old:Disconnect()
        end
        G.AnimeDiceFuseRetryConn = nil
        local sig = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "FusingService"):GetSignal("Result")
        if not sig or type(sig.Connect) ~= "function" then
            return
        end
        G.AnimeDiceFuseRetryConn = sig:Connect(function(unit, err)
            if type(unit) == "table" then
                lastWait = ""
                paintHeader()
                return
            end
            bumpFail(err)
        end)
    end)

    local function pickStillOk(pick)
        if type(pick) ~= "table" or not pick[1] or not pick[2] or not pick[3] then
            return false
        end
        local data = Core.data()
        local inv
        local okInv = pcall(function()
            inv = data.Inventory()
        end)
        if not okInv or type(inv) ~= "table" then
            return false
        end
        local plotted = plottedIds(data)
        for i = 1, 3 do
            local p = pick[i]
            local key = tostring(p.key or "")
            if key == "" then
                return false
            end
            if skipMap.onPlot and plotted[key] then
                return false
            end
            local row = inv[key]
            if type(row) ~= "table" then
                return false
            end
            local info = profile(row, key)
            if not info or not info.chance or info.locked or info.amount ~= 1 then
                return false
            end
            if hasNamed(info.quirk) and skipQuirks[info.quirk] then
                return false
            end
        end
        return true
    end

    local function tryFuse()
        lastWait = ""
        lastNames = ""
        lastCost = 0
        lastNeed = 0
        if pendingTrade() then
            lastWait = "pending trade"
            useDelay(delaySec)
            paintHeader()
            return
        end
        if not fuseWhileRolling and isRolling() then
            lastWait = "rolling"
            useDelay(delaySec)
            paintHeader()
            return
        end
        if #readyRules() == 0 then
            lastWait = #enabledRules() == 0 and "" or "rule incomplete"
            useDelay(delaySec)
            paintHeader()
            return
        end
        if os.clock() - lastFire < 3.2 then
            useDelay(0.25)
            paintHeader()
            return
        end
        local util, cfg = fuseMods()
        if type(util) ~= "table" or type(cfg) ~= "table" or type(cfg.GetCost) ~= "function" then
            lastWait = "fuse module missing"
            useDelay(delaySec)
            paintHeader()
            return
        end
        local money = 0
        pcall(function()
            money = tonumber(Core.data().Money()) or 0
        end)
        local pick, sum, cost, canPay
        if readyPick and os.clock() - readyAt < 0.9 and pickStillOk(readyPick) then
            pick, sum, cost, canPay = readyPick, readySum, readyCost, true
        else
            readyPick = nil
            pick, sum, cost, canPay = pickTriplet(collectCandidates(), money)
            if not pick then
                lastWait = "need closer 1-in"
                useDelay(delaySec)
                paintHeader()
                return
            end
            if canPay then
                readyPick = pick
                readyAt = os.clock()
                readySum = sum
                readyCost = cost
            end
        end
        lastCost = cost
        lastNames = tostring(pick[1].name) .. " · " .. tostring(pick[2].name) .. " · " .. tostring(pick[3].name)
        lastNeed = Core.money().required(cost, keepPercent)
        if canPay ~= true or not Core.money().allows(money, cost, keepPercent) then
            lastWait = Core.compact(money) .. " / " .. Core.compact(lastNeed)
            readyPick = nil
            useDelay(delaySec)
            paintHeader()
            return
        end
        local fastOn = false
        local fast = Core.env().AnimeDiceFastRoll
        if type(fast) == "table" and type(fast.enabled) == "function" then
            fastOn = fast.enabled() == true
        end
        if isRolling() and not fastOn and not inRollWindow() then
            lastWait = "sync roll"
            useDelay(0.1)
            paintHeader()
            return
        end
        if not pickStillOk(pick) then
            bumpFail("pick moved")
            return
        end
        local remote = getFuseRemote()
        if type(remote) ~= "table" or type(remote.Fire) ~= "function" then
            lastWait = "no fuse remote"
            useDelay(delaySec)
            paintHeader()
            return
        end
        local fired = pcall(function()
            local units = {}
            for i = 1, 3 do
                local p = pick[i]
                units[i] = {
                    name = p.name,
                    mutation = p.mutation,
                    chance = p.chance,
                    earn = p.earn,
                    rarity = p.rarity,
                    trait = p.trait,
                    grade = p.grade,
                }
            end
            G.AnimeDicePendingFuse = {
                at = os.clock(),
                units = units,
            }
            remote:Fire(pick[1].key, pick[2].key, pick[3].key)
        end)
        readyPick = nil
        bustCands()
        useDelay(delaySec)
        if fired then
            lastFire = os.clock()
            lastWait = ""
        else
            bumpFail("fire failed")
            return
        end
        paintHeader()
    end

