 end, required = true, feature = true },
    { key = "AutoPotion", name = "Auto Item", factory = function() -- AUTO → Auto Item.
-- Potion Use. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local Catalog = Core.potions and Core.potions() or G.AnimeDicePotionCatalog
    if type(Catalog) ~= "table" then
        warn("[ANIME DICE] Item catalog missing")
        return
    end

    local old = G.AnimeDiceAutoPotion
    if type(old) == "table" and type(old.setEnabled) == "function" then
        pcall(old.setEnabled, false)
    end

    local rules = {}
    local draft = {
        potions = {},
        whens = {},
    }
    local delaySec = 1
    local refreshSec = 30
    local headerApi
    local potionLoop

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
            return nil
        end
        if type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function mapPreview(map, namer)
        if mapSize(map) == 0 then
            return nil
        end
        local names = {}
        for k in pairs(map) do
            names[#names + 1] = namer and namer(k) or k
        end
        table.sort(names)
        if #names == 1 then
            return names[1]
        end
        return names[1] .. ", +" .. tostring(#names - 1)
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local function clampDelay(n)
        n = tonumber(n) or 1
        if n < 0.5 then
            n = 0.5
        elseif n > 10 then
            n = 10
        end
        return n
    end

    local function clampRefresh(n)
        n = tonumber(n) or 0
        if n < 0 then
            n = 0
        elseif n > 180 then
            n = 180
        end
        return n
    end

    local function newRuleId()
        return tostring(os.clock()) .. "-" .. tostring(math.random(1000, 9999))
    end

    local function sanitizeRule(rule)
        if type(rule) ~= "table" then
            return nil
        end
        local potions = copyMap(rule.potions)
        local cleanPotions = {}
        for k in pairs(potions) do
            if Catalog.byName(k) or Catalog.byCategory(k) then
                cleanPotions[k] = true
            end
        end
        potions = cleanPotions
        local whens = copyMap(rule.whens)
        if mapSize(potions) == 0 or mapSize(whens) == 0 then
            return nil
        end
        return {
            id = tostring(rule.id or newRuleId()),
            enabled = rule.enabled ~= false,
            potions = potions,
            whens = whens,
        }
    end

    local function setRules(list)
        local out = {}
        if type(list) == "table" then
            for _, rule in ipairs(list) do
                local clean = sanitizeRule(rule)
                if clean then
                    out[#out + 1] = clean
                end
            end
        end
        rules = out
        return rules
    end

    local function enabledRules()
        local out = {}
        for _, rule in ipairs(rules) do
            if rule.enabled ~= false then
                out[#out + 1] = rule
            end
        end
        return out
    end

    local function inMap(map, value)
        if mapSize(map) == 0 then
            return false
        end
        return map[tostring(value or "")] == true
    end

    local function itemAllowed(item)
        if type(item) ~= "table" then
            return false
        end
        for _, rule in ipairs(enabledRules()) do
            if Catalog.whenMatches(rule.whens) then
                if inMap(rule.potions, item.name) or inMap(rule.potions, item.category) then
                    return true
                end
            end
        end
        return false
    end

    local function potionLabel(key)
        local cat = Catalog.byCategory(key)
        return (cat and cat.key) or tostring(key)
    end

    local function compactAmt(n)
