        if math.abs(n - math.floor(n + 0.5)) < 0.001 then
            return tostring(math.floor(n + 0.5))
        end
        return (string.format("%.2f", n):gsub("0+$", ""):gsub("%.$", ""))
    end

    local ownedCache = {}
    local ownedAt = 0
    local function ownedStock()
        local now = os.clock()
        if type(ownedCache) == "table" and (now - ownedAt) < 1 then
            return ownedCache
        end
        local stock = {}
        pcall(function()
            local data = Core.data()
            local inv = data and data.Inventory and data.Inventory()
            if type(inv) ~= "table" then
                return
            end
            for _, row in pairs(inv) do
                if type(row) == "table" then
                    local name = readVal(row.name)
                    local amount = tonumber(readVal(row.amount)) or 0
                    if type(name) == "string" and amount > 0 and Catalog.byName(name) then
                        stock[name] = (stock[name] or 0) + amount
                    end
                end
            end
        end)
        ownedCache = stock
        ownedAt = now
        return stock
    end

    local function potionLabelWithCount(key)
        key = tostring(key or "")
        local item = Catalog.byName(key)
        if item then
            local have = tonumber(ownedStock()[item.name]) or 0
            return item.name .. " x" .. compactAmt(item.amount) .. " · x" .. tostring(have)
        end
        local cat = Catalog.byCategory(key)
        if cat then
            return tostring(cat.key) .. " (all types)"
        end
        return key
    end

    local function formatRule(rule)
        rule = sanitizeRule(rule) or {}
        local parts = {}
        local function add(text, style)
            text = tostring(text or "")
            if text == "" then
                return
            end
            if #parts > 0 then
                parts[#parts + 1] = { text = " · ", style = "sep" }
            end
            parts[#parts + 1] = { text = text, style = style }
        end
        add(mapPreview(rule.potions, potionLabelWithCount) or "Item", "fruit")
        add(mapPreview(rule.whens, Catalog.whenName) or "When", "kg")
        return {
            id = rule.id,
            enabled = rule.enabled ~= false,
            parts = parts,
