    local pendingUntil = {}

    local function remainingOf(entry)
        if type(entry) ~= "table" then
            return 0
        end
        local remaining = tonumber(readVal(entry.remaining))
        if not remaining or remaining <= 0 then
            return 0
        end
        local startedAt = tonumber(readVal(entry.startedAt))
        if startedAt then
            return math.max(0, remaining - (workspace:GetServerTimeNow() - startedAt))
        end
        return remaining
    end

    local function isApplying(entry)
        return remainingOf(entry) > 0
    end

    local function readActiveSnapshot(data)
        if not data or data.ActiveEntries == nil then
