    local function activeByCategory(data)
        local out = {}
        local snap = readActiveSnapshot(data)
        if type(snap) ~= "table" then
            return nil
        end
        for key, entry in pairs(snap) do
            if type(entry) == "table" and isApplying(entry) then
                local item = Catalog.byName(readVal(entry.name) or key)
                if item then
                    local rem = remainingOf(entry)
                    local cur = out[item.category]
                    if not cur or (item.tier or 0) > (cur.tier or 0) then
                        out[item.category] = {
                            name = item.name,
                            tier = item.tier,
                            amount = item.amount,
                            remaining = rem,
