        end
        return out
    end

    local function lockFromActive(applying)
        local now = os.clock()
        for category, cur in pairs(applying) do
            local rem = tonumber(cur.remaining) or 0
            if rem > refreshSec then
                local untilT = now + (rem - refreshSec)
                local prev = tonumber(pendingUntil[category]) or 0
                if untilT > prev then
