    local function findInvId(data, name)
        local inv = data.Inventory()
        if type(inv) ~= "table" then
            return nil
        end
        for id, row in pairs(inv) do
            if type(row) == "table" and readVal(row.name) == name then
                if (tonumber(readVal(row.amount)) or 0) > 0 then
                    return id
