        return ok and useBoost ~= nil
    end

    local function tryUse()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return
            end
        end
        if #enabledRules() == 0 then
            return
        end
        local Data = Core.data()
        if not Data then
            return
        end
        if not nets() then
            return
        end
        local inv = Data.Inventory()
        if type(inv) ~= "table" then
            return
        end
        local owned = {}
        for _, row in pairs(inv) do
            if type(row) == "table" then
                local name = readVal(row.name)
                local amount = tonumber(readVal(row.amount)) or 0
                if type(name) == "string" and amount > 0 then
                    owned[name] = (owned[name] or 0) + amount
                end
            end
        end
        local applying = activeByCategory(Data)
        if applying == nil then
            return
        end
        lockFromActive(applying)
        local now = os.clock()
        local bestByCat = {}
        for _, item in ipairs(Catalog.items()) do
            if owned[item.name] and itemAllowed(item) then
                local cur = bestByCat[item.category]
                if not cur or Catalog.cmpBest(item, cur) then
                    bestByCat[item.category] = item
                end
            end
        end
        local needList = {}
        for category, item in pairs(bestByCat) do
            local cur = applying[category]
            local lock = tonumber(pendingUntil[category]) or 0
            local locked = lock > now
            if locked and cur and (cur.remaining or 0) <= refreshSec then
                locked = false
            end
            local need = false
            if not cur then
                need = not locked
            elseif (item.tier or 0) > (cur.tier or 0) then
                need = true
            elseif item.name == cur.name and (cur.remaining or 0) <= refreshSec then
                need = not locked
            end
            if need then
                needList[#needList + 1] = item
            end
        end
        if #needList == 0 then
            return
        end
        table.sort(needList, Catalog.cmpBest)
        local pick = needList[1]
        if not pick then
