    potionLoop = Core.loop("auto_potion", {
        delay = delaySec,
        step = tryUse,
    })
    G.AnimeDiceAutoPotion = {
        setEnabled = potionLoop.setEnabled,
    }

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 6,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Item",
                expanded = false,
                status = {
