                end,
            })

            ui:CreateRowDropdown(group, {
                id = "auto.potion.draft.whens",
                label = "When used",
                mode = "multi",
                placeholder = "Always / Tower / Event",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                getItems = function()
                    return Catalog.whenItems()
                end,
                onChanged = function(a, b)
                    draft.whens = copyMap(dropdownValue(a, b))
                end,
            })

            ui:CreateRowButton(group, {
                text = "APPLY → Add Rule",
                kind = "primary",
                onClick = function()
                    local clean = sanitizeRule({
                        enabled = true,
                        potions = draft.potions,
                        whens = draft.whens,
                    })
                    if not clean then
                        return
                    end
                    rules[#rules + 1] = clean
                    persistRules()
                end,
            })

            ui:CreateRowSlider(group, {
                id = "auto.potion.delay",
                label = "Delay",
                min = 0.5,
                max = 10,
                step = 0.1,
                initial = delaySec,
                suffix = "s",
                persist = true,
                onChanged = function(n)
                    delaySec = clampDelay(n)
                    potionLoop.setDelay(delaySec)
                end,
            })

            local enableGroup = ui:CreateGroup(body)
            ui:CreateRowSlider(enableGroup, {
                id = "auto.potion.refresh",
                label = "Refresh below",
                min = 0,
                max = 180,
                step = 5,
                initial = refreshSec,
                suffix = "s",
                persist = true,
                onChanged = function(n)
                    refreshSec = clampRefresh(n)
                end,
            })
            local note = ui:CreateRowLabel(enableGroup, {
                text = "On enable it reads active items first. Best potion per category can all apply. 1 use per delay. A category already running is skipped until Refresh below. Higher tier can replace. Game keeps the highest luck per category — Auto Item and Auto Spin both run; spin uses max-tier when its window is on.",
                wrap = true,
                style = "detail",
            })
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            pad.Parent = note
            Core.bindToggle(ui, enableGroup, {
                id = "auto.potion",
                label = "Enable Auto Item",
                initial = potionLoop.enabled(),
                onChanged = function(on)
                    potionLoop.setEnabled(on == true)
                    paintHeader()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if type(values["auto.potion.rules"]) == "table" then
            setRules(values["auto.potion.rules"])
        end
        if values["auto.potion.delay"] ~= nil then
            delaySec = clampDelay(values["auto.potion.delay"])
            potionLoop.setDelay(delaySec)
        end
        if values["auto.potion.refresh"] ~= nil then
