 end, required = true, feature = true },
    { key = "AutoSpin", name = "Auto Lucky Spin & Jackpot Spin", factory = function() -- AUTO → Auto Lucky Spin & Jackpot Spin.
-- 1 spin per roll. JP dulu, lalu LS. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local Catalog = Core.potions and Core.potions() or G.AnimeDicePotionCatalog
    if type(Catalog) ~= "table" then
        warn("[ANIME DICE] Spin catalog missing")
        return
    end

    local old = G.AnimeDiceAutoSpin
    if type(old) == "table" then
        if type(old.setEnabled) == "function" then
            pcall(old.setEnabled, false)
        end
        if type(old.stop) == "function" then
            pcall(old.stop)
        end
    end

    local JP = "Jackpot Spin"
    local LS = "Lucky Spin"
    local EVENT_MULT = 2.5
    local LS_MULT = 100
    local JP_MULT = 1000
    pcall(function()
        local row = require(RS.Framework.Features.Weather.WeatherConfig).Get("Luck Event")
        local amt = row and row.buffs and row.buffs.Luck and tonumber(row.buffs.Luck.amount)
        if amt and amt > 0 then
            EVENT_MULT = amt
        end
    end)
    pcall(function()
        local entries = require(RS.Framework.Features.Inventory.Kinds.Spin.SpinConfig).entries
        local ls = entries and entries[LS] and tonumber(entries[LS].luckMultiplier)
        local jp = entries and entries[JP] and tonumber(entries[JP].luckMultiplier)
        if ls and ls > 0 then
            LS_MULT = ls
        end
        if jp and jp > 0 then
            JP_MULT = jp
        end
    end)
    local REFRESH = 15
    local READY_RATIO = 0.98

    local selected = {}
    local whens = { luck_event = true }
    local MODE_MAX = "max_tier"
    local MODE_ANY = "any"
    local potionMode = MODE_MAX
    local spinOn = false
    local maxLs = 1
    local maxJp = 1
    local queueDelay = 0.2
    local headerApi
    local cards = {}
    local usedLs = 0
    local usedJp = 0
    local windowEvent = false
    local pendingUntil = {}
    local lastUseAt = 0
    local weather = { name = nil, remain = 0, startedAt = 0, duration = 0 }
    local useBoost
    local useSpin
    local diceMod
    local workLoop
    local paintLoop
    local enableApi
    local jpInfoApi
    local lsInfoApi
    local gapInfoApi
    local gateOk = false
    local gateReason = nil
    local lockedTargets = nil
    local armedName = nil
    local armedAt = 0
    local armedSeen = false
    local runKind = nil

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
            return nil
        end
        if type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function mapOn(map, key)
        return type(map) == "table" and map[tostring(key or "")] == true
    end

    local function dropdownValue(a, b)
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if type(a) == "table" then
            return a
        end
        return b
    end

    local function clampPotionMode(key)
        if tostring(key or "") == MODE_ANY then
            return MODE_ANY
        end
        return MODE_MAX
    end

    local function clampMax(n)
        n = math.floor(tonumber(n) or 0)
        if n < 0 then
            n = 0
        elseif n > 1000 then
            n = 1000
        end
        return n
    end

    local function clampQueueDelay(n)
        n = tonumber(n) or 0.2
        if n < 0.1 then
            n = 0.1
        elseif n > 2 then
            n = 2
        end
        return math.floor(n * 100 + 0.5) / 100
    end

    local function remainingOf(entry)
        if type(entry) ~= "table" then
            return 0
        end
        local remaining = tonumber(readVal(entry.remaining))
        local startedAt = tonumber(readVal(entry.startedAt))
        if remaining and remaining > 0 and remaining == remaining and remaining < math.huge then
            local elapsed = 0
            if startedAt and startedAt > 0 then
                elapsed = math.max(0, workspace:GetServerTimeNow() - startedAt)
            end
            return math.max(0, remaining - elapsed)
        end
        local expiresAt = tonumber(readVal(entry.expiresAt))
        if expiresAt and expiresAt > 0 then
            return math.max(0, expiresAt - os.time())
        end
        return 0
    end

    pcall(function()
        local prop = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "WeatherService"):GetProperty("ActiveWeather")
        local function apply(value)
            weather = { name = nil, remain = 0, startedAt = 0, duration = 0 }
            if type(value) ~= "table" then
                return
            end
            weather.name = value.name
            weather.startedAt = tonumber(value.startedAt) or 0
            weather.duration = tonumber(value.duration) or 300
        end
        if prop.IsReady and prop:IsReady() then
            apply(prop:Get())
        end
        if type(prop.Observe) == "function" then
            prop:Observe(apply)
        end
    end)

    local function weatherRemain()
        if not weather.name or weather.startedAt <= 0 then
            return 0
        end
        return math.max(0, weather.duration - (workspace:GetServerTimeNow() - weather.startedAt))
    end

    local function luckEventOn()
        return weather.name == "Luck Event" and weatherRemain() > 0.25
    end

    local function whenOk()
        local map = whens
        if mapSize(map) == 0 then
            map = { luck_event = true }
        end
        if mapOn(map, "always") then
            return true
        end
        if mapOn(map, "luck_event") then
            return luckEventOn()
        end
        return Catalog.whenMatches(map)
    end

    local function whenWantsEvent()
        if mapOn(whens, "always") then
            return false
        end
        if mapSize(whens) == 0 then
            return true
        end
        return mapOn(whens, "luck_event")
    end

    local function whenHint()
        if mapOn(whens, "always") then
            return " When Always: use now. Toggle off when this quota is done."
        end
        return " When Luck Event: only during Luck Event. Pause when event ends. Quota resets next event."
    end

    local function maxInfoText(kind, n)
        n = clampMax(n)
        local name = kind == JP and "Jackpot" or "Lucky"
        local tag = kind == JP and "JP" or "LS"
        local body
        if n <= 0 then
            body = tag .. " 0 = use ALL " .. name .. " in bag. 0 stock = skip this kind."
        else
            body = tag
                .. " "
                .. tostring(n)
                .. " = stop after "
                .. tostring(n)
                .. " uses. This kind starts only with ≥"
                .. tostring(n)
                .. " in bag. Other kind still runs."
        end
        return body .. whenHint()
    end

    local function gapInfoText(n)
        n = clampQueueDelay(n)
        return "Min " .. string.format("%.2f", n) .. "s between uses. Both selected: JP first if it can run, else LS. Empty kind is skipped."
    end

    local function paintGapInfo()
        if type(gapInfoApi) == "table" and type(gapInfoApi.set) == "function" then
            pcall(gapInfoApi.set, gapInfoText(queueDelay))
        end
    end

    local function paintMaxInfo()
        if type(jpInfoApi) == "table" and type(jpInfoApi.set) == "function" then
            pcall(jpInfoApi.set, maxInfoText(JP, maxJp))
        end
        if type(lsInfoApi) == "table" and type(lsInfoApi.set) == "function" then
            pcall(lsInfoApi.set, maxInfoText(LS, maxLs))
        end
        paintGapInfo()
    end

    local function eventReady()
        if not whenOk() then
            return false
        end
        if whenWantsEvent() then
            return weatherRemain() > 1.5
        end
        return true
    end

    local function hudLuck()
        local n = 0
        pcall(function()
            n = require(RS.Framework.Features.Buffs.BuffController).GetBuff("Luck")
        end)
        return tonumber(n) or 0
    end

    local function diceLuck(data)
        local name
        pcall(function()
            name = readVal(data and data.Dice)
        end)
        if type(name) ~= "string" or name == "" then
            return 1
        end
        if not diceMod then
            pcall(function()
                diceMod = require(RS.Framework.Features.Rolling.Dice)
            end)
        end
        local n = 1
        pcall(function()
            local row = diceMod and diceMod.Get and diceMod.Get(name)
            n = tonumber(row and row.luck) or 1
        end)
        if n <= 0 then
            n = 1
        end
        return n
    end

    local function maxDiceLuck(data)
        local best = diceLuck(data)
        pcall(function()
            if not diceMod then
                diceMod = require(RS.Framework.Features.Rolling.Dice)
            end
            local all = diceMod and diceMod.GetAll and diceMod.GetAll()
            if type(all) ~= "table" then
                return
            end
            for name, row in pairs(all) do
                local n = tonumber(row and row.luck) or 0
                if n > best then
                    local owned = row.price == nil
                    if not owned and data then
                        pcall(function()
                            owned = data.OwnedDice[name]() == true
                        end)
                    end
                    if owned then
                        best = n
                    end
                end
            end
        end)
        if best <= 0 then
            best = 1
        end
        return best
    end

    local function readActive(data)
        if not data or data.ActiveEntries == nil then
            return nil
        end
        local snap
        local ok = pcall(function()
            snap = data.ActiveEntries()
        end)
        if not ok or type(snap) ~= "table" then
            return nil
        end
        return snap
    end

    local function ownedStock(data)
        local stock = {}
        if not data then
            return stock
        end
        local inv
        pcall(function()
            inv = data.Inventory()
        end)
        if type(inv) ~= "table" then
            return stock
        end
        for _, row in pairs(inv) do
            if type(row) == "table" then
                local name = readVal(row.name)
                local amount = tonumber(readVal(row.amount)) or 0
                if type(name) == "string" and amount > 0 then
                    stock[name] = (stock[name] or 0) + amount
                end
            end
        end
        return stock
    end

    local unitRegistry
    local lastBagAt = 0
    local lastBagFull = false
    local lastBagCount = 0
    local lastBagCap = 0

    local function isUnitName(name)
        if type(name) ~= "string" or name == "" then
            return false
        end
        if type(unitRegistry) ~= "table" then
            pcall(function()
                unitRegistry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
        end
        if type(unitRegistry) ~= "table" or type(unitRegistry.getEntryConfig) ~= "function" then
            return false
        end
        local ok, cfg = pcall(unitRegistry.getEntryConfig, name)
        return ok and type(cfg) == "table" and cfg.kind == "Unit"
    end

    local function bagState(data)
        local now = os.clock()
        if now - lastBagAt < 0.4 then
            return lastBagFull, lastBagCount, lastBagCap
        end
        lastBagAt = now
        local count = 0
        local cap = 0
        local rolls = 1
        pcall(function()
            local buffs = require(RS.Framework.Features.Buffs.BuffController)
            cap = tonumber(buffs.GetBuff("Unit Storage")) or 0
            rolls = tonumber(buffs.GetBuff("Rolls")) or 1
        end)
        if rolls < 1 then
            rolls = 1
        end
        if type(data) == "table" then
            local inv
            pcall(function()
                inv = data.Inventory()
            end)
            if type(inv) == "table" then
                for _, row in pairs(inv) do
                    if type(row) == "table" and isUnitName(readVal(row.name)) then
                        count = count + 1
                    end
                end
            end
            pcall(function()
                local trade = data.PendingTrade()
                if type(trade) == "table" and readVal(trade.applied) ~= true then
                    count = count + (tonumber(readVal(trade.reservedUnits)) or 0)
                end
            end)
        end
        lastBagCount = count
        lastBagCap = cap
        local room = cap + (rolls - 1)
        lastBagFull = room > 0 and count >= room
        return lastBagFull, lastBagCount, lastBagCap
    end

    local function findInvId(data, name)
        local inv
        pcall(function()
            inv = data.Inventory()
        end)
        if type(inv) ~= "table" then
            return nil
        end
        for id, row in pairs(inv) do
            if type(row) == "table" and readVal(row.name) == name then
                if (tonumber(readVal(row.amount)) or 0) > 0 then
                    return id
                end
            end
        end
        return nil
    end

    local function luckItems()
        local out = {}
        for _, item in ipairs(Catalog.items()) do
            if item.buff == "Luck" then
                out[#out + 1] = item
            end
        end
        return out
    end

    local maxTierCache

    local function maxTierLuck()
        if type(maxTierCache) == "table" then
            return maxTierCache
        end
        local best = {}
        for _, item in ipairs(luckItems()) do
            local cur = best[item.category]
            if not cur or Catalog.cmpBest(item, cur) then
                best[item.category] = item
            end
        end
        maxTierCache = best
        return best
    end

    local function bestOwnedLuck(stock)
        local best = {}
        for _, item in ipairs(luckItems()) do
            if (tonumber(stock[item.name]) or 0) > 0 then
                local cur = best[item.category]
                if not cur or Catalog.cmpBest(item, cur) then
                    best[item.category] = item
                end
            end
        end
        return best
    end

    local function hasMaxActive(applying, item)
        if type(item) ~= "table" or type(applying) ~= "table" then
            return false
        end
        local cur = applying[item.category]
        return cur and cur.name == item.name and (tonumber(cur.remaining) or 0) > 0
    end

    local function hasAllMaxTier(stock, applying)
        stock = type(stock) == "table" and stock or {}
        local n = 0
        for _, item in pairs(maxTierLuck()) do
            n = n + 1
            local owned = (tonumber(stock[item.name]) or 0) > 0
            if not owned and not hasMaxActive(applying, item) then
                return false
            end
        end
        return n > 0
    end

    local function activeLuck(data)
        local byCat = {}
        local acc = { base = 1, multi = 1, percent = 1 }
        local snap = readActive(data)
        if type(snap) ~= "table" then
            return byCat, 1
        end
        if type(unitRegistry) ~= "table" then
            pcall(function()
                unitRegistry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
        end
        for key, entry in pairs(snap) do
            entry = readVal(entry)
            if type(entry) == "table" and remainingOf(entry) > 0 then
                local name = readVal(entry.name) or key
                local cfg
                if type(unitRegistry) == "table" and type(unitRegistry.getEntryConfig) == "function" then
                    pcall(function()
                        cfg = unitRegistry.getEntryConfig(name)
                    end)
                end
                if type(cfg) == "table" and cfg.kind == "Boost" then
                    local luck = cfg.buffs and cfg.buffs.Luck
                    if type(luck) == "table" then
                        local bucket = luck.bucket
                        local amount = tonumber(luck.amount) or 0
                        if bucket == "base" then
                            acc.base = acc.base + amount
                        elseif bucket == "multiplier" and amount ~= 0 then
                            acc.multi = acc.multi * amount
                        elseif bucket == "percentage" then
                            acc.percent = acc.percent + amount
                        end
                    end
                end
                local item = Catalog.byName(name)
                if item and item.buff == "Luck" then
                    local cur = byCat[item.category]
                    if not cur or (item.tier or 0) > (cur.tier or 0) then
                        byCat[item.category] = {
                            name = item.name,
                            tier = item.tier,
                            amount = item.amount,
                            remaining = remainingOf(entry),
                        }
                    end
                end
            end
        end
        local potionMult = acc.base * acc.multi * acc.percent
        if potionMult <= 0 then
            potionMult = 1
        end
        return byCat, potionMult
    end

    local function queuedSpins(data)
        local out = {}
        local snap = readActive(data)
        if type(snap) ~= "table" then
            return out
        end
        for key, entry in pairs(snap) do
            local name = readVal(type(entry) == "table" and entry.name or nil) or key
            if name == JP or name == LS then
                local n = 0
                if type(entry) == "table" then
                    n = tonumber(readVal(entry.amount)) or 0
                    if n <= 0 then
                        n = remainingOf(entry) > 0 and 1 or 0
                    end
                end
                if n > 0 then
                    out[name] = (out[name] or 0) + n
                end
            end
        end
        return out
    end

    local function queuedSpin(data)
        local map = queuedSpins(data)
        if map[JP] then
            return JP, map[JP], map
        end
        if map[LS] then
            return LS, map[LS], map
        end
        return nil, 0, map
    end

    local function nets()
        if useBoost and useSpin then
            return true
        end
        pcall(function()
            local Net = require(RS.Packages.Network)
            if not useBoost then
                useBoost = Net.ClientComm.new(RS.Network, false, "BoostService"):GetSignal("Use")
            end
            if not useSpin then
                useSpin = Net.ClientComm.new(RS.Network, false, "SpinService"):GetSignal("Use")
            end
        end)
        return useBoost ~= nil and useSpin ~= nil
    end

    local function itemPicked(name)
        if mapSize(selected) == 0 then
            return false
        end
        return mapOn(selected, name)
    end

    local function kindMax(name)
        return name == JP and maxJp or maxLs
    end

    local function kindOwned(stock, name)
        stock = type(stock) == "table" and stock or {}
        return math.max(0, math.floor(tonumber(stock[name]) or 0))
    end

    local function usedOf(kind)
        return kind == JP and usedJp or usedLs
    end

    -- 0 = pakai stok yang ada; 0 stok = skip jenis ini.
    -- N = jenis ini baru mulai kalau stok ≥ N. Jenis lain tetap boleh jalan.
    local function kindMayRun(name, stock)
        if not itemPicked(name) then
            return false
        end
        local owned = kindOwned(stock, name)
        local maxN = kindMax(name)
        local used = usedOf(name)
        if maxN > 0 then
            if used >= maxN then
                return false
            end
            if used > 0 then
                return owned > 0
            end
            return owned >= maxN
        end
        return owned > 0
    end

    local function kindNeedText(name, stock)
        if not itemPicked(name) or kindMayRun(name, stock) then
            return nil
        end
        local owned = kindOwned(stock, name)
        local maxN = kindMax(name)
        local used = usedOf(name)
        if maxN > 0 and used >= maxN then
            return nil
        end
        local tag = name == JP and "JP" or "LS"
        if maxN > 0 then
            return tag .. " " .. tostring(owned) .. "/" .. tostring(maxN)
        end
        if owned <= 0 then
            return tag .. " 0"
        end
        return nil
    end

    local function joinNeed(list, maxN)
        maxN = maxN or 3
        if type(list) ~= "table" or #list == 0 then
            return ""
        end
        if #list <= maxN then
            return table.concat(list, ", ")
        end
        local head = {}
        for i = 1, maxN do
            head[i] = list[i]
        end
        return table.concat(head, ", ") .. " +" .. tostring(#list - maxN)
    end

    local function stockIssues(stock, applying)
        stock = type(stock) == "table" and stock or {}
        applying = type(applying) == "table" and applying or {}
        local issues = {}
        if mapSize(selected) == 0 then
            issues[#issues + 1] = "item"
        else
            local any = kindMayRun(JP, stock) or kindMayRun(LS, stock)
            if not any then
                for _, name in ipairs({ JP, LS }) do
                    local why = kindNeedText(name, stock)
                    if why then
                        issues[#issues + 1] = why
                    end
                end
                if #issues == 0 then
                    issues[#issues + 1] = "item"
                end
            end
        end
        local missPot = {}
        if potionMode == MODE_MAX then
            for _, item in pairs(maxTierLuck()) do
                local owned = (tonumber(stock[item.name]) or 0) > 0
                if not owned and not hasMaxActive(applying, item) then
                    missPot[#missPot + 1] = item.name
                end
            end
        else
            local best = bestOwnedLuck(stock)
            for cat in pairs(maxTierLuck()) do
                if not best[cat] and not applying[cat] then
                    missPot[#missPot + 1] = tostring(cat)
                end
            end
        end
        table.sort(missPot)
        if #missPot > 0 then
            issues[#issues + 1] = "potion " .. joinNeed(missPot)
        end
        return issues
    end

    local function resetGate()
        gateOk = false
        gateReason = nil
        lockedTargets = nil
    end

    local function clearArmed()
        armedName = nil
        armedAt = 0
        armedSeen = false
    end

    local function clearRun()
        runKind = nil
    end

    local function startGate(stock, applying)
        local issues = stockIssues(stock, applying)
        if #issues > 0 then
            gateOk = false
            gateReason = "Need " .. table.concat(issues, " · ")
            lockedTargets = nil
            return false
        end
        gateOk = true
        gateReason = nil
        if potionMode == MODE_MAX then
            lockedTargets = maxTierLuck()
        else
            lockedTargets = bestOwnedLuck(stock)
        end
        return true
    end

    local function quotaCap(kind, owned)
        local maxN = kind == JP and maxJp or maxLs
        owned = math.max(0, math.floor(tonumber(owned) or 0))
        if maxN <= 0 then
            return owned
        end
        return math.min(maxN, owned)
    end

    local function itemFinished(name, snap)
        if not itemPicked(name) then
            return true
        end
        local stock = snap and snap.stock
        local owned = kindOwned(stock, name)
        local maxN = kindMax(name)
        local used = usedOf(name)
        if maxN > 0 then
            if used >= maxN then
                return true
            end
            if used > 0 then
                return owned <= 0
            end
            return owned < maxN
        end
        return owned <= 0
    end

    local function alwaysMode()
        return mapOn(whens, "always")
    end

    local function alwaysFinished(snap)
        if not alwaysMode() then
            return false
        end
        if mapSize(selected) == 0 then
            return true
        end
        for _, name in ipairs({ JP, LS }) do
            if itemPicked(name) and not itemFinished(name, snap) then
                return false
            end
        end
        return true
    end

    local function bumpUsed(kind)
        if kind == JP then
            usedJp = usedJp + 1
        else
            usedLs = usedLs + 1
        end
    end

    local function resetWindow()
        usedLs = 0
        usedJp = 0
        clearArmed()
        clearRun()
    end

    local function addLuck(acc, bucket, amount)
        amount = tonumber(amount) or 0
        if bucket == "base" then
            acc.base = acc.base + amount
        elseif bucket == "multiplier" then
            if amount ~= 0 then
                acc.multi = acc.multi * amount
            end
        elseif bucket == "percentage" then
            acc.percent = acc.percent + amount
        end
    end

    local function replicaSnap(node)
        local snap
        pcall(function()
            snap = node()
        end)
        if type(snap) == "table" then
            return snap
        end
        if type(node) ~= "table" then
            return nil
        end
        local out = {}
        local any = false
        for k, v in pairs(node) do
            if type(k) == "string" then
                out[k] = readVal(v)
                any = true
            end
        end
        if any then
            return out
        end
        return nil
    end

    local function luckFromAccount(data, wantMax)
        local acc = { base = 1, multi = 1, percent = 1 }
        pcall(function()
            local upgrades = require(RS.Framework.Features.Upgrades.Upgrades)
            local owned = data and replicaSnap(data.Upgrades)
            if type(owned) ~= "table" or type(upgrades) ~= "table" then
                return
            end
            for name, on in pairs(owned) do
                if on == true or readVal(on) == true then
                    local row = upgrades[name]
                    local luck = type(row) == "table" and row.buffs and row.buffs.Luck
                    if type(luck) == "table" then
                        addLuck(acc, luck.bucket, luck.amount)
                    end
                end
            end
        end)
        pcall(function()
            local rebirths = require(RS.Framework.Features.Rebirth.Rebirths)
            local n = 0
            if data then
                n = tonumber(readVal(data.Rebirth)) or 0
            end
            local row = rebirths.Get(n)
            local m = tonumber(row and row.luckMultiplier)
            if m and m > 0 then
                acc.multi = acc.multi * m
            end
        end)
        pcall(function()
            local passes = require(RS.Framework.Features.Monetization.MonetizationConfig).Gamepasses
            local owned = data and replicaSnap(data.OwnedGamepasses) or {}
            if type(passes) ~= "table" then
                return
            end
            for name, row in pairs(passes) do
                local on = owned[name]
                if on == true or readVal(on) == true then
                    local luck = type(row) == "table" and row.buffs and row.buffs.Luck
                    if type(luck) == "table" then
                        addLuck(acc, luck.bucket, luck.amount)
                    end
                end
            end
        end)
        pcall(function()
            local gears = Core.gears and Core.gears() or G.AnimeDiceGearCatalog
            if wantMax and type(gears) == "table" and type(gears.pickBest) == "function" then
                local picks = gears.pickBest(ownedStock(data), "luck")
                for _, item in pairs(picks) do
                    local luck = item and item.buffs and item.buffs.Luck
                    if type(luck) == "table" then
                        addLuck(acc, luck.bucket, luck.amount)
                    end
                end
                return
            end
            local eq = data and replicaSnap(data.EquippedGear) or {}
            if type(unitRegistry) ~= "table" then
                pcall(function()
                    unitRegistry = require(RS.Framework.Features.Inventory.EntryRegistry)
                end)
            end
            for slot, name in pairs(eq) do
                name = readVal(name)
                if type(name) == "string" and name ~= "" then
                    local cfg
                    if type(unitRegistry) == "table" then
                        pcall(function()
                            cfg = unitRegistry.getEntryConfig(name)
                        end)
                    end
                    local luck = cfg and cfg.buffs and cfg.buffs.Luck
                    if type(luck) == "table" and (not cfg.slot or cfg.slot == slot) then
                        addLuck(acc, luck.bucket, luck.amount)
                    end
                end
            end
        end)
        local n = acc.base * acc.multi * acc.percent
        if n <= 0 then
            n = 1
        end
        return n
    end

    local function fmtRemain(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
    end

    local function snapshot()
        local data = Core.data()
        local now = hudLuck()
        local stock = ownedStock(data)
        local applying, potionMult = activeLuck(data)
        if potionMult <= 0 then
            potionMult = 1
        end
        local eventMult = luckEventOn() and EVENT_MULT or 1
        local dice = diceLuck(data)
        local permData = luckFromAccount(data, false)
        local akun = now / potionMult / eventMult
        if akun ~= akun or akun <= 0 then
            akun = permData > 0 and permData or (now > 0 and now or 0)
        elseif permData > 1 then
            local ratio = akun / permData
            if ratio > 0.9 and ratio < 1.1 then
                akun = permData
            end
        end
        local bestOwned = bestOwnedLuck(stock)
        local best = {}
        local missing = {}
        local targets
        if gateOk and type(lockedTargets) == "table" then
            targets = lockedTargets
        elseif potionMode == MODE_MAX then
            targets = maxTierLuck()
        else
            targets = bestOwned
        end
        local targetMult = 1
        for _, item in pairs(targets) do
            if (tonumber(stock[item.name]) or 0) > 0 then
                targetMult = targetMult * (tonumber(item.amount) or 1)
                best[item.category] = item
            end
            if gateOk then
                local cur = applying[item.category]
                local same = cur and cur.name == item.name
                local rem = cur and tonumber(cur.remaining) or 0
                if not same or rem <= REFRESH then
                    missing[#missing + 1] = item
                end
            end
        end
        if targetMult <= 0 then
            targetMult = 1
        end
        local eventForMax = whenWantsEvent() and EVENT_MULT or eventMult
        local targetHud = akun * targetMult
        local maxHud = targetHud * eventForMax
        local maxRoll = maxHud * dice
        local queued, queuedAmt, queuedMap = queuedSpin(data)
        local bagFull, bagCount, bagCap = bagState(data)
        return {
            data = data,
            now = now,
            akun = akun,
            potMult = targetMult,
            targetMult = targetMult,
            potHud = targetHud,
            targetHud = targetHud,
            eventMult = eventForMax,
            maxHud = maxHud,
            dice = dice,
            stock = stock,
            best = best,
            missing = missing,
            applying = applying,
            queued = queued,
            queuedAmt = queuedAmt or 0,
            queuedMap = queuedMap or {},
            bagFull = bagFull == true,
            bagCount = bagCount or 0,
            bagCap = bagCap or 0,
            lsRoll = maxRoll * LS_MULT,
            jpRoll = maxRoll * JP_MULT,
            lsBase = targetHud * dice * LS_MULT,
            jpBase = targetHud * dice * JP_MULT,
            akunMax = luckFromAccount(data, true) * maxDiceLuck(data),
        }
    end

    local lastBareAkun = 0
    local potSettledAt = 0

    local function applyingMult(applying)
        local m = 1
        if type(applying) ~= "table" then
            return 1
        end
        for _, cur in pairs(applying) do
            m = m * (tonumber(cur.amount) or 1)
        end
        if m <= 0 then
            return 1
        end
        return m
    end

    local function luckReady(snap)
        if not snap then
            return false
        end
        if snap.needMax or #snap.missing > 0 or not gateOk then
            potSettledAt = 0
            return false
        end
        local target = tonumber(snap.targetMult) or tonumber(snap.potMult) or 1
        local live = applyingMult(snap.applying)
        if target > 1.05 and live + 1e-6 < target * READY_RATIO then
            potSettledAt = 0
            return false
        end
        local now = tonumber(snap.now) or 0
        if live <= 1.02 and not luckEventOn() and now > 0 then
            lastBareAkun = now
        end
        if potSettledAt <= 0 then
            potSettledAt = os.clock()
        end
        if target > 1.05 and os.clock() - potSettledAt < 0.45 then
            return false
        end
        if lastBareAkun > 0 then
            local expected = lastBareAkun * math.max(target, 1) * (luckEventOn() and EVENT_MULT or 1)
            return now + 1e-6 >= expected * READY_RATIO
        end
        return now > 0
    end

    local function fmtMul(n)
        n = tonumber(n) or 1
        local nearest = math.floor(n + 0.5)
        if math.abs(n - nearest) < 0.005 then
            return tostring(nearest)
        end
        local text = string.format("%.2f", n)
        return (text:gsub("0+$", ""):gsub("%.$", ""))
    end

    local function paintCards(snap)
        if type(cards) ~= "table" or not cards.akun then
            return
        end
        local c = Core.compact
        local dice = tonumber(snap.dice) or 1
        local akunNow = (tonumber(snap.akun) or 0) * dice
        local akunMax = tonumber(snap.akunMax) or akunNow
        if akunNow > akunMax then
            akunMax = akunNow
        end
        local pot = (tonumber(snap.potHud) or 0) * dice
        local ls = tonumber(snap.lsBase) or (pot * LS_MULT)
        local jp = tonumber(snap.jpBase) or (pot * JP_MULT)
        local showEvent = whenWantsEvent() or luckEventOn()
        if cards.akun.value then
            cards.akun.value.Text = c(akunNow) .. ' <font color="#8A8F98">/ ' .. c(akunMax) .. "</font>"
        end
        if cards.pot.value then
            cards.pot.value.Text = c(pot) .. ' <font color="#8A8F98">x' .. fmtMul(snap.potMult) .. "</font>"
        end
        if cards.ls.value then
            if showEvent then
                cards.ls.value.Text = c(ls) .. ' <font color="#8A8F98">/ ' .. c(ls * EVENT_MULT) .. "</font>"
            else
                cards.ls.value.Text = c(ls)
            end
        end
        if cards.jp.value then
            if showEvent then
                cards.jp.value.Text = c(jp) .. ' <font color="#8A8F98">/ ' .. c(jp * EVENT_MULT) .. "</font>"
            else
                cards.jp.value.Text = c(jp)
            end
        end
    end

    local function paintHeader()
        local snap = snapshot()
        local eventOn = luckEventOn()
        paintCards(snap)
        if not headerApi then
            return
        end
        local value = "Off"
        local style = "muted"
        local detail = "Off"
        local on = spinOn
        if eventOn then
            detail = "Luck Event " .. fmtRemain(weatherRemain())
        elseif whenWantsEvent() then
            detail = "waiting Luck Event"
        elseif weather.name then
            detail = tostring(weather.name)
        end
        if on and snap.bagFull then
            value = "Pause bag " .. tostring(snap.bagCount) .. "/" .. tostring(snap.bagCap > 0 and snap.bagCap or "-")
            style = "muted"
        elseif on and eventReady() and luckReady(snap) then
            value = "On"
            style = "success"
            local bits = {}
            local jpCap = quotaCap(JP, snap.stock[JP] or 0)
            local lsCap = quotaCap(LS, snap.stock[LS] or 0)
            if spinOn and itemPicked(JP) then
                bits[#bits + 1] = "JP " .. tostring(usedJp) .. "/" .. (maxJp <= 0 and tostring(snap.stock[JP] or 0) or tostring(jpCap))
            end
            if spinOn and itemPicked(LS) then
                bits[#bits + 1] = "LS " .. tostring(usedLs) .. "/" .. (maxLs <= 0 and tostring(snap.stock[LS] or 0) or tostring(lsCap))
            end
            if snap.queuedMap then
                local armed = {}
                if snap.queuedMap[JP] then
                    armed[#armed + 1] = "JP"
                end
                if snap.queuedMap[LS] then
                    armed[#armed + 1] = "LS"
                end
                if #armed > 0 then
                    bits[#bits + 1] = "armed " .. table.concat(armed, "+")
                end
            elseif snap.queued then
                bits[#bits + 1] = "armed " .. (snap.queued == JP and "JP" or "LS")
            end
            if #bits > 0 then
                value = value .. " · " .. table.concat(bits, " · ")
            end
        elseif on then
            value = "Wait"
            if gateReason then
                value = tostring(gateReason)
            elseif not whenOk() and whenWantsEvent() then
                value = "Pause"
            elseif #snap.missing > 0 then
                local names = {}
                for i = 1, #snap.missing do
                    names[#names + 1] = snap.missing[i].name
                end
                table.sort(names)
                value = "Wait potion " .. joinNeed(names)
            elseif whenOk() then
                value = "Wait luck"
            end
        end
        Core.paintHeader(headerApi, value, style, detail)
    end

    local applyWaitUntil = 0

    local function liveRemain(data, name)
        local snap = readActive(data)
        if type(snap) ~= "table" then
            return nil
        end
        local function remainOf(entry)
            entry = readVal(entry)
            if type(entry) ~= "table" then
                return 0
            end
            return remainingOf(entry)
        end
        if snap[name] ~= nil then
            return remainOf(snap[name])
        end
        for key, entry in pairs(snap) do
            entry = readVal(entry)
            local entryName = type(entry) == "table" and readVal(entry.name) or nil
            if key == name or entryName == name then
                return remainOf(entry)
            end
        end
        return 0
    end

    local function tryLuckPotion(snap)
        if not spinOn or not snap or not snap.data or not gateOk or not whenOk() or snap.bagFull then
            return false
        end
        if not nets() or not useBoost then
            return false
        end
        if mapSize(snap.applying) == 0 then
            if applyWaitUntil <= 0 then
                applyWaitUntil = os.clock() + 2
            end
            if os.clock() < applyWaitUntil then
                return false
            end
        else
            applyWaitUntil = 0
        end
        table.sort(snap.missing, Catalog.cmpBest)
        local now = os.clock()
        for _, item in ipairs(snap.missing) do
            local cur = snap.applying[item.category]
            local curRem = cur and tonumber(cur.remaining) or 0
            local skip = cur and cur.name == item.name and curRem > REFRESH
            if not skip then
                local live = liveRemain(snap.data, item.name)
                if live == nil then
                    return false
                end
                if live <= REFRESH then
                    local lock = tonumber(pendingUntil[item.category]) or 0
                    if lock > now then
                        if cur and curRem <= REFRESH and cur.name == item.name then
                            lock = 0
                        end
                    end
                    if lock <= now then
                        local id = findInvId(snap.data, item.name)
                        if id then
                            useBoost:Fire(id)
                            local wait = math.max(0.5, (tonumber(item.duration) or 0) - REFRESH)
                            pendingUntil[item.category] = os.clock() + wait
                            return true
                        end
                    end
                end
            end
        end
        return false
    end

    local function queuedCount(snap, name)
        local q = type(snap) == "table" and snap.queuedMap or nil
        if type(q) ~= "table" then
            return 0
        end
        return math.max(0, math.floor(tonumber(q[name]) or 0))
    end

    local activeAt = 0

    local function spinBusy(snap)
        local jpN = queuedCount(snap, JP)
        local lsN = queuedCount(snap, LS)
        if armedName then
            local n = armedName == JP and jpN or lsN
            if n > 0 then
                armedSeen = true
            elseif armedSeen then
                clearArmed()
            end
        end
        if jpN > 0 or lsN > 0 then
            return true
        end
        if not armedName then
            return false
        end
        local ack = math.max(0.45, clampQueueDelay(queueDelay) + 0.2)
        if os.clock() - armedAt < ack then
            return true
        end
        clearArmed()
        return false
    end

    local function spinSafe(snap)
        if not spinOn or not snap or not gateOk then
            return false
        end
        if snap.bagFull then
            return false
        end
        if not whenOk() or not eventReady() then
            return false
        end
        if spinBusy(snap) then
            return false
        end
        return luckReady(snap) == true
    end

    local function nextKind(snap)
        local function canRun(name)
            return kindMayRun(name, snap and snap.stock)
        end
        if canRun(JP) then
            return JP
        end
        if canRun(LS) then
            return LS
        end
        return nil
    end

    local function pickSpins(snap)
        local out = {}
        if not spinSafe(snap) or spinBusy(snap) then
            return out
        end
        local function canUse(name)
            return kindMayRun(name, snap.stock)
        end
        local kind = runKind
        if not kind or not kindMayRun(kind, snap.stock) then
            kind = nextKind(snap)
            runKind = kind
        end
        if not kind or not canUse(kind) then
            return out
        end
        out[1] = kind
        return out
    end

    local function turnOff()
        clearArmed()
        clearRun()
        if not spinOn then
            return
        end
        if enableApi and type(enableApi.set) == "function" then
            pcall(function()
                enableApi.set(false)
            end)
            return
        end
        spinOn = false
        resetGate()
        clearArmed()
        if workLoop then
            pcall(function()
                workLoop.setEnabled(false)
            end)
        end
        paintHeader()
    end

    local function stepOnce()
        local eventOn = luckEventOn()
        if whenWantsEvent() and windowEvent ~= eventOn then
            if windowEvent and not eventOn then
                if maxJp > 0 then
                    usedJp = 0
                end
                if maxLs > 0 then
                    usedLs = 0
                end
                resetGate()
                clearArmed()
                clearRun()
            elseif eventOn then
                resetWindow()
            end
            windowEvent = eventOn
        elseif not whenWantsEvent() then
            windowEvent = eventOn
        end
        local snap = snapshot()
        local busyNow = spinBusy(snap)
        activeAt = (spinOn and (busyNow or spinSafe(snap))) and os.clock() or 0
        if not spinOn then
            paintHeader()
            return
        end
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                paintHeader()
                return
            end
        end
        if alwaysFinished(snap) then
            turnOff()
            return
        end
        if not gateOk and not startGate(snap.stock, snap.applying) then
            paintHeader()
            return
        end
        if not whenOk() then
            potSettledAt = 0
            paintHeader()
            return
        end
        if snap.bagFull then
            paintHeader()
            return
        end
        if tryLuckPotion(snap) then
            potSettledAt = 0
            paintHeader()
            return
        end
        if not eventReady() then
            paintHeader()
            return
        end
        if not luckReady(snap) then
            paintHeader()
            return
        end
        if alwaysFinished(snap) then
            turnOff()
            return
        end
        local names = pickSpins(snap)
        if #names == 0 or not snap.data or not nets() or not useSpin then
            if alwaysFinished(snap) then
                turnOff()
            else
                paintHeader()
            end
            return
        end
        local gap = clampQueueDelay(queueDelay)
        if os.clock() - lastUseAt < gap then
            paintHeader()
            return
        end
        snap = snapshot()
        if not spinSafe(snap) or spinBusy(snap) then
            paintHeader()
            return
        end
        names = pickSpins(snap)
        local name = names[1]
        if not name then
            paintHeader()
            return
        end
        local id = findInvId(snap.data, name)
        if not id then
            paintHeader()
            return
        end
        useSpin:Fire(id)
        bumpUsed(name)
        lastUseAt = os.clock()
        armedName = name
        armedAt = lastUseAt
        armedSeen = false
        runKind = name
        if alwaysFinished(snapshot()) then
            turnOff()
            return
        end
        paintHeader()
    end

    workLoop = Core.loop("auto_spin", {
        delay = queueDelay,
        step = stepOnce,
    })
    paintLoop = Core.loop("auto_spin_paint", {
        delay = 5,
        step = function()
            if Core.uiIs("auto", "main") then
                paintHeader()
            end
        end,
    })
    paintLoop.setEnabled(true)

    local function anyWork()
        return spinOn
    end

    local function syncWork()
        workLoop.setEnabled(anyWork())
        if not anyWork() then
            paintHeader()
        end
    end

    G.AnimeDiceAutoSpin = {
        setEnabled = function(on)
            if on ~= true then
                spinOn = false
            end
            syncWork()
        end,
        stop = function()
            workLoop.setEnabled(false)
            paintLoop.setEnabled(false)
        end,
        luckBusy = function()
            return spinOn == true
        end,
        spinning = function()
            return spinOn == true and activeAt > 0 and os.clock() - activeAt < math.max(1.5, clampQueueDelay(queueDelay) * 3)
        end,
    }

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 7,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Lucky Spin & Jackpot Spin",
                expanded = false,
                status = {
                    id = "auto.spin.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "Off",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            cards = {}

            local function corner(inst, radius)
                local c = Instance.new("UICorner")
                c.CornerRadius = UDim.new(0, radius or 8)
                c.Parent = inst
            end

            local panel = Instance.new("Frame")
            panel.Name = "SpinLuck"
            panel.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
            panel.BackgroundTransparency = 0.2
            panel.BorderSizePixel = 0
            panel.Size = UDim2.new(1, 0, 0, 0)
            panel.AutomaticSize = Enum.AutomaticSize.Y
            panel.LayoutOrder = 0
            panel.Parent = group
            corner(panel, 8)
            Core.panelStroke(panel, Color3.fromRGB(255, 170, 90))

            local list = Instance.new("UIListLayout")
            list.FillDirection = Enum.FillDirection.Vertical
            list.SortOrder = Enum.SortOrder.LayoutOrder
            list.Padding = UDim.new(0, 1)
            list.Parent = panel
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 6)
            pad.PaddingBottom = UDim.new(0, 6)
            pad.PaddingLeft = UDim.new(0, 8)
            pad.PaddingRight = UDim.new(0, 8)
            pad.Parent = panel

            local function makeLine(order, caption, accent)
                local row = Instance.new("Frame")
                row.Name = caption
                row.BackgroundTransparency = 1
                row.Size = UDim2.new(1, 0, 0, 16)
                row.LayoutOrder = order
                row.Parent = panel

                local cap = Instance.new("TextLabel")
                cap.Name = "Head"
                cap.BackgroundTransparency = 1
                cap.Size = UDim2.new(0.5, 0, 1, 0)
                cap.Font = Enum.Font.Gotham
                cap.TextSize = 11
                cap.TextXAlignment = Enum.TextXAlignment.Left
                cap.TextYAlignment = Enum.TextYAlignment.Center
                cap.TextColor3 = accent
                cap.TextTruncate = Enum.TextTruncate.AtEnd
