                value.Font = Enum.Font.GothamMedium
                value.TextSize = 12
                value.TextXAlignment = Enum.TextXAlignment.Right
                value.TextYAlignment = Enum.TextYAlignment.Center
                value.TextColor3 = accent
                value.TextTruncate = Enum.TextTruncate.AtEnd
                value.RichText = true
                value.Text = "—"
                value.Parent = row
                return { value = value }
            end

            cards.akun = makeLine(1, "Account", Color3.fromRGB(255, 214, 90))
            cards.pot = makeLine(2, "Potion", Color3.fromRGB(196, 160, 255))
            cards.ls = makeLine(3, "Lucky x" .. tostring(LS_MULT) .. " & event", Color3.fromRGB(120, 190, 255))
            cards.jp = makeLine(4, "Jackpot x" .. tostring(JP_MULT) .. " & event", Color3.fromRGB(255, 170, 90))
            pcall(function()
                paintCards(snapshot())
            end)

            ui:CreateRowDropdown(group, {
                id = "animedice.spin.items",
                label = "Item",
