                placeholder = "Lucky / Jackpot...",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                getItems = function()
                    local data = Core.data()
                    local stock = ownedStock(data)
                    return {
                        { key = JP, name = JP .. " (" .. tostring(stock[JP] or 0) .. ")" },
                        { key = LS, name = LS .. " (" .. tostring(stock[LS] or 0) .. ")" },
                    }
                end,
                labelForKey = function(key)
                    local stock = ownedStock(Core.data())
                    return tostring(key) .. " (" .. tostring(stock[key] or 0) .. ")"
                end,
                onChanged = function(a, b)
                    selected = copyMap(dropdownValue(a, b))
                    resetGate()
                    paintHeader()
                end,
