                    if mapSize(whens) == 0 then
                        whens = { luck_event = true }
                    end
                    paintMaxInfo()
                    paintHeader()
                end,
            })
            ui:CreateRowSlider(group, {
                id = "animedice.spin.maxJp",
                label = "Max Jackpot Spin",
                min = 0,
                max = 1000,
                step = 1,
                initial = maxJp,
                persist = true,
                onChanged = function(n)
                    maxJp = clampMax(n)
                    resetGate()
                    paintMaxInfo()
                    paintHeader()
                end,
            })
            local jpInfoRow, _, jpApi = ui:CreateRowLabel(group, {
                text = maxInfoText(JP, maxJp),
                wrap = true,
                style = "detail",
            })
            jpInfoApi = jpApi
            local jpPad = Instance.new("UIPadding")
            jpPad.PaddingTop = UDim.new(0, 0)
            jpPad.PaddingBottom = UDim.new(0, 4)
            if jpInfoRow then
                jpPad.Parent = jpInfoRow
            end
            ui:CreateRowSlider(group, {
                id = "animedice.spin.maxLs",
                label = "Max Lucky Spin",
                min = 0,
                max = 1000,
                step = 1,
                initial = maxLs,
                persist = true,
                onChanged = function(n)
                    maxLs = clampMax(n)
                    resetGate()
                    paintMaxInfo()
                    paintHeader()
                end,
            })
            local lsInfoRow, _, lsApi = ui:CreateRowLabel(group, {
                text = maxInfoText(LS, maxLs),
                wrap = true,
                style = "detail",
            })
            lsInfoApi = lsApi
            local lsPad = Instance.new("UIPadding")
            lsPad.PaddingTop = UDim.new(0, 0)
            lsPad.PaddingBottom = UDim.new(0, 4)
            if lsInfoRow then
                lsPad.Parent = lsInfoRow
            end
            ui:CreateRowSlider(group, {
                id = "animedice.spin.queueDelay",
                label = "JP → LS delay",
                min = 0.1,
                max = 1,
                step = 0.05,
                initial = queueDelay,
                suffix = "s",
                persist = true,
                onChanged = function(n)
