            gapPad.PaddingTop = UDim.new(0, 0)
            gapPad.PaddingBottom = UDim.new(0, 4)
            if gapRow then
                gapPad.Parent = gapRow
            end

            ui:CreateRowDropdown(group, {
                id = "animedice.spin.potionMode",
                label = "Luck potion",
                placeholder = "Potion max tier",
