                        { key = MODE_ANY, name = "Any potion have" },
                    }
                end,
                onChanged = function(a, b)
                    potionMode = clampPotionMode(dropdownValue(a, b))
                    resetGate()
                    paintHeader()
                end,
            })

            local enableGroup = ui:CreateGroup(body)
            local _, _, api = Core.bindToggle(ui, enableGroup, {
                id = "animedice.spin.enable",
                label = "Enable Auto Lucky Spin & Jackpot Spin",
                initial = false,
