                    spinOn = on == true
                    resetGate()
                    if spinOn then
                        resetWindow()
                    end
                    syncWork()
                    paintHeader()
                end,
            })
            enableApi = api
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if type(values["animedice.spin.items"]) == "table" then
            selected = copyMap(values["animedice.spin.items"])
        end
        if type(values["animedice.spin.whens"]) == "table" then
