        end
        if values["animedice.spin.potionMode"] ~= nil then
            potionMode = clampPotionMode(dropdownValue("single", values["animedice.spin.potionMode"]))
        end
        spinOn = values["animedice.spin.enable"] == true
        if values["animedice.spin.enable"] == nil then
            spinOn = values["animedice.spin.jp"] == true or values["animedice.spin.ls"] == true
        end
