        paintMaxInfo()
        paintGapInfo()
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "AutoGear", name = "Auto Gear", factory = function() -- AUTO → Auto Gear.
-- Equip Best per Goal. 1 slot / tick. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local Catalog = Core.gears and Core.gears() or G.AnimeDiceGearCatalog
    if type(Catalog) ~= "table" then
        warn("[ANIME DICE] Gear catalog missing")
        return
    end

    local old = G.AnimeDiceAutoGear
    if type(old) == "table" and type(old.setEnabled) == "function" then
        pcall(old.setEnabled, false)
    end

    local goalKey = "luck"
    local headerApi
    local previewApi
    local gearLoop
    local equipSignal

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
            return nil
        end
        if type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if ok then
                return r
            end
        end
        return v
    end

    local function dropdownValue(a, b)
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local function clampGoal(key)
        return Catalog.goalOf(key).key
    end

    local function ownedGears(data)
        local owned = {}
        if type(data) ~= "table" or type(data.Inventory) ~= "table" then
            return owned
        end
        local inv
        pcall(function()
            inv = data.Inventory()
        end)
        if type(inv) == "table" then
            for _, row in pairs(inv) do
                if type(row) == "table" then
                    local name = readVal(row.name)
                    local amount = tonumber(readVal(row.amount)) or 0
                    if type(name) == "string" and amount > 0 and Catalog.byName(name) then
                        owned[name] = (owned[name] or 0) + amount
                    end
                end
            end
        end
        for _, item in ipairs(Catalog.items()) do
            if not owned[item.name] then
                local getter = data.Inventory[item.name]
                if getter ~= nil then
                    local ok, row = pcall(function()
                        if type(getter) == "function" then
                            return getter()
                        end
                        return getter
                    end)
                    if ok and row ~= nil then
                        local amount
                        if type(row) == "number" then
                            amount = row
                        elseif type(row) == "table" then
                            amount = tonumber(readVal(row.amount)) or 0
                        end
                        if (tonumber(amount) or 0) > 0 then
                            owned[item.name] = amount
                        end
                    end
                end
            end
        end
        return owned
    end

    local function equippedName(data, slot)
        if type(data) ~= "table" or type(slot) ~= "string" then
            return nil
        end
        local map = data.EquippedGear
        if type(map) ~= "table" then
            return nil
        end
        local v = readVal(map[slot])
        if type(v) == "string" and v ~= "" then
            return v
        end
        return nil
    end

    local function snapshot()
        local Data
        local okData = pcall(function()
            Data = Core.data()
        end)
        if not okData or not Data then
            return nil
        end
        local owned
        local okOwned = pcall(function()
            owned = ownedGears(Data)
        end)
        if not okOwned then
            owned = {}
        end
        local picks = Catalog.pickBest(owned, goalKey)
        local filled = 0
        local match = 0
        local names = {}
        for _, slot in ipairs(Catalog.slots()) do
            local pick = picks[slot]
            local cur = equippedName(Data, slot)
            if pick then
                filled = filled + 1
                names[#names + 1] = pick.name
                if cur == pick.name then
                    match = match + 1
                end
            else
                names[#names + 1] = "—"
            end
        end
        return {
            picks = picks,
            filled = filled,
            match = match,
            line = table.concat(names, " · "),
        }
    end

    local function paintHeader()
        local api = headerApi
        if type(api) ~= "table" then
            return
        end
        local goal = Catalog.goalOf(goalKey)
        local snap = snapshot()
        local line = snap and snap.line or "no gear"
        if previewApi and type(previewApi.set) == "function" then
            pcall(previewApi.set, line)
        elseif previewApi then
            pcall(function()
                previewApi.Text = line
            end)
        end
        local on = gearLoop and gearLoop.enabled()
        if not on then
            Core.paintHeader(api, "Off", "muted", goal.name)
            return
        end
        local match = snap and snap.match or 0
        local filled = snap and snap.filled or 0
        Core.paintHeader(api, "On", "success", goal.name .. " · " .. tostring(match) .. "/" .. tostring(filled))
    end

    local function nets()
        if equipSignal then
            return true
        end
        local ok = pcall(function()
            local RS = game:GetService("ReplicatedStorage")
            equipSignal = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "GearService"):GetSignal("Equip")
        end)
        return ok and equipSignal ~= nil
    end

    local EQUIP_GAP = 0.25
    local CHECK_SEC = 20

    local function tryEquip()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return
            end
        end
        if not nets() then
            return
        end
        local Data = Core.data()
        if not Data then
            return
        end
        local picks = Catalog.pickBest(ownedGears(Data), goalKey)
        local fired = 0
        for _, slot in ipairs(Catalog.slots()) do
            local pick = picks[slot]
            if pick then
                local cur = equippedName(Data, slot)
                if cur ~= pick.name then
                    if fired > 0 then
                        task.wait(EQUIP_GAP)
                    end
                    equipSignal:Fire(slot, pick.name)
                    fired = fired + 1
                end
            end
        end
        paintHeader()
    end

    gearLoop = Core.loop("auto_gear", {
        delay = CHECK_SEC,
        step = tryEquip,
    })
    G.AnimeDiceAutoGear = {
        setEnabled = gearLoop.setEnabled,
        enabled = gearLoop.enabled,
    }

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 7,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Gear",
                expanded = false,
                status = {
                    id = "auto.gear.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "Luck",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)

            ui:CreateRowDropdown(group, {
                id = "auto.gear.goal",
                label = "Goal",
                placeholder = "Luck",
                clearable = false,
                persist = true,
                preserveItemOrder = true,
                initial = goalKey,
                getItems = function()
                    return Catalog.goalItems()
                end,
                onChanged = function(a, b)
                    goalKey = clampGoal(dropdownValue(a, b))
                    paintHeader()
                end,
            })

            local note, _, noteApi = ui:CreateRowLabel(group, {
                text = "— · — · — · — · —",
                wrap = true,
                style = "detail",
            })
            previewApi = noteApi
            local pad = Instance.new("UIPadding")
            pad.PaddingTop = UDim.new(0, 2)
            pad.PaddingBottom = UDim.new(0, 4)
            if note then
                pad.Parent = note
            end

            Core.bindToggle(ui, group, {
                id = "auto.gear",
                label = "Enable Auto Gear",
                initial = gearLoop.enabled(),
                onChanged = function(on)
                    gearLoop.setEnabled(on == true)
                    paintHeader()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if values["auto.gear.goal"] ~= nil then
            goalKey = clampGoal(dropdownValue("single", values["auto.gear.goal"]))
        end
        gearLoop.setEnabled(values["auto.gear"] == true)
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "AutoQuest", name = "Auto Quest", factory = function() -- AUTO → Quest.
-- Auto Claim Daily/Weekly. Auto Buy Quest Shop dari dropdown. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local QuestConfig
    pcall(function()
        QuestConfig = require(RS.Framework.Features.Quests.QuestConfig)
    end)
    if type(QuestConfig) ~= "table" or type(QuestConfig.Periods) ~= "table" then
        warn("[ANIME DICE] Quest config missing")
        return
    end

    local old = G.AnimeDiceAutoQuest
    if type(old) == "table" then
        if type(old.setEnabled) == "function" then
            pcall(old.setEnabled, false)
        end
        if type(old.setBuyEnabled) == "function" then
            pcall(old.setBuyEnabled, false)
        end
    end

    local headerApi
    local claimLoop
    local buyLoop
    local claimSig
    local buySig
    local selected = {}
    local PERIODS = { "Daily", "Weekly" }
    local shopItems = {}
    if type(QuestConfig.Shop) == "table" then
        for _, item in ipairs(QuestConfig.Shop) do
            local name = tostring(item.name or "")
            if name ~= "" then
                shopItems[#shopItems + 1] = {
                    name = name,
                    amount = tonumber(item.amount),
                    tickets = tonumber(item.tickets) or 0,
                    gamepass = item.gamepass == true,
                }
            end
        end
    end

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
            return nil
        end
        if type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a
        end
        if type(b) == "table" then
            return b
        end
        return a
    end

    local function shopByName(name)
        for _, item in ipairs(shopItems) do
            if item.name == name then
                return item
            end
        end
        return nil
    end

    local function knownShop(map)
        local out = {}
        for k in pairs(copyMap(map)) do
            if shopByName(k) then
                out[k] = true
            end
        end
        return out
    end

    local function shopLabel(name)
        local item = shopByName(name)
        if not item then
            return tostring(name or "")
        end
        if item.gamepass then
            return item.name .. " (gp) · " .. tostring(item.tickets) .. " tix"
        end
        if item.amount then
            return item.name .. " x" .. tostring(item.amount) .. " · " .. tostring(item.tickets) .. " tix"
        end
        return item.name .. " · " .. tostring(item.tickets) .. " tix"
    end

    local function mapOf(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        local dumped = src
        local ok, r = pcall(function()
            return src()
        end)
        if ok and type(r) == "table" then
            dumped = r
        end
        for k, v in pairs(dumped) do
            local val = readVal(v)
            if val == true or val == 1 or val == "true" then
                out[tostring(k)] = true
            else
                local n = tonumber(val)
                if n then
                    out[tostring(k)] = n
                end
            end
        end
        return out
    end

    local function nets()
        if claimSig and buySig then
            return true
        end
        local ok = pcall(function()
            local comm = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "QuestService")
            claimSig = comm:GetSignal("Claim")
            buySig = comm:GetSignal("Buy")
        end)
        return ok and claimSig ~= nil and buySig ~= nil
    end

    local function ticketsOf(data)
        local n = 0
        pcall(function()
            local row = data.Inventory.Tickets()
            if type(row) == "table" then
                n = tonumber(readVal(row.amount)) or 0
            else
                n = tonumber(readVal(row)) or 0
            end
        end)
        return n
    end

    local function periodState(data, period)
        local raw
        pcall(function()
            raw = data.Quests[period]()
        end)
        if type(raw) ~= "table" then
            return {
                expiresAt = 0,
                progress = {},
                claimed = {},
            }
        end
        return {
            expiresAt = tonumber(readVal(raw.expiresAt)) or 0,
            progress = mapOf(raw.progress),
            claimed = mapOf(raw.claimed),
        }
    end

    local function ownsPass(data, name)
        local on = false
        pcall(function()
            local node = data.OwnedGamepasses[name]
            on = readVal(node) == true
        end)
        return on == true
    end

    local function readyList(data)
        local ready = {}
        if not data then
            return ready
        end
        for _, period in ipairs(PERIODS) do
            local cfg = QuestConfig.Periods[period]
            if type(cfg) == "table" and type(cfg.quests) == "table" then
                local state = periodState(data, period)
                for _, q in ipairs(cfg.quests) do
                    local id = tostring(q.id or "")
                    local prog = tonumber(state.progress[id]) or 0
                    local target = tonumber(q.target) or 0
                    if id ~= "" and not state.claimed[id] and prog >= target and target > 0 then
                        ready[#ready + 1] = {
                            period = period,
                            id = id,
                            tickets = tonumber(q.tickets) or 0,
                            expiresAt = state.expiresAt,
                        }
                    end
                end
            end
        end
        return ready
    end

    local function paintHeader()
        if type(headerApi) ~= "table" then
            return
        end
        local data
        pcall(function()
            data = Core.data()
        end)
        local n = 0
        local tix = 0
        if data then
            n = #readyList(data)
            tix = ticketsOf(data)
        end
        local claimOn = claimLoop and claimLoop.enabled()
        local buyOn = buyLoop and buyLoop.enabled()
        local badge = (claimOn or buyOn) and "On" or "Off"
        local style = (claimOn or buyOn) and "success" or "muted"
        local detail = tostring(n) .. " ready"
        if buyOn then
            detail = detail .. " · Buy " .. tostring(mapSize(selected))
        end
        detail = detail .. " · " .. Core.compact(tix) .. " tix"
        Core.paintHeader(headerApi, badge, style, detail)
    end

    local function tryClaim()
        if not nets() then
            return
        end
        local data = Core.data()
        if not data then
            return
        end
        local ready = readyList(data)
        for i, row in ipairs(ready) do
            if i > 1 then
                task.wait(0.25)
            end
            pcall(function()
                claimSig:Fire(row.period, row.id, row.expiresAt)
            end)
        end
        paintHeader()
    end

    local function tryBuy()
        if not nets() then
            return
        end
        local data = Core.data()
        if not data or mapSize(selected) == 0 then
            paintHeader()
            return
        end
        local tix = ticketsOf(data)
        local fired = 0
        for _, item in ipairs(shopItems) do
            if selected[item.name] then
                local skip = item.gamepass and ownsPass(data, item.name)
                local cost = tonumber(item.tickets) or 0
                if not skip and cost > 0 and tix >= cost then
                    if fired > 0 then
                        task.wait(0.25)
                    end
                    pcall(function()
                        buySig:Fire(item.name)
                    end)
                    tix = tix - cost
                    fired = fired + 1
                    if fired >= 4 then
                        break
                    end
                end
            end
        end
        paintHeader()
    end

    claimLoop = Core.loop("auto_quest", {
        delay = 4,
        step = tryClaim,
    })
    buyLoop = Core.loop("auto_quest_buy", {
        delay = 4,
        step = tryBuy,
    })
    buyLoop.setEnabled(true)
    G.AnimeDiceAutoQuest = {
        setEnabled = claimLoop.setEnabled,
        enabled = claimLoop.enabled,
        setBuyEnabled = buyLoop.setEnabled,
        buyEnabled = buyLoop.enabled,
    }

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "main",
        subLabel = "Main",
        subOrder = 1,
        order = 8,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Quest",
                expanded = false,
                status = {
                    id = "auto.quest.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "claim / shop",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            Core.bindToggle(ui, group, {
                id = "animedice.quest.claim",
                label = "Enable Auto Claim Quest",
                initial = claimLoop.enabled(),
                onChanged = function(on)
                    claimLoop.setEnabled(on == true)
                    paintHeader()
                end,
            })

            ui:CreateRowDropdown(group, {
                id = "animedice.quest.shopItems",
                label = "Quest Shop",
                mode = "multi",
                placeholder = "Pick shop items...",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                initial = {},
                maxLabelChars = 36,
                getItems = function()
                    local out = {}
                    for _, item in ipairs(shopItems) do
                        out[#out + 1] = {
                            key = item.name,
                            name = shopLabel(item.name),
                        }
                    end
                    return out
                end,
                labelForKey = shopLabel,
                onChanged = function(a, b)
                    selected = knownShop(dropdownValue(a, b))
                    paintHeader()
                end,
            })

            Core.bindToggle(ui, group, {
                id = "animedice.quest.buy",
                label = "Enable Auto Buy Quest Shop",
                initial = true,
                onChanged = function(on)
                    buyLoop.setEnabled(on == true)
                    paintHeader()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if type(values["animedice.quest.shopItems"]) == "table" then
            selected = knownShop(values["animedice.quest.shopItems"])
        end
        if values["animedice.quest.claim"] ~= nil then
            claimLoop.setEnabled(values["animedice.quest.claim"] == true)
        end
        if values["animedice.quest.buy"] ~= nil then
            buyLoop.setEnabled(values["animedice.quest.buy"] == true)
        else
            buyLoop.setEnabled(true)
        end
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "Halloween", name = "Halloween Event", factory = function() -- EVENT -> Halloween.
-- Quest / Shop / Pass / Pumpkin Dice = remote. Trick-or-Treat = PivotTo pintu.
-- Masuk island lewat HalloweenService.Teleport("Island") (portal). Toggle default off.

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local Players = game:GetService("Players")
    local CollectionService = game:GetService("CollectionService")
    local LP = Core.player() or Players.LocalPlayer

    local old = G.AnimeDiceHalloween
    if type(old) == "table" and type(old.stopAll) == "function" then
        pcall(old.stopAll)
    end

    local HalloweenShop, HalloweenQuests, PumpkinDice, PumpkinPass
    pcall(function()
        HalloweenShop = require(RS.Framework.Features.Halloween.HalloweenShop)
    end)
    pcall(function()
        HalloweenQuests = require(RS.Framework.Features.Halloween.HalloweenQuests)
    end)
    pcall(function()
        PumpkinDice = require(RS.Framework.Features.Halloween.PumpkinDice)
    end)
    pcall(function()
        PumpkinPass = require(RS.Framework.Features.Halloween.PumpkinPass)
    end)

    local headerApi
    local hauntInfoApi
    local paintHauntInfo
    local shopPick = {}
    local sellPick = {}
    local hauntWing = "Front Yard"
    local hauntBestWing = false
    local hauntGearHunt = false
    local hauntExclusiveSig = ""
    local hauntDriveWanted = false
    local hauntDriveRunning = false
    local hauntDriveWing = nil
    local hauntDriveStage = 0
    local hauntDrivePhase = ""
    local hauntShotFloor = 0
    local hauntShotAt = 0
    local hauntTeam = nil
    local hauntTeamAt = 0
