    pcall(function()
        HauntedHouse = require(RS.Framework.Features.Halloween.HauntedHouse)
    end)
    local weatherProp
    local weather = { name = nil, startedAt = 0, duration = 0 }
    local claimHourly = false
    local claimDaily = false
    local claimPassFree = false
    local claimPassPremium = false
    local claimPassAll = false
    local lastTotAt = {}
    local lastTotPos = nil
    local lastTotTime = 0
