    local HAUNT_WINGS = {
        "Front Yard",
        "Foyer",
        "Crypt",
        "Attic",
        "Bell Tower",
        "The Abyss",
    }

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
            return nil
        end
        if type(v) == "table" then
            local ok, r = pcall(function()
                return v()
            end)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and type(v) == "string" then
                out[v] = true
            end
        end
        return out
    end

    local function dropdownValue(a, b)
        if a == "multi" or a == "single" then
            return b
        end
        return b or a
    end

    local function dataCtrl()
        local ok, DC = pcall(function()
            return require(RS.Framework.Features.Data.DataController)
        end)
        if ok then
            return DC
        end
        return nil
    end

    local function halloweenData()
        local DC = dataCtrl()
        return DC and DC.Halloween
    end

    local function entryAmount(name)
        local DC = dataCtrl()
        local inv = DC and DC.Inventory
        local row = inv and inv[name]
        if row == nil then
            return 0
        end
        local amt = readVal(row)
        if type(amt) == "table" then
            amt = readVal(amt.amount)
        elseif type(row) == "table" and row.amount ~= nil then
            amt = readVal(row.amount)
        end
        return tonumber(amt) or 0
    end

    local function candyNow()
        return entryAmount("Candy")
    end

    local function pumpkinsNow()
        return entryAmount("Pumpkins")
    end

    local function candyEarned()
        local hw = halloweenData()
        return tonumber(readVal(hw and hw.CandyEarned)) or 0
    end

    local function pathPremium()
        local hw = halloweenData()
        return readVal(hw and hw.PathPremium) == true
    end

    local function netSignal(service, name)
        local ok, sig = pcall(function()
            return require(RS.Packages.Network).ClientComm.new(RS.Network, false, service):GetSignal(name)
        end)
        if ok then
            return sig
        end
        return Core.remote(service, name)
    end

    local function netFunction(service, name)
        local ok, fn = pcall(function()
            return require(RS.Packages.Network).ClientComm.new(RS.Network, false, service):GetFunction(name)
        end)
        if ok then
            return fn
        end
        return nil
    end

    local function tradeBusy()
        if type(Core.tradeBusy) == "function" then
            local ok, on = pcall(Core.tradeBusy)
            return ok and on == true
        end
        return false
    end

    local function makeUnitBusy()
        local U = G.AnimeDiceAutoUnit
        if type(U) ~= "table" then
            return false
        end
        -- Make Unit nyala = karakter harus di hub. Jangan TP island sama sekali.
        if type(U.anyOn) == "function" then
            local ok, on = pcall(U.anyOn)
            if ok and on == true then
                return true
            end
        end
        if type(U.busy) == "function" then
            local ok, on = pcall(U.busy)
            if ok and on == true then
                return true
            end
        end
        if U.holdHub == true or U.working == true then
            return true
        end
        return type(U.needMachine) == "string" and U.needMachine ~= ""
    end

    local function towerBusy()
        if hauntDrivePhase == "run" then
            return true
        end
        local A = G.AnimeDiceAutoTower
        if type(A) == "table" and type(A.busy) == "function" then
            local ok, on = pcall(A.busy)
            return ok and on == true
        end
        return false
    end

    -- Island cuma untuk ToT/Haunt. Pumpkin Dice remote, jangan tarik ke island.
    local function halloweenFarmOn()
        return (type(G.AnimeDiceHwTot) == "table" and G.AnimeDiceHwTot.on == true)
            or (type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true)
    end

    local function inHalloweenWorld()
        local char = LP and LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then
            return false
        end
        local zones = workspace:FindFirstChild("Zones")
        local zone = zones and zones:FindFirstChild("HalloweenWorld")
        if zone and zone:IsA("BasePart") then
            local rel = zone.CFrame:PointToObjectSpace(hrp.Position)
            local s = zone.Size
            if math.abs(rel.X) <= s.X * 0.5 + 40
                and math.abs(rel.Y) <= s.Y * 0.5 + 80
                and math.abs(rel.Z) <= s.Z * 0.5 + 40 then
                return true
            end
        end
        local folder = workspace:FindFirstChild("Halloween")
        local back = folder and folder:FindFirstChild("ReturnPoint")
        if back and back:IsA("BasePart") and (hrp.Position - back.Position).Magnitude < 90 then
            return false
        end
        local arr = folder and folder:FindFirstChild("ArrivalPoint")
        if arr and arr:IsA("BasePart") then
            return (hrp.Position - arr.Position).Magnitude < 120
        end
        return false
    end

    local function ensureIsland()
        if not halloweenFarmOn() then
            return true
        end
        if inHalloweenWorld() then
            return true
        end
        if tradeBusy() or makeUnitBusy() then
            return false
        end
        if os.clock() - lastIslandAt < 2.2 then
            return false
        end
        lastIslandAt = os.clock()
        local fn = netFunction("HalloweenService", "Teleport")
        if type(fn) ~= "function" then
            return false
        end
        local ok, res = pcall(fn, "Island")
        if ok and res then
            task.wait(0.35)
            return inHalloweenWorld()
        end
        return false
    end

    -- ToT hanya nunggu kalau karakter BENAR-benar di dalam tower, bukan saat Auto Tower idle/pending.
    local function inTowerNow()
        if hauntDrivePhase == "run" then
            return true
        end
        local A = G.AnimeDiceAutoTower
        if type(A) == "table" and type(A.inside) == "function" then
            local ok, on = pcall(A.inside)
            return ok and on == true
        end
        return false
    end

    local function anyOn()
        return claimHourly
            or claimDaily
            or claimPassFree
            or claimPassPremium
            or claimPassAll
            or (type(G.AnimeDiceHwTot) == "table" and G.AnimeDiceHwTot.on == true)
            or (type(G.AnimeDiceHwDice) == "table" and G.AnimeDiceHwDice.on == true)
            or (type(G.AnimeDiceHwShop) == "table" and G.AnimeDiceHwShop.on == true)
            or (type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true)
    end

    local function paint(value, style, detail)
        Core.paintHeader(headerApi, value, style, detail)
    end

    local function buffOf(name)
        local n = 1
        pcall(function()
            n = tonumber(require(RS.Framework.Features.Buffs.BuffController).GetBuff(name)) or 1
        end)
        if n < 1 then
            n = 1
        end
        return n
    end

    local function weatherRemain()
        if type(weather.name) ~= "string" or (tonumber(weather.startedAt) or 0) <= 0 then
            return 0
        end
        return math.max(
            0,
            (tonumber(weather.duration) or 300) - (workspace:GetServerTimeNow() - weather.startedAt)
        )
    end

    local function hauntedNightOn()
        return weather.name == "Haunted Night" and weatherRemain() > 0.25
    end

    pcall(function()
        weatherProp = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "WeatherService"):GetProperty("ActiveWeather")
        local function apply(value)
            weather = { name = nil, startedAt = 0, duration = 0 }
            if type(value) ~= "table" then
                return
            end
            weather.name = value.name
            weather.startedAt = tonumber(value.startedAt) or 0
            weather.duration = tonumber(value.duration) or 300
        end
        if weatherProp.IsReady and weatherProp:IsReady() then
            apply(weatherProp:Get())
        elseif type(weatherProp.Get) == "function" then
            apply(weatherProp:Get())
        end
        if type(weatherProp.Observe) == "function" then
            weatherProp:Observe(apply)
        end
    end)

    local function remainingOf(entry)
        if type(entry) ~= "table" then
            return 0
        end
        local remaining = tonumber(readVal(entry.remaining))
        if not remaining or remaining <= 0 then
            return 0
        end
        local startedAt = tonumber(readVal(entry.startedAt))
        if startedAt then
            return math.max(0, remaining - (workspace:GetServerTimeNow() - startedAt))
        end
        return remaining
    end

    local function hauntedPotionActive()
        local data = type(Core.data) == "function" and Core.data() or nil
        if not data or data.ActiveEntries == nil then
            return false
        end
        local snap
        pcall(function()
            snap = data.ActiveEntries()
        end)
        if type(snap) ~= "table" then
            return false
        end
        for _, entry in pairs(snap) do
            if type(entry) == "table" and readVal(entry.name) == "Haunted Potion" and remainingOf(entry) > 0.5 then
                return true
            end
        end
        return false
    end

    local function findInvId(name)
        local data = type(Core.data) == "function" and Core.data() or nil
        if not data then
            return nil
        end
        local inv
        pcall(function()
            inv = data.Inventory()
        end)
        if type(inv) ~= "table" then
            return nil
        end
        for id, row in pairs(inv) do
            if type(row) == "table" and readVal(row.name) == name then
                if (tonumber(readVal(row.amount)) or 0) > 0 then
                    return id
                end
            end
        end
        return nil
    end

    local useBoost
    local function boostNet()
        if useBoost then
            return true
        end
        local ok = pcall(function()
            useBoost = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "BoostService"):GetSignal("Use")
        end)
        return ok and useBoost ~= nil
    end

    local function tryUseHauntedPotion()
        if hauntedPotionActive() then
            return true
        end
        if os.clock() < potionPendingUntil then
            return false
        end
        if not boostNet() then
            return false
        end
        local id = findInvId("Haunted Potion")
        if not id then
            return false
        end
        pcall(function()
            useBoost:Fire(id)
        end)
        potionPendingUntil = os.clock() + 2
        return false
    end

    local function luckDetail()
        local pumpkin = buffOf("Pumpkin Luck")
        local luck = buffOf("Luck")
        local bits = {
            "PLuck x" .. Core.compact(pumpkin),
            "Luck x" .. Core.compact(luck),
        }
        if hauntedNightOn() then
            bits[#bits + 1] = "Night"
        end
        if hauntedPotionActive() then
            bits[#bits + 1] = "Potion"
        end
        return table.concat(bits, " · ")
    end

    local function paintStatus(extra)
        local bag = Core.compact(candyNow())
            .. "c · "
            .. Core.compact(pumpkinsNow())
            .. "p · "
            .. luckDetail()
        if not anyOn() then
            paint("Off", "muted", bag)
            if paintHauntInfo then
                paintHauntInfo()
            end
            return
        end
        local detail = bag
        if type(extra) == "string" and extra ~= "" then
            detail = extra .. " · " .. bag
        end
        paint("On", "success", detail)
        if paintHauntInfo then
            paintHauntInfo()
        end
    end

    local function questPool(period)
        local bag = type(HalloweenQuests) == "table" and HalloweenQuests[period]
        return type(bag) == "table" and bag.pool or nil
    end

    local function questById(period, id)
        local pool = questPool(period)
        if type(pool) ~= "table" then
            return nil
        end
        for i = 1, #pool do
            if pool[i].id == id then
                return pool[i]
            end
        end
        return nil
    end

    local function questBag(period)
        local hw = halloweenData()
        if not hw then
            return nil
        end
        local key = period == "Hourly" and "HourlyQuests" or "Quests"
        local raw = hw[key]
        local bag = readVal(raw)
        if type(bag) ~= "table" then
            return nil
        end
        return bag
    end

    local function questIds(bag)
        local ids = readVal(bag and bag.ids)
        if type(ids) ~= "table" then
            return {}
        end
        local out = {}
        for i, id in ipairs(ids) do
            if type(id) == "string" then
                out[#out + 1] = id
            end
        end
        if #out == 0 then
            for k, v in pairs(ids) do
                if type(k) == "number" and type(v) == "string" then
                    out[#out + 1] = v
                elseif type(k) == "string" and (v == true or type(v) == "number") then
                    out[#out + 1] = k
                end
            end
        end
        return out
    end

    local function tryClaimQuests()
        if tradeBusy() then
            return
        end
        local sig = netSignal("HalloweenQuestService", "Claim")
        if not sig then
            return
        end
        local periods = {}
        if claimHourly then
            periods[#periods + 1] = "Hourly"
        end
        if claimDaily then
            periods[#periods + 1] = "Daily"
        end
        for _, period in ipairs(periods) do
            local bag = questBag(period)
            if bag then
                local ids = questIds(bag)
                for _, id in ipairs(ids) do
                    local info = questById(period, id)
                    local prog = 0
                    local claimed = false
                    if type(bag.progress) == "table" then
                        prog = tonumber(readVal(bag.progress[id])) or 0
                    end
                    if type(bag.claimed) == "table" then
                        claimed = readVal(bag.claimed[id]) == true
                    end
                    local target = info and tonumber(info.target) or 0
                    if info and not claimed and target > 0 and prog >= target then
                        pcall(function()
                            sig:Fire(period, id)
                        end)
                        task.wait(0.2)
                    end
                end
            end
        end
    end

    local function pathClaimed(map, index)
        if type(map) ~= "table" then
            return false
        end
        local key = tostring(index)
        return readVal(map[key]) == true
    end

    local function tryClaimPass()
        if tradeBusy() then
            return
        end
        if claimPassAll then
            local all = netSignal("HalloweenService", "ClaimAllPath")
            if all then
                pcall(function()
                    all:Fire()
                end)
            end
            return
        end
        if not (claimPassFree or claimPassPremium) then
            return
        end
        if type(PumpkinPass) ~= "table" then
            return
        end
        local hw = halloweenData()
        if not hw then
            return
        end
        local earned = candyEarned()
        local premium = pathPremium()
        local sig = netSignal("HalloweenService", "ClaimPath")
        if not sig then
            return
        end
        for i, tier in ipairs(PumpkinPass) do
            local need = tonumber(tier.candy) or 0
            if earned < need then
                break
            end
            if claimPassFree and not pathClaimed(hw.PathClaimed, i) then
                pcall(function()
                    sig:Fire(i, false)
                end)
                task.wait(0.15)
            end
            if claimPassPremium and premium and not pathClaimed(hw.PathPremiumClaimed, i) then
                pcall(function()
                    sig:Fire(i, true)
                end)
                task.wait(0.15)
            end
        end
    end

    local function tryBuyShop()
        if tradeBusy() then
            return
        end
        local sig = netSignal("HalloweenService", "BuyOffer")
        if not sig or type(HalloweenShop) ~= "table" then
            return
        end
        local selected = {}
        local total = 0
        for i, item in ipairs(HalloweenShop) do
            if shopPick[item.name] == true then
                local cost = tonumber(item.candy) or 0
                if cost > 0 then
                    selected[#selected + 1] = { index = i, cost = cost, name = item.name }
                    total = total + cost
                end
            end
        end
        if #selected == 0 or total <= 0 then
            return
        end
        local candy = candyNow()
        if candy < total then
            paintStatus("shop wait " .. Core.compact(total) .. "c set")
            return
        end
        -- 1 set penuh (semua selected) per tick; ulangi max 2x kalau masih cukup.
        local sets = 0
        while candy >= total and sets < 2 do
            for _, row in ipairs(selected) do
                pcall(function()
                    sig:Fire(row.index)
                end)
                candy = candy - row.cost
                task.wait(0.2)
            end
            sets = sets + 1
        end
        if sets > 0 then
            paintStatus("shop bought x" .. tostring(sets))
        end
    end

    local function syncAutoSell()
        local sig = netSignal("PumpkinDiceService", "SetAutoSell")
        if not sig or type(PumpkinDice) ~= "table" or type(PumpkinDice.Units) ~= "table" then
            return
        end
        for _, unit in ipairs(PumpkinDice.Units) do
            local id = unit.id
            if type(id) == "string" then
                local want = sellPick[id] == true
                pcall(function()
                    sig:Fire(id, want)
                end)
                task.wait(0.05)
            end
        end
    end

    local function tryPumpkinRoll()
        if os.clock() < diceReadyAt then
            return
        end
        if tradeBusy() then
            return
        end
        if makeUnitBusy() then
            paintStatus("wait make unit")
            return
        end
        local fn = netFunction("PumpkinDiceService", "Roll")
        if type(fn) ~= "function" then
            return
        end
        if diceRequireNight and not hauntedNightOn() then
            paintStatus("dice wait Haunted Night")
            return
        end
        local needPotion = diceUsePotion or diceRequirePotion
        if needPotion and not hauntedPotionActive() then
            if diceUsePotion then
                tryUseHauntedPotion()
            end
            if not hauntedPotionActive() then
                if findInvId("Haunted Potion") then
                    paintStatus("dice wait potion")
                else
                    paintStatus("dice no Haunted Potion")
                end
                return
            end
        end
        -- Server cuma izinin count 1 atau MULTI (5), debounce 2 detik per invoke.
        local multi = 5
        local unitCost = 100
        if type(PumpkinDice) == "table" then
            multi = tonumber(PumpkinDice.MULTI) or 5
            unitCost = tonumber(PumpkinDice.COST) or 100
        end
        local have = pumpkinsNow()
        local count = 1
        if diceMulti then
            count = multi
        elseif have >= unitCost * multi then
            count = multi
        end
        local cost = unitCost * count
        if have < cost then
            paintStatus("dice wait pumpkins")
            return
        end
        local t0 = os.clock()
        local ok, res = pcall(fn, count)
        if not ok then
            diceReadyAt = os.clock() + 0.25
            return
        end
        if type(res) == "table" then
            if res.ok == true then
                diceReadyAt = t0 + 2
                paintStatus("dice x" .. tostring(count))
            elseif type(res.message) == "string" then
                -- Debounce server sudah kepakai meski inventory/pumpkin gagal.
                diceReadyAt = t0 + 2
                paintStatus(res.message)
            else
                diceReadyAt = os.clock() + 0.05
            end
            -- Top 100 dicatat hook Info dari invoke yang sama. Jangan note manual
            -- di sini: roll x5 tercatat dobel (1 unit kebaca 2 di Top 100).
        end
    end

    local function doorList()
        local out = {}
        for _, part in ipairs(CollectionService:GetTagged("TrickOrTreatDoor")) do
            if part:IsA("BasePart") and part.Parent then
                out[#out + 1] = part
            end
        end
        return out
    end

    local function doorKey(part)
        local home = part:GetAttribute("TrickOrTreatHome")
        local pos = typeof(home) == "CFrame" and home.Position or part.Position
        return string.format("%.1f,%.1f,%.1f", pos.X, pos.Y, pos.Z)
    end

    -- Baca sign game (Title = "Refilling..." / "Trick or Treat!") — sumber ready yang sama dengan UI.
    local function doorSignReady(part)
        local home = part:GetAttribute("TrickOrTreatHome")
        local pos = typeof(home) == "CFrame" and home.Position or part.Position
        local best, bestDist
        for _, att in ipairs(workspace.Terrain:GetChildren()) do
            if att.Name == "TrickOrTreatSign" and att:IsA("Attachment") then
                local dist = (att.Position - pos).Magnitude
                if not best or dist < bestDist then
                    best = att
                    bestDist = dist
                end
            end
        end
        if not best or (bestDist and bestDist > 25) then
            return true
        end
        local title
        for _, d in ipairs(best:GetDescendants()) do
            if d:IsA("TextLabel") and d.Name == "Title" then
                title = d.Text
                break
            end
        end
        if type(title) ~= "string" then
            return true
        end
        if title == "Refilling..." or string.lower(title):find("refill", 1, true) then
            return false
        end
        if title == "Trick or Treat!" then
            return true
        end
        -- rolling / outcome: jangan TP lagi
        return false
    end

    local function doorFront(part)
        local front = part:GetAttribute("TrickOrTreatFront")
        if typeof(front) ~= "Vector3" then
            front = part.CFrame.LookVector
        end
        local flat = Vector3.new(front.X, 0, front.Z)
        if flat.Magnitude < 0.05 then
            return Vector3.new(0, 0, -1)
        end
        return flat.Unit
    end

    local function standAt(part, side)
        local flat = doorFront(part)
        side = tonumber(side) or 1
        if side == 2 then
            flat = -flat
        elseif side == 3 then
            flat = Vector3.new(-flat.Z, 0, flat.X)
        end
        return part.Position + flat * 5 + Vector3.new(0, 3, 0)
    end

    -- Map Halloween pakai StreamingEnabled. PivotTo jauh tanpa stream = hitch/pause.
    -- Teleport resmi event juga RequestStreamAroundAsync dulu.
    local function streamAround(pos)
        if typeof(pos) ~= "Vector3" or not LP then
            return
        end
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp and (hrp.Position - pos).Magnitude < 120 then
            return
        end
        pcall(function()
            LP:RequestStreamAroundAsync(pos, 2)
        end)
    end

    local function travelWait(fromPos, toPos)
        if typeof(fromPos) ~= "Vector3" or typeof(toPos) ~= "Vector3" then
            return 2
        end
        local dist = (Vector3.new(fromPos.X, 0, fromPos.Z) - Vector3.new(toPos.X, 0, toPos.Z)).Magnitude
        return math.max(2, dist / 60)
    end

    local totKnockGen = 0
    local totKnockPart = nil

    local function hookTot()
        if totHooked then
            return
        end
        totHooked = true
        local sig = netSignal("TrickOrTreatService", "Knocked")
        if not sig or type(sig.Connect) ~= "function" then
            return
        end
        sig:Connect(function(part, _outcome, readyAt)
            if typeof(part) == "Instance" and part:IsA("BasePart") then
                local at = tonumber(readyAt) or (workspace:GetServerTimeNow() + 30)
                lastTotAt[doorKey(part)] = at
                lastTotPos = part.Position
                lastTotTime = workspace:GetServerTimeNow()
                totKnockPart = part
                totKnockGen = totKnockGen + 1
            end
        end)
    end

    local function waitKnock(part, timeout)
        local startGen = totKnockGen
        local t0 = os.clock()
        timeout = tonumber(timeout) or 1.4
        while os.clock() - t0 < timeout do
            if totKnockGen > startGen then
                if totKnockPart == part or (totKnockPart and doorKey(totKnockPart) == doorKey(part)) then
                    return true
                end
                -- knock lain; tetap anggap sukses kalau baru saja
                return true
            end
            task.wait(0.05)
        end
        return false
    end

    local function readyDoors(doors, now)
        local ready = {}
        for _, part in ipairs(doors) do
            local key = doorKey(part)
            if now >= (lastTotAt[key] or 0) and doorSignReady(part) then
                ready[#ready + 1] = part
            end
        end
        return ready
    end

    -- Satu pintu per tick (nearest). Jangan burst PivotTo semua rumah — streaming hitch.
    -- Jangan tarik karakter saat Haunt run. GUI AutoTower.inside sering false-positive.
    local function tryTot()
        if totBusy then
            return
        end
        if tradeBusy() then
            paintStatus("tot wait trade")
            return
        end
        if makeUnitBusy() then
            paintStatus("wait make unit")
            return
        end
        if not ensureIsland() then
            paintStatus("island portal")
            return
        end
        hookTot()
        local char = LP and LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then
            paintStatus("tot no char")
            return
        end
        local doors = doorList()
        totDoorN = #doors
        if #doors == 0 then
            totReadyN = 0
            paintStatus("tot no doors")
            return
        end
        local now = workspace:GetServerTimeNow()
        local ready = readyDoors(doors, now)
        totReadyN = #ready
        if #ready == 0 then
            local refill = 0
            for _, part in ipairs(doors) do
                if not doorSignReady(part) then
                    refill = refill + 1
                end
            end
            if refill > 0 then
                paintStatus("tot refill " .. tostring(refill) .. "/" .. tostring(#doors))
            else
                paintStatus("tot 0/" .. tostring(#doors) .. " ready")
            end
            return
        end
        local from = lastTotPos
        if typeof(from) ~= "Vector3" or (hrp.Position - from).Magnitude > 250 then
            from = hrp.Position
        end
        local part, nearDist
        for i = 1, #ready do
            local d = (ready[i].Position - from).Magnitude
            if not part or d < nearDist then
                part = ready[i]
                nearDist = d
            end
        end
        totBusy = true
        local okTot, errTot = pcall(function()
            if typeof(lastTotPos) == "Vector3" then
                local waitSec = travelWait(lastTotPos, part.Position) + 0.15
                local elapsed = workspace:GetServerTimeNow() - (lastTotTime or 0)
                if elapsed < waitSec then
                    task.wait(waitSec - elapsed)
                end
            end
            local got = false
            for side = 1, 3 do
                if tradeBusy() or not (G.AnimeDiceHwTot and G.AnimeDiceHwTot.on) then
                    break
                end
                char = LP and LP.Character
                if not (char and char.Parent) then
                    break
                end
                local stand = standAt(part, side)
                streamAround(stand)
                local ok = pcall(function()
                    char:PivotTo(CFrame.new(stand, part.Position))
                end)
                if ok and waitKnock(part, 1.2) then
                    got = true
                    break
                end
            end
            lastTotPos = part.Position
            if got then
                paintStatus("tot knock · " .. tostring(totReadyN - 1) .. "/" .. tostring(totDoorN) .. " left")
            else
                lastTotAt[doorKey(part)] = workspace:GetServerTimeNow() + 4
                paintStatus("tot miss · " .. tostring(totReadyN) .. "/" .. tostring(totDoorN) .. " ready")
            end
            totReadyN = #readyDoors(doorList(), workspace:GetServerTimeNow())
        end)
        totBusy = false
        if not okTot then
            warn("[halloween] tot " .. tostring(errTot))
        end
    end

    local function wingPumpkins(name)
        if type(HauntedHouse) ~= "table" or type(HauntedHouse.GetWing) ~= "function" then
            return 0
        end
        local w = HauntedHouse.GetWing(name)
        return w and tonumber(w.pumpkins) or 0
    end

    local function bestFloorNow()
        local hw = halloweenData()
        return tonumber(readVal(hw and hw.BestFloor)) or 0
    end

    local function wingUnlocked(name)
        if type(HauntedHouse) ~= "table" or type(HauntedHouse.GetWing) ~= "function" then
            return name == "Front Yard"
        end
        local w = HauntedHouse.GetWing(name)
        if type(w) ~= "table" then
            return false
        end
        local first = tonumber(w.firstFloor) or 1
        return bestFloorNow() >= (first - 1)
    end

    -- Prioritas pumpkin/floor: Abyss > Bell > Attic > Crypt > Foyer > Front.
    local function pickBestHauntWing()
        local bestName = "Front Yard"
        local bestRate = -1
        local list = type(HauntedHouse) == "table" and HauntedHouse.Wings or nil
        if type(list) == "table" then
            for _, w in ipairs(list) do
                if type(w) == "table" and type(w.name) == "string" and wingUnlocked(w.name) then
                    local rate = tonumber(w.pumpkins) or 0
                    if w.endless then
                        rate = rate + 8
                    end
                    if rate > bestRate then
                        bestRate = rate
                        bestName = w.name
                    end
                end
            end
            return bestName
        end
        for i = #HAUNT_WINGS, 1, -1 do
            local name = HAUNT_WINGS[i]
            if wingUnlocked(name) then
                return name
            end
        end
        return bestName
    end

    local function wingGearLabel(name)
        if type(HauntedHouse) ~= "table" or type(HauntedHouse.GetWing) ~= "function" then
            return nil
        end
        local w = HauntedHouse.GetWing(name)
        if type(w) ~= "table" then
            return nil
        end
        local gear = w.gear
        if type(gear) ~= "string" or gear == "" then
            return "no gear"
        end
        return gear .. " x" .. tostring(entryAmount(gear))
    end

    local function hauntItems()
        local out = {}
        for i = 1, #HAUNT_WINGS do
            local name = HAUNT_WINGS[i]
            local p = wingPumpkins(name)
            local tag = p > 0 and (tostring(p) .. "p/fl") or "?"
            if name == "The Abyss" then
                tag = tag .. "+"
            end
            local gear = wingGearLabel(name)
            if gear then
                tag = tag .. " · " .. gear
            end
            out[#out + 1] = {
                key = name,
                name = name .. " · " .. tag,
            }
        end
        return out
    end

    local PUMPKIN_POTS = { "Pumpkin Pot III", "Pumpkin Pot II", "Pumpkin Pot I" }

    local function pumpkinPotActive()
        local data = type(Core.data) == "function" and Core.data() or nil
        if not data or data.ActiveEntries == nil then
            return false, nil
        end
        local snap
        pcall(function()
            snap = data.ActiveEntries()
        end)
        if type(snap) ~= "table" then
            return false, nil
        end
        for _, entry in pairs(snap) do
            if type(entry) == "table" then
                local name = readVal(entry.name)
                if type(name) == "string" and name:find("Pumpkin Pot", 1, true) and remainingOf(entry) > 0.5 then
                    return true, name
                end
            end
        end
        return false, nil
    end

    local function tryUsePumpkinPot()
        local on = pumpkinPotActive()
        if on then
            return true
        end
        if os.clock() < pumpkinPotPendingUntil then
            return false
        end
        if not boostNet() then
            return false
        end
        for _, name in ipairs(PUMPKIN_POTS) do
            local id = findInvId(name)
            if id then
                pcall(function()
                    useBoost:Fire(id)
                end)
                pumpkinPotPendingUntil = os.clock() + 2
                return false
            end
        end
        return false
    end

    local function shopItems()
        local out = {}
        if type(HalloweenShop) ~= "table" then
            return out
        end
        for _, item in ipairs(HalloweenShop) do
            out[#out + 1] = {
                key = item.name,
                name = item.name .. " · " .. Core.compact(item.candy or 0) .. "c",
            }
        end
        return out
    end

    local function pumpkinEarn(name)
        local n = 0
        pcall(function()
            local cfg = require(RS.Framework.Features.Inventory.EntryRegistry).getEntryConfig(name)
            if type(cfg) == "table" and type(cfg.income) == "function" then
                local ok, v = pcall(cfg.income, {})
                if ok then
                    n = tonumber(v) or 0
                end
            end
        end)
        if n <= 0 and type(PumpkinDice) == "table" and type(PumpkinDice.Get) == "function" then
            local row = PumpkinDice.Get(name)
            n = row and tonumber(row.power) or 0
        end
        return n
    end

    local function pumpkinOneIn(unit)
        if type(PumpkinDice) == "table" and type(PumpkinDice.GetChance) == "function" then
            local ok, v = pcall(PumpkinDice.GetChance, unit, 1)
            if ok and tonumber(v) then
                return tonumber(v)
            end
        end
        return tonumber(unit and unit.chance) or 0
    end

    local function sellItems()
        local out = {}
        if type(PumpkinDice) ~= "table" or type(PumpkinDice.Units) ~= "table" then
            return out
        end
        for _, unit in ipairs(PumpkinDice.Units) do
            if type(unit.id) == "string" then
                local oneIn = pumpkinOneIn(unit)
                local earn = pumpkinEarn(unit.id)
                out[#out + 1] = {
                    key = unit.id,
                    name = string.format(
                        "%s · 1-in %s · %s/s",
                        unit.id,
                        Core.compact(oneIn),
                        Core.compact(earn)
                    ),
                    label = string.format(
                        "1-in %s · %s/s",
                        Core.compact(oneIn),
                        Core.compact(earn)
                    ),
                }
            end
        end
        return out
    end

    local function sellLabelForKey(key)
        key = tostring(key or "")
        if key == "" then
            return key
        end
        local unit = type(PumpkinDice) == "table" and type(PumpkinDice.Get) == "function" and PumpkinDice.Get(key)
        if type(unit) ~= "table" then
            unit = { id = key, chance = nil }
        end
        return string.format(
            "%s · 1-in %s · %s/s",
            key,
            Core.compact(pumpkinOneIn(unit)),
            Core.compact(pumpkinEarn(key))
        )
    end

    local function wingByName(name)
        if type(HauntedHouse) ~= "table" or type(HauntedHouse.GetWing) ~= "function" then
            return nil
        end
        local w = HauntedHouse.GetWing(name)
        if type(w) ~= "table" then
            return nil
        end
        return w
    end

    -- Musuh balas 30% HP sebelum unit berikutnya. Floor aman kalau 1 unit one-shot.
    local function shotFloorNow()
        local now = os.clock()
        if now - hauntShotAt < 10 and hauntShotFloor > 0 then
            return hauntShotFloor
        end
        hauntShotAt = now
        local best = 0
        local data = type(Core.data) == "function" and Core.data() or nil
        local inv
        if data then
            pcall(function()
                inv = data.Inventory()
            end)
        end
        if type(inv) == "table" then
            local Registry
            pcall(function()
                Registry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
            local seen = 0
            for _, item in pairs(inv) do
                seen = seen + 1
                if seen > 2500 then
                    break
                end
                local row = readVal(item)
                if type(row) == "table" then
                    local name = readVal(row.name)
                    local cfg = Registry and type(name) == "string" and Registry.getEntryConfig(name)
                    if type(cfg) == "table" and cfg.kind == "Unit" and type(cfg.damage) == "function" then
                        local attrs = readVal(row.attributes)
                        if type(attrs) ~= "table" then
                            attrs = row
                        end
                        local mutation = readVal(attrs.mutation)
                        if type(mutation) ~= "string" or mutation == "" then
                            mutation = nil
                        end
                        local okD, dmg = pcall(cfg.damage, {
                            mutation = mutation,
                            trait = readVal(attrs.trait),
                            grade = readVal(attrs.grade),
                            level = tonumber(readVal(attrs.level)) or 1,
                        })
                        dmg = okD and tonumber(dmg) or 0
                        if dmg > best then
                            best = dmg
                        end
                    end
                end
            end
        end
        local buff = 1
        pcall(function()
            local b = require(RS.Framework.Features.Buffs.BuffController).GetBuff("Damage Multiplier")
            if type(b) == "number" and b > 0 then
                buff = b
            end
        end)
        best = best * buff
        if best < 250 then
            hauntShotFloor = 0
            return 0
        end
        local n = 1 + math.log(best / 250) / math.log(1.18)
        if n ~= n or n == math.huge then
            hauntShotFloor = 0
            return 0
        end
        hauntShotFloor = math.max(0, math.floor(n + 1e-6))
        return hauntShotFloor
    end

    local function combatBuffs()
        local dmg, hp = 1, 1
        pcall(function()
            local b = require(RS.Framework.Features.Buffs.BuffController)
            local d = b.GetBuff("Damage Multiplier")
            local h = b.GetBuff("Health Multiplier")
            if type(d) == "number" and d > 0 then
                dmg = d
            end
            if type(h) == "number" and h > 0 then
                hp = h
            end
        end)
        return dmg, hp
    end

    local function unitCombat(item)
        if type(item) ~= "table" then
            return nil
        end
        local name = readVal(item.name)
        local Registry
        pcall(function()
            Registry = require(RS.Framework.Features.Inventory.EntryRegistry)
        end)
        local cfg = Registry and type(name) == "string" and Registry.getEntryConfig(name)
        if type(cfg) ~= "table" or cfg.kind ~= "Unit" then
            return nil
        end
        local attrs = readVal(item.attributes)
        if type(attrs) ~= "table" then
            attrs = item
        end
        local mutation = readVal(attrs.mutation)
        if type(mutation) ~= "string" or mutation == "" then
            mutation = nil
        end
        local opts = {
            mutation = mutation,
            trait = readVal(attrs.trait),
            grade = readVal(attrs.grade),
            level = tonumber(readVal(attrs.level)) or 1,
        }
        local dmg, hp = 0, 0
        if type(cfg.damage) == "function" then
            local ok, v = pcall(cfg.damage, opts)
            dmg = ok and tonumber(v) or 0
        end
        if type(cfg.health) == "function" then
            local ok, v = pcall(cfg.health, opts)
            hp = ok and tonumber(v) or 0
        end
        local dmgMul, hpMul = combatBuffs()
        return { dmg = dmg * dmgMul, hp = hp * hpMul }
    end

    local function towerTeamCombat()
        local now = os.clock()
        if hauntTeam and (now - hauntTeamAt) < 4 then
            return hauntTeam
        end
        local out = {}
        local data = type(Core.data) == "function" and Core.data() or nil
        if data and data.TowerTeam then
            for i = 1, 4 do
                local id
                pcall(function()
                    local getter = data.TowerTeam[i]
                    if type(getter) == "function" then
                        id = getter()
                    else
                        id = readVal(getter)
                    end
                end)
                if type(id) == "string" and id ~= "" then
                    local item
                    pcall(function()
                        item = data.Inventory[id]()
                    end)
                    local row = unitCombat(item)
                    if row then
                        out[#out + 1] = row
                    end
                end
            end
        end
        hauntTeam = out
        hauntTeamAt = now
        return out
    end

    local function absEnemy(absFloor)
        absFloor = tonumber(absFloor) or 1
        local hp, dmg = 0, 0
        if type(HauntedHouse) == "table" then
            if type(HauntedHouse.EnemyHealth) == "function" then
                hp = tonumber(HauntedHouse.EnemyHealth(absFloor)) or 0
            end
            if type(HauntedHouse.EnemyDamage) == "function" then
                dmg = tonumber(HauntedHouse.EnemyDamage(absFloor)) or 0
            end
        end
        if hp <= 0 then
            hp = math.floor(1.18 ^ (absFloor - 1) * 250)
        end
        if dmg <= 0 then
            dmg = math.floor(0.3 * hp)
        end
        return hp, dmg
    end

    -- Satu CompleteTowerFloor memproses seluruh giliran sampai musuh mati / tim kalah.
    -- Kalau kalah, server mengunci animasi wipe ±2 dtk per unit.
    local function canClearAbsFloor(absFloor)
        local team = towerTeamCombat()
        if #team == 0 then
            return true
        end
        local enemyHp, enemyDmg = absEnemy(absFloor)
        if enemyHp <= 0 then
            return true
        end
        local idx = 1
        local hpLeft = team[1].hp
        while idx <= #team and enemyHp > 0 do
            enemyHp = enemyHp - team[idx].dmg
            if enemyHp <= 0 then
                return true
            end
            hpLeft = hpLeft - enemyDmg
            if hpLeft <= 0 then
                idx = idx + 1
                if team[idx] then
                    hpLeft = team[idx].hp
                end
            end
        end
        return false
    end

    -- Masuk wing kalau one-shot cukup ATAU tim 4 slot bisa kalahkan lantai pertama
    -- (Bell 201 butuh 2 hit: one-shot 200 tetap boleh Bell).
    local function canStartWing(name, shot)
        local w = wingByName(name)
        if not w or not wingUnlocked(name) then
            return false
        end
        local first = tonumber(w.firstFloor) or 1
        if type(shot) == "number" and shot >= first then
            return true
        end
        return canClearAbsFloor(first)
    end

    local function pickStrengthWing()
        local shot = shotFloorNow()
        local bestName = "Front Yard"
        local bestOrder = -1
        for i = 1, #HAUNT_WINGS do
            local name = HAUNT_WINGS[i]
            local w = wingByName(name)
            local order = w and tonumber(w.order) or i
            if canStartWing(name, shot) and order > bestOrder then
                bestOrder = order
                bestName = name
            end
        end
        return bestName
    end

    local function missingGearWings(shot)
        local out = {}
        for i = 1, #HAUNT_WINGS do
            local name = HAUNT_WINGS[i]
            local w = wingByName(name)
            local gear = w and w.gear
            if type(gear) == "string" and gear ~= "" and entryAmount(gear) < 1 and canStartWing(name, shot) then
                out[#out + 1] = name
            end
        end
        return out
    end

    local function hauntSelection()
        if hauntGearHunt then
            local shot = shotFloorNow()
            local missing = missingGearWings(shot)
            if #missing > 0 then
                local map = {}
                for i = 1, #missing do
                    map[missing[i]] = true
                end
                hauntWing = missing[#missing]
                return map, "gear " .. table.concat(missing, ", ")
            end
            hauntWing = pickStrengthWing()
            return { [hauntWing] = true }, "farm " .. hauntWing
        end
        if hauntBestWing then
            hauntWing = pickBestHauntWing()
        end
        return { [hauntWing] = true }, "haunt " .. hauntWing
    end

    local function hauntInfoText()
        local shot = shotFloorNow()
        local owned, total = 0, 0
        local missing = {}
        local blocked = {}
        for i = 1, #HAUNT_WINGS do
            local name = HAUNT_WINGS[i]
            local w = wingByName(name)
            local gear = w and w.gear
            if type(gear) == "string" and gear ~= "" then
                total = total + 1
                local n = entryAmount(gear)
                if n >= 1 then
                    owned = owned + 1
                else
                    missing[#missing + 1] = gear .. " (" .. name .. ")"
                    if shot > 0 and not canStartWing(name, shot) then
                        blocked[#blocked + 1] = name
                    end
                end
            end
        end
        local action
        local hauntOn = type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true
        if not hauntOn then
            action = "Haunt mati. Nyalakan Auto Haunted House."
        elseif hauntGearHunt then
            local reach = missingGearWings(shot)
            if #reach > 0 then
                action = "Gear hunt · gilir " .. table.concat(reach, ", ")
            elseif #missing > 0 then
                action = "Gear belum lengkap, unit belum kuat ke wing yang kurang. Farm " .. pickStrengthWing()
            else
                action = "Gear lengkap · farm " .. pickStrengthWing() .. " (wing tertinggi yang unit kuat)"
            end
        elseif hauntBestWing then
            action = "Best wing · " .. pickBestHauntWing() .. " (pumpkin/floor tertinggi yang terbuka)"
        else
            action = "Manual · " .. hauntWing
        end
        local progress = "Belum di tower"
        local A = G.AnimeDiceAutoTower
        local row
        if hauntDriveWanted or hauntDriveRunning then
            row = {
                tower = hauntDriveWing or hauntWing,
                floor = hauntDrivePhase == "run" and (hauntDriveStage + 1)
                    or (hauntDriveStage > 0 and hauntDriveStage or nil),
                inside = hauntDrivePhase == "run",
                equipping = hauntDrivePhase == "equip" or hauntDrivePhase == "wait" or hauntDrivePhase == "rematch",
            }
        elseif type(A) == "table" and type(A.progress) == "function" then
            local okRow, got = pcall(A.progress)
            if okRow and type(got) == "table" then
                row = got
            end
        end
        local liveTower = row and row.tower or hauntWing
        local stage = row and tonumber(row.floor)
        local wing = wingByName(liveTower)
        local span = 50
        if type(HauntedHouse) == "table" and tonumber(HauntedHouse.WING_FLOORS) then
            span = tonumber(HauntedHouse.WING_FLOORS)
        end
        if hauntDrivePhase == "rematch" or hauntDrivePhase == "wait" then
            progress = "Rematch " .. tostring(liveTower)
        elseif row and row.equipping and not row.inside then
            progress = "Equip unit · berikutnya " .. tostring(liveTower)
        elseif row and row.inside and stage then
            local absolute = stage
            if wing then
                absolute = (tonumber(wing.firstFloor) or 1) + stage - 1
            end
            local cap = (wing and wing.endless) and "" or ("/" .. tostring(span))
            progress = "Sekarang " .. tostring(liveTower)
                .. " · stage " .. tostring(stage) .. cap
                .. " · lantai " .. tostring(absolute)
        elseif row and row.inside then
            progress = "Sekarang " .. tostring(liveTower) .. " · stage belum kebaca"
        elseif liveTower then
            progress = "Antrian " .. tostring(liveTower) .. " · belum mulai"
        end
        progress = progress .. " · best " .. tostring(bestFloorNow())
        local power = shot > 0 and ("Unit one-shot sampai lantai " .. tostring(shot)) or "Unit belum kebaca"
        local gearLine = "Gear " .. tostring(owned) .. "/" .. tostring(total)
        if #missing > 0 then
            gearLine = gearLine .. " · kurang " .. table.concat(missing, ", ")
        else
            gearLine = gearLine .. " · lengkap"
        end
        if #blocked > 0 then
            gearLine = gearLine .. " · belum kuat: " .. table.concat(blocked, ", ")
        end
        return progress .. "\n" .. action .. "\n" .. power .. "\n" .. gearLine
    end

    function paintHauntInfo()
        if hauntInfoApi and type(hauntInfoApi.set) == "function" then
            pcall(hauntInfoApi.set, hauntInfoText())
        end
    end

    local hauntDriveLastWing = nil
    local hauntDriveRematch = false
    local hauntDriveLastEquipAt = 0
    local PLAY_DEBOUNCE = 5.05
    local EQUIP_WAIT = 1.1

    local function nextDriveWing(map)
        if hauntDriveRematch and type(hauntDriveLastWing) == "string" and map[hauntDriveLastWing] == true then
            return hauntDriveLastWing
        end
        local order = {}
        for i = 1, #HAUNT_WINGS do
            if map[HAUNT_WINGS[i]] == true then
                order[#order + 1] = HAUNT_WINGS[i]
            end
        end
        if #order == 0 then
            return hauntWing
        end
        for i = 1, #order do
            if order[i] == hauntDriveLastWing then
                return order[(i % #order) + 1]
            end
        end
        return order[1]
    end

    local function wingCleared(name, stage)
        local w = wingByName(name)
        if type(w) == "table" and w.endless then
            return false
        end
        local cap = 50
        if type(HauntedHouse) == "table" and tonumber(HauntedHouse.WING_FLOORS) then
            cap = tonumber(HauntedHouse.WING_FLOORS)
        end
        return (tonumber(stage) or 0) >= cap
    end

    -- Direct-drive: panggil remote tower sendiri, tanpa UI/playback TowerController.
    -- Server tetap kunci tiap stage (stage one-shot ±1,24 dtk); driver poll 0,04 dtk
    -- supaya stage berikutnya mulai tepat saat kunci server lepas.
    local function driveHaunt()
        if hauntDriveRunning then
            return
        end
        hauntDriveRunning = true
        task.spawn(function()
            local playFn = netFunction("Towers", "PlayTower")
            local completeFn = netFunction("Towers", "CompleteTowerFloor")
            local cancelFn = netFunction("Towers", "CancelTower")
            local equipSig = netSignal("Towers", "EquipBestTowerTeam")
            local setAutoSig = netSignal("Towers", "SetAutoTower")
            if type(playFn) ~= "function" or type(completeFn) ~= "function" then
                hauntDriveRunning = false
                return
            end
            -- Ambil alih: batalkan run TowerController yang masih jalan.
            local A = G.AnimeDiceAutoTower
            if type(A) == "table" and type(A.inside) == "function" then
                local okIn, inside = pcall(A.inside)
                if okIn and inside == true and type(cancelFn) == "function" then
                    pcall(cancelFn)
                    task.wait(0.6)
                end
            end
            local lastPlayAt = 0
            while hauntDriveWanted and type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true do
                while hauntDriveWanted and tradeBusy() do
                    hauntDrivePhase = "wait"
                    task.wait(0.5)
                end
                while hauntDriveWanted and makeUnitBusy() do
                    hauntDrivePhase = "wait"
                    paintStatus("wait make unit")
                    task.wait(0.5)
                end
                if not hauntDriveWanted then
                    break
                end
                local map, label = hauntSelection()
                local wing = nextDriveWing(map)
                hauntDriveWing = wing
                hauntDriveStage = 0
                paintStatus(label)
                local rematch = hauntDriveRematch == true and wing == hauntDriveLastWing
                hauntDriveRematch = false
                local needEquip = not rematch or (os.clock() - hauntDriveLastEquipAt) > 8
                if needEquip and equipSig then
                    hauntDrivePhase = "equip"
                    pcall(function()
                        equipSig:Fire()
                    end)
                    hauntDriveLastEquipAt = os.clock()
                    local equipUntil = os.clock() + EQUIP_WAIT
                    while hauntDriveWanted and os.clock() < equipUntil do
                        task.wait(0.05)
                    end
                end
                if not hauntDriveWanted then
                    break
                end
                if setAutoSig then
                    pcall(function()
                        setAutoSig:Fire(false)
                    end)
                end
                hauntDrivePhase = rematch and "rematch" or "run"
                local played = false
                while hauntDriveWanted and not played do
                    local remain = lastPlayAt > 0 and (PLAY_DEBOUNCE - (os.clock() - lastPlayAt)) or 0
                    if remain > 0 then
                        hauntDrivePhase = "wait"
                        task.wait(math.min(0.08, remain))
                    else
                        local okPlay, resPlay = pcall(playFn, wing)
                        if okPlay and resPlay == true then
                            played = true
                            lastPlayAt = os.clock()
                        else
                            hauntDrivePhase = "wait"
                            task.wait(0.12)
                        end
                    end
                end
                if not hauntDriveWanted then
                    break
                end
                if played then
                    hauntDriveLastWing = wing
                    hauntDrivePhase = "run"
                    local ended = false
                    while hauntDriveWanted and type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true do
                        local wcfg = wingByName(wing)
                        local first = wcfg and tonumber(wcfg.firstFloor) or 1
                        local nextAbs = first + hauntDriveStage
                        if not canClearAbsFloor(nextAbs) then
                            hauntDrivePhase = "rematch"
                            if type(cancelFn) == "function" then
                                pcall(cancelFn)
                            end
                            hauntDriveRematch = true
                            break
                        end
                        local okRes, res = pcall(completeFn)
                        if okRes and type(res) == "table" and #res > 0 then
                            for _, row in ipairs(res) do
                                if type(row) == "table" then
                                    local done = tonumber(row.floor)
                                    if row.action == "floorCompleted" and done then
                                        hauntDriveStage = math.max(hauntDriveStage, done)
                                    elseif row.action == "ended" then
                                        ended = true
                                    end
                                end
                            end
                            if ended then
                                -- Belum clear (Abyss endless / kalah di tengah) → rematch wing yang sama.
                                hauntDriveRematch = not wingCleared(wing, hauntDriveStage)
                                break
                            end
                        elseif okRes and type(res) == "string" then
                            hauntDriveRematch = not wingCleared(wing, hauntDriveStage)
                            break
                        else
                            task.wait(0.04)
                        end
                    end
                end
            end
            if type(cancelFn) == "function" then
                pcall(cancelFn)
            end
            hauntDrivePhase = ""
            hauntDriveWing = nil
            hauntDriveStage = 0
            hauntDriveRunning = false
        end)
    end

    local function setHauntExclusive(on)
        local A = G.AnimeDiceAutoTower
        if on then
            local direct = type(A) == "table" and type(A.hauntHold) == "function"
            if not direct then
                -- fast_tower lama: fallback loop controller seperti sebelumnya.
                if type(A) ~= "table" then
                    return
                end
                local map, label = hauntSelection()
                local keys = {}
                for name, picked in pairs(map) do
                    if picked == true then
                        keys[#keys + 1] = name
                    end
                end
                table.sort(keys)
                local sig = label .. "|" .. table.concat(keys, ",")
                if sig == hauntExclusiveSig then
                    return
                end
                hauntExclusiveSig = sig
                local F = G.AnimeDiceFastTower
                if type(F) == "table" and type(F.setEnabled) == "function" then
                    pcall(F.setEnabled, true)
                end
                if type(A.beginExclusive) == "function" then
                    pcall(A.beginExclusive, map)
                elseif type(A.setEnabled) == "function" then
                    pcall(A.setEnabled, true)
                end
                paintStatus(label)
                return
            end
            hauntDriveWanted = true
            pcall(A.hauntHold)
            local _, label = hauntSelection()
            paintStatus(label)
            driveHaunt()
        else
            hauntDriveWanted = false
            hauntExclusiveSig = ""
            if type(A) == "table" and type(A.endExclusive) == "function" then
                pcall(A.endExclusive)
            end
        end
    end

    local function tryHauntFarm()
        if not (type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true) then
