        local totOn = values["event.halloween.tot"] == true
        G.AnimeDiceHwTot.on = totOn
        totLoop.setEnabled(totOn)
        syncIslandLoop()

        paintStatus()
    end)
end
 end, required = true, feature = true },
    { key = "AutoClaim", name = "Auto Claim", factory = function() -- AUTO → gear tab: Auto Claim Daily + Offline money + Claim Code.
-- Sekali per sesi (JobId). Default on. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local GEAR_ICON = "rbxasset://textures/ui/Settings/MenuBarIcons/GameSettingsTab.png"

    local old = G.AnimeDiceAutoClaim
    if type(old) == "table" and type(old.stop) == "function" then
        pcall(old.stop)
    end

    local dailyOn = true
    local codeOn = true
    local offlineOn = true
    local headerApi
    local workLoop
    local dailySig
    local codeSig
    local offlineSig
    local codeBusy = false
    local codeCfg

    local function session()
        local job = tostring(game.JobId or "")
        local s = G.AnimeDiceClaimSession
        if type(s) ~= "table" or s.job ~= job then
            s = {
                job = job,
                dailyDone = false,
                codeDone = false,
                offlineDone = false,
                offlineWait = 0,
            }
            G.AnimeDiceClaimSession = s
        end
        return s
    end

    local function nets()
        pcall(function()
            local Net = require(RS.Packages.Network)
            if not dailySig then
                dailySig = Net.ClientComm.new(RS.Network, false, "DailyRewardService"):GetSignal("Claim")
            end
            if not codeSig then
                codeSig = Net.ClientComm.new(RS.Network, false, "CodesService"):GetSignal("RedeemCode")
            end
            if not offlineSig then
                offlineSig = Net.ClientComm.new(RS.Network, false, "OfflineEarningsService"):GetSignal("Claim")
            end
        end)
        return dailySig ~= nil or codeSig ~= nil or offlineSig ~= nil
    end

    local function readVal(v)
        for _ = 1, 4 do
            local t = type(v)
            if t == "function" or t == "userdata" then
                local ok, r = pcall(v)
                if not ok then
                    return nil
                end
                v = r
            elseif t == "table" then
                local ok, r = pcall(function()
                    return v()
                end)
                if not ok or r == nil or r == v then
                    break
                end
                v = r
            else
                break
            end
        end
        return v
    end

    local function isOn(v)
        v = readVal(v)
        return v == true or v == 1 or v == "true"
    end

    local function normCode(name)
        name = tostring(name or "")
        return (name:gsub("^%s+", ""):gsub("%s+$", "")):upper()
    end

    local function dailyReady()
        local data = Core.data()
        if not data then
            return false
        end
        local last = 0
        local cool = 86400
        pcall(function()
            last = tonumber(data.LastDailyRewardClaim()) or 0
        end)
        if last == 0 then
            pcall(function()
                last = tonumber(readVal(data.LastDailyRewardClaim)) or 0
            end)
        end
        pcall(function()
            cool = tonumber(require(RS.Framework.Features.Rewards.DailyRewardConfig).Cooldown) or 86400
        end)
        if last == 0 then
            return true
        end
        return (os.time() - last) >= cool
    end

    local function closeDailyMenu()
        pcall(function()
            local MenuController = require(RS.Framework.Features.UI.MenuController)
            local UI = require(RS.Framework.Features.UI.UIReferences)
            local menu = UI and UI.Menus and UI.Menus.DailyRewards
            if menu and MenuController.ActiveMenu() == menu then
                MenuController.CloseMenu()
            end
        end)
    end

    local function codeList()
        local out = {}
        local seen = {}
        pcall(function()
            if type(codeCfg) ~= "table" then
                codeCfg = require(RS.Framework.Features.Codes.CodesConfig)
            end
            if type(codeCfg) == "table" then
                for name in pairs(codeCfg) do
                    if type(name) == "string" and name ~= "" then
                        seen[name] = true
                        out[#out + 1] = name
                    end
                end
            end
        end)
        table.sort(out)
        return out
    end

    local function redeemedSnapshot()
        local map = {}
        local ready = false
        pcall(function()
            local data = Core.data()
            if not data or data.RedeemedCodes == nil then
                return
            end
            local node = data.RedeemedCodes
            local raw = readVal(node)
            if type(raw) ~= "table" then
                raw = {}
                pcall(function()
                    raw = node()
                end)
            end
            if type(raw) ~= "table" then
                return
            end
            ready = true
            for k, v in pairs(raw) do
                if isOn(v) then
                    map[normCode(k)] = true
                end
            end
        end)
        return map, ready
    end

    local function alreadyRedeemed(name)
        name = normCode(name)
        if name == "" then
            return false
        end
        local map, ready = redeemedSnapshot()
        if map[name] == true then
            return true
        end
        if not ready then
            return false
        end
        local on = false
        pcall(function()
            local row = Core.data().RedeemedCodes[name]
            on = isOn(row)
        end)
        return on
    end

    local function pendingOffline()
        local n = 0
        pcall(function()
            n = tonumber(Core.data().PendingOfflineEarnings()) or 0
        end)
        return n
    end

    local function offlineMenuOpen()
        local on = false
        pcall(function()
            local MenuController = require(RS.Framework.Features.UI.MenuController)
            local UI = require(RS.Framework.Features.UI.UIReferences)
            local menu = UI and UI.Menus and UI.Menus.OfflineRewards
            on = menu ~= nil and MenuController.ActiveMenu() == menu
        end)
        return on
    end

    local function fireOffline()
        local ok = false
        if offlineSig then
            ok = pcall(function()
                offlineSig:Fire()
            end) or ok
        end
        local re = Core.remote("OfflineEarningsService", "Claim")
        if re then
            ok = pcall(function()
                re:FireServer()
            end) or ok
        end
        return ok
    end

    local function anyOn()
        return dailyOn or codeOn or offlineOn
    end

    local function paintHeader()
        if not headerApi then
            return
        end
        local sess = session()
        local bits = {}
        if dailyOn then
            bits[#bits + 1] = sess.dailyDone and "Daily done" or "Daily"
        end
        if offlineOn then
            bits[#bits + 1] = sess.offlineDone and "Offline done" or "Offline"
        end
        if codeOn then
            bits[#bits + 1] = sess.codeDone and "Code done" or "Code"
        end
        if #bits == 0 then
            Core.paintHeader(headerApi, "Off", "muted", "off")
            return
        end
        local allDone = (not dailyOn or sess.dailyDone) and (not offlineOn or sess.offlineDone) and (not codeOn or sess.codeDone)
        Core.paintHeader(headerApi, allDone and "Done" or "On", allDone and "muted" or "success", table.concat(bits, " · "))
    end

    local function tryDaily()
        local sess = session()
        if not dailyOn or sess.dailyDone then
            return
        end
        if not nets() or not dailySig then
            return
        end
        if not dailyReady() then
            sess.dailyDone = true
            closeDailyMenu()
            paintHeader()
            return
        end
        pcall(function()
            dailySig:Fire()
        end)
        local re = Core.remote("DailyRewardService", "Claim")
        if re then
            pcall(function()
                re:FireServer()
            end)
        end
        paintHeader()
    end

    local function tryOffline()
        local sess = session()
        if not offlineOn or sess.offlineDone then
            return
        end
        if not nets() then
            return
        end
        local pending = pendingOffline()
        local menuOn = pending <= 0 and offlineMenuOpen()
        if pending <= 0 and not menuOn then
            if sess.offlineFired then
                sess.offlineDone = true
                paintHeader()
            end
            return
        end
        if fireOffline() then
            sess.offlineFired = true
            if pendingOffline() <= 0 then
                sess.offlineDone = true
            end
            paintHeader()
        end
    end

    local function tryCodes()
        local sess = session()
        if not codeOn or sess.codeDone or codeBusy then
            return
        end
        if not nets() or not codeSig then
            return
        end
        local map, ready = redeemedSnapshot()
        if not ready then
            return
        end
        local list = codeList()
        local pending = {}
        for i = 1, #list do
            local name = list[i]
            if type(name) == "string" and map[normCode(name)] ~= true and not alreadyRedeemed(name) then
                pending[#pending + 1] = name
            end
        end
        if #pending == 0 then
            sess.codeDone = true
            paintHeader()
            return
        end
        sess.codeDone = true
        codeBusy = true
        task.spawn(function()
            for i = 1, #pending do
                if not codeOn then
                    break
                end
                local name = pending[i]
                if not alreadyRedeemed(name) then
                    codeSig:Fire(name)
                    task.wait(0.6)
                end
            end
            codeBusy = false
            paintHeader()
        end)
        paintHeader()
    end

    local function stepOnce()
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                return
            end
        end
        if not Core.data() then
            return
        end
        tryDaily()
        tryOffline()
        tryCodes()
        paintHeader()
    end

    workLoop = Core.loop("auto_claim", {
        delay = 4,
        step = stepOnce,
    })
    workLoop.setEnabled(true)

    G.AnimeDiceAutoClaim = {
        stop = function()
            dailyOn = false
            codeOn = false
            offlineOn = false
            if workLoop then
                workLoop.setEnabled(false)
            end
        end,
    }

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "claim",
        subLabel = "",
        subIcon = GEAR_ICON,
        subOrder = 9,
        order = 1,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Claim",
                expanded = false,
                status = {
                    id = "auto.claim.status",
                    persist = false,
                    value = "On",
                    style = "success",
                    detail = "once per session",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            Core.bindToggle(ui, group, {
                id = "auto.claim.daily",
                label = "Auto Claim Daily",
                persist = true,
                initial = true,
                onChanged = function(on)
                    dailyOn = on == true
                    if dailyOn and workLoop then
                        workLoop.setEnabled(true)
                    end
                    paintHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.claim.offline",
                label = "Auto Claim Offline Money",
                persist = true,
                initial = true,
                onChanged = function(on)
                    offlineOn = on == true
                    if offlineOn and workLoop then
                        workLoop.setEnabled(true)
                    end
                    paintHeader()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.claim.code",
                label = "Claim Code",
                persist = true,
                initial = true,
                onChanged = function(on)
                    codeOn = on == true
                    if codeOn and workLoop then
                        workLoop.setEnabled(true)
                    end
                    paintHeader()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if values["auto.claim.daily"] == nil then
            dailyOn = true
        else
            dailyOn = values["auto.claim.daily"] == true
        end
        if values["auto.claim.code"] == nil then
            codeOn = true
        else
            codeOn = values["auto.claim.code"] == true
        end
        if values["auto.claim.offline"] == nil then
            offlineOn = true
        else
            offlineOn = values["auto.claim.offline"] == true
        end
        if workLoop then
            workLoop.setEnabled(anyOn())
        end
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "Perf", name = "Perf", factory = function() -- MISC → gear tab: Boost FPS (block loop visual game + pohon/plot orang) + Low VFX + debris.
-- Slot plot sendiri tidak dihapus. Roll / Fast Roll / Make Unit tetap jalan.
-- Jangan QualityLevel / setfpscap. Loop pelan. Default on. Section tertutup.

return function(Core)
    local G = Core.env()
    local GEAR_ICON = "rbxasset://textures/ui/Settings/MenuBarIcons/GameSettingsTab.png"

    local old = G.AnimeDicePerf
    if type(old) == "table" and type(old.stop) == "function" then
        pcall(old.stop)
    end

    local vfxOn = true
    local hideOn = true
    local debrisOn = true
    local boostOn = true
    local headerApi
    local workLoop
    local conns = {}
    local watching = false
    local lastSweepAt = 0
    local lastPe = 0
    local lastDebris = 0
    local lastHidden = 0
    local lastVfxAt = 0
    local lastBlockAt = 0
    local ownIdCache, ownIdAt = nil, 0
    local gamePerfSet = false
    local lightingDone = false
    local shadowsDone = false
    local loopsBlocked = false
    local blockedConns = {}
    local refreshOrig
    local joinQuietUntil = 0
    local hiddenPlots = setmetatable({}, { __mode = "k" })
    local ownMuted = false
    local charHidden = setmetatable({}, { __mode = "k" })

    local function maidAdd(conn)
        if not conn then
            return
        end
        conns[#conns + 1] = conn
        local bag = G.AnimeDicePerfMaid
        if type(bag) ~= "table" then
            bag = {}
            G.AnimeDicePerfMaid = bag
        end
        bag[#bag + 1] = conn
    end

    local function disconnectAll()
        for i = 1, #conns do
            pcall(function()
                conns[i]:Disconnect()
            end)
            conns[i] = nil
        end
        conns = {}
        watching = false
    end

    local function isFx(inst)
        local cls = inst and inst.ClassName
        return cls == "ParticleEmitter"
            or cls == "Beam"
            or cls == "Trail"
            or cls == "Fire"
            or cls == "Smoke"
            or cls == "Sparkles"
            or cls == "PointLight"
            or cls == "SpotLight"
            or cls == "SurfaceLight"
    end

    local function muteFx(inst)
        if not (inst and isFx(inst)) then
            return
        end
        pcall(function()
            inst.Enabled = false
            if inst.ClassName == "ParticleEmitter" then
                inst.Rate = 0
            end
        end)
    end

    local function muteTree(root)
        if not root then
            return 0
        end
        local n = 0
        if isFx(root) then
            muteFx(root)
            n = 1
        end
        local ok, list = pcall(function()
            return root:GetDescendants()
        end)
        if not ok or type(list) ~= "table" then
            return n
        end
        for i = 1, #list do
            local inst = list[i]
            if isFx(inst) then
                muteFx(inst)
                n = n + 1
            end
        end
        return n
    end

    local function claimedFolder()
        local plots = workspace:FindFirstChild("Plots")
        return plots and plots:FindFirstChild("Claimed")
    end

    local function ownPlotId()
        local id
        pcall(function()
            id = Core.plotId()
        end)
        if type(id) == "string" and id ~= "" then
            ownIdCache = id
            ownIdAt = os.clock()
            return id
        end
        if type(ownIdCache) == "string" and ownIdCache ~= "" then
            return ownIdCache
        end
        return nil
    end

    local function isOwnPlotDescendant(inst)
        if not inst then
            return false
        end
        local claimed = claimedFolder()
        local own = ownPlotId()
        local plot = own and claimed and claimed:FindFirstChild(own)
        if plot then
            local ok, yes = pcall(function()
                return inst == plot or inst:IsDescendantOf(plot)
            end)
            return ok and yes == true
        end
        if claimed then
            local ok, yes = pcall(function()
                return inst:IsDescendantOf(claimed)
            end)
            if ok and yes == true then
                return true
            end
        end
        return false
    end

    local function hidePlot(plot, on)
        if not plot then
            return
        end
        local ok, list = pcall(function()
            return plot:GetDescendants()
        end)
        if not ok or type(list) ~= "table" then
            return
        end
        local hide = on == true
        for i = 1, #list do
            local inst = list[i]
            if inst:IsA("BasePart") then
                pcall(function()
                    inst.LocalTransparencyModifier = hide and 1 or 0
                    inst.CastShadow = not hide
                    inst.CanQuery = not hide
                    inst.CanTouch = not hide
                end)
            elseif inst:IsA("Decal") or inst:IsA("Texture") then
                pcall(function()
                    inst.Transparency = hide and 1 or 0
                end)
            elseif inst:IsA("LayerCollector") then
                pcall(function()
                    inst.Enabled = not hide
                end)
            elseif hide and inst:IsA("Animator") then
                pcall(function()
                    local tracks = inst:GetPlayingAnimationTracks()
                    for t = 1, #tracks do
                        tracks[t]:Stop(0)
                    end
                end)
            end
            if hide then
                muteFx(inst)
            end
        end
        if hide then
            muteFx(plot)
        end
    end

    local function restoreOwnPlotVisual()
        local own = ownPlotId()
        local claimed = claimedFolder()
        local plot = own and claimed and claimed:FindFirstChild(own)
        if not plot then
            return
        end
        local slots = plot:FindFirstChild("Slots")
        if not slots then
            return
        end
        pcall(function()
            local pc = game:GetService("ReplicatedStorage").Framework.Features.Plot.PlotController
            local hidden = pc:FindFirstChild(own)
            if hidden then
                for _, ch in ipairs(hidden:GetChildren()) do
                    ch.Parent = slots
                end
            end
        end)
    end

    local function sweepHidePlots()
        restoreOwnPlotVisual()
        local claimed = claimedFolder()
        if not claimed then
            return 0
        end
        local own = ownPlotId()
        if type(own) ~= "string" or own == "" then
            return 0
        end
        local n = 0
        for _, plot in ipairs(claimed:GetChildren()) do
            if plot.Name ~= own then
                if hideOn then
                    if hiddenPlots[plot] ~= true then
                        hidePlot(plot, true)
                        hiddenPlots[plot] = true
                    end
                    n = n + 1
                elseif hiddenPlots[plot] then
                    hidePlot(plot, false)
                    hiddenPlots[plot] = nil
                end
            end
        end
        return n
    end

    local function eatRollJunk(inst)
        if not inst then
            return false
        end
        local name = inst.Name
        if name == "Ripple"
            or name == "Money"
            or name == "Cash"
            or name == "CutsceneBlackFade"
        then
            pcall(function()
                inst:Destroy()
            end)
            return true
        end
        if name == "RollItemShower" then
            pcall(function()
                inst:ClearAllChildren()
            end)
            return true
        end
        if name == "RollTemplate" then
            local par = inst.Parent
            local vis = true
            pcall(function()
                vis = inst.Visible
            end)
            if par and par.Name == "Frame" and vis == true then
                pcall(function()
                    inst:Destroy()
                end)
                return true
            end
        end
        return false
    end

    local function backpackGui()
        local plr = Core.player()
        local pg = plr and plr:FindFirstChild("PlayerGui")
        local root = pg and pg:FindFirstChild("Root")
        local menus = root and root:FindFirstChild("Menus")
        return menus and menus:FindFirstChild("Backpack")
    end

    local function gutBackpack()
        local bp = backpackGui()
        if not bp then
            return 0
        end
        local n = 0
        local ok, list = pcall(function()
            return bp:GetDescendants()
        end)
        if not ok or type(list) ~= "table" then
            return 0
        end
        for i = 1, #list do
            local inst = list[i]
            local cls = inst.ClassName
            if cls == "WorldModel" then
                local kids = inst:GetChildren()
                for k = 1, #kids do
                    pcall(function()
                        kids[k]:Destroy()
                    end)
                    n = n + 1
                end
            elseif cls == "ParticleEmitter" or cls == "Beam" or cls == "Trail" then
                pcall(function()
                    inst:Destroy()
                end)
                n = n + 1
            elseif cls == "ViewportFrame" then
                pcall(function()
                    inst:ClearAllChildren()
                    inst.Visible = false
                end)
                n = n + 1
            end
        end
        return n
    end

    local function eatGui3d(inst)
        if not (vfxOn or boostOn) or not inst then
            return
        end
        local cls = inst.ClassName
        if cls == "WorldModel" then
            task.defer(function()
                if not inst.Parent then
                    return
                end
                local kids = inst:GetChildren()
                for i = 1, #kids do
                    pcall(function()
                        kids[i]:Destroy()
                    end)
                end
            end)
            return
        end
        if cls == "ParticleEmitter" or cls == "Beam" or cls == "Trail" or cls == "Model" then
            local par = inst.Parent
            if par and (par:IsA("WorldModel") or par:IsA("ViewportFrame") or inst:FindFirstAncestorOfClass("ViewportFrame")) then
                task.defer(function()
                    if inst.Parent then
                        pcall(function()
                            inst:Destroy()
                        end)
                    end
                end)
            end
        end
    end

    local function sweepDebris()
        local n = 0
        local folder = workspace:FindFirstChild("Debris")
        if folder then
            local kids = folder:GetChildren()
            for i = 1, #kids do
                pcall(function()
                    kids[i]:Destroy()
                end)
                n = n + 1
            end
        end
        local kids = workspace:GetChildren()
        for i = 1, #kids do
            local inst = kids[i]
            if eatRollJunk(inst) then
                n = n + 1
            end
        end
        pcall(function()
            local UI = require(game:GetService("ReplicatedStorage").Framework.Features.UI.UIReferences)
            local frame = UI and UI.Root and UI.Root.Rolling and UI.Root.Rolling:FindFirstChild("Frame")
            if frame then
                for _, ch in ipairs(frame:GetChildren()) do
                    if eatRollJunk(ch) then
                        n = n + 1
                    end
                end
            end
            local root = UI and UI.Root
            if root then
                local shower = root:FindFirstChild("RollItemShower")
                if shower then
                    shower:ClearAllChildren()
                    n = n + 1
                end
            end
            local pg = Core.player() and Core.player():FindFirstChild("PlayerGui")
            if pg then
                for _, ch in ipairs(pg:GetChildren()) do
                    if eatRollJunk(ch) then
                        n = n + 1
                    end
                end
            end
        end)
        return n
    end

    local function sweepVfx()
        local n = 0
        local debris = workspace:FindFirstChild("Debris")
        if debris then
            n = n + muteTree(debris)
        end
        if vfxOn or boostOn then
            n = n + gutBackpack()
        end
        return n
    end

    local function isKeepWalk(inst)
        if not inst then
            return false
        end
        if inst:IsA("Terrain") or inst:IsA("SpawnLocation") then
            return true
        end
        local n = string.lower(tostring(inst.Name or ""))
        if n:find("floor", 1, true)
            or n:find("ground", 1, true)
            or n:find("spawn", 1, true)
            or n == "baseplate"
            or n:find("path", 1, true)
            or n:find("bridge", 1, true)
            or n:find("walk", 1, true)
            or n:find("stand", 1, true)
            or n:find("booth", 1, true)
            or n:find("npc", 1, true)
            or n:find("shop", 1, true)
            or n:find("chest", 1, true)
            or n:find("machine", 1, true)
            or n:find("vendor", 1, true)
            or n:find("limited", 1, true)
        then
            return true
        end
        return false
    end

    local function isFoliage(inst)
        if not inst then
            return false
        end
        local n = string.lower(tostring(inst.Name or ""))
        return n:find("tree", 1, true)
            or n:find("palm", 1, true)
            or n:find("wind", 1, true)
            or n:find("grass", 1, true)
            or n:find("bush", 1, true)
            or n:find("plant", 1, true)
            or n:find("flower", 1, true)
            or n:find("leaf", 1, true)
    end

    local function eatInst(inst)
        if not (inst and inst.Parent) then
            return false
        end
        if isOwnPlotDescendant(inst) then
            return false
        end
        if isKeepWalk(inst) then
            return false
        end
        pcall(function()
            inst:Destroy()
        end)
        return true
    end

    local function eatLighting()
        if lightingDone then
            return
        end
        lightingDone = true
        local Lighting = game:GetService("Lighting")
        pcall(function()
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 250
            Lighting.Brightness = 1
        end)
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            pcall(function()
                terrain.Decoration = false
                terrain.WaterWaveSize = 0
                terrain.WaterWaveSpeed = 0
                terrain.WaterReflectance = 0
            end)
        end
        for _, fx in ipairs(Lighting:GetChildren()) do
            local cls = fx.ClassName
            if cls == "BloomEffect"
                or cls == "BlurEffect"
                or cls == "SunRaysEffect"
                or cls == "DepthOfFieldEffect"
                or cls == "ColorCorrectionEffect"
                or cls == "Atmosphere"
                or cls == "Clouds"
            then
                pcall(function()
                    if fx:IsA("PostEffect") or fx:IsA("Atmosphere") or fx:IsA("Clouds") then
                        fx.Enabled = false
                    end
                end)
                if cls == "Clouds" then
                    eatInst(fx)
                end
            end
        end
    end

    local function eatShadows()
        shadowsDone = true
    end

    local function connSrc(c)
        local fn, src
        pcall(function()
            fn = c.Function
        end)
        if type(fn) == "function" then
            pcall(function()
                src = debug.info(fn, "s")
            end)
        end
        return type(src) == "string" and src or ""
    end

    local function shouldBlockSrc(src)
        return src:find("WindShake", 1, true)
            or src:find("WindLines", 1, true)
            or src:find("FusingController", 1, true)
            or src:find("UIGradientPlus", 1, true)
            or src:find("TooltipController", 1, true)
            or src:find("ProductDisplay", 1, true)
            or src:find("JackpotRoll", 1, true)
            or src:find("LightRay", 1, true)
            or src:find("Roll.Ray", 1, true)
            or src:find("Portal.Inner", 1, true)
            or src:find("Portal.Shine", 1, true)
            or src:find("Gear.Selection", 1, true)
            or src:find("RbxCharacterSounds", 1, true)
            or src:find("GearController", 1, true)
            or src:find("GradientController", 1, true)
            or src:find("RollController", 1, true)
            or src:find("UnitConfig", 1, true)
            or src:find("OnboardingController", 1, true)
            or src:find("ImpactFrameUtil", 1, true)
            or src:find("DamageUtil", 1, true)
            or src:find("ConfettiUtil", 1, true)
    end

    local function blockSignal(sig)
        if type(getconnections) ~= "function" then
            return
        end
        local ok, list = pcall(getconnections, sig)
        if not ok or type(list) ~= "table" then
            return
        end
        for _, c in pairs(list) do
            local fs
            pcall(function()
                fs = c.ForeignState
            end)
            if not fs and shouldBlockSrc(connSrc(c)) then
                local d = false
                pcall(function()
                    c:Disable()
                    d = true
                end)
                if d then
                    blockedConns[#blockedConns + 1] = c
                end
            end
        end
    end

    local function blockGameLoops()
        local rs = game:GetService("RunService")
        blockSignal(rs.Heartbeat)
        blockSignal(rs.RenderStepped)
        blockSignal(rs.Stepped)
        blockSignal(workspace.DescendantAdded)
        if loopsBlocked then
            return
        end
        loopsBlocked = true
        pcall(function()
            local plr = Core.player()
            if plr then
                plr:SetAttribute("WindDisabled", true)
            end
        end)
        pcall(function()
            local pc = require(game:GetService("ReplicatedStorage").Framework.Features.Plot.PlotController)
            if type(pc) == "table" and type(pc.refreshSlots) == "function" then
                if type(refreshOrig) ~= "function" then
                    refreshOrig = pc.refreshSlots
                end
                pc.refreshSlots = function()
                    restoreOwnPlotVisual()
                end
            end
        end)
    end

    local function unblockGameLoops()
        for i = 1, #blockedConns do
            pcall(function()
                blockedConns[i]:Enable()
            end)
            blockedConns[i] = nil
        end
        blockedConns = {}
        loopsBlocked = false
        pcall(function()
            local plr = Core.player()
            if plr then
                plr:SetAttribute("WindDisabled", false)
            end
        end)
        pcall(function()
            if type(refreshOrig) ~= "function" then
                return
            end
            local pc = require(game:GetService("ReplicatedStorage").Framework.Features.Plot.PlotController)
            if type(pc) == "table" then
                pc.refreshSlots = refreshOrig
            end
        end)
    end

    local function eatDecor()
        local n = 0
        local map = workspace:FindFirstChild("Map")
        if map then
            for _, child in ipairs(map:GetChildren()) do
                if isFoliage(child) then
                    if eatInst(child) then
                        n = n + 1
                    end
                end
            end
        end
        return n
    end

    local function eatOtherSlots()
        local claimed = claimedFolder()
        local own = ownPlotId()
        if not (claimed and own) then
            return 0
        end
        local n = 0
        for _, plot in ipairs(claimed:GetChildren()) do
            if plot.Name == own then
                if not ownMuted then
                    n = n + muteTree(plot)
                    ownMuted = true
                end
            elseif hiddenPlots[plot] ~= true then
                hidePlot(plot, true)
                hiddenPlots[plot] = true
                n = n + 1
            end
        end
        return n
    end

    local function eatOtherChars()
        local lp = Core.player()
        local mine = lp and lp.Character
        local n = 0
        local folder = workspace:FindFirstChild("Players")
        local list = folder and folder:GetChildren() or {}
        for i = 1, #list do
            local model = list[i]
            if model and model ~= mine and model:IsA("Model") then
                if charHidden[model] then
                    n = n + 1
                else
                    pcall(function()
                        for _, d in ipairs(model:GetDescendants()) do
                            if d:IsA("BasePart") then
                                d.LocalTransparencyModifier = 1
                                d.CastShadow = false
                                d.CanQuery = false
                                d.CanTouch = false
                            elseif d:IsA("Decal") or d:IsA("Texture") then
                                d.Transparency = 1
                            elseif d.ClassName == "ParticleEmitter"
                                or d.ClassName == "Beam"
                                or d.ClassName == "Trail"
                                or d.ClassName == "Fire"
                            then
                                d.Enabled = false
                            elseif d.Name == "Animate" and (d:IsA("LocalScript") or d:IsA("Script")) then
                                d.Disabled = true
                            end
                        end
                    end)
                    charHidden[model] = true
                    n = n + 1
                end
            end
        end
        return n
    end

    local function forceGamePerf()
        if gamePerfSet or not boostOn then
            return
        end
        pcall(function()
            local SC = require(game:GetService("ReplicatedStorage").Framework.Features.Settings.SettingsController)
            if type(SC) == "table" and type(SC.Set) == "function" then
                SC.Set("Performance", true)
                gamePerfSet = true
            end
        end)
    end

    local function runBoost()
        if not boostOn then
            return
        end
        eatLighting()
        eatShadows()
        eatDecor()
        forceGamePerf()
        if os.clock() < joinQuietUntil then
            return
        end
        eatOtherSlots()
        eatOtherChars()
    end

    local function paintHeader()
        if not headerApi then
            return
        end
        local bits = {}
        if vfxOn then
            bits[#bits + 1] = "VFX"
        end
        if hideOn then
            bits[#bits + 1] = "Plots"
        end
        if debrisOn then
            bits[#bits + 1] = "Debris"
        end
        if boostOn then
            bits[#bits + 1] = "Boost"
        end
        if #bits == 0 then
            Core.paintHeader(headerApi, "Off", "muted", "off")
            return
        end
        Core.paintHeader(
            headerApi,
            "On",
            "success",
            table.concat(bits, " · ") .. " · pe " .. tostring(lastPe)
        )
    end

    local function hookParticles()
        if G.AnimeDiceParticleHook == true or type(hookfunction) ~= "function" then
            return
        end
        pcall(function()
            local PU = require(game:GetService("ReplicatedStorage").Framework.Utils.ParticleUtil)
            if type(PU) ~= "table" or type(PU.Emit) ~= "function" then
                return
            end
            local original
            original = hookfunction(PU.Emit, function(...)
                if vfxOn == true then
                    return
                end
                local F = G.AnimeDiceFastRoll
                if type(F) == "table" and type(F.enabled) == "function" then
                    local ok, on = pcall(F.enabled)
                    if ok and on == true then
                        return
                    end
                end
                return original(...)
            end)
            G.AnimeDiceParticleHook = true
        end)
    end

    local function hookViewports()
        if G.AnimeDiceVpHook == true or type(hookfunction) ~= "function" then
            return
        end
        pcall(function()
            local EI = require(game:GetService("ReplicatedStorage").Framework.Features.Inventory.EntryIcon)
            if type(restorefunction) == "function" and type(EI) == "table" and type(EI.new) == "function" then
                restorefunction(EI.new)
            end
        end)
        local function skipHeavyViewport(vp)
            if not (vfxOn or boostOn) then
                local F = G.AnimeDiceFastRoll
                if not (type(F) == "table" and type(F.enabled) == "function" and F.enabled() == true) then
                    return false
                end
            end
            if typeof(vp) ~= "Instance" then
                return false
            end
            local okRoll, inRoll = pcall(function()
                local UI = require(game:GetService("ReplicatedStorage").Framework.Features.UI.UIReferences)
                local rolling = UI and UI.Root and UI.Root:FindFirstChild("Rolling")
                return rolling and vp:IsDescendantOf(rolling)
            end)
            if okRoll and inRoll then
                return true
            end
            local bp = backpackGui()
            if not bp then
                return false
            end
            local ok, yes = pcall(function()
                return vp:IsDescendantOf(bp)
            end)
            return ok and yes == true
        end
        pcall(function()
            local VU = require(game:GetService("ReplicatedStorage").Framework.Utils.ViewportUtil)
            if type(VU) ~= "table" or type(VU.ApplyModelToViewport) ~= "function" then
                return
            end
            if type(restorefunction) == "function" then
                pcall(restorefunction, VU.ApplyModelToViewport)
            end
            local original
            original = hookfunction(VU.ApplyModelToViewport, function(vp, model, opts)
                if skipHeavyViewport(vp) then
                    if typeof(model) == "Instance" then
                        pcall(function()
                            model:Destroy()
                        end)
                    end
                    return
                end
                return original(vp, model, opts)
            end)
        end)
        G.AnimeDiceVpHook = true
    end

    local function onDescendant(inst)
        if not inst then
            return
        end
        if (vfxOn or boostOn) and isFx(inst) then
            muteFx(inst)
        end
        if inst:IsA("BasePart") then
            if boostOn then
                pcall(function()
                    inst.CastShadow = false
                end)
            end
            if hideOn or boostOn then
                local claimed = claimedFolder()
                local own = ownPlotId()
                if claimed and own then
                    local plot = inst
                    while plot and plot.Parent ~= claimed do
                        plot = plot.Parent
                    end
                    if plot and plot.Parent == claimed and plot.Name ~= own then
                        pcall(function()
                            inst.LocalTransparencyModifier = 1
                            inst.CastShadow = false
                            inst.CanQuery = false
                            inst.CanTouch = false
                        end)
                    end
                end
            end
        end
        if debrisOn then
            local debris = workspace:FindFirstChild("Debris")
            if debris and inst.Parent == debris then
                pcall(function()
                    inst:Destroy()
                end)
            end
            eatRollJunk(inst)
        end
    end

    local function watchDebris(folder)
        if not folder then
            return
        end
        maidAdd(folder.ChildAdded:Connect(function(child)
            if debrisOn then
                pcall(function()
                    child:Destroy()
                end)
            elseif vfxOn then
                muteTree(child)
            end
        end))
    end

    local function watchClaimed(claimed)
        if not claimed then
            return
        end
        maidAdd(claimed.ChildAdded:Connect(function(plot)
            joinQuietUntil = math.max(joinQuietUntil, os.clock() + 2.5)
            if hideOn and plot and plot.Name ~= ownPlotId() then
                task.defer(function()
                    if hideOn and plot.Parent then
                        hidePlot(plot, true)
                    end
                end)
            end
        end))
    end

    local function startWatch()
        if watching then
            return
        end
        watching = true
        maidAdd(workspace.DescendantAdded:Connect(onDescendant))
        pcall(function()
            maidAdd(game:GetService("Players").PlayerAdded:Connect(function()
                joinQuietUntil = os.clock() + 2.5
            end))
        end)
        local charFolder = workspace:FindFirstChild("Players")
        if charFolder then
            maidAdd(charFolder.ChildAdded:Connect(function()
                if boostOn and os.clock() >= joinQuietUntil then
                    eatOtherChars()
                end
            end))
        end
        local plots = workspace:FindFirstChild("Plots")
        if plots then
            watchClaimed(plots:FindFirstChild("Claimed"))
            maidAdd(plots.ChildAdded:Connect(function(ch)
                if ch.Name == "Claimed" then
                    watchClaimed(ch)
                end
            end))
        end
        watchDebris(workspace:FindFirstChild("Debris"))
        local map = workspace:FindFirstChild("Map")
        if map then
            maidAdd(map.ChildAdded:Connect(function(sub)
                if boostOn and isFoliage(sub) then
                    eatInst(sub)
                end
            end))
        end
        maidAdd(workspace.ChildAdded:Connect(function(child)
            local name = child.Name
            if name == "Plots" then
                watchClaimed(child:FindFirstChild("Claimed"))
                maidAdd(child.ChildAdded:Connect(function(ch)
                    if ch.Name == "Claimed" then
                        watchClaimed(ch)
                    end
                end))
            elseif name == "Debris" then
                watchDebris(child)
            elseif debrisOn and eatRollJunk(child) then
                return
            elseif boostOn and name == "Map" then
                for _, sub in ipairs(child:GetChildren()) do
                    if isFoliage(sub) then
                        eatInst(sub)
                    end
                end
                maidAdd(child.ChildAdded:Connect(function(sub)
                    if boostOn and isFoliage(sub) then
                        eatInst(sub)
                    end
                end))
            end
        end))
        pcall(function()
            local UI = require(game:GetService("ReplicatedStorage").Framework.Features.UI.UIReferences)
            local frame = UI and UI.Root and UI.Root.Rolling and UI.Root.Rolling:FindFirstChild("Frame")
            if frame then
                maidAdd(frame.ChildAdded:Connect(function(ch)
                    if debrisOn then
                        eatRollJunk(ch)
                    end
                end))
            end
            local root = UI and UI.Root
            if root then
                maidAdd(root.ChildAdded:Connect(function(ch)
                    if debrisOn then
                        eatRollJunk(ch)
                    end
                end))
            end
        end)
        pcall(function()
            local pg = Core.player() and Core.player():FindFirstChild("PlayerGui")
            if pg then
                maidAdd(pg.ChildAdded:Connect(function(ch)
                    if debrisOn then
                        eatRollJunk(ch)
                    end
                end))
                local root = pg:FindFirstChild("Root")
                local menus = root and root:FindFirstChild("Menus")
                local bp = menus and menus:FindFirstChild("Backpack")
                if bp then
                    maidAdd(bp.DescendantAdded:Connect(eatGui3d))
                end
            end
        end)
    end

    local function stepOnce()
        if not (vfxOn or hideOn or debrisOn or boostOn) then
            return
        end
        startWatch()
        local now = os.clock()
        if now - lastSweepAt < 4 then
            return
        end
        lastSweepAt = now
        if boostOn and (lastBlockAt == 0 or now - lastBlockAt > 15) then
            lastBlockAt = now
            blockGameLoops()
        end
        if lastVfxAt == 0 and (vfxOn or boostOn) then
            lastVfxAt = now
            lastPe = sweepVfx()
        end
        if hideOn and os.clock() >= joinQuietUntil then
            lastHidden = sweepHidePlots()
        elseif hideOn then
            restoreOwnPlotVisual()
        else
            hiddenPlots = {}
        end
        if debrisOn then
            lastDebris = sweepDebris()
        end
        if boostOn then
            runBoost()
            restoreOwnPlotVisual()
        end
        paintHeader()
    end

    local function syncLoop()
        if workLoop then
            workLoop.setEnabled(vfxOn or hideOn or debrisOn or boostOn)
        end
        if vfxOn or hideOn or debrisOn or boostOn then
            startWatch()
            stepOnce()
        end
        if not boostOn then
            unblockGameLoops()
        end
        paintHeader()
    end

    hookParticles()
    hookViewports()

    workLoop = Core.loop("perf", {
        delay = 3,
        step = stepOnce,
    })
    workLoop.setEnabled(true)

    G.AnimeDicePerf = {
        vfx = function()
            return vfxOn == true
        end,
        boost = function()
            return boostOn == true
        end,
        purge = function()
            gutBackpack()
            eatOtherSlots()
            sweepDebris()
        end,
        stop = function()
            vfxOn = false
            hideOn = false
            debrisOn = false
            boostOn = false
            unblockGameLoops()
            disconnectAll()
            if workLoop then
                workLoop.setEnabled(false)
            end
        end,
    }

    Core.section({
        main = "misc",
        mainLabel = "MISC",
        mainOrder = 2,
        sub = "config",
        subLabel = "",
        subIcon = GEAR_ICON,
        subOrder = 9,
        order = 2,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Perf",
                expanded = false,
                status = {
                    id = "auto.perf.status",
                    persist = false,
                    value = "On",
                    style = "success",
                    detail = "boost fps",
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            Core.bindToggle(ui, group, {
                id = "auto.perf.boost",
                label = "Boost FPS",
                persist = true,
                initial = true,
                onChanged = function(on)
                    boostOn = on == true
                    if boostOn then
                        runBoost()
                    else
                        unblockGameLoops()
                    end
                    syncLoop()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.perf.vfx",
                label = "Low VFX",
                persist = true,
                initial = true,
                onChanged = function(on)
                    vfxOn = on == true
                    if vfxOn then
                        lastPe = sweepVfx()
                        lastVfxAt = os.clock()
                    end
                    syncLoop()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.perf.hidePlots",
                label = "Hide Other Plots",
                persist = true,
                initial = true,
                onChanged = function(on)
                    hideOn = on == true
                    sweepHidePlots()
                    syncLoop()
                end,
            })
            Core.bindToggle(ui, group, {
                id = "auto.perf.debris",
                label = "Clear Debris",
                persist = true,
                initial = true,
                onChanged = function(on)
                    debrisOn = on == true
                    if debrisOn then
                        lastDebris = sweepDebris()
                    end
                    syncLoop()
                end,
            })
            paintHeader()
        end,
    })

    Core.onSync(function(values)
        if values["auto.perf.boost"] == nil then
            boostOn = true
        else
            boostOn = values["auto.perf.boost"] == true
        end
        if values["auto.perf.vfx"] == nil then
            vfxOn = true
        else
            vfxOn = values["auto.perf.vfx"] == true
        end
        if values["auto.perf.hidePlots"] == nil then
            hideOn = true
        else
            hideOn = values["auto.perf.hidePlots"] == true
        end
        if values["auto.perf.debris"] == nil then
            debrisOn = true
        else
            debrisOn = values["auto.perf.debris"] == true
        end
        syncLoop()
    end)
end
 end, required = true, feature = true },
    { key = "AutoUnit", name = "Auto Make Unit", factory = function() -- AUTO → Units → Auto Make Unit (Level, Trait, Grade, Quirk).
-- Multi rule: tiap unit ikut 1 rule (nama + Earn / 1-in) dan keep grade/trait/quirk rule itu.
-- Unit aktif dulu. Jenis yang sudah kena filter (nganggur) langsung ke target berikutnya. Toggle default off.

return function(Core)
    local RS = game:GetService("ReplicatedStorage")
    local G = Core.env()
    local Earn = Core.unitEarn or G.AnimeDiceUnitEarn
    local Rules = Core.unitRules or G.AnimeDiceUnitRules
    if type(Earn) ~= "table" or type(Rules) ~= "table" then
        return
    end

    local gradeOn = false
    local traitOn = false
    local quirkOn = false
    local upgradeOn = false
    local targetEarn = Earn.parseCompact("200qd")
    local maxEarnLv1 = Earn.parseCompact("1sx")
    local pickMode = "earn"
    local oneIn = Earn.parseCompact("1qd")
    local oneInMax = 0
    local maxLevel = 60
    local DEFAULT_MAX_UNITS = 50
    local maxUnits = DEFAULT_MAX_UNITS
    local SORTS = {
        { key = "highest", name = "Highest 1-in" },
        { key = "lowest", name = "Lowest 1-in" },
    }
    local sortBy = "highest"
    local keepPercent = 80
    local gradeEventMode = false
    local traitEventMode = false
    local gradeEventPct = 100
    local traitEventPct = 100
    local liveWeatherName = nil
    local gradeMap = {}
    local traitMap = {}
    local quirkMap = {}
    local unitMap = {}
    local skipQuirkMap = {}
    local earnMaxDraft = 0
    local ruleList = {}
    local compiledRules = {}
    local rulesLoaded = false
    local lastConflicts = {}
    local editingId = nil
    local stickyId = nil
    local displacedId = nil
    local displacedSlot = nil
    local workSlot = nil
    local upgradeHeldId = nil
    local rotateBusy = false
    local lastStatus = { value = "Off", style = "muted", detail = "0 units" }
    local lastMatched = 0
    local lastKeepers = {}
    local lastWorkIds = {}
    local lastFinished = {}
    local headerApi
    local previewHead
    local previewEmpty
    local previewList
    local previewCards = {}

    local gradesMod, traitsMod, quirksMod
    pcall(function()
        gradesMod = require(RS.Framework.Features.Grades.Grades)
    end)
    pcall(function()
        traitsMod = require(RS.Framework.Features.Traits.Traits)
    end)
    pcall(function()
        quirksMod = require(RS.Framework.Features.Quirks.Quirks)
    end)

    local pendingRoll = {}
    local pendingLevel = {}
    local pendingLevelAt = {}
    local lastKindAt = {
        grade = 0,
        trait = 0,
        quirk = 0,
    }
    local lastUpgradeAt = 0
    local maybeRestore
    local pickVictim
    local ROLL_DELAY = 0.04
    local UPGRADE_DELAY = 0.12
    local Cache = {
        qAt = 0,
        q = nil,
        data = nil,
        onPlot = nil,
        slots = nil,
        pubAt = 0,
        pubKey = "",
    }
    local REPLICA_WAIT = 0.08
    local INTERACT_WAIT = 0.55
    local ROLL_KIND_FLAG = {
        grade = "AnimeDiceLastGradeRoll",
        trait = "AnimeDiceLastTraitRoll",
        quirk = "AnimeDiceLastQuirkRoll",
    }
    -- Penahan quirk terakhir karena uang (biar kelihatan di status, tidak diam).
    local quirkMoneyBlock = nil

    local function noteQuirkMoney(snap, price)
        quirkMoneyBlock = {
            at = os.clock(),
            name = snap and snap.name or nil,
            price = tonumber(price) or 0,
        }
    end

    local function quirkMoneyTag()
        if not quirkOn or type(quirkMoneyBlock) ~= "table" then
            return nil
        end
        if os.clock() - (tonumber(quirkMoneyBlock.at) or 0) > 3 then
            return nil
        end
        if quirkMoneyBlock.price <= 0 then
            return nil
        end
        return "quirk butuh " .. Core.compact(quirkMoneyBlock.price)
    end

    local function kindDebounce(kind)
        local now = os.clock()
        if now - (tonumber(lastKindAt[kind]) or 0) < ROLL_DELAY then
            return true
        end
        local flag = ROLL_KIND_FLAG[kind]
        if flag and now - (tonumber(G[flag]) or 0) < ROLL_DELAY then
            return true
        end
        return false
    end

    local function kindPending(id, kind, old)
        if type(id) ~= "string" or id == "" then
            return false
        end
        local bag = pendingRoll[id]
        local pend = type(bag) == "table" and bag[kind]
        if type(pend) ~= "table" then
            return false
        end
        if old ~= pend.old then
            bag[kind] = nil
            return false
        end
        if (os.clock() - (tonumber(pend.at) or 0)) < REPLICA_WAIT then
            return true
        end
        bag[kind] = nil
        return false
    end

    local function markKindPending(id, kind, old)
        if type(id) ~= "string" or id == "" then
            return
        end
        local bag = pendingRoll[id]
        if type(bag) ~= "table" then
            bag = {}
            pendingRoll[id] = bag
        end
        local now = os.clock()
        lastKindAt[kind] = now
        local flag = ROLL_KIND_FLAG[kind]
        if flag then
            G[flag] = now
        end
        bag[kind] = { old = old, at = now }
    end

    local State = {
        upgradeOn = false,
        blockEquipBest = false,
        rotating = false,
        view = nil,
        needMachine = nil,
        working = false,
    }
    G.AnimeDiceAutoUnit = State

    local function makeSession()
        local job = tostring(game.JobId or "")
        local s = G.AnimeDiceMakeUnitSession
        if type(s) ~= "table" or s.job ~= job then
            s = {
                job = job,
                t0 = os.clock(),
                gems = 0,
                traits = 0,
                money = 0,
                gradeN = 0,
                traitN = 0,
                quirkN = 0,
                upN = 0,
                done = {},
                doneIds = {},
                touched = {},
                stockSnap = false,
                startGems = 0,
                startTraits = 0,
            }
            G.AnimeDiceMakeUnitSession = s
        end
        s.gems = tonumber(s.gems) or 0
        s.traits = tonumber(s.traits) or 0
        s.money = tonumber(s.money) or 0
        s.gradeN = tonumber(s.gradeN) or 0
        s.traitN = tonumber(s.traitN) or 0
        s.quirkN = tonumber(s.quirkN) or 0
        s.upN = tonumber(s.upN) or 0
        s.startGems = tonumber(s.startGems) or 0
        s.startTraits = tonumber(s.startTraits) or 0
        s.stockSnap = s.stockSnap == true
        if type(s.done) ~= "table" then
            s.done = {}
        end
        if type(s.doneIds) ~= "table" then
            s.doneIds = {}
        end
        if type(s.touched) ~= "table" then
            s.touched = {}
        end
        return s
    end

    local function markSpent(kind, amount)
        local s = makeSession()
        if kind == "gems" then
            s.gems = s.gems + 1
            s.gradeN = s.gradeN + 1
        elseif kind == "traits" then
            s.traits = s.traits + 1
            s.traitN = s.traitN + 1
        elseif kind == "quirks" then
            s.money = s.money + (tonumber(amount) or 0)
            s.quirkN = s.quirkN + 1
        elseif kind == "money" then
            s.money = s.money + (tonumber(amount) or 0)
            s.upN = s.upN + 1
        end
    end

    local function touchUnit(id)
        if type(id) == "string" and id ~= "" then
            makeSession().touched[id] = true
        end
    end

    local function readVal(v)
        return Earn.readVal(v)
    end

    local function field(source, key)
        return Earn.field(source, key)
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            elseif type(v) == "table" then
                local key = v.key or v.id or v.name
                if key then
                    out[tostring(key)] = true
                end
            end
        end
        return out
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            return b
        end
        if type(a) == "table" then
            return a
        end
        if type(b) == "table" then
            return b
        end
        return b ~= nil and b or a
    end

    local function clampLevel(n)
        n = tonumber(n) or 0
        if n < 0 then
            n = 0
        elseif n > 9999 then
            n = 9999
        end
        return math.floor(n + 0.5)
    end

    local function clampMaxUnits(n)
        n = tonumber(n)
        if not n then
            n = DEFAULT_MAX_UNITS
        end
        n = math.floor(n + 0.5)
        if n < 1 then
            n = 1
        elseif n > 9999 then
            n = 9999
        end
        return n
    end

    local function clampSortBy(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "highest"))
        if mode == "lowest" or mode == "low" or mode == "min" then
            return "lowest"
        end
        return "highest"
    end

    local function clampPickMode(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "earn"))
        mode = mode:gsub("%s+", ""):gsub("_", ""):gsub("-", "")
        if mode == "onein" or mode == "1in" or mode == "in" or mode == "chance" then
            return "onein"
        end
        return "earn"
    end

    local function doneCount()
        return #lastFinished
    end

    local function inventoryItem(data, unitId)
        if type(unitId) ~= "string" or unitId == "" or type(data) ~= "table" then
            return nil
        end
        local getter = data.Inventory and data.Inventory[unitId]
        if getter == nil then
            return nil
        end
        local ok, item = pcall(getter)
        if not ok or type(item) ~= "table" then
            return nil
        end
        return item
    end

    local function tokenAmount(data, name)
        if type(data) ~= "table" or type(name) ~= "string" then
            return 0
        end
        local getter = data.Inventory and data.Inventory[name]
        if getter == nil then
            return 0
        end
        local ok, row = pcall(getter)
        if not ok or row == nil then
            return 0
        end
        if type(row) == "number" then
            return row
        end
        if type(row) == "table" then
            local a = row.amount
            if type(a) == "function" then
                local ok2, v = pcall(a)
                return ok2 and tonumber(v) or 0
            end
            return tonumber(a) or 0
        end
        return tonumber(row) or 0
    end

    pcall(function()
        local prop = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "WeatherService"):GetProperty("ActiveWeather")
        local function applyWeather(value)
            liveWeatherName = nil
            if type(value) == "table" then
                if type(value.name) == "string" and value.name ~= "" then
                    liveWeatherName = value.name
                end
            elseif type(value) == "string" and value ~= "" then
                liveWeatherName = value
            end
        end
        if prop.IsReady and prop:IsReady() then
            applyWeather(prop:Get())
        end
        if type(prop.Observe) == "function" then
            prop:Observe(applyWeather)
        end
    end)

    local function clampPct(n)
        n = tonumber(n) or 0
        if n < 0 then
            return 0
        end
        if n > 100 then
            return 100
        end
        return math.floor(n + 0.5)
    end

    local function weatherIs(name)
        if liveWeatherName == name then
            return true
        end
        local ok, hit = pcall(function()
            return workspace:FindFirstChild(name) ~= nil
        end)
        return ok and hit == true
    end

    local function eventFocus()
        if gradeOn and gradeEventMode and weatherIs("Grade Event") then
            return "grade"
        end
        if traitOn and traitEventMode and weatherIs("Trait Event") then
            return "trait"
        end
        return nil
    end

    local function invalidateStockSnap()
        local s = makeSession()
        s.stockSnap = false
        s.startGems = 0
        s.startTraits = 0
    end

    local function ensureStockSnap(data)
        local s = makeSession()
        if type(data) ~= "table" then
            data = Core.data()
        end
        if type(data) ~= "table" then
            return s
        end
        local gems = tokenAmount(data, "Gems")
        local traits = tokenAmount(data, "Trait Reroll")
        if not s.stockSnap then
            s.startGems = gems
            s.startTraits = traits
            s.stockSnap = true
            return s
        end
        if gems > (tonumber(s.startGems) or 0) then
            s.startGems = gems
        end
        if traits > (tonumber(s.startTraits) or 0) then
            s.startTraits = traits
        end
        local gUse = math.max(0, (tonumber(s.startGems) or 0) - gems)
        local tUse = math.max(0, (tonumber(s.startTraits) or 0) - traits)
        s.gems = gUse
        s.traits = tUse
        s.gradeN = gUse
        s.traitN = tUse
        return s
    end

    local function eventActive(kind)
        if kind == "gems" then
            return weatherIs("Grade Event")
        end
        return weatherIs("Trait Event")
    end

    local function tokenFloor(kind, data)
        local eventMode = kind == "gems" and gradeEventMode or traitEventMode
        if eventMode ~= true then
            return 0
        end
        if eventActive(kind) then
            return 0
        end
        local pct = clampPct(kind == "gems" and gradeEventPct or traitEventPct)
        local amount = kind == "gems" and tokenAmount(data, "Gems") or tokenAmount(data, "Trait Reroll")
        if pct >= 100 then
            return amount
        end
        local s = ensureStockSnap(data)
        local start = kind == "gems" and s.startGems or s.startTraits
        return math.floor((tonumber(start) or 0) * pct / 100)
    end

    local function moneyNow(data)
        local n = 0
        pcall(function()
            n = tonumber(data.Money()) or 0
        end)
        return n
    end

    local function isProtected(data, kind, name)
        if type(name) ~= "string" or name == "" then
            return false
        end
        local bag = kind == "grade" and data.ProtectedGrades
            or kind == "quirk" and data.ProtectedQuirks
            or data.ProtectedTraits
        if type(bag) ~= "table" then
            return false
        end
        local getter = bag[name]
        if getter == nil then
            return false
        end
        local ok, v = pcall(getter)
        return ok and v == true
    end

    local function liveLevel(unitId, dataLevel)
        dataLevel = tonumber(dataLevel) or 1
        local pred = pendingLevel[unitId]
        if not pred then
            return dataLevel
        end
        if dataLevel >= pred or (os.clock() - (pendingLevelAt[unitId] or 0)) > 1.5 then
            pendingLevel[unitId] = nil
            pendingLevelAt[unitId] = nil
            return dataLevel
        end
        if dataLevel > pred then
            return dataLevel
        end
        return pred
    end

    local function slotUnitId(data, slot)
        local getter = data.Slots and data.Slots[tostring(slot)]
        if getter == nil then
            return nil
        end
        local ok, row = pcall(getter)
        if not ok or type(row) ~= "table" then
            return nil
        end
        local id = field(row, "unitId")
        if type(id) == "string" and id ~= "" then
            return id
        end
        return nil
    end

    local function plotIndex(data)
        local onPlot = {}
        local slots = Core.slots()
        if type(data) ~= "table" then
            return onPlot, slots
        end
        for _, slot in ipairs(slots) do
            local id = slotUnitId(data, slot)
            if id then
                onPlot[id] = slot
            end
        end
        return onPlot, slots
    end

    local function mulTag(info)
        local inc = tonumber(info.incomeMultiplier)
        local dmg = tonumber(info.damageMultiplier)
        local hp = tonumber(info.healthMultiplier)
        local n = 0
        if inc then
            n = n + 1
        end
        if dmg then
            n = n + 1
        end
        if hp then
            n = n + 1
        end
        if n == 0 then
            return nil
        end
        if n >= 2 and inc and dmg and hp and inc == dmg and dmg == hp then
            return tostring(inc) .. "x"
        end
        if n == 1 and inc then
            return tostring(inc) .. "x"
        end
        local bits = {}
        if inc then
            bits[#bits + 1] = tostring(inc) .. "x $"
        end
        if dmg then
            bits[#bits + 1] = tostring(dmg) .. "x dmg"
        end
        if hp then
            bits[#bits + 1] = tostring(hp) .. "x HP"
        end
        return table.concat(bits, " ")
    end

    local function gradeItems()
        local out = {}
        if type(gradesMod) ~= "table" then
            return out
        end
        for key, info in pairs(gradesMod) do
            local tag = type(key) == "string" and type(info) == "table" and tonumber(info.incomeMultiplier) and (tostring(info.incomeMultiplier) .. "x")
            if tag then
                out[#out + 1] = {
                    key = key,
                    label = key .. "  " .. tag,
                    order = -(tonumber(info.order) or 0),
                }
            end
        end
        table.sort(out, function(a, b)
            return a.order < b.order
        end)
        return out
    end

    local function traitItems()
        local out = {}
        if type(traitsMod) ~= "table" then
            return out
        end
        for key, info in pairs(traitsMod) do
            local tag = type(key) == "string" and type(info) == "table" and mulTag(info)
            if tag then
                out[#out + 1] = {
                    key = key,
                    label = key .. "  " .. tag,
                    order = -(tonumber(info.order) or 0),
                }
            end
        end
        table.sort(out, function(a, b)
            return a.order < b.order
        end)
        return out
    end

    local function quirkTag(info)
        if type(info) ~= "table" or type(info.buffs) ~= "table" then
            return nil
        end
        local bits = {}
        for name, buff in pairs(info.buffs) do
            local amt = type(buff) == "table" and tonumber(buff.amount)
            if amt then
                local pct = amt * 100
                local label
                if name == "Luck" then
                    label = string.format("%g%% luck", pct)
                elseif name == "Money Multiplier" then
                    label = string.format("%g%% $", pct)
                elseif name == "Trait Luck" then
                    label = string.format("%g%% trait", pct)
                elseif name == "Grade Luck" then
                    label = string.format("%g%% grade", pct)
                elseif name == "Roll Duration" then
                    label = string.format("%g%% time", pct)
                else
                    label = string.format("%g%% %s", pct, tostring(name))
                end
                bits[#bits + 1] = label
            end
        end
        if #bits == 0 then
            return nil
        end
        table.sort(bits)
        return table.concat(bits, " ")
    end

    local function quirkItems()
        local out = {}
        if type(quirksMod) ~= "table" then
            return out
        end
        for key, info in pairs(quirksMod) do
            local tag = type(key) == "string" and type(info) == "table" and quirkTag(info)
            if tag then
                out[#out + 1] = {
                    key = key,
                    label = key .. "  " .. tag,
                    order = -(tonumber(info.order) or 0),
                }
            end
        end
        table.sort(out, function(a, b)
            return a.order < b.order
        end)
        return out
    end

    local unitItemCache, unitItemAt = nil, 0
    local function unitItems()
        if unitItemCache and os.clock() - unitItemAt < 5 then
            return unitItemCache
        end
        local out = {}
        local okInv, inv = pcall(function()
            return Core.data().Inventory()
        end)
        if not okInv or type(inv) ~= "table" then
            return out
        end
        for id, item in pairs(inv) do
            if type(id) == "string" and type(item) == "table" then
                local cfg = Earn.entryConfig(Earn.name(Earn.field(item, "name") or item.name))
                if type(cfg) == "table" and cfg.kind == "Unit" then
                    local attrs = Earn.attrs(item)
                    local earn = tonumber(Earn.income(cfg, attrs)) or 0
                    local unitName = Earn.name(Earn.field(item, "name") or item.name)
                    local chance = tonumber(Earn.chance(cfg, attrs, unitName)) or 0
                    out[#out + 1] = {
                        key = id,
                        label = string.format(
                            "1-in %s · %s/s · %s",
                            Core.compact(chance),
                            Core.compact(earn),
                            attrs.quirk or "no quirk"
                        ),
                        chance = chance,
                        name = unitName,
                    }
                end
            end
        end
        table.sort(out, function(a, b)
            if a.chance ~= b.chance then
                return a.chance > b.chance
            end
            return a.key < b.key
        end)
        unitItemCache, unitItemAt = out, os.clock()
        return out
    end

    local function compileRules()
        compiledRules = Rules.compileAll(ruleList, {
            Earn = Earn,
            gradesMod = gradesMod,
            traitsMod = traitsMod,
