    local function gameAutoRoll(kind)
        local ok, on = pcall(function()
            local UI = require(RS.Framework.Features.UI.UIReferences)
            local menu = kind == "grade" and UI.Menus.Grades or kind == "quirk" and UI.Menus.Quirks or UI.Menus.Traits
            if not menu then
                return false
            end
            local confirm = kind == "grade" and menu:FindFirstChild("ConfirmGrade")
                or kind == "quirk" and menu:FindFirstChild("ConfirmQuirk")
                or menu:FindFirstChild("ConfirmTrait")
            if confirm and confirm.Visible == true then
                return true
            end
            local btn = menu.Buttons and menu.Buttons.AutoRoll
            if not btn then
                return false
            end
            local grad = btn:FindFirstChildWhichIsA("UIGradient", true)
            if not grad or typeof(grad.Color) ~= "ColorSequence" then
                return false
            end
            local kp = grad.Color.Keypoints[1]
            if not kp then
                return false
            end
            local c = kp.Value
            return c.G > 0.7 and c.R < 0.55
        end)
        return ok and on == true
    end

