    -- Jangan local function baru di chunk Core: batas register Luau 200.
    function State.rollZoneName(kind)
        if kind == "grade" then
            return "Grades"
        end
        if kind == "quirk" then
            return "Quirks"
        end
        return "Traits"
    end

    function State.inNamedZone(name)
        local LP = Core.player()
        local zones = workspace:FindFirstChild("Zones")
        local z = zones and zones:FindFirstChild(name)
        local char = LP and LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not (z and z:IsA("BasePart") and hrp) then
            return false
        end
        local rel = z.CFrame:PointToObjectSpace(hrp.Position)
        local s = z.Size
        return math.abs(rel.X) <= s.X * 0.5
            and math.abs(rel.Y) <= s.Y * 0.5
            and math.abs(rel.Z) <= s.Z * 0.5
    end

    function State.halloweenFarmOn()
        return (type(G.AnimeDiceHwTot) == "table" and G.AnimeDiceHwTot.on == true)
            or (type(G.AnimeDiceHwHaunt) == "table" and G.AnimeDiceHwHaunt.on == true)
    end

    -- Pad hub wajib AntiCheat. Jangan PivotTo dari Halloween island — itu yang bikin crash.
    -- Pulang dulu lewat HalloweenService.Teleport("Hub"), baru ke pad.
    function State.goToRollZone(kind)
        local name = State.rollZoneName(kind)
        State.needMachine = name
        State.working = true
        if State.inNamedZone(name) then
            pcall(function()
                require(RS.Framework.Features.UI.MenuController).CloseMenu()
            end)
            return true
        end
        local LP = Core.player()
        local char = LP and LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local onIsland = false
        if hrp then
            local folder = workspace:FindFirstChild("Halloween")
            local back = folder and folder:FindFirstChild("ReturnPoint")
            local nearHub = back and back:IsA("BasePart") and (hrp.Position - back.Position).Magnitude < 90
            if not nearHub then
                local hwZones = workspace:FindFirstChild("Zones")
                local hwZone = hwZones and hwZones:FindFirstChild("HalloweenWorld")
                if hwZone and hwZone:IsA("BasePart") then
                    local rel = hwZone.CFrame:PointToObjectSpace(hrp.Position)
                    local s = hwZone.Size
                    if math.abs(rel.X) <= s.X * 0.5 + 20
                        and math.abs(rel.Y) <= s.Y * 0.5 + 40
                        and math.abs(rel.Z) <= s.Z * 0.5 + 20 then
                        onIsland = true
                    end
                end
                if not onIsland then
                    local arr = folder and folder:FindFirstChild("ArrivalPoint")
                    if arr and arr:IsA("BasePart") and (hrp.Position - arr.Position).Magnitude < 120 then
                        onIsland = true
                    end
                end
            end
        end
        if onIsland then
            if os.clock() - (tonumber(State._hwLeaveAt) or 0) >= 1.2 then
                State._hwLeaveAt = os.clock()
                pcall(function()
                    local Net = require(RS.Packages.Network)
                    local fn = Net.ClientComm.new(RS.Network, false, "HalloweenService"):GetFunction("Teleport")
                    if type(fn) == "function" then
                        fn("Hub")
                    end
                end)
            end
            return false
        end
        local A = G.AnimeDiceAutoTower
        if type(A) == "table" and type(A.inside) == "function" then
            local okIn, inside = pcall(A.inside)
            if okIn and inside == true then
                return false
            end
        end
        if os.clock() - (tonumber(State._zoneGoAt) or 0) < 1.1 then
            return State.inNamedZone(name)
        end
        State._zoneGoAt = os.clock()
        local zones = workspace:FindFirstChild("Zones")
        local z = zones and zones:FindFirstChild(name)
        if not (z and z:IsA("BasePart")) then
            return false
        end
        local stand = z.Position + Vector3.new(0, 3, 0)
        pcall(function()
            LP:RequestStreamAroundAsync(stand, 6)
        end)
        if not (char and char.Parent) then
            return false
        end
        local ok = pcall(function()
            char:PivotTo(CFrame.new(stand))
        end)
        if not ok then
            return false
        end
        task.wait(0.12)
        if not State.inNamedZone(name) then
            return false
        end
        pcall(function()
            require(RS.Framework.Features.UI.MenuController).CloseMenu()
        end)
        return true
    end

    local function quirkSignal()
        local Net = require(RS.Packages.Network)
        return Net.ClientComm.new(RS.Network, false, "QuirkService"):GetSignal("Roll")
    end

    local function waitUntil(pred, timeout)
        local untilAt = os.clock() + (tonumber(timeout) or 1.2)
        while os.clock() < untilAt do
            if pred() then
                return true
            end
            task.wait(0.08)
        end
        return pred()
    end

    local function clearHand()
        if not holdingId() then
            return
        end
        local ok, _, unequipFn = pcall(plotNet)
        if ok and unequipFn then
            pcall(unequipFn)
            task.wait(INTERACT_WAIT)
        end
    end

    local function paint(value, style, detail)
        lastStatus.value = value
        lastStatus.style = style
        lastStatus.detail = detail
        Core.paintHeader(headerApi, value, style, detail)
    end

    local function setUpgradeFlag(on)
        State.upgradeOn = on == true
        if not on then
            State.blockEquipBest = false
            State.rotating = false
            rotateBusy = false
            displacedId = nil
            displacedSlot = nil
            workSlot = nil
            upgradeHeldId = nil
            pcall(clearHand)
        end
    end

    -- List = yang BENAR-benar akan diproses. Toggle off = tidak tampil.
    -- Guard: grade/trait yang sudah >= min pilihan tidak di-roll (jangan turun).
    -- Finish = sudah sesuai pilihan, BUKAN karena toggle dimatikan.
    local function powerOf(mod, name, kind)
        name = Earn.name(name)
        if type(name) ~= "string" or type(mod) ~= "table" then
            return 0
        end
        local info = mod[name]
        if kind == "trait" then
            return Earn.strength(info) or 0
        end
        if kind == "quirk" then
            return (type(info) == "table" and tonumber(info.order)) or 0
        end
        return (type(info) == "table" and tonumber(info.incomeMultiplier)) or 0
    end

    local function isModuleBest(mod, name, kind)
        local have = powerOf(mod, name, kind)
        if have <= 0 then
            return false
        end
        for key, info in pairs(mod) do
            if type(key) == "string" and type(info) == "table" then
                local other
                if kind == "trait" then
                    other = Earn.strength(info) or 0
                elseif kind == "quirk" then
                    other = tonumber(info.order) or 0
                else
                    other = tonumber(info.incomeMultiplier) or 0
                end
                if other > have + 1e-12 then
                    return false
                end
            end
        end
        return true
    end

    -- Sudah bener = jangan roll. Nama di dropdown, >= min 3 teratas, atau yang paling tinggi di game.
    local function keepGrade(name, snap)
        name = Earn.name(name)
        if type(name) ~= "string" then
            return false
        end
        if ruleKeep(snap, "grades")[name] == true then
            return true
        end
        if snap and Earn.inSet(snap.g3, name) then
            return true
        end
        if snap and Earn.atLeast(gradesMod, name, snap.gmin, "grade") then
            return true
        end
        if isModuleBest(gradesMod, name, "grade") then
            return true
        end
        local have = powerOf(gradesMod, name, "grade")
        local need = snap and snap.gmin and (tonumber(snap.gmin.mul) or tonumber(snap.gmin.income) or 0) or 0
        return have > 0 and need > 0 and have + 1e-12 >= need
    end

    local function keepTrait(name, snap)
        name = Earn.name(name)
        if type(name) ~= "string" then
            return false
        end
        if ruleKeep(snap, "traits")[name] == true then
            return true
        end
        if snap and Earn.inSet(snap.t3, name) then
            return true
        end
        if snap and Earn.atLeast(traitsMod, name, snap.tmin, "trait") then
            return true
        end
        if isModuleBest(traitsMod, name, "trait") then
            return true
        end
        local have = powerOf(traitsMod, name, "trait")
        local need = snap and snap.tmin and (tonumber(snap.tmin.mul) or 0) or 0
        return have > 0 and need > 0 and have + 1e-12 >= need
    end

    -- Quirk: hanya nama yang dipilih di rule. Jangan keep "order lebih tinggi"
    -- (Fortune's Favor 19 > Midas 18) — beda efek, bukan upgrade dari target.
    local function keepQuirk(name, snap)
        name = Earn.name(name)
        if type(name) ~= "string" then
            return false
        end
        if ruleKeep(snap, "quirks")[name] == true then
            return true
        end
        if snap and Earn.inSet(snap.q3, name) then
            return true
        end
        return false
    end

    local function gradeReady(snap)
        if not snap or not snap.gmin then
            return true
        end
        return keepGrade(snap.grade, snap)
    end

    local function traitReady(snap)
        if not snap or not snap.tmin then
            return true
        end
        return keepTrait(snap.trait, snap)
    end

    local function quirkReady(snap)
        if not snap or not snap.qmin then
            return true
        end
        return keepQuirk(snap.quirk, snap)
    end

    local function upgradeReady(snap)
        if not snap then
            return true
        end
        local cap = ruleLevel(snap)
        if cap <= 0 then
            return true
        end
        return (tonumber(snap.level) or 1) >= cap
    end

    local function isFinished(snap)
        return gradeReady(snap) and traitReady(snap) and quirkReady(snap) and upgradeReady(snap)
    end

    local function gradeNeeds(snap)
        return gradeOn and not gradeReady(snap)
    end

    local function traitNeeds(snap)
        return traitOn and not traitReady(snap)
    end

    local function quirkNeeds(snap)
        return quirkOn and not quirkReady(snap)
    end

    local function upgradeNeeds(snap)
        return upgradeOn and not upgradeReady(snap)
    end

    local function stillOpen(snap)
        return not isFinished(snap)
    end

    local function capTotal()
        local n = 0
        for _, rule in ipairs(compiledRules) do
            n = n + (tonumber(rule.maxUnits) or 0)
        end
        return n
    end

    local function capList(open, room)
        if room <= 0 then
            return {}
        end
        local s = makeSession()
        if #open <= room then
            return open
        end
        local keep = {}
        local seen = {}
        local function take(snap)
            if not snap or seen[snap.id] or #keep >= room then
                return
            end
            seen[snap.id] = true
            keep[#keep + 1] = snap
        end
        if type(stickyId) == "string" and stickyId ~= "" then
            for _, snap in ipairs(open) do
                if snap.id == stickyId then
                    take(snap)
                    break
                end
            end
        end
        for _, snap in ipairs(open) do
            if s.touched[snap.id] then
                take(snap)
            end
        end
        for _, snap in ipairs(open) do
            take(snap)
        end
        return keep
    end

    local function applyUnitCap(queue)
        queue = type(queue) == "table" and queue or {}
        local doneBy = {}
        for _, snap in ipairs(lastFinished) do
            local rid = snap.rule and tostring(snap.rule.id) or ""
            doneBy[rid] = (doneBy[rid] or 0) + 1
        end
        local groups, order = {}, {}
        for _, snap in ipairs(queue) do
            if snap and type(snap.id) == "string" and stillOpen(snap) then
                local rid = snap.rule and tostring(snap.rule.id) or ""
                if not groups[rid] then
                    groups[rid] = {}
                    order[#order + 1] = rid
                end
                table.insert(groups[rid], snap)
            end
        end
        local keepSet = {}
        for _, rid in ipairs(order) do
            local list = groups[rid]
            local rule = list[1].rule
            local cap = tonumber(rule and rule.maxUnits) or maxUnits
            for _, snap in ipairs(capList(list, math.max(0, cap - (doneBy[rid] or 0)))) do
                keepSet[snap.id] = true
            end
        end
        local out = {}
        for _, snap in ipairs(queue) do
            if snap and keepSet[snap.id] then
                keepSet[snap.id] = nil
                out[#out + 1] = snap
            end
        end
        return out
    end

    local function hasProgress(snap)
        if not snap then
            return false
        end
        local level = tonumber(snap.level) or 1
        if level > 1 then
            return true
        end
        if type(snap.grade) == "string" and snap.grade ~= "" then
            return true
        end
        if type(snap.trait) == "string" and snap.trait ~= "" then
            return true
        end
        if type(snap.quirk) == "string" and snap.quirk ~= "" then
            return true
        end
        return false
    end

    local function sortQueue(queue)
        local high = sortBy ~= "lowest"
        table.sort(queue, function(a, b)
            local ap = hasProgress(a)
            local bp = hasProgress(b)
            if ap ~= bp then
                return ap
            end
            local ac = tonumber(a.chance) or -1
            local bc = tonumber(b.chance) or -1
            if ac ~= bc then
                if high then
                    return ac > bc
                end
                return ac < bc
            end
            return tostring(a.id or "") < tostring(b.id or "")
        end)
        return queue
    end

    local function listByChance(queue)
        local out = {}
        if type(queue) ~= "table" then
            return out
        end
        for i, snap in ipairs(queue) do
            out[i] = snap
        end
        table.sort(out, function(a, b)
            local ac = tonumber(a and a.chance) or -1
            local bc = tonumber(b and b.chance) or -1
            if ac ~= bc then
                return ac > bc
            end
            return tostring(a and a.id or "") < tostring(b and b.id or "")
        end)
        return out
    end

    local function needsWork(snap)
        return gradeNeeds(snap) or traitNeeds(snap) or quirkNeeds(snap) or upgradeNeeds(snap)
    end

    local function plannedStep(snap)
        if not snap then
            return "none"
        end
        if snap.gmin and not gradeReady(snap) then
            return "grade"
        end
        if snap.tmin and not traitReady(snap) then
            return "trait"
        end
        if snap.qmin and not quirkReady(snap) then
            return "quirk"
        end
        if not upgradeReady(snap) then
            return "upgrade"
        end
        return "done"
    end

    local function unitUtil()
        local ok, util = pcall(function()
            return require(RS.Framework.Features.Inventory.Kinds.Unit.UnitUtil)
        end)
        if ok and type(util) == "table" then
            return util
        end
        return nil
    end

    local function levelPrice(name, attrs)
        local util = unitUtil()
        if not util or type(util.GetLevelPrice) ~= "function" then
            return nil
        end
        local ok, price = pcall(util.GetLevelPrice, name, attrs)
        return ok and tonumber(price) or nil
    end

    local function quirkPrice(snap)
        if not snap or type(snap.id) ~= "string" then
            return nil
        end
        local item = inventoryItem(Core.data(), snap.id)
        if type(item) ~= "table" then
            return nil
        end
        local ok, util = pcall(function()
            return require(RS.Framework.Features.Quirks.QuirkUtil)
        end)
        if not ok or type(util) ~= "table" or type(util.GetRollCost) ~= "function" then
            return nil
        end
        local name = snap.name or Earn.field(item, "name")
        local ok2, price = pcall(util.GetRollCost, name, item.attributes)
        price = ok2 and tonumber(price) or nil
        if price and price > 0 then
            return price
        end
        return nil
    end

    local function invalidateQueue()
        Cache.qAt = 0
        Cache.q = nil
    end

    local function buildQueue(opts)
        opts = type(opts) == "table" and opts or {}
        local includeAll = opts.includeAll == true
        local now = os.clock()
        if not includeAll and Cache.q ~= nil and (now - Cache.qAt) < 1 then
            local cached = Cache.q
            local data = Cache.data or Core.data()
            local onPlot, slots = plotIndex(data)
            Cache.onPlot = onPlot
            Cache.slots = slots
            for i = 1, #cached do
                local snap = cached[i]
                if type(snap) == "table" and type(snap.id) == "string" then
                    snap.level = liveLevel(snap.id, snap.level)
                    snap.onPlot = onPlot[snap.id] ~= nil
                    snap.slot = onPlot[snap.id]
                end
            end
            return cached, data, onPlot, slots
        end
        local wasWorking = lastWorkIds
        local touched = makeSession().touched
        lastMatched = 0
        lastKeepers = {}
        lastWorkIds = {}
        lastFinished = {}
        lastConflicts = {}
        local data = Core.data()
        if not data then
            return {}, data, {}, {}
        end
        local rules = compileRules()
        local onPlot, slots = plotIndex(data)
        local inv = data.Inventory
        local invTable
        pcall(function()
            invTable = inv()
        end)
        if type(invTable) ~= "table" then
            return {}, data, onPlot, slots
        end
        local queue = {}
        local finished = {}
        local matched = 0
        for id, item in pairs(invTable) do
            if type(id) == "string" and type(item) == "table" and id ~= "Gems" and id ~= "Trait Reroll" and id ~= "Tickets" then
                local name = Earn.name(Earn.field(item, "name") or item.name)
                local inProcess = wasWorking[id] or touched[id] or stickyId == id
                local quirkNow = not inProcess and Earn.name((Earn.attrs(item) or {}).quirk) or nil
                local snap, hitRule
                local hits = 0
                for _, rule in ipairs(rules) do
                    if Rules.unitIn(rule, name, id) and not Rules.blocked(rule, quirkNow) then
                        local s = Earn.snapshot(item, Rules.snapOpts(rule))
                        if s and Rules.pass(s, rule) then
                            hits = hits + 1
                            if hits == 1 then
                                snap, hitRule = s, rule
                            end
                        end
                    end
                end
                local amount = snap and (tonumber(field(item, "amount")) or 1) or 0
                if snap and hits > 1 and amount > 0 then
                    snap.id = id
                    lastConflicts[#lastConflicts + 1] = snap
                    snap = nil
                end
                if snap then
                    if amount > 0 then
                        matched = matched + 1
                        lastKeepers[id] = true
                        snap.id = id
                        snap.rule = hitRule
                        snap.ruleLabel = hitRule.label
                        snap.onPlot = onPlot[id] ~= nil
                        snap.slot = onPlot[id]
                        snap.level = liveLevel(id, snap.level)
                        snap.g3 = hitRule.g3
                        snap.t3 = hitRule.t3
                        snap.q3 = hitRule.q3
                        snap.gmin = hitRule.gmin
                        snap.tmin = hitRule.tmin
                        snap.qmin = hitRule.qmin
                        if isFinished(snap) then
                            finished[#finished + 1] = snap
                        elseif includeAll or stillOpen(snap) then
                            queue[#queue + 1] = snap
                        end
                    end
                end
            end
        end
        lastMatched = matched
        sortQueue(queue)
        lastFinished = listByChance(finished)
        queue = applyUnitCap(queue)
        lastWorkIds = {}
        for _, snap in ipairs(queue) do
            if type(snap) == "table" and type(snap.id) == "string" and snap.id ~= "" and needsWork(snap) then
                lastWorkIds[snap.id] = true
            end
        end
        if not includeAll then
            Cache.qAt = os.clock()
            Cache.q = queue
            Cache.data = data
            Cache.onPlot = onPlot
            Cache.slots = slots
        end
        return queue, data, onPlot, slots
    end

    local function corner(inst, radius)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius or 8)
        c.Parent = inst
    end

    local function applyGradient(label, gradient)
        local old = label:FindFirstChild("RarityGrad")
        if old then
            old:Destroy()
        end
        if typeof(gradient) ~= "ColorSequence" then
            label.TextColor3 = Color3.fromRGB(232, 232, 236)
            return
        end
        label.TextColor3 = Color3.new(1, 1, 1)
        local grad = Instance.new("UIGradient")
        grad.Name = "RarityGrad"
        grad.Color = gradient
        grad.Parent = label
    end

    local function unitGradient(snap)
        local cfg = snap and snap.cfg
        if type(cfg) ~= "table" or type(cfg.getRarity) ~= "function" then
            return nil
        end
        local ok, rarity = pcall(cfg.getRarity, {
            mutation = snap.mutation,
        })
        if not ok or rarity == nil then
            return nil
        end
        local okInfo, info = pcall(function()
            return require(RS.Framework.Other.Rarities).Get(tostring(rarity))
        end)
        if okInfo and type(info) == "table" then
            return info.gradient
        end
        return nil
    end

    local function gradientColor(gradient)
        if typeof(gradient) == "ColorSequence" and gradient.Keypoints[1] then
            return gradient.Keypoints[1].Value
        end
        return Color3.fromRGB(255, 211, 0)
    end

    local function hexColor(c)
        if typeof(c) ~= "Color3" then
            return "#E8E8EC"
        end
        return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
    end

    local function escapeRich(s)
        s = tostring(s or "")
        return s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
    end

    local function refreshSnapLive(snap, onPlot)
        if not snap or type(snap.id) ~= "string" then
            return snap
        end
        local data = Core.data()
        local item = inventoryItem(data, snap.id)
        if item then
            local attrs = Earn.attrs(item)
            snap.grade = attrs.grade
            snap.trait = attrs.trait
            snap.quirk = attrs.quirk
            snap.mutation = attrs.mutation or snap.mutation
            snap.level = liveLevel(snap.id, attrs.level or snap.level)
        end
        if type(onPlot) ~= "table" then
            onPlot = plotIndex(data)
        end
        snap.onPlot = onPlot[snap.id] ~= nil
        snap.slot = onPlot[snap.id]
        return snap
    end

    local function rowFromSnap(snap, step, current)
        if not snap then
            return nil
        end
        return {
            id = snap.id,
            title = snap.title or snap.name,
            name = snap.name,
            rule = snap.ruleLabel,
            chance = snap.chance,
            earnNow = snap.earnNow,
            earnMin = snap.earnMin or snap.earnGoal,
            earnMax = snap.earnMax,
            grade = snap.grade,
            trait = snap.trait,
            quirk = snap.quirk,
            level = snap.level,
            mutation = snap.mutation,
            onPlot = snap.onPlot == true,
            slot = snap.slot,
            step = step or plannedStep(snap),
            current = current == true,
            gradient = unitGradient(snap),
        }
    end

    local function markDone(snap)
        if not snap or type(snap.id) ~= "string" then
            return
        end
        local s = makeSession()
        if s.doneIds[snap.id] then
            return
        end
        s.doneIds[snap.id] = true
        local row = rowFromSnap(snap, "done", false)
        table.insert(s.done, 1, row)
        while #s.done > 40 do
            table.remove(s.done)
        end
    end

    local lastCurrent = { snap = nil, step = nil }
    local hotRolls = {}

    local function hotIs(id)
        local h = type(id) == "string" and hotRolls[id]
        if type(h) ~= "table" then
            return false
        end
        return (os.clock() - (tonumber(h.at) or 0)) < 0.5
    end

    local function hotStep(id)
        local h = hotRolls[id]
        return type(h) == "table" and h.step or nil
    end

    local function publishView(queue, currentSnap, currentStep, force)
        queue = type(queue) == "table" and queue or {}
        if currentSnap ~= nil or currentStep ~= nil then
            lastCurrent.snap = currentSnap
            lastCurrent.step = currentStep
        end
        local hotKey = ""
        for id, h in pairs(hotRolls) do
            if type(h) == "table" and (os.clock() - (tonumber(h.at) or 0)) < 0.5 then
                hotKey = hotKey .. id .. ":"
            end
        end
        local key = tostring(lastCurrent.snap and lastCurrent.snap.id or "") .. ":" .. tostring(lastCurrent.step or "") .. ":" .. hotKey
        local now = os.clock()
        if force ~= true and key == Cache.pubKey and (now - Cache.pubAt) < 1 then
            return
        end
        Cache.pubKey = key
        Cache.pubAt = now
        currentSnap = lastCurrent.snap
        currentStep = lastCurrent.step
        local data = Core.data()
        local onPlotMap = plotIndex(data)
        if currentSnap then
            refreshSnapLive(currentSnap, onPlotMap)
        end
        local s = makeSession()
        local inQueue = {}
        local process = {}
        for _, snap in ipairs(listByChance(queue)) do
            if snap and snap.id then
                refreshSnapLive(snap, onPlotMap)
                inQueue[snap.id] = true
                local live = hotStep(snap.id) or (currentSnap and currentSnap.id == snap.id and currentStep) or plannedStep(snap)
                process[#process + 1] = rowFromSnap(snap, live, hotIs(snap.id) or (currentSnap and currentSnap.id == snap.id))
            end
        end
        local done = {}
        for _, snap in ipairs(lastFinished) do
            if snap and snap.id and not inQueue[snap.id] then
                refreshSnapLive(snap, onPlotMap)
                done[#done + 1] = rowFromSnap(snap, "done", false)
            end
        end
        local gems = tokenAmount(data, "Gems")
        local traits = tokenAmount(data, "Trait Reroll")
        local money = moneyNow(data)
        local hotN = 0
        for id in pairs(hotRolls) do
            if hotIs(id) then
                hotN = hotN + 1
            end
        end
        local curName = currentSnap and (currentSnap.title or currentSnap.name) or nil
        if hotN > 1 then
            curName = tostring(hotN) .. " units"
        end
        local curCost
        if currentStep == "grade" then
            curCost = "1 gem"
        elseif currentStep == "trait" then
            curCost = "1 trait"
        elseif currentStep == "quirk" and currentSnap then
            local price = quirkPrice(currentSnap)
            curCost = price and (Core.compact(price) .. " money") or "cash"
        elseif currentStep == "upgrade" and currentSnap then
            local price = levelPrice(currentSnap.name, {
                level = currentSnap.level,
                mutation = currentSnap.mutation,
            })
            curCost = price and (Core.compact(price) .. " money") or "level"
        elseif currentStep == "rotate" then
            curCost = "plot"
        end
        State.view = {
            on = anyOn(),
            gradeOn = gradeOn,
            traitOn = traitOn,
            quirkOn = quirkOn,
            upgradeOn = upgradeOn,
            status = {
                value = lastStatus.value,
                style = lastStatus.style,
                detail = lastStatus.detail,
            },
            remaining = {
                money = money,
                gems = gems,
                traits = traits,
                keepPercent = keepPercent,
                maxUnits = capTotal(),
                doneN = doneCount(),
                processN = #process,
                usableGems = math.max(0, gems - tokenFloor("gems", data)),
                usableTraits = math.max(0, traits - tokenFloor("traits", data)),
                startGems = s.startGems,
                startTraits = s.startTraits,
                gradeEvent = gradeEventMode,
                traitEvent = traitEventMode,
                gradeEventPct = gradeEventPct,
                traitEventPct = traitEventPct,
                weather = liveWeatherName,
                gradeEventNow = weatherIs("Grade Event"),
                traitEventNow = weatherIs("Trait Event"),
                pickMode = pickMode,
                oneIn = oneIn,
                oneInMax = oneInMax,
            },
            recap = {
                gems = s.gems,
                traits = s.traits,
                money = s.money,
                gradeN = s.gradeN,
                traitN = s.traitN,
                quirkN = s.quirkN,
                upN = s.upN,
                doneN = doneCount(),
                capMax = capTotal(),
                capUsed = doneCount() + #process,
                elapsed = os.clock() - (tonumber(s.t0) or os.clock()),
                currentName = curName,
                currentStep = currentStep,
                currentCost = curCost,
                hotN = hotN,
                currentGrade = currentSnap and currentSnap.grade or nil,
                currentTrait = currentSnap and currentSnap.trait or nil,
                currentQuirk = currentSnap and currentSnap.quirk or nil,
                currentLevel = currentSnap and currentSnap.level or nil,
                currentOnPlot = currentSnap and currentSnap.onPlot == true,
                currentSlot = currentSnap and currentSnap.slot or nil,
            },
            process = process,
            done = done,
        }
        G.AnimeDiceAutoUnit = State
    end

    local function makePreviewCard(parent, order)
        local card = Instance.new("Frame")
        card.Name = "UnitCard"
        card.BackgroundColor3 = Color3.fromRGB(28, 28, 32)
        card.BackgroundTransparency = 0.15
        card.BorderSizePixel = 0
        card.Size = UDim2.new(1, -4, 0, 28)
        card.LayoutOrder = order
        card.Parent = parent
        corner(card, 8)
        local stroke = Instance.new("UIStroke")
        stroke.Name = "Tint"
        stroke.Thickness = 1
        stroke.Transparency = 0.35
        stroke.Color = Color3.fromRGB(255, 211, 0)
        stroke.Parent = card

        local bar = Instance.new("Frame")
        bar.Name = "Bar"
        bar.BackgroundColor3 = Color3.fromRGB(255, 211, 0)
        bar.BorderSizePixel = 0
        bar.AnchorPoint = Vector2.new(0, 0.5)
        bar.Position = UDim2.new(0, 6, 0.5, 0)
        bar.Size = UDim2.new(0, 3, 1, -10)
        bar.ZIndex = 1
        bar.Parent = card
        corner(bar, 2)

        local line = Instance.new("TextLabel")
        line.Name = "Line"
        line.BackgroundTransparency = 1
        line.Position = UDim2.new(0, 14, 0, 0)
        line.Size = UDim2.new(1, -22, 1, 0)
        line.Font = Enum.Font.GothamMedium
        line.TextSize = 10
        line.TextXAlignment = Enum.TextXAlignment.Left
        line.TextYAlignment = Enum.TextYAlignment.Center
        line.RichText = true
        line.TextTruncate = Enum.TextTruncate.AtEnd
        line.Text = ""
        line.ZIndex = 2
        line.Parent = card

        return {
            frame = card,
            line = line,
            bar = bar,
            stroke = stroke,
        }
    end

    local function paintPreview()
        local queue = buildQueue({ includeAll = not anyOn() })
        if not anyOn() then
            local n = tonumber(lastMatched) or #queue
            paint("Off", "muted", tostring(n) .. " match · cap " .. tostring(capTotal()))
        end
        publishView(queue, nil, nil, true)
        local shown = listByChance(queue)
        local onPlotMap = plotIndex(Core.data())
        if not previewList or not previewList.Parent then
            return #queue
        end
        if previewHead and previewHead.Parent then
            local n = #queue
            local used = doneCount() + n
            local plotN = 0
            for i = 1, #shown do
                if shown[i] and shown[i].onPlot == true then
                    plotN = plotN + 1
                end
            end
            local text = tostring(n) .. (n == 1 and " unit" or " units") .. " · " .. tostring(used) .. "/" .. tostring(capTotal())
            local ruleN = #compiledRules
            text = text .. " · " .. tostring(ruleN) .. (ruleN == 1 and " rule" or " rules")
            if #lastConflicts > 0 then
                local names = {}
                for i = 1, math.min(2, #lastConflicts) do
                    names[#names + 1] = tostring(lastConflicts[i].name or "?")
                end
                local more = #lastConflicts > 2 and (" +" .. tostring(#lastConflicts - 2)) or ""
                text = text .. ' · <font color="#FF6B6B">' .. tostring(#lastConflicts) .. " conflict (" .. table.concat(names, ", ") .. more .. ")</font>"
            end
            local rollN = 0
            for i = 1, #shown do
                if shown[i] and hotIs(shown[i].id) then
                    rollN = rollN + 1
                end
            end
            if rollN > 0 then
                text = text .. " · " .. tostring(rollN) .. " rolling"
            end
            if plotN > 0 then
                text = text .. " · " .. tostring(plotN) .. " on plot"
            end
            previewHead.Text = text
        end
        if previewEmpty and previewEmpty.Parent then
            previewEmpty.Visible = #shown == 0
            local emptyText = "No units match any rule"
            if #compiledRules == 0 then
                emptyText = "No rules yet. Add a rule above."
            elseif anyOn() and lastMatched > 0 then
                emptyText = "No units need work"
            end
            previewEmpty.Text = #shown == 0 and emptyText or ""
        end
        for i, snap in ipairs(shown) do
            local card = previewCards[i]
            if not card or not card.frame or not card.frame.Parent or not card.line then
                if card and card.frame then
                    pcall(function()
                        card.frame:Destroy()
                    end)
                end
                card = makePreviewCard(previewList, i)
                previewCards[i] = card
            end
            card.frame.Visible = true
            card.frame.LayoutOrder = i
            refreshSnapLive(snap, onPlotMap)
            local grad = unitGradient(snap)
            local tint = gradientColor(grad)
            local rolling = hotIs(snap.id)
            if rolling then
                tint = Color3.fromRGB(255, 211, 0)
            end
            if card.bar then
                card.bar.BackgroundColor3 = tint
            end
            if card.stroke then
                card.stroke.Color = tint
                card.stroke.Transparency = rolling and 0.1 or (snap.onPlot == true and 0.15 or 0.35)
            end
            local name = escapeRich(snap.title or snap.name or "-")
            local have = {}
            if type(snap.grade) == "string" and snap.grade ~= "" then
                have[#have + 1] = tostring(snap.grade)
            end
            if type(snap.trait) == "string" and snap.trait ~= "" then
                have[#have + 1] = tostring(snap.trait)
            end
            if type(snap.quirk) == "string" and snap.quirk ~= "" then
                have[#have + 1] = tostring(snap.quirk)
            end
            if tonumber(snap.level) then
                have[#have + 1] = "Lv " .. tostring(snap.level)
            end
            local haveText = #have > 0 and table.concat(have, " · ") or "-"
            local inText = snap.chance and ("1 in " .. Core.compact(snap.chance)) or "1 in -"
            local nowE = Core.compact(snap.earnNow)
            local minE = Core.compact(snap.earnMin or snap.earnGoal)
            local maxE = Core.compact(snap.earnMax or snap.earnGoal)
            local plotHtml = ""
            if snap.onPlot == true then
                local slot = tonumber(snap.slot)
                plotHtml = string.format(
                    '<font color="#8A8F98"> | </font><font color="#78DC96">%s</font>',
                    slot and ("Plot " .. tostring(slot)) or "Plot"
                )
            end
            local mark = rolling and '<font color="#FFD300">▶ </font>' or ""
            if snap.ruleLabel then
                mark = mark .. '<font color="#8EC8FF">' .. escapeRich(snap.ruleLabel) .. " </font>"
            end
            card.line.Text = string.format(
                '%s<font color="#F2F3F5">%s</font><font color="#8A8F98"> | </font><font color="#FFD300">%s</font><font color="#8A8F98"> | </font><font color="#8EC8FF">%s</font><font color="#8A8F98"> | </font><font color="#FFD300">%s</font><font color="#8A8F98"> → </font><font color="#FF9A4A">min %s</font><font color="#8A8F98"> → </font><font color="#5CFF9A">max %s</font>%s',
                mark,
                name,
                escapeRich(haveText),
                inText,
                nowE,
                minE,
                maxE,
                plotHtml
            )
        end
        for i = #queue + 1, #previewCards do
            local card = previewCards[i]
            if card and card.frame and card.frame.Parent then
                card.frame.Visible = false
            end
        end
        return #queue
    end

    local function gradeStep(snap, data)
        if not gradeOn or not snap.gmin then
            return nil
        end
        local live = Earn.attrs(inventoryItem(data, snap.id) or {})
        local gradeNow = live.grade or snap.grade
        snap.grade = gradeNow
        if keepGrade(gradeNow, snap) then
            return nil
        end
        if gameAutoRoll("grade") then
            return "wait_game_roll"
        end
        ensureStockSnap(data)
        local gems = tokenAmount(data, "Gems")
        local floor = tokenFloor("gems", data)
        if gems < (floor + 1) then
            if gradeEventMode and not eventActive("gems") then
                return "wait_grade_event"
            end
            return "wait_gems"
        end
        if kindPending(snap.id, "grade", snap.grade) then
            return "wait_replica"
        end
        if kindDebounce("grade") then
            return "wait_debounce"
        end
        return "grade"
    end

    local function traitStep(snap, data)
        if not traitOn or not snap.tmin then
            return nil
        end
        local live = Earn.attrs(inventoryItem(data, snap.id) or {})
        local traitNow = live.trait or snap.trait
        snap.trait = traitNow
        if keepTrait(traitNow, snap) then
            return nil
        end
        if gameAutoRoll("trait") then
            return "wait_game_roll"
        end
        ensureStockSnap(data)
        local traits = tokenAmount(data, "Trait Reroll")
        local floor = tokenFloor("traits", data)
        if traits < (floor + 1) then
            if traitEventMode and not eventActive("traits") then
                return "wait_trait_event"
            end
            return "wait_traits"
        end
        if kindPending(snap.id, "trait", snap.trait) then
            return "wait_replica"
        end
        if kindDebounce("trait") then
            return "wait_debounce"
        end
        return "trait"
    end

    local function quirkStep(snap, data)
        if not quirkOn or not snap.qmin then
            return nil
        end
        local live = Earn.attrs(inventoryItem(data, snap.id) or {})
        local quirkNow = live.quirk or snap.quirk
        snap.quirk = quirkNow
        if keepQuirk(quirkNow, snap) then
            return nil
        end
        if gameAutoRoll("quirk") then
            return "wait_game_roll"
        end
        local price = quirkPrice(snap)
        if not price then
            return "wait_money"
        end
        if not Core.money().allows(moneyNow(data), price, keepPercent) then
            noteQuirkMoney(snap, price)
            return "wait_money"
        end
        if kindPending(snap.id, "quirk", snap.quirk) then
            return "wait_replica"
        end
        if kindDebounce("quirk") then
            return "wait_debounce"
        end
        return "quirk"
    end

    local function upgradeStep(snap, data)
        if not upgradeOn then
            return nil
        end
        local cap = ruleLevel(snap)
        if cap > 0 and (tonumber(snap.level) or 1) >= cap then
            return nil
        end
        if towerBusy() and not snap.onPlot then
            return "wait_tower"
        end
        local price = levelPrice(snap.name, {
            level = snap.level,
            mutation = snap.mutation,
        })
        if not price then
            return "wait_money"
        end
        if not Core.money().allows(moneyNow(data), price, keepPercent) then
            return "wait_money"
        end
        if os.clock() - lastUpgradeAt < UPGRADE_DELAY then
            return "wait_debounce"
        end
        if not snap.onPlot then
            return "rotate"
        end
        return "upgrade"
    end

    local ACTION_STEPS = {
        grade = true,
        trait = true,
        quirk = true,
        roll = true,
        upgrade = true,
        rotate = true,
    }
    local SYNC_STEPS = {
        wait_debounce = true,
        wait_replica = true,
    }
    local EVENT_WAIT_STEPS = {
        wait_grade_event = true,
        wait_trait_event = true,
        wait_halloween = true,
    }

    -- Roll grade/trait/quirk bareng. SYNC satu jenis jangan nahan jenis lain yang sudah bisa Fire.
    -- Upgrade/rotate setelah roll, atau kalau roll lagi nunggu bahan.
    local function nextStep(snap, data)
        if not snap then
            return "none"
        end
        if fuseBusy() and not snap.locked and not lastKeepers[snap.id] then
            return "fuse"
        end
        local blocked
        local eventWait
        local firstRoll
        local firstSync
        local rolls = { gradeStep(snap, data), traitStep(snap, data), quirkStep(snap, data) }
        for i = 1, #rolls do
            local step = rolls[i]
            if ACTION_STEPS[step] then
                firstRoll = firstRoll or step
            elseif SYNC_STEPS[step] then
                firstSync = firstSync or step
            elseif EVENT_WAIT_STEPS[step] then
                eventWait = eventWait or step
            elseif not blocked and step then
                blocked = step
            end
        end
        if firstRoll then
            return firstRoll
        end
        local up = upgradeStep(snap, data)
        if ACTION_STEPS[up] or SYNC_STEPS[up] then
            return up
        end
        if EVENT_WAIT_STEPS[up] then
            eventWait = eventWait or up
        elseif not blocked and up then
            blocked = up
        end
        return firstSync or blocked or eventWait or "done"
    end

    local function actionable(step)
        return step == "grade" or step == "trait" or step == "quirk" or step == "upgrade" or step == "rotate"
    end

    local function findSnap(queue, id)
        for _, snap in ipairs(queue) do
            if snap.id == id then
                return snap
            end
        end
        return nil
    end

    local function pickUnit(queue, data)
        local _, slots = plotIndex(data)
        local function canRotate(sticky)
            if towerBusy() or type(pickVictim) ~= "function" then
                return false
            end
            local victim = pickVictim(data, slots, queue, sticky)
            return victim ~= nil
        end
        local function take(snap, step)
            if stickyId and stickyId ~= snap.id then
                local old = findSnap(queue, stickyId)
                if old then
                    maybeRestore(data, old)
                end
                if upgradeHeldId == stickyId then
                    upgradeHeldId = nil
                end
            end
            stickyId = snap.id
            return snap, step
        end
        local function scanPhase()
            if traitOn then
                for i = 1, #queue do
                    if traitStep(queue[i], data) then
                        return "trait"
                    end
                end
            end
            if gradeOn then
                for i = 1, #queue do
                    if gradeStep(queue[i], data) then
                        return "grade"
                    end
                end
            end
            if upgradeOn then
                for i = 1, #queue do
                    if upgradeStep(queue[i], data) then
                        return "upgrade"
                    end
                end
            end
            if quirkOn then
                for i = 1, #queue do
                    if quirkStep(queue[i], data) then
                        return "quirk"
                    end
                end
            end
            return nil
        end
        State._jobPhase = scanPhase()
        local function unitStep(snap)
            if fuseBusy() and not snap.locked and not lastKeepers[snap.id] then
                return "fuse"
            end
            local ph = State._jobPhase
            if ph == "trait" then
                return traitStep(snap, data) or "done"
            end
            if ph == "grade" then
                return gradeStep(snap, data) or "done"
            end
            if ph == "upgrade" then
                return upgradeStep(snap, data) or "done"
            end
            if ph == "quirk" then
                return quirkStep(snap, data) or "done"
            end
            return nextStep(snap, data)
        end
        local function stayOn(step, snap)
            if step == "rotate" then
                return canRotate(snap)
            end
            if ACTION_STEPS[step] or SYNC_STEPS[step] then
                return true
            end
            return step == "fuse" or step == "wait_game_roll"
        end
        local function collect(stepOf)
            local hit = {
                action = nil,
                sync = nil,
                stock = nil,
                eventWait = nil,
                blocked = nil,
            }
            for _, snap in ipairs(queue) do
                local step = stepOf(snap, data)
                if step == "rotate" and not canRotate(snap) then
                    hit.blocked = hit.blocked or { snap = snap, step = step }
                elseif ACTION_STEPS[step] then
                    hit.action = hit.action or { snap = snap, step = step }
                elseif SYNC_STEPS[step] or step == "fuse" or step == "wait_game_roll" or step == "wait_money" then
                    hit.sync = hit.sync or { snap = snap, step = step }
                elseif step == "wait_gems" or step == "wait_traits" then
                    hit.stock = hit.stock or { snap = snap, step = step }
                elseif EVENT_WAIT_STEPS[step] then
                    hit.eventWait = hit.eventWait or { snap = snap, step = step }
                elseif step == "wait_tower" then
                    hit.tower = hit.tower or { snap = snap, step = step }
                elseif step and step ~= "done" and step ~= "none" then
                    hit.blocked = hit.blocked or { snap = snap, step = step }
                end
            end
            return hit.action or hit.sync or hit.blocked or hit.stock or hit.eventWait or hit.tower
        end
        if stickyId then
            local snap = findSnap(queue, stickyId)
            if snap then
                local step = unitStep(snap)
                if stayOn(step, snap) then
                    return take(snap, step)
                end
                if step == "done" then
                    maybeRestore(data, snap)
                end
            end
            stickyId = nil
        end
        local picked = collect(unitStep)
        if picked then
            return take(picked.snap, picked.step)
        end
        stickyId = nil
        return nil, "none"
    end

    local function fireRoll(kind, unitId, force)
        if not State.goToRollZone(kind) then
            return false
        end
        local getter = kind == "grade" and gradeSignal or kind == "quirk" and quirkSignal or traitSignal
        local ok, sig = pcall(getter)
        if not ok or sig == nil then
            return false
        end
        if force then
            return pcall(function()
                sig:Fire(unitId, true)
            end)
        end
        return pcall(function()
            sig:Fire(unitId)
        end)
    end

    local function fireLevel(slot)
        local re = Core.remote("PlotService", "LevelUpSlot")
        if not re then
            return false
        end
        if pcall(function()
            re:FireServer(slot)
        end) then
            return true
        end
        return pcall(function()
            re:Fire(slot)
        end)
    end

    local function highestPlotEarn(data, slots, exceptId)
        local bestId, bestEarn, bestSlot
        for _, slot in ipairs(slots) do
            local id = slotUnitId(data, slot)
            if id and id ~= exceptId then
                local item = inventoryItem(data, id)
                local snap = item and Earn.snapshot(item, {})
                local earn = snap and snap.earnNow or 0
                if not bestEarn or earn > bestEarn then
                    bestEarn = earn
                    bestId = id
                    bestSlot = slot
                end
            end
        end
        return bestId, bestSlot, bestEarn or 0
    end

    -- Upgrade cuma 1 slot: selalu slot yang sama, bergantian unit. Slot lain biar Equip.
    pickVictim = function(data, slots, queue, sticky)
        if type(slots) ~= "table" or #slots == 0 or type(sticky) ~= "table" then
            return nil, nil, "none"
        end
        local function hasSlot(slot)
            for _, s in ipairs(slots) do
                if s == slot then
                    return true
                end
            end
            return false
        end
        for _, slot in ipairs(slots) do
            if slotUnitId(data, slot) == sticky.id then
                workSlot = slot
                return workSlot, nil, "self"
            end
        end
        if workSlot and hasSlot(workSlot) then
            local id = slotUnitId(data, workSlot)
            if id == sticky.id then
                return workSlot, nil, "self"
            end
            return workSlot, id, id and "swap" or "empty"
        end
        for _, slot in ipairs(slots) do
            if not slotUnitId(data, slot) then
                workSlot = slot
                return workSlot, nil, "empty"
            end
        end
        local eq = G.AnimeDiceEquipBest
        local function isPrio(id)
            return type(eq) == "table" and type(eq.isPriority) == "function" and eq.isPriority(id) == true
        end
        local pick, pickId, pickEarn, pickPrio
        for _, slot in ipairs(slots) do
            local id = slotUnitId(data, slot)
            if id and id ~= sticky.id then
                local item = inventoryItem(data, id)
                local snap = item and Earn.snapshot(item, {})
                local earn = snap and snap.earnNow or 0
                local prio = isPrio(id)
                if not pick or (pickPrio and not prio) or (prio == pickPrio and earn < pickEarn) then
                    pick = slot
                    pickId = id
                    pickEarn = earn
                    pickPrio = prio
                end
            end
        end
        if pick then
            workSlot = pick
            return workSlot, pickId, "swap"
        end
        return nil, nil, "none"
    end

    local function rotateOnto(data, slots, queue, sticky)
        if rotateBusy or towerBusy() then
            return false
        end
        local victim, oldId = pickVictim(data, slots, queue, sticky)
        if not victim then
            return false
        end
        local okNet, equipFn, unequipFn, interact = pcall(plotNet)
        if not okNet or not equipFn or not unequipFn or not interact then
            return false
        end
        rotateBusy = true
        State.rotating = true
        local ok = pcall(function()
            if slotUnitId(data, victim) == sticky.id then
                return
            end
            clearHand()
            if oldId then
                displacedId = oldId
                displacedSlot = victim
                interact:Fire(victim)
                waitUntil(function()
                    return slotUnitId(data, victim) == nil
                end, 1.2)
                task.wait(INTERACT_WAIT)
                if holdingId() then
                    unequipFn()
                    task.wait(INTERACT_WAIT)
                end
            end
            clearHand()
            equipFn(sticky.id)
            waitUntil(function()
                return holdingId() == sticky.id
            end, 1.2)
            interact:Fire(victim)
            waitUntil(function()
                return slotUnitId(data, victim) == sticky.id
            end, 1.2)
            task.wait(INTERACT_WAIT)
            clearHand()
        end)
        rotateBusy = false
        State.rotating = false
        if ok and slotUnitId(data, victim) == sticky.id then
            upgradeHeldId = sticky.id
            workSlot = victim
            return true
        end
        return false
    end

    maybeRestore = function(data, sticky)
        if upgradeHeldId == (sticky and sticky.id) then
            upgradeHeldId = nil
        end
        if not upgradeOn or not displacedId or not displacedSlot then
            return
        end
        local item = inventoryItem(data, displacedId)
        local other = item and Earn.snapshot(item, {})
        if not other or (other.earnNow or 0) <= (sticky.earnNow or 0) then
            displacedId = nil
            displacedSlot = nil
            return
        end
        local okNet, equipFn, unequipFn, interact = pcall(plotNet)
        if not okNet then
            return
        end
        pcall(function()
            clearHand()
            local slot = sticky.slot or displacedSlot
            if not slot then
                return
            end
            if slotUnitId(data, slot) == sticky.id then
                interact:Fire(slot)
                waitUntil(function()
                    return slotUnitId(data, slot) == nil
                end, 1.2)
                task.wait(INTERACT_WAIT)
                if holdingId() then
                    unequipFn()
                    task.wait(INTERACT_WAIT)
                end
            end
            equipFn(displacedId)
            waitUntil(function()
                return holdingId() == displacedId
            end, 1.2)
            interact:Fire(slot)
            waitUntil(function()
                return slotUnitId(data, slot) == displacedId
            end, 1.2)
            task.wait(INTERACT_WAIT)
            clearHand()
        end)
        displacedId = nil
        displacedSlot = nil
    end

    local function doGrade(data, snap)
        local live = Earn.attrs(inventoryItem(data, snap.id) or {})
        local grade = live.grade or snap.grade
        if keepGrade(grade, snap) then
            return false
        end
        if tokenAmount(data, "Gems") < (tokenFloor("gems", data) + 1) then
            return false
        end
        local force = isProtected(data, "grade", grade) and not keepGrade(grade, snap)
        if force and keepGrade(grade, snap) then
            return false
        end
        if fireRoll("grade", snap.id, force) then
            markKindPending(snap.id, "grade", grade)
            markSpent("gems")
            touchUnit(snap.id)
            return true
        end
        return false
    end

    local function doTrait(data, snap)
        local live = Earn.attrs(inventoryItem(data, snap.id) or {})
        local trait = live.trait or snap.trait
        if keepTrait(trait, snap) then
            return false
        end
        if tokenAmount(data, "Trait Reroll") < (tokenFloor("traits", data) + 1) then
            return false
        end
        local force = isProtected(data, "trait", trait) and not keepTrait(trait, snap)
        if force and keepTrait(trait, snap) then
            return false
        end
        if fireRoll("trait", snap.id, force) then
            markKindPending(snap.id, "trait", trait)
            markSpent("traits")
            touchUnit(snap.id)
            return true
        end
        return false
    end

    local function doQuirk(data, snap)
        local live = Earn.attrs(inventoryItem(data, snap.id) or {})
        local quirk = live.quirk or snap.quirk
        if keepQuirk(quirk, snap) then
            return false
        end
        local price = quirkPrice(snap)
        if not price then
            return false
        end
        local money = moneyNow(data)
        if money < price then
            noteQuirkMoney(snap, price)
            return false
        end
        if not Core.money().allows(money, price, keepPercent) then
            noteQuirkMoney(snap, price)
            return false
        end
        local force = isProtected(data, "quirk", quirk) and not keepQuirk(quirk, snap)
        if force and keepQuirk(quirk, snap) then
            return false
        end
        if fireRoll("quirk", snap.id, force) then
            markKindPending(snap.id, "quirk", quirk)
            markSpent("quirks", price)
            touchUnit(snap.id)
            return true
        end
        return false
    end

    local ROLL_DO = {
        grade = function(data, snap)
            return doGrade(data, snap)
        end,
        trait = function(data, snap)
            return doTrait(data, snap)
        end,
        quirk = function(data, snap)
            return doQuirk(data, snap)
        end,
    }
    local ROLL_STEP = {
        grade = function(snap, data)
            return gradeStep(snap, data)
        end,
        trait = function(snap, data)
            return traitStep(snap, data)
        end,
        quirk = function(snap, data)
            return quirkStep(snap, data)
        end,
    }
    local ROLL_ORDER = { "grade", "trait", "quirk" }

    -- Prefer unit aktif. Jenis yang sudah keep (nganggur) di-Fire ke unit berikutnya.
    local function fireKindSlots(queue, data, prefer)
        local fired = {}
        local nextHot = {}
        local nUnit = 0
        local function unitOk(snap)
            if not snap or type(snap.id) ~= "string" then
                return false
            end
            if fuseBusy() and not snap.locked and not lastKeepers[snap.id] then
                return false
            end
            return true
        end
        local function markHot(snap, kind)
            local id = snap.id
            local h = nextHot[id]
            if type(h) ~= "table" then
                h = {
                    step = kind,
                    at = os.clock(),
                    grade = false,
                    trait = false,
                    quirk = false,
                }
                nextHot[id] = h
                nUnit = nUnit + 1
            end
            h[kind] = true
            h.at = os.clock()
            local bits = {}
            if h.grade then
                bits[#bits + 1] = "grade"
            end
            if h.trait then
                bits[#bits + 1] = "trait"
            end
            if h.quirk then
                bits[#bits + 1] = "quirk"
            end
            h.step = #bits > 1 and "roll" or bits[1]
            fired[#fired + 1] = kind
        end
        local function snapForKind(kind)
            if unitOk(prefer) and ROLL_STEP[kind](prefer, data) == kind then
                return prefer
            end
            if type(queue) ~= "table" then
                return nil
            end
            for i = 1, #queue do
                local snap = queue[i]
                if snap and (not prefer or snap.id ~= prefer.id) and unitOk(snap) then
                    if ROLL_STEP[kind](snap, data) == kind then
                        return snap
                    end
                end
            end
            return nil
        end
        -- Satu pekerjaan: trait semua → grade semua → upgrade semua → quirk semua.
        local ok, err = pcall(function()
            local kind = State._jobPhase
            if kind ~= "trait" and kind ~= "grade" and kind ~= "quirk" then
                return
            end
            local snap = snapForKind(kind)
            if snap and ROLL_DO[kind](data, snap) then
                markHot(snap, kind)
            end
        end)
        if not ok then
            warn("[auto_unit] kind slots " .. tostring(err))
        end
        if nUnit > 0 then
            hotRolls = nextHot
        end
        if #fired == 0 then
            local kind = State._jobPhase
            if (kind == "trait" or kind == "grade" or kind == "quirk") and snapForKind(kind) then
                State.needMachine = State.rollZoneName(kind)
                State.holdHub = true
            elseif State.holdHub ~= true then
                State.needMachine = nil
            end
        end
        return fired, nUnit
    end

    local function doUpgrade(snap)
        if not snap.slot then
            return false
        end
        if fireLevel(snap.slot) then
            lastUpgradeAt = os.clock()
            pendingLevel[snap.id] = (tonumber(snap.level) or 1) + 1
            pendingLevelAt[snap.id] = os.clock()
            local price = levelPrice(snap.name, {
                level = snap.level,
                mutation = snap.mutation,
            })
            markSpent("money", price)
            touchUnit(snap.id)
            return true
        end
        return false
    end

    local function queueNeedsLevel(queue, data)
        if not upgradeOn or type(queue) ~= "table" or type(data) ~= "table" then
            return false
        end
        for _, snap in ipairs(queue) do
            local step = upgradeStep(snap, data)
            if step == "upgrade" or step == "rotate" or step == "wait_tower" or step == "wait_money" then
                return true
            end
        end
        return false
    end

    local function refreshEquipBlock(queue, data, step)
        -- Blok Equip hanya saat 1 slot upgrade dipakai. Roll grade/trait/quirk tidak blok.
        State.blockEquipBest = rotateBusy == true
            or step == "upgrade"
            or step == "rotate"
            or (type(upgradeHeldId) == "string" and upgradeHeldId ~= "")
    end

    local function shortName(snap)
        if not snap then
            return "-"
        end
        local n = tostring(snap.name or "")
        if #n > 18 then
            n = string.sub(n, 1, 16) .. ".."
        end
        return n
    end

    local workLoop

    local function paceWork(step)
        if type(workLoop) ~= "table" or type(workLoop.setDelay) ~= "function" then
            return
        end
        local rolling = step == "grade"
            or step == "trait"
            or step == "quirk"
            or step == "roll"
            or step == "wait_replica"
            or step == "wait_debounce"
        if rolling then
            workLoop.setDelay(ROLL_DELAY)
            return
        end
        local fast = rotateBusy == true or ACTION_STEPS[step] == true or SYNC_STEPS[step] == true
        workLoop.setDelay(fast and UPGRADE_DELAY or 1)
    end

    local function stepOnce()
        if not anyOn() then
            State.working = false
            State.holdHub = false
            State.needMachine = nil
            lastCurrent.snap = nil
            lastCurrent.step = nil
            workSlot = nil
            upgradeHeldId = nil
            State.blockEquipBest = false
            paintPreview()
            paceWork(nil)
            return
        end
        if type(Core.tradeBusy) == "function" then
            local okTrade, onTrade = pcall(Core.tradeBusy)
            if okTrade and onTrade then
                paint("Paused", "muted", "trade")
                paceWork(nil)
                return
            end
        end
        if rotateBusy then
            State.working = true
            State.blockEquipBest = true
            paceWork("rotate")
            return
        end
        local spin = G.AnimeDiceAutoSpin
        if type(spin) == "table" and type(spin.spinning) == "function" then
            local okSpin, onSpin = pcall(spin.spinning)
            if okSpin and onSpin then
                paint("Paused", "muted", "auto spin")
                paceWork(nil)
                return
            end
        end
        local queue, data, _, slots = buildQueue()
        if not data then
            State.working = false
            paint("Wait", "muted", "no data")
            publishView(queue)
            paceWork(nil)
            return
        end
        ensureStockSnap(data)
        if #compiledRules == 0 then
            State.working = false
            paint("Wait", "muted", "add rule")
            publishView(queue)
            refreshEquipBlock(queue, data, nil)
            paceWork(nil)
            return
        end
        local snap, step = pickUnit(queue, data)
        local holdSteps = {
            upgrade = true,
            rotate = true,
            wait_debounce = true,
            wait_money = true,
            wait_tower = true,
        }
        if upgradeHeldId and (not snap or snap.id ~= upgradeHeldId or not holdSteps[step]) then
            upgradeHeldId = nil
        end
        refreshEquipBlock(queue, data, step)
        if not snap then
            State.working = false
            State.holdHub = false
            State.needMachine = nil
            lastCurrent.snap = nil
            lastCurrent.step = nil
            local used = doneCount()
            local cap = capTotal()
            if used >= cap then
                paint("Cap", "muted", tostring(used) .. "/" .. tostring(cap))
            else
                paint("On", "muted", "no unit · " .. tostring(used) .. "/" .. tostring(cap))
            end
            publishView(queue)
            paceWork(nil)
            return
        end
        local pad = step == "grade"
            or step == "trait"
            or step == "quirk"
            or step == "roll"
            or step == "wait_replica"
            or step == "wait_debounce"
            or step == "wait_gems"
            or step == "wait_traits"
            or step == "wait_game_roll"
            or step == "wait_grade_event"
            or step == "wait_trait_event"
        State.holdHub = pad == true
        if pad then
            local kind = "trait"
            if step == "grade" or step == "wait_gems" or step == "wait_grade_event" then
                kind = "grade"
            elseif step == "quirk" then
                kind = "quirk"
            end
            State.needMachine = State.rollZoneName(kind)
        end
        State.working = step == "grade"
            or step == "trait"
            or step == "quirk"
            or step == "upgrade"
            or step == "rotate"
            or step == "roll"
            or step == "fuse"
            or step == "wait_replica"
            or step == "wait_debounce"
            or step == "wait_game_roll"
            or step == "wait_tower"
        local gems = tokenAmount(data, "Gems")
        local label = shortName(snap)
        local fired, nUnit = fireKindSlots(queue, data, snap)
        if type(fired) == "table" and #fired > 0 then
            invalidateQueue()
            local uniq = {}
            local bits = {}
            for i = 1, #fired do
                local kind = fired[i]
                if not uniq[kind] then
                    uniq[kind] = true
                    bits[#bits + 1] = kind
                end
            end
            local tag = (tonumber(nUnit) or 1) > 1 and (tostring(nUnit) .. "u · " .. table.concat(bits, "+"))
                or (label .. " · " .. table.concat(bits, "+"))
            local qTag = quirkMoneyTag()
            if qTag and not uniq.quirk then
                tag = tag .. " · " .. qTag
            end
            paint("Roll", "success", tag)
            publishView(queue, snap, (tonumber(nUnit) or 1) > 1 and "roll" or bits[1], true)
            paceWork("roll")
            return
        end
        if step == "wait_gems" then
            paint("Wait gems", "muted", label .. " · " .. Core.grouped(gems))
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_traits" then
            paint("Wait traits", "muted", label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_money" then
            local qTag = quirkMoneyTag()
            paint("Wait money", "muted", qTag and (label .. " · " .. qTag) or label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_tower" then
            paint("Wait tower", "muted", label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_game_roll" then
            paint("Wait game roll", "muted", label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_grade_event" then
            paint("Wait Grade Event", "muted", label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_trait_event" then
            paint("Wait Trait Event", "muted", label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_halloween" then
            paint("Wait Halloween", "muted", label .. " · pad hub nunggu Haunt/ToT/Dice off")
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "fuse" then
            paint("Wait fuse", "muted", label)
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "wait_replica" or step == "wait_debounce" then
            publishView(queue, snap, step)
            paceWork(step)
            return
        end
        if step == "done" then
            maybeRestore(data, snap)
            if isFinished(snap) then
                markDone(snap)
            end
            stickyId = nil
            lastCurrent.snap = nil
            lastCurrent.step = nil
            paint("On", "success", label .. " done")
            publishView(queue)
            paceWork("done")
            return
        end
        if step == "grade" then
            doGrade(data, snap)
            invalidateQueue()
            paint("Grade", "success", label .. " · " .. Core.grouped(gems) .. " gems")
            publishView(queue, snap, step, true)
            paceWork(step)
            return
        end
        if step == "trait" then
            doTrait(data, snap)
            invalidateQueue()
            paint("Trait", "success", label)
            publishView(queue, snap, step, true)
            paceWork(step)
            return
        end
        if step == "quirk" then
            doQuirk(data, snap)
            invalidateQueue()
            paint("Quirk", "success", label)
            publishView(queue, snap, step, true)
            paceWork(step)
            return
        end
        if step == "rotate" then
            paint("Rotate", "muted", label)
            touchUnit(snap.id)
            local okRotate = rotateOnto(data, slots, queue, snap)
            if not okRotate then
                stickyId = nil
            end
            invalidateQueue()
            publishView(queue, snap, step, true)
            paceWork(step)
            return
        end
        if step == "upgrade" then
            doUpgrade(snap)
            invalidateQueue()
            paint("Upgrade", "success", label .. " · Lv " .. tostring(snap.level))
            publishView(queue, snap, step, true)
            paceWork(step)
        end
    end

    workLoop = Core.loop("auto_unit", {
        delay = UPGRADE_DELAY,
        step = stepOnce,
    })

    local previewLoop = Core.loop("auto_unit_preview", {
        delay = 0.3,
        step = function()
            if Core.uiIs("auto", "units") then
                paintPreview()
            end
        end,
    })
    previewLoop.setEnabled(true)
    pcall(paintPreview)

    local function syncWorkLoop()
        local on = anyOn()
        workLoop.setEnabled(on)
        previewLoop.setEnabled(true)
        setUpgradeFlag(upgradeOn)
        if on then
            pcall(function()
                ensureStockSnap(Core.data())
            end)
        end
        if not on then
            stickyId = nil
            pendingRoll = {}
            workSlot = nil
            upgradeHeldId = nil
            State.blockEquipBest = false
            State.needMachine = nil
            State.working = false
            State.holdHub = false
            paintPreview()
        end
    end

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "units",
        subLabel = "Units",
        subOrder = 2,
        order = 1,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Make Unit ( Level , Trait , Grade , Quirk )",
                expanded = false,
                status = {
                    id = "auto.unit.status",
                    persist = false,
                    value = lastStatus.value,
                    style = lastStatus.style,
                    detail = lastStatus.detail,
                },
            })
            headerApi = api
            local group = ui:CreateGroup(body)
            previewCards = {}
            local targetApi
            local maxLv1Api
            local oneInApi
            local oneInMaxApi
            local earnMaxApi
            local filterApi, unitsApi, gradesApi, traitsApi, quirksApi, levelApi
            local ruleApi, addBtnApi, ruleNoteApi
            local skipQuirksApi, maxUnitsApi

            local function inputText(a, fallback)
                if a and type(a.get) == "function" then
                    local ok, v = pcall(a.get)
                    if ok and v ~= nil and tostring(v) ~= "" then
                        return tostring(v)
                    end
                end
                return fallback
            end

            local function draftRule()
                return Rules.sanitize({
                    id = editingId or Rules.newId(),
                    enabled = true,
                    units = unitMap,
                    mode = pickMode,
                    target = inputText(targetApi, "0"),
                    earnMax = inputText(earnMaxApi, "0"),
                    maxLv1 = inputText(maxLv1Api, "0"),
                    oneIn = inputText(oneInApi, "0"),
                    oneInMax = inputText(oneInMaxApi, "0"),
                    maxLevel = maxLevel,
                    maxUnits = maxUnits,
                    grades = gradeMap,
                    traits = traitMap,
                    quirks = quirkMap,
                    skipQuirks = skipQuirkMap,
                })
            end

            local function note(text, style)
                if ruleNoteApi then
                    pcall(ruleNoteApi.set, text)
                    pcall(ruleNoteApi.setStyle, style or "detail")
                end
            end

            local function syncAddBtn()
                if addBtnApi then
                    pcall(addBtnApi.set, editingId and "Update rule" or "Add rule")
                end
            end

            local function persistRules()
                ruleList = Rules.sanitizeList(ruleList)
                if ruleApi then
                    pcall(ruleApi.set, ruleList)
                end
                compileRules()
                invalidateQueue()
                paintPreview()
            end

            local function loadDraft(rule)
                rule = Rules.sanitize(rule)
                if not rule then
                    return
                end
                if filterApi then
                    pcall(filterApi.setSelected, rule.mode)
                end
                pickMode = rule.mode
                if unitsApi then
                    pcall(unitsApi.setSelected, copyMap(rule.units))
                end
                unitMap = copyMap(rule.units)
                for _, pair in ipairs({
                    { targetApi, rule.target },
                    { earnMaxApi, rule.earnMax },
                    { maxLv1Api, rule.maxLv1 },
                    { oneInApi, rule.oneIn },
                    { oneInMaxApi, rule.oneInMax },
                    { levelApi, tostring(rule.maxLevel) },
                    { maxUnitsApi, tostring(rule.maxUnits) },
                }) do
                    if pair[1] then
                        pcall(pair[1].set, pair[2])
                    end
                end
                maxLevel = rule.maxLevel
                if gradesApi then
                    pcall(gradesApi.setSelected, copyMap(rule.grades))
                end
                if traitsApi then
                    pcall(traitsApi.setSelected, copyMap(rule.traits))
                end
                if quirksApi then
                    pcall(quirksApi.setSelected, copyMap(rule.quirks))
                end
                if skipQuirksApi then
                    pcall(skipQuirksApi.setSelected, copyMap(rule.skipQuirks))
                end
                gradeMap = copyMap(rule.grades)
                traitMap = copyMap(rule.traits)
                quirkMap = copyMap(rule.quirks)
                skipQuirkMap = copyMap(rule.skipQuirks)
                maxUnits = rule.maxUnits
                if State.syncFilterVis then
                    pcall(State.syncFilterVis)
                end
            end

            local function ruleIndex(id)
                for i, item in ipairs(ruleList) do
                    if tostring(item.id) == tostring(id) then
                        return i
                    end
                end
                return nil
            end

            local _, rApi = ui:CreateRuleList(group, {
                id = "auto.unit.rules",
                title = "Make Unit Rules",
                searchPlaceholder = "Search rules...",
                emptyText = "No rules yet. Fill the form below, then Add rule.",
                visibleRows = 4,
                persist = true,
                getItems = function()
                    return ruleList
                end,
                formatItem = function(rule, index)
                    local view = Rules.format(rule, index, Earn)
                    view.chips = {
                        {
                            text = "Edit",
                            onClick = function(item)
                                editingId = tostring(item.id)
                                loadDraft(item)
                                syncAddBtn()
                                note("Editing R" .. tostring(ruleIndex(item.id) or "?") .. ". Change fields, then Update rule.", "warn")
                            end,
                        },
                    }
                    return view
                end,
                onLoad = function(list)
                    ruleList = Rules.sanitizeList(list)
                    rulesLoaded = true
                    compileRules()
                    invalidateQueue()
                end,
                onToggle = function(rule, enabled)
                    local i = ruleIndex(type(rule) == "table" and rule.id)
                    if not i then
                        return
                    end
                    if enabled == true then
                        local copy = Rules.sanitize(ruleList[i])
                        copy.enabled = true
                        local j = Rules.findOverlap(copy, ruleList, Earn, copy.id)
                        if j then
                            note("R" .. i .. " overlaps R" .. j .. " (same Earn / 1-in range). Not enabled.", "error")
                            persistRules()
                            return
                        end
                    end
                    ruleList[i].enabled = enabled == true
                    persistRules()
                end,
                onDelete = function(rule)
                    local i = ruleIndex(type(rule) == "table" and rule.id)
                    if i then
                        if editingId == tostring(ruleList[i].id) then
                            editingId = nil
                            syncAddBtn()
                        end
                        table.remove(ruleList, i)
                        persistRules()
                    end
                end,
            })
            ruleApi = rApi

            local function syncFilterVis()
                local earnOn = pickMode ~= "onein"
                if targetApi and type(targetApi.setVisible) == "function" then
                    pcall(targetApi.setVisible, earnOn)
                end
                if earnMaxApi and type(earnMaxApi.setVisible) == "function" then
                    pcall(earnMaxApi.setVisible, earnOn)
                end
                if maxLv1Api and type(maxLv1Api.setVisible) == "function" then
                    pcall(maxLv1Api.setVisible, earnOn)
                end
                if oneInApi and type(oneInApi.setVisible) == "function" then
                    pcall(oneInApi.setVisible, not earnOn)
                end
                if oneInMaxApi and type(oneInMaxApi.setVisible) == "function" then
                    pcall(oneInMaxApi.setVisible, not earnOn)
                end
            end

            ui:CreateRowLabel(group, {
                text = "Rule editor (Earn / 1-in range must not overlap another rule for the same unit)",
                wrap = true,
                style = "section",
            })
            _, unitsApi = ui:CreateRowDropdown(group, {
                id = "auto.unit.ruleUnits",
                label = "Units",
                mode = "multi",
                placeholder = "All units",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = unitItems,
                onChanged = function(a, b)
                    unitMap = copyMap(dropdownValue(a, b))
                end,
            })
            _, filterApi = ui:CreateRowDropdown(group, {
                id = "auto.unit.filter",
                label = "Filter",
                placeholder = "Earn",
                clearable = false,
                persist = true,
                preserveItemOrder = true,
                initial = pickMode,
                getItems = function()
                    return {
                        { key = "earn", name = "Earn" },
                        { key = "onein", name = "1-in" },
                    }
                end,
                onChanged = function(a, b)
                    pickMode = clampPickMode(dropdownValue(a, b))
                    syncFilterVis()
                    invalidateQueue()
                    paintPreview()
                end,
            })
            local _, _, _, tApi = ui:CreateRowInput(group, {
                id = "auto.unit.target",
                label = "Target earn",
                hintText = "Worst picked grade x trait at max level must beat this.",
                initial = "200qd",
                persist = true,
                onChanged = function(text)
                    targetEarn = Earn.parseCompact(text)
                    invalidateQueue()
                    paintPreview()
                end,
            })
            targetApi = tApi
            local _, _, _, eMaxApi = ui:CreateRowInput(group, {
                id = "auto.unit.earnMax",
                label = "Target earn max",
                hintText = "Upper earn bound for this rule. 0 = no max.",
                initial = "0",
                persist = true,
                onChanged = function(text)
                    earnMaxDraft = Earn.parseCompact(text) or 0
                end,
            })
            earnMaxApi = eMaxApi
            local _, _, _, mApi = ui:CreateRowInput(group, {
                id = "auto.unit.maxLv1",
                label = "Max earn at Lv1",
                hintText = "Base Lv1 only. Current grade/trait ignored.",
                initial = "1sx",
                persist = true,
                onChanged = function(text)
                    maxEarnLv1 = Earn.parseCompact(text)
                    invalidateQueue()
                    paintPreview()
                end,
            })
            maxLv1Api = mApi
            local _, _, _, oApi = ui:CreateRowInput(group, {
                id = "auto.unit.oneIn",
                label = "1-in min",
                hintText = "Min 1-in. 0 = no min. No earn check. Grade / trait / level still apply.",
                initial = "1qd",
                persist = true,
                onChanged = function(text)
                    oneIn = Earn.parseCompact(text)
                    invalidateQueue()
                    paintPreview()
                end,
            })
            oneInApi = oApi
            local _, _, _, oMaxApi = ui:CreateRowInput(group, {
                id = "auto.unit.oneInMax",
                label = "1-in max",
                hintText = "Max 1-in. 0 = no max.",
                initial = "0",
                persist = true,
                onChanged = function(text)
                    oneInMax = Earn.parseCompact(text)
                    invalidateQueue()
                    paintPreview()
                end,
            })
            oneInMaxApi = oMaxApi
            syncFilterVis()
            State.syncFilterVis = syncFilterVis
            local _, _, _, lvApi = ui:CreateRowInput(group, {
                id = "auto.unit.maxLevel",
                label = "Max level",
                initial = "60",
                persist = true,
                onChanged = function(text)
                    maxLevel = clampLevel(text)
                end,
            })
            levelApi = lvApi
            _, gradesApi = ui:CreateRowDropdown(group, {
                id = "auto.unit.grades",
                label = "Grades",
                mode = "multi",
                placeholder = "Pick grades...",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 18,
                getItems = gradeItems,
                onChanged = function(a, b)
                    gradeMap = copyMap(dropdownValue(a, b))
                end,
            })
            _, traitsApi = ui:CreateRowDropdown(group, {
                id = "auto.unit.traits",
                label = "Traits",
                mode = "multi",
                placeholder = "Pick traits...",
