    Core.onSync(function(values, ui)
        if values["auto.unit.filter"] ~= nil then
            pickMode = clampPickMode(values["auto.unit.filter"])
        else
            pickMode = "earn"
        end
        if values["auto.unit.oneIn"] ~= nil then
            oneIn = Earn.parseCompact(values["auto.unit.oneIn"])
        else
            oneIn = Earn.parseCompact("1qd")
        end
        if values["auto.unit.oneInMax"] ~= nil then
            oneInMax = Earn.parseCompact(values["auto.unit.oneInMax"])
        else
            oneInMax = 0
        end
        if values["auto.unit.target"] ~= nil then
            targetEarn = Earn.parseCompact(values["auto.unit.target"])
        end
        if values["auto.unit.maxLv1"] ~= nil then
            maxEarnLv1 = Earn.parseCompact(values["auto.unit.maxLv1"])
        end
        if values["auto.unit.maxLevel"] ~= nil then
            maxLevel = clampLevel(values["auto.unit.maxLevel"])
        end
        if values["auto.unit.maxUnits"] ~= nil then
            maxUnits = clampMaxUnits(values["auto.unit.maxUnits"])
        else
            maxUnits = DEFAULT_MAX_UNITS
        end
        if values["auto.unit.grades"] ~= nil then
            gradeMap = copyMap(values["auto.unit.grades"])
        end
        if values["auto.unit.traits"] ~= nil then
            traitMap = copyMap(values["auto.unit.traits"])
        end
        if values["auto.unit.quirks"] ~= nil then
            quirkMap = copyMap(values["auto.unit.quirks"])
        end
        if values["auto.unit.sortBy"] ~= nil then
            sortBy = clampSortBy(values["auto.unit.sortBy"])
        else
            sortBy = "highest"
        end
        if values["auto.unit.keepPercent"] ~= nil then
            keepPercent = tonumber(values["auto.unit.keepPercent"]) or keepPercent
        end
        if values["auto.unit.gradeEventPct"] ~= nil then
            gradeEventPct = clampPct(values["auto.unit.gradeEventPct"])
        end
        if values["auto.unit.traitEventPct"] ~= nil then
            traitEventPct = clampPct(values["auto.unit.traitEventPct"])
        end
        gradeEventMode = values["auto.unit.gradeEvent"] == true
        traitEventMode = values["auto.unit.traitEvent"] == true
        if values["auto.unit.ruleUnits"] ~= nil then
            unitMap = copyMap(values["auto.unit.ruleUnits"])
        end
        if values["auto.unit.earnMax"] ~= nil then
            earnMaxDraft = Earn.parseCompact(values["auto.unit.earnMax"]) or 0
        end
        if values["auto.unit.ruleSkipQuirks"] ~= nil then
            skipQuirkMap = copyMap(values["auto.unit.ruleSkipQuirks"])
        end
        local savedRules = values["auto.unit.rules"]
        if type(savedRules) == "table" then
            local legacyCap = false
            for _, raw in ipairs(savedRules) do
                if type(raw) == "table" and raw.maxUnits == nil then
                    raw.maxUnits = maxUnits
                    legacyCap = true
                end
            end
            ruleList = Rules.sanitizeList(savedRules)
            rulesLoaded = true
            if legacyCap and ui and type(ui.SetValues) == "function" then
                pcall(ui.SetValues, ui, { ["auto.unit.rules"] = ruleList }, false)
            end
        elseif not rulesLoaded and (next(gradeMap) or next(traitMap) or next(quirkMap)) then
            local function txt(id, fallback)
                local v = values[id]
                return v ~= nil and tostring(v) or fallback
            end
            ruleList = Rules.sanitizeList({
                {
                    units = {},
                    mode = pickMode,
                    target = txt("auto.unit.target", "200qd"),
                    earnMax = "0",
                    maxLv1 = txt("auto.unit.maxLv1", "1sx"),
                    oneIn = txt("auto.unit.oneIn", "1qd"),
                    oneInMax = txt("auto.unit.oneInMax", "0"),
                    maxLevel = maxLevel,
                    maxUnits = maxUnits,
                    grades = gradeMap,
                    traits = traitMap,
                    quirks = quirkMap,
                },
            })
            rulesLoaded = true
            if ui and type(ui.SetValues) == "function" then
                pcall(ui.SetValues, ui, { ["auto.unit.rules"] = ruleList }, false)
            end
        end
        compileRules()
        invalidateStockSnap()
        gradeOn = values["auto.unit.grade"] == true
        traitOn = values["auto.unit.trait"] == true
        quirkOn = values["auto.unit.quirk"] == true
        upgradeOn = values["auto.unit.upgrade"] == true
        invalidateQueue()
        syncWorkLoop()
        if type(State.syncFilterVis) == "function" then
            pcall(State.syncFilterVis)
        end
        paintPreview()
    end)
end
 end, required = true, feature = true },
    { key = "AutoTrade", name = "Auto Trade", factory = function() -- AUTO → Trade.
-- Once: tombol Send trade. >20 unique = batch: confirm sekali, kirim 20, lanjut otomatis setelah Completed. Auto: toggle Enable Auto send trade. Accept terpisah.
-- State machine + timeout. CancelTrade hanya trade milik kita. NodeHubNeonUI tidak diubah.

return function(Core)
    local G = Core.env()
    local RS = game:GetService("ReplicatedStorage")
    local Players = game:GetService("Players")
    local LP = Core.player() or Players.LocalPlayer
    local NONE = "None"
    local FAST = 0.12
    local IDLE = 0.35
    local MAX_UNIQUE = 20
    local MIN_ROLLS = 1000
    local MIN_AGE = 14
    local REQ_WAIT = 8
    local OFFER_WAIT = 20
    local READY_WAIT = 16
    local WAIT_THEM = 24
    local END_WAIT = 14
    local COMPARE = {
        { key = "below", name = "Below" },
        { key = "above", name = "Above" },
    }
    local MODES = {
        { key = "once", name = "Once" },
        { key = "auto", name = "Auto" },
    }
    local STACK_KINDS = {
        { key = "potion", name = "Potion", order = 1 },
        { key = "spin", name = "Spin", order = 2 },
        { key = "gear", name = "Gear", order = 3 },
        { key = "gems", name = "Gems", order = 4 },
        { key = "trait_reroll", name = "Trait Reroll", order = 5 },
    }
    local ALL_KINDS = {
        { key = "unit", name = "Unit", order = 0 },
        { key = "potion", name = "Potion", order = 1 },
        { key = "spin", name = "Spin", order = 2 },
        { key = "gear", name = "Gear", order = 3 },
        { key = "gems", name = "Gems", order = 4 },
        { key = "trait_reroll", name = "Trait Reroll", order = 5 },
    }

    local old = G.AnimeDiceAutoTrade
    if type(old) == "table" then
        if type(old.setEnabled) == "function" then
            pcall(old.setEnabled, false)
        end
        if type(old.stop) == "function" then
            pcall(old.stop)
        end
    end

    local function readVal(v)
        if type(v) == "function" then
            local ok, r = pcall(v)
            if ok then
                return r
            end
        end
        return v
    end

    local function copyMap(src)
        local out = {}
        if type(src) ~= "table" then
            return out
        end
        for k, v in pairs(src) do
            if v == true or v == 1 or v == "true" then
                out[tostring(k)] = true
            elseif type(v) == "table" then
                local key = v.key or v.id or v.name
                if key ~= nil and key ~= false then
                    out[tostring(key)] = true
                end
            elseif type(k) == "number" and v ~= nil and v ~= false then
                out[tostring(v)] = true
            end
        end
        return out
    end

    local function mapSize(map)
        local n = 0
        if type(map) ~= "table" then
            return 0
        end
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function mapPreview(map)
        if mapSize(map) == 0 then
            return "any"
        end
        local first
        local extra = 0
        for k in pairs(map) do
            if not first then
                first = k
            else
                extra = extra + 1
            end
        end
        if extra > 0 then
            return first .. ", +" .. tostring(extra)
        end
        return first
    end

    local function escapeRich(s)
        s = tostring(s or "")
        return s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
    end

    local function dropdownValue(a, b)
        if a == "multi" then
            return type(b) == "table" and b or a
        end
        if a == "single" then
            if type(b) == "table" then
                return b.key or b.id or b.name
            end
            return b
        end
        if type(a) == "table" then
            return a.key or a.id or a
        end
        if type(b) == "table" then
            return b.key or b.id or b
        end
        return a
    end

    local SUFFIX = {
        k = 1e3,
        m = 1e6,
        b = 1e9,
        t = 1e12,
        qd = 1e15,
        qi = 1e18,
        sx = 1e21,
        sp = 1e24,
    }

    local function parseNum(text)
        text = tostring(text or ""):gsub(",", ""):gsub("%s", "")
        if text == "" then
            return 0
        end
        local n = tonumber(text)
        if n then
            return math.max(0, n)
        end
        local ok, value = pcall(function()
            return require(RS.Packages.NumberFormatter).ParseCompact(text)
        end)
        if ok and tonumber(value) then
            return math.max(0, tonumber(value))
        end
        local num, suf = text:lower():match("^([%d%.]+)([a-z]+)$")
        n = tonumber(num)
        local mul = suf and SUFFIX[suf]
        if n and mul then
            return math.max(0, n * mul)
        end
        return 0
    end

    local function clampMode(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "below"))
        if mode == "above" or mode == "over" or mode == ">=" then
            return "above"
        end
        return "below"
    end

    local function clampTradeMode(mode)
        if type(mode) == "table" then
            mode = mode.key or mode.id or mode.name
        end
        mode = string.lower(tostring(mode or "once"))
        if mode == "auto" then
            return "auto"
        end
        return "once"
    end

    local function matchesNum(value, n, mode)
        n = tonumber(n) or 0
        if n <= 0 then
            return true
        end
        value = tonumber(value) or 0
        if clampMode(mode) == "above" then
            return value >= n
        end
        return value <= n
    end

    local function newRuleId()
        return tostring(os.clock()) .. "-" .. tostring(math.random(1000, 9999))
    end

    local function sanitizeRule(rule)
        if type(rule) ~= "table" then
            return nil
        end
        local fields = {}
        local src = type(rule.fields) == "table" and rule.fields or nil
        if src then
            for _, key in ipairs({ "rarity", "mutation", "trait", "grade", "level", "earn", "chance" }) do
                if src[key] == true or src[key] == 1 or src[key] == "true" then
                    fields[key] = true
                end
            end
        end
        local earnMin = tostring(rule.earnMin or "")
        local earnMax = tostring(rule.earnMax or "")
        if earnMin == "" and earnMax == "" then
            local n = tostring(rule.earnRule or "0")
            if clampMode(rule.earnMode) == "above" then
                earnMin = n
                earnMax = "0"
            else
                earnMin = "0"
                earnMax = n
            end
        end
        if earnMin == "" then
            earnMin = "0"
        end
        if earnMax == "" then
            earnMax = "0"
        end
        local chanceMin = tostring(rule.chanceMin or "")
        local chanceMax = tostring(rule.chanceMax or "")
        if chanceMin == "" and chanceMax == "" then
            local n = tostring(rule.chanceRule or "0")
            if clampMode(rule.chanceMode) == "above" then
                chanceMin = n
                chanceMax = "0"
            else
                chanceMin = "0"
                chanceMax = n
            end
        end
        if chanceMin == "" then
            chanceMin = "0"
        end
        if chanceMax == "" then
            chanceMax = "0"
        end
        return {
            id = tostring(rule.id or newRuleId()),
            enabled = rule.enabled ~= false,
            fields = fields,
            rarities = copyMap(rule.rarities),
            mutations = copyMap(rule.mutations),
            traits = copyMap(rule.traits),
            grades = copyMap(rule.grades),
            levelRule = tostring(rule.levelRule or "0"),
            levelMode = clampMode(rule.levelMode),
            earnMin = earnMin,
            earnMax = earnMax,
            chanceMin = chanceMin,
            chanceMax = chanceMax,
        }
    end

    local function setRuleList(list)
        local out = {}
        if type(list) == "table" then
            for _, rule in ipairs(list) do
                local clean = sanitizeRule(rule)
                if clean then
                    out[#out + 1] = clean
                end
            end
        end
        return out
    end

    local function enabledRules(list)
        local out = {}
        for _, rule in ipairs(list) do
            if rule.enabled ~= false then
                out[#out + 1] = rule
            end
        end
        return out
    end

    local function fieldOn(rule, key)
        local fields = type(rule) == "table" and rule.fields or nil
        if type(fields) ~= "table" or mapSize(fields) == 0 then
            return true
        end
        return fields[key] == true
    end

    local function inMap(map, value)
        if mapSize(map) == 0 then
            return false
        end
        return map[tostring(value or NONE)] == true
    end

    local function earnLabel(rule)
        local lo = parseNum(rule and rule.earnMin)
        local hi = parseNum(rule and rule.earnMax)
        if lo > 0 and hi > 0 then
            if lo > hi then
                lo, hi = hi, lo
            end
            return Core.compact(lo) .. "-" .. Core.compact(hi) .. "/s"
        end
        if lo > 0 then
            return "≥ " .. Core.compact(lo) .. "/s"
        end
        if hi > 0 then
            return "≤ " .. Core.compact(hi) .. "/s"
        end
        return "any/s"
    end

    local function chanceLabel(rule)
        local lo = parseNum(rule and rule.chanceMin)
        local hi = parseNum(rule and rule.chanceMax)
        if lo > 0 and hi > 0 then
            if lo > hi then
                lo, hi = hi, lo
            end
            return "1-in " .. Core.compact(lo) .. "-" .. Core.compact(hi)
        end
        if lo > 0 then
            return "1-in ≥ " .. Core.compact(lo)
        end
        if hi > 0 then
            return "1-in ≤ " .. Core.compact(hi)
        end
        return "1-in any"
    end

    local function levelLabel(rule)
        local word = clampMode(rule and rule.levelMode) == "above" and "Above" or "Below"
        local n = parseNum(rule and rule.levelRule)
        if n > 0 then
            return "Lv " .. word .. " " .. tostring(math.floor(n + 0.5))
        end
        return "Lv any"
    end

    local function ruleMatches(rule, info)
        if type(rule) ~= "table" or type(info) ~= "table" then
            return false
        end
        if fieldOn(rule, "rarity") and not inMap(rule.rarities, info.rarity) then
            return false
        end
        if fieldOn(rule, "mutation") and not inMap(rule.mutations, info.mutation or NONE) then
            return false
        end
        if fieldOn(rule, "trait") and not inMap(rule.traits, info.trait or NONE) then
            return false
        end
        if fieldOn(rule, "grade") and not inMap(rule.grades, info.grade or NONE) then
            return false
        end
        if fieldOn(rule, "level") and not matchesNum(info.level, parseNum(rule.levelRule), rule.levelMode) then
            return false
        end
        if fieldOn(rule, "earn") then
            local lo = parseNum(rule.earnMin)
            local hi = parseNum(rule.earnMax)
            if lo > 0 and hi > 0 and lo > hi then
                lo, hi = hi, lo
            end
            local n = tonumber(info.earn) or 0
            if lo > 0 and n < lo then
                return false
            end
            if hi > 0 and n > hi then
                return false
            end
        end
        if fieldOn(rule, "chance") then
            local lo = parseNum(rule.chanceMin)
            local hi = parseNum(rule.chanceMax)
            if lo > 0 and hi > 0 and lo > hi then
                lo, hi = hi, lo
            end
            local n = tonumber(info.chance)
            if lo > 0 or hi > 0 then
                if not n then
                    return false
                end
                if lo > 0 and n < lo then
                    return false
                end
                if hi > 0 and n > hi then
                    return false
                end
            end
        end
        return true
    end

    local function unitAllowed(list, info)
        local enabled = enabledRules(list)
        if #enabled == 0 then
            return false
        end
        for _, rule in ipairs(enabled) do
            if ruleMatches(rule, info) then
                return true
            end
        end
        return false
    end

    local function formatRule(rule)
        rule = sanitizeRule(rule) or {}
        local parts = {}
        local function add(text, style)
            text = tostring(text or "")
            if text == "" then
                return
            end
            if #parts > 0 then
                parts[#parts + 1] = { text = " · ", style = "sep" }
            end
            parts[#parts + 1] = { text = text, style = style }
        end
        if fieldOn(rule, "rarity") then
            add(mapPreview(rule.rarities), "rarity")
        end
        if fieldOn(rule, "mutation") then
            add(mapPreview(rule.mutations), "fruit")
        end
        if fieldOn(rule, "trait") then
            add(mapPreview(rule.traits), "kg")
        end
        if fieldOn(rule, "grade") then
            add(mapPreview(rule.grades), "rarity")
        end
        if fieldOn(rule, "level") then
            add(levelLabel(rule), "kg")
        end
        if fieldOn(rule, "earn") then
            add(earnLabel(rule), "rarity")
        end
        if fieldOn(rule, "chance") then
            add(chanceLabel(rule), "kg")
        end
        if #parts == 0 then
            add("Any unit", "default")
        end
        return {
            id = rule.id,
            enabled = rule.enabled ~= false,
            parts = parts,
        }
    end

    local function sortedItems(mod, extra)
        local out = {}
        if extra then
            out[#out + 1] = extra
        end
        if type(mod) ~= "table" then
            return out
        end
        local rows = {}
        for key, info in pairs(mod) do
            if type(key) == "string" and type(info) == "table" then
                rows[#rows + 1] = {
                    key = key,
                    label = key,
                    order = tonumber(info.order or info.sortOrder) or 99,
                }
            end
        end
        table.sort(rows, function(a, b)
            if a.order == b.order then
                return a.label < b.label
            end
            return a.order < b.order
        end)
        for _, row in ipairs(rows) do
            out[#out + 1] = row
        end
        return out
    end

    local rarityItemsCache
    local function rarityItems()
        if rarityItemsCache then
            return rarityItemsCache
        end
        local out = {}
        pcall(function()
            local Rarities = require(RS.Framework.Other.Rarities)
            local refs = Rarities.Refs
            for _, name in pairs(refs) do
                local info = Rarities.Get(name)
                out[#out + 1] = {
                    key = name,
                    label = name,
                    order = type(info) == "table" and tonumber(info.sortOrder) or 99,
                }
            end
        end)
        table.sort(out, function(a, b)
            if a.order == b.order then
                return tostring(a.label) < tostring(b.label)
            end
            return a.order < b.order
        end)
        rarityItemsCache = out
        return out
    end

