    local function wrapFieldStack(parent)
        local wrap = Instance.new("Frame")
        wrap.Name = "FieldStack"
        wrap.BackgroundTransparency = 1
        wrap.BorderSizePixel = 0
        wrap.Size = UDim2.new(1, 0, 0, 0)
        wrap.AutomaticSize = Enum.AutomaticSize.Y
        wrap.LayoutOrder = #parent:GetChildren() + 1
        wrap.Parent = parent
        local list = Instance.new("UIListLayout")
        list.FillDirection = Enum.FillDirection.Vertical
        list.SortOrder = Enum.SortOrder.LayoutOrder
        list.Padding = UDim.new(0, 0)
        list.Parent = wrap
        return wrap
    end

    local registry
    local function entryConfig(name)
        if type(registry) ~= "table" then
            pcall(function()
                registry = require(RS.Framework.Features.Inventory.EntryRegistry)
            end)
        end
        if type(registry) ~= "table" or type(registry.getEntryConfig) ~= "function" then
            return nil
        end
        local ok, cfg = pcall(registry.getEntryConfig, name)
        if ok and type(cfg) == "table" then
            return cfg
        end
        return nil
    end

    local function kindConfig(kind)
        if type(registry) ~= "table" or type(registry.getKindConfig) ~= "function" then
            return nil
        end
        local ok, cfg = pcall(registry.getKindConfig, kind)
        if ok and type(cfg) == "table" then
            return cfg
        end
        return nil
    end

    local function kindKey(cfg, name)
        name = tostring(name or "")
        if name == "Tickets" then
            return nil
        end
        if name == "Gems" then
            return "gems"
        end
        if name == "Trait Reroll" then
            return "trait_reroll"
        end
        local kind = type(cfg) == "table" and cfg.kind or nil
        if kind == "Unit" then
            return "unit"
        end
        if kind == "Boost" then
            return "potion"
        end
        if kind == "Spin" then
            return "spin"
        end
        if kind == "Gear" then
            return "gear"
        end
        if kind == "Token" then
            return nil
        end
        return nil
    end

    local function profile(item, id)
        if type(item) ~= "table" then
            return nil
        end
        local name = readVal(item.name)
        if type(name) ~= "string" or name == "" or name == "Tickets" then
            return nil
        end
        local cfg = entryConfig(name)
        if not cfg then
            return nil
        end
        local attrs = type(item.attributes) == "table" and item.attributes or item
        local opts = {
            mutation = readVal(attrs.mutation),
            trait = readVal(attrs.trait),
            grade = readVal(attrs.grade),
            level = readVal(attrs.level),
        }
        if type(opts.mutation) ~= "string" or opts.mutation == "" then
            opts.mutation = nil
        end
        local rarity
        if type(cfg.getRarity) == "function" then
            local ok, value = pcall(cfg.getRarity, opts)
            if ok and value ~= nil then
                rarity = tostring(value)
            end
        end
        local earn = 0
        if type(cfg.income) == "function" then
            local ok, value = pcall(cfg.income, opts)
            earn = ok and tonumber(value) or 0
        end
        local chance
        if type(cfg.chance) == "function" then
            local ok, value = pcall(cfg.chance, opts)
            chance = ok and tonumber(value) or nil
        end
        local kcfg = kindConfig(cfg.kind)
        local amount = tonumber(readVal(item.amount)) or 1
        return {
            key = tostring(id),
            name = name,
            kind = cfg.kind,
            tradeKind = kindKey(cfg, name),
            stackable = type(kcfg) == "table" and kcfg.stackable == true,
            rarity = rarity,
            mutation = opts.mutation,
            trait = opts.trait,
            grade = opts.grade,
            quirk = readVal(attrs.quirk),
            level = opts.level,
            earn = earn,
            chance = chance,
            locked = readVal(attrs.locked) == true,
            amount = amount,
        }
    end

    local function plottedIds(data)
        local out = {}
        for _, slot in ipairs(Core.slots()) do
            local getter = data.Slots and data.Slots[tostring(slot)]
            if getter ~= nil then
                local ok, row = pcall(getter)
                if ok and type(row) == "table" then
                    local id = readVal(row.unitId)
                    if type(id) == "string" and id ~= "" then
                        out[id] = true
                    end
                end
            end
        end
        return out
    end

    local function reservedId(id)
        local au = G.AnimeDiceAutoUnit
        if type(au) == "table" and type(au.isReserved) == "function" then
