            return ok and on == true
        end
        return false
    end

    local function pendingTrade()
        if type(Core.pendingTrade) == "function" then
            local ok, on = pcall(Core.pendingTrade)
            if ok then
                return on == true
            end
        end
        local row
        pcall(function()
            row = Core.data().PendingTrade()
        end)
        return type(row) == "table" and row.applied ~= true
    end

    local requestTrade, respondReq, changeOffer, advanceTrade, cancelTrade, setRequests, tradeEvent, tradingEnabled
    local function nets()
        if requestTrade and tradeEvent then
            return true
        end
        local ok = pcall(function()
            local comm = require(RS.Packages.Network).ClientComm.new(RS.Network, false, "TradeService")
            requestTrade = comm:GetSignal("RequestTrade")
            respondReq = comm:GetSignal("RespondToRequest")
            changeOffer = comm:GetSignal("ChangeOffer")
            advanceTrade = comm:GetSignal("AdvanceTrade")
            cancelTrade = comm:GetSignal("CancelTrade")
            setRequests = comm:GetSignal("SetTradeRequestsEnabled")
            tradeEvent = comm:GetSignal("TradeEvent")
            tradingEnabled = comm:GetProperty("TradingEnabled")
        end)
        return ok and requestTrade ~= nil and tradeEvent ~= nil
    end

