    local function clampStack(n)
        n = tonumber(n) or 1
        n = math.floor(n + 0.5)
        if n < 1 then
            n = 1
        elseif n > 1e12 then
            n = 1e12
        end
        return n
    end

    local function amtOf(store, kind, name)
        local bag = type(store) == "table" and store[kind]
        if type(bag) ~= "table" then
            return 1
        end
        return clampStack(bag[tostring(name or "")] or 1)
    end

    local function setAmt(store, kind, name, n)
        name = tostring(name or "")
        if name == "" or type(store) ~= "table" then
            return
        end
        if type(store[kind]) ~= "table" then
            store[kind] = {}
        end
        store[kind][name] = clampStack(n)
    end

    local function pickedNames(map)
        local keys = {}
        if type(map) ~= "table" then
            return keys
        end
        for k, on in pairs(map) do
            if on == true then
                keys[#keys + 1] = tostring(k)
            end
        end
        table.sort(keys)
        return keys
    end

    autoUi.allHelp = {}
    function autoUi.allHelp.is(name)
        return type(name) == "string" and string.sub(name, 1, 7) == "__all__"
    end
    function autoUi.allHelp.key(group)
        if type(group) ~= "string" or group == "" then
            return "__all__"
        end
        return "__all__" .. group
    end
    function autoUi.allHelp.potionBuff(name)
        local cat = Core.potions and Core.potions()
        if type(cat) ~= "table" or type(cat.byName) ~= "function" then
            return nil
        end
        local ok, item = pcall(cat.byName, name)
        local buff = ok and item and item.buff
        if buff == "Luck" then
            return "luck"
        end
        if buff == "Income" then
            return "income"
        end
        if buff == "Damage" then
            return "damage"
        end
        return nil
    end
    function autoUi.allHelp.gearHas(name, goal)
        local cat = Core.gears and Core.gears()
        if type(cat) ~= "table" or type(cat.byName) ~= "function" or type(cat.score) ~= "function" then
            return false
        end
        local ok, item = pcall(cat.byName, name)
        if not ok or type(item) ~= "table" then
            return false
        end
        local okScore, n = pcall(cat.score, item, goal)
        return okScore and (tonumber(n) or 0) > 0
    end
    function autoUi.allHelp.covers(kind, name, picks)
        if type(picks) ~= "table" or type(name) ~= "string" or name == "" then
            return false
        end
        if picks["__all__"] == true then
            return true
        end
        if kind == "potion" then
            local g = autoUi.allHelp.potionBuff(name)
            return g ~= nil and picks[autoUi.allHelp.key(g)] == true
        end
        if kind == "gear" then
            if picks["__all__luck"] == true and autoUi.allHelp.gearHas(name, "luck") then
                return true
            end
            if picks["__all__income"] == true and autoUi.allHelp.gearHas(name, "income") then
                return true
            end
            if picks["__all__damage"] == true and autoUi.allHelp.gearHas(name, "damage") then
                return true
            end
        end
        return false
    end
    function autoUi.allHelp.options(kind)
        local out = {}
        local function add(key, label, order)
            out[#out + 1] = { key = key, label = label, order = order }
        end
        if kind == "potion" then
            add("__all__", "All Potion", "!0")
            add("__all__luck", "All Luck", "!1")
            add("__all__income", "All Income", "!2")
            add("__all__damage", "All Damage", "!3")
        elseif kind == "gear" then
            add("__all__", "All Gear", "!0")
            add("__all__luck", "All Luck", "!1")
            add("__all__income", "All Income", "!2")
            add("__all__damage", "All Damage", "!3")
        elseif kind == "spin" then
            add("__all__", "All Spin", "!0")
        elseif kind == "gems" then
            add("__all__", "All Gems", "!0")
        elseif kind == "trait_reroll" then
            add("__all__", "All Trait Reroll", "!0")
        end
        return out
    end
    function autoUi.allHelp.amtLabel(name, total)
        return tostring(name) .. "  (" .. Core.compact(tonumber(total) or 0) .. ")"
    end
    function autoUi.allHelp.setLabel(rec, text)
        if type(rec) ~= "table" then
            return
        end
        if type(rec.setLabel) == "function" then
            pcall(rec.setLabel, text)
            return
        end
        local row = rec.row or rec.root
        if not row then
            return
        end
        local lab = row:FindFirstChild("Label")
        if typeof(lab) == "Instance" and lab:IsA("TextLabel") then
            pcall(function()
                lab.Text = tostring(text or "")
            end)
        end
    end
    function autoUi.allHelp.needAmt(kind, name, picks)
        if autoUi.allHelp.is(name) then
            return false
        end
        return autoUi.allHelp.covers(kind, name, picks) ~= true
    end

    local function clampMaxUnits(n)
        n = tonumber(n) or maxUnitsSend
        n = math.floor(n + 0.5)
        if n < 1 then
            n = 1
        elseif n > MAX_UNIQUE then
            n = MAX_UNIQUE
        end
        return n
    end

    local function inSession()
        return session ~= nil and session.ours == true
    end

    local function isBusy()
        return inSession() and phase ~= "idle" and phase ~= "cooldown"
    end

    local function sending()
        return onceRun == true or (mode == "auto" and autoSendOn == true)
    end

    local function shouldRun()
        return sending() or acceptOn == true
    end

    local function sendBusyNow()
        if onceConfirmOpen or onceRun then
            return true
        end
        if session and session.ours and session.role == "send" then
            return phase ~= "idle"
        end
        return false
    end

    local function paintSendHeader()
        if stopped then
            return
        end
        if sendBusyNow() or sending() then
            Core.paintHeader(headerApi, lastStatus.value, lastStatus.style, lastStatus.detail)
            return
        end
        if mode == "auto" then
            Core.paintHeader(headerApi, "Off", "muted", "turn Auto send on")
            return
        end
        Core.paintHeader(headerApi, "Ready", "muted", "press Send trade")
    end

    local function parseNameList(text)
        local map = {}
        for part in string.gmatch(tostring(text or ""), "[^%s,;|]+") do
            part = string.gsub(part, "^@", "")
            part = string.lower(part)
            if part ~= "" then
                map[part] = true
            end
        end
        return map
    end

    local function countNames(map)
        local n = 0
        for _ in pairs(map) do
            n = n + 1
        end
        return n
    end

    local function setAcceptList(text)
        acceptListText = tostring(text or "")
        acceptNames = parseNameList(acceptListText)
    end

    local function livePlayer(id)
        id = tostring(id or "")
        if id == "" then
            return nil
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if tostring(p.UserId) == id then
                return p
            end
        end
        return nil
    end

    local function playerLabel(p)
        if not p then
            return ""
        end
        return tostring(p.DisplayName) .. "  @" .. tostring(p.Name)
    end

    local function rememberPlayer(p)
        if not p or p == LP then
            return
        end
        local id = tostring(p.UserId or "")
        if id == "" or id == "nil" then
            return
        end
        acceptPlayerMeta[id] = {
            name = tostring(p.Name or ""),
            display = tostring(p.DisplayName or ""),
            label = playerLabel(p),
        }
    end

    local function persistPlayerMeta()
        local ui = hubUi
        if ui and type(ui._touchConfig) == "function" then
            pcall(function()
                ui:_touchConfig("auto.trade.accept.playerMeta", acceptPlayerMeta)
            end)
            return
        end
        if type(G.__RideAPetSavedConfig) ~= "table" then
            G.__RideAPetSavedConfig = {}
        end
        G.__RideAPetSavedConfig["auto.trade.accept.playerMeta"] = acceptPlayerMeta
    end

    local function loadPlayerMeta(src)
        local nextMeta = {}
        if type(src) == "table" then
            for k, v in pairs(src) do
                local id = tostring(k)
                if type(v) == "table" and id ~= "" then
                    local name = tostring(v.name or "")
                    local display = tostring(v.display or "")
                    local label = tostring(v.label or "")
                    if label == "" then
                        if display ~= "" and name ~= "" then
                            label = display .. "  @" .. name
                        else
                            label = display ~= "" and display or (name ~= "" and name or id)
                        end
                    end
                    nextMeta[id] = {
                        name = name,
                        display = display,
                        label = label,
                    }
                end
            end
        end
        acceptPlayerMeta = nextMeta
    end

    local function setAcceptPlayers(map)
        acceptPlayers = copyMap(map)
        for uid in pairs(acceptPlayers) do
            local p = livePlayer(uid)
            if p then
                rememberPlayer(p)
            end
        end
        for uid in pairs(acceptPlayerMeta) do
            if acceptPlayers[uid] ~= true then
                acceptPlayerMeta[uid] = nil
            end
        end
        persistPlayerMeta()
    end

    local function whitelistSize()
        return countNames(acceptNames) + mapSize(acceptPlayers)
    end

    local function acceptPlayerItems()
        local seen = {}
        local out = {}
        local function add(uid, label, online)
            uid = tostring(uid or "")
            if uid == "" or seen[uid] then
                return
            end
            seen[uid] = true
            label = tostring(label or uid)
            if not online then
                label = label .. "  (saved)"
            end
            out[#out + 1] = {
                key = uid,
                label = label,
                order = (online and "1" or "0") .. string.lower(label),
            }
        end
        for uid in pairs(acceptPlayers) do
            local p = livePlayer(uid)
            if p then
                rememberPlayer(p)
                add(uid, playerLabel(p), true)
            else
                local meta = acceptPlayerMeta[uid]
                local label = meta and (meta.label or meta.display or meta.name) or uid
                add(uid, label, false)
            end
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP then
                add(tostring(p.UserId), playerLabel(p), true)
            end
        end
        table.sort(out, function(a, b)
            return tostring(a.order) < tostring(b.order)
        end)
        return out
    end

    local function acceptAllowed(who)
        if whitelistSize() == 0 then
            return true
        end
        if type(who) ~= "userdata" and type(who) ~= "table" then
            return false
        end
        local name = string.lower(tostring(who.Name or ""))
        local display = string.lower(tostring(who.DisplayName or ""))
        local uid = tostring(who.UserId or "")
        if uid ~= "" and uid ~= "nil" and acceptPlayers[uid] then
            return true
        end
        if name ~= "" and acceptNames[name] then
            return true
        end
        if display ~= "" and acceptNames[display] then
            return true
        end
        if uid ~= "" and uid ~= "nil" and acceptNames[uid] then
            return true
        end
        for id, meta in pairs(acceptPlayerMeta) do
            if acceptPlayers[id] == true and type(meta) == "table" then
                local mName = string.lower(tostring(meta.name or ""))
                local mDisp = string.lower(tostring(meta.display or ""))
                if (mName ~= "" and (mName == name or mName == display))
                    or (mDisp ~= "" and (mDisp == name or mDisp == display)) then
                    return true
                end
            end
        end
        return false
    end

    local function paintAcceptHeader()
        if stopped then
            return
        end
        if not acceptOn then
            Core.paintHeader(acceptHeader, "Off", "muted", "off")
            return
        end
        local takeBusy = session and session.ours and session.role == "accept"
        if takeBusy then
            Core.paintHeader(acceptHeader, lastAccept.value, lastAccept.style, lastAccept.detail)
            return
        end
        local n = whitelistSize()
        if n > 0 then
            Core.paintHeader(acceptHeader, "Idle", "muted", n == 1 and "1 name" or (tostring(n) .. " names"))
        else
            Core.paintHeader(acceptHeader, "Idle", "muted", "any player")
        end
    end

    local function paintHeader()
        paintSendHeader()
        paintAcceptHeader()
        if type(paintSendControls) == "function" then
            paintSendControls()
        end
    end

    local function setStatus(value, style, detail)
        if session and session.role == "accept" then
            lastAccept.value = value
            lastAccept.style = style or "muted"
            lastAccept.detail = detail or ""
        else
            lastStatus.value = value
            lastStatus.style = style or "muted"
            lastStatus.detail = detail or ""
        end
        paintHeader()
    end

    local function pace(sec)
        if workLoop and type(workLoop.setDelay) == "function" then
            pcall(workLoop.setDelay, sec)
        end
    end

    local function playerById(id)
        id = tostring(id or "")
        if id == "" then
            return nil
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if tostring(p.UserId) == id then
                return p
            end
        end
        return nil
    end

    local function tradeOpen()
        local on = true
        pcall(function()
            if tradingEnabled and type(tradingEnabled.Get) == "function" then
                on = tradingEnabled:Get() == true
            end
        end)
        return on == true
    end

    local function rollsNow()
        local n = 0
        pcall(function()
            n = tonumber(Core.data().Rolls()) or 0
        end)
        return n
    end

    local function canTradeSelf()
        if not tradeOpen() then
            return false, "Private", "private server"
        end
        if LP and tonumber(LP.AccountAge) and LP.AccountAge < MIN_AGE then
            return false, "Need age", tostring(MIN_AGE) .. " days"
        end
        if rollsNow() < MIN_ROLLS then
            return false, "Need rolls", tostring(rollsNow()) .. "/" .. tostring(MIN_ROLLS)
        end
        return true
    end

    local function scanBag()
        local data = Core.data()
        local inv
        pcall(function()
            inv = data.Inventory()
        end)
        local out = {}
        if type(inv) ~= "table" then
            return out, data
        end
        local plotted = plottedIds(data)
        for id, item in pairs(inv) do
            local info = profile(item, id)
            if info and info.amount > 0 then
                info.plotted = plotted[info.key] == true
                info.reserved = reservedId(info.key)
                out[#out + 1] = info
            end
        end
        return out, data
    end

    local function unitSendable(info)
        if not info or info.tradeKind ~= "unit" then
            return false
        end
        if info.stackable then
            return false
        end
        return (tonumber(info.amount) or 1) >= 1
    end

    local function unitSendableOnce(info)
        if not info or info.tradeKind ~= "unit" then
            return false
        end
        if info.stackable then
            return false
        end
        return (tonumber(info.amount) or 1) >= 1
    end

    local function bagKindItems(kind)
        kind = tostring(kind or "")
        local bag = scanBag()
        local out = {}
        if kind == "unit" then
            local rows = {}
            for _, info in ipairs(bag) do
                if info.tradeKind == "unit" then
                    rows[#rows + 1] = info
                end
            end
            table.sort(rows, function(a, b)
                local ac = tonumber(a.chance) or -1
                local bc = tonumber(b.chance) or -1
                if ac ~= bc then
                    return ac > bc
                end
                return tostring(a.name or "") < tostring(b.name or "")
            end)
            for i, info in ipairs(rows) do
                local title = info.name
                if type(info.mutation) == "string" and info.mutation ~= "" then
                    title = title .. "  " .. info.mutation
                end
                local bits = {}
                if type(info.trait) == "string" and info.trait ~= "" then
                    bits[#bits + 1] = escapeRich(info.trait)
                end
                if type(info.grade) == "string" and info.grade ~= "" then
                    bits[#bits + 1] = escapeRich(info.grade)
                end
                if type(info.quirk) == "string" and info.quirk ~= "" and info.quirk ~= NONE then
                    bits[#bits + 1] = '<font color="#FFC85A">' .. escapeRich(info.quirk) .. "</font>"
                end
                local lv = tonumber(info.level)
                if lv then
                    bits[#bits + 1] = "Lv " .. tostring(lv)
                end
                local detail = table.concat(bits, " · ")
                if tonumber(info.earn) then
                    detail = (detail ~= "" and (detail .. "  ·  ") or "")
                        .. '<font color="#FFD300">'
                        .. Core.compact(info.earn)
                        .. "</font>"
                end
                if info.chance then
                    detail = (detail ~= "" and (detail .. "  ·  ") or "")
                        .. '<font color="#8EC8FF">1 in '
                        .. Core.compact(info.chance)
                        .. "</font>"
                end
                if info.locked then
                    detail = detail .. "  · locked"
                elseif info.plotted then
                    detail = detail .. "  · plot"
                elseif info.reserved then
                    detail = detail .. "  · make"
                end
                out[#out + 1] = {
                    key = info.key,
                    name = info.name,
                    label = title,
                    detail = detail,
                    order = i,
                }
            end
            return out
        end
        local seen = {}
        for _, info in ipairs(bag) do
            if info.tradeKind == kind and type(info.name) == "string" then
                if not seen[info.name] then
                    seen[info.name] = true
                    out[#out + 1] = {
                        key = info.name,
                        label = info.name .. "  x" .. Core.compact(info.amount),
                        order = info.name,
                    }
                end
            end
        end
        local function addName(name)
            if type(name) == "string" and name ~= "" and not seen[name] then
                seen[name] = true
                out[#out + 1] = { key = name, label = name, order = name }
            end
        end
        if kind == "potion" then
            local cat = Core.potions and Core.potions()
            if type(cat) == "table" and type(cat.items) == "function" then
                local ok, items = pcall(cat.items)
                if ok and type(items) == "table" then
                    for _, item in ipairs(items) do
                        addName(item and item.name)
                    end
                end
            end
        elseif kind == "gear" then
            local cat = Core.gears and Core.gears()
            if type(cat) == "table" and type(cat.items) == "function" then
                local ok, items = pcall(cat.items)
                if ok and type(items) == "table" then
                    for _, item in ipairs(items) do
                        addName(item and item.name)
                    end
                end
            end
        elseif kind == "spin" then
            addName("Jackpot Spin")
            addName("Lucky Spin")
        elseif kind == "gems" then
            addName("Gems")
        elseif kind == "trait_reroll" then
            addName("Trait Reroll")
        end
        table.sort(out, function(a, b)
            return tostring(a.order or a.label) < tostring(b.order or b.label)
        end)
        local alls = autoUi.allHelp.options(kind)
        for i = #alls, 1, -1 do
            table.insert(out, 1, alls[i])
        end
        return out
    end

    local function collectStacks(bag, used, slotsLeft)
        local out = {}
        if slotsLeft <= 0 then
            return out
        end
        for _, kindRow in ipairs(STACK_KINDS) do
            local kind = kindRow.key
            if giveKinds[kind] == true and slotsLeft > 0 then
                local picks = autoBag.picks[kind]
                if mapSize(picks) > 0 then
                    for _, info in ipairs(bag) do
                        if slotsLeft <= 0 then
                            break
                        end
                        if info.tradeKind == kind and info.stackable and not used[info.key] then
                            local n = 0
                            if autoUi.allHelp.covers(kind, info.name, picks) then
                                n = tonumber(info.amount) or 0
                            elseif picks[info.name] == true then
                                n = math.min(amtOf(autoBag.amt, kind, info.name), info.amount)
                            end
                            if n > 0 then
                                out[#out + 1] = { key = info.key, amount = n, kind = kind, name = info.name }
                                used[info.key] = true
                                slotsLeft = slotsLeft - 1
                            end
                        end
                    end
                end
            end
        end
        return out
    end

    local function collectOnce(bag, limit)
        limit = math.floor(tonumber(limit) or MAX_UNIQUE)
        if limit < 1 then
            limit = MAX_UNIQUE
        end
        local used = {}
        local offer = {}
        local function take(row)
            if not row or used[row.key] or #offer >= limit then
                return
            end
            used[row.key] = true
            offer[#offer + 1] = row
        end
        if onceFields.unit == true then
            local selected = copyMap(oncePicks.unit)
            for _, info in ipairs(bag) do
                if selected[info.key] == true and unitSendableOnce(info) then
                    take({
                        key = info.key,
                        amount = 1,
                        kind = "unit",
                        name = info.name,
                        mutation = info.mutation,
                        trait = info.trait,
                        grade = info.grade,
                        quirk = info.quirk,
                        level = info.level,
                        earn = info.earn,
                        chance = info.chance,
                        locked = info.locked == true,
                        plotted = info.plotted == true,
                    })
                end
            end
        end
        local function takeStacks(kind)
            if onceFields[kind] ~= true or #offer >= limit then
                return
            end
            local picks = copyMap(oncePicks[kind])
            if mapSize(picks) == 0 then
                return
            end
            for _, info in ipairs(bag) do
                if #offer >= limit then
                    break
                end
                if info.tradeKind == kind and info.stackable and not used[info.key] then
                    local n = 0
                    if autoUi.allHelp.covers(kind, info.name, picks) then
                        n = tonumber(info.amount) or 0
                    elseif picks[info.name] == true then
                        local want = amtOf(onceAmt, kind, info.name)
                        local sent = 0
                        if type(autoUi.onceSent) == "table" then
                            sent = tonumber(autoUi.onceSent[kind .. "|" .. info.name]) or 0
                        end
                        local left = want - sent
                        if left < 0 then
                            left = 0
                        end
                        n = math.min(left, info.amount)
                    end
                    if n > 0 then
                        take({ key = info.key, amount = n, kind = kind, name = info.name })
                    end
                end
            end
        end
        takeStacks("potion")
        takeStacks("spin")
        takeStacks("gear")
        takeStacks("gems")
        takeStacks("trait_reroll")
        return offer
    end

    local function onceEmptyReason()
        if mapSize(onceFields) == 0 then
            return "Pick fields", "select Unit / Potion / Spin"
        end
        local picked = false
        for kind in pairs(onceFields) do
            if mapSize(oncePicks[kind]) > 0 then
                picked = true
                break
            end
        end
        if not picked then
            return "Pick items", "select from lists"
        end
        return "No stock", "selected missing"
    end

    local function onceConfirmLines(planned, extra)
        extra = math.max(0, math.floor(tonumber(extra) or 0))
        local lines = {}
        local hasLock = false
        local hasPlot = false
        for _, row in ipairs(planned) do
            if row.kind == "unit" then
                local title = escapeRich(row.name or "Unit")
                if type(row.mutation) == "string" and row.mutation ~= "" then
                    title = title .. "  " .. escapeRich(row.mutation)
                end
                local bits = {}
                if type(row.trait) == "string" and row.trait ~= "" then
                    bits[#bits + 1] = escapeRich(row.trait)
                end
                if type(row.grade) == "string" and row.grade ~= "" then
                    bits[#bits + 1] = escapeRich(row.grade)
                end
                if type(row.quirk) == "string" and row.quirk ~= "" and row.quirk ~= NONE then
                    bits[#bits + 1] = '<font color="#FFC85A">' .. escapeRich(row.quirk) .. "</font>"
                end
                local lv = tonumber(row.level)
                if lv then
                    bits[#bits + 1] = "Lv " .. tostring(lv)
                end
                local detail = table.concat(bits, " · ")
                if tonumber(row.earn) then
                    detail = (detail ~= "" and (detail .. "  ·  ") or "")
                        .. '<font color="#FFD300">'
                        .. Core.compact(row.earn)
                        .. "</font>"
                end
                if row.chance then
                    detail = (detail ~= "" and (detail .. "  ·  ") or "")
                        .. '<font color="#8EC8FF">1 in '
                        .. Core.compact(row.chance)
                        .. "</font>"
                end
                if row.locked then
                    hasLock = true
                    detail = detail .. "  · locked"
                end
                if row.plotted then
                    hasPlot = true
                    detail = detail .. "  · plot"
                end
                lines[#lines + 1] = { text = title, sub = detail, rich = true }
            else
                local n = tonumber(row.amount) or 1
                lines[#lines + 1] = {
                    text = escapeRich(row.name or row.kind or "Item") .. "  x" .. Core.compact(n),
                    rich = true,
                }
            end
        end
        if extra > 0 then
            lines[#lines + 1] = {
                text = "+"
                    .. tostring(extra)
                    .. " more · next trade"
                    .. (extra > MAX_UNIQUE and "s" or ""),
                rich = false,
            }
        end
        return lines, hasLock, hasPlot
    end

    local function collectAuto(bag)
        local used = {}
        local offer = {}
        if giveKinds.unit == true then
            local units = {}
            for _, info in ipairs(bag) do
                if unitSendable(info) and unitAllowed(giveRules, info) then
                    units[#units + 1] = info
                end
            end
            table.sort(units, function(a, b)
                local ac = tonumber(a.chance) or -1
                local bc = tonumber(b.chance) or -1
                if ac == bc then
                    return tostring(a.key) < tostring(b.key)
                end
                return ac > bc
            end)
            local cap = math.min(maxUnitsSend, MAX_UNIQUE)
            for i = 1, math.min(cap, #units) do
                local info = units[i]
                offer[#offer + 1] = { key = info.key, amount = 1, kind = "unit", name = info.name }
                used[info.key] = true
            end
        end
        local stacks = collectStacks(bag, used, MAX_UNIQUE - #offer)
        for _, row in ipairs(stacks) do
            offer[#offer + 1] = row
        end
        return offer
    end

    local function collectGive(bag)
        if mode == "auto" then
            return collectAuto(bag)
        end
        return collectOnce(bag)
    end

    local function ownOfferAmt(key)
        key = tostring(key or "")
        if key == "" or not session or type(session.ownOffer) ~= "table" then
            return 0
        end
        local n = session.ownOffer[key]
        if type(n) == "number" then
            return n
        end
        for k, v in pairs(session.ownOffer) do
            if tostring(k) == key then
                if type(v) == "number" then
                    return v
                end
                if type(v) == "table" then
                    return tonumber(v.amount) or 0
                end
            end
            if type(v) == "table" and tostring(v.key or "") == key then
                return tonumber(v.amount) or 0
            end
        end
        return 0
    end

    local function missingOffer()
        if not session or type(session.planned) ~= "table" then
            return nil
        end
        for _, row in ipairs(session.planned) do
            local want = math.floor(tonumber(row.amount) or 0)
            if want < 1 then
                want = 1
            end
            local have = ownOfferAmt(row.key)
            if have < want then
                return row, math.floor(want - have)
            end
        end
        return nil
    end

    local function putOffer(row, need)
        if not row or not nets() or not changeOffer then
            return false
        end
        need = math.floor(tonumber(need) or 0)
        if need == 0 then
            return false
        end
        lastFireAt = os.clock()
        session.offerWaitKey = row.key
        session.offerWaitAt = os.clock()
        session.offerWaitHave = ownOfferAmt(row.key)
        pcall(function()
            changeOffer:Fire(tostring(row.key), need)
        end)
        return true
    end

    local function newSession(kind, player)
        return {
            ours = true,
            role = kind,
            player = player,
            planned = {},
            ownOffer = {},
            otherOffer = {},
            tradePhase = "Offer",
            ownReady = false,
            otherReady = false,
            ownAccepted = false,
            otherAccepted = false,
            inTrade = false,
        }
    end

    local function enter(nextPhase, value, style, detail)
        phase = nextPhase
        phaseAt = os.clock()
        if value then
            setStatus(value, style, detail)
        else
            paintHeader()
        end
        if nextPhase == "idle" or nextPhase == "cooldown" then
            pace(nextPhase == "cooldown" and delaySec or IDLE)
        else
            pace(FAST)
        end
    end

    local function clearSession()
        session = nil
        dropNext = false
        phase = "idle"
        phaseAt = os.clock()
    end

    local function fireCancel()
        if not session or not session.inTrade then
            return
        end
        if not nets() or not cancelTrade then
            return
        end
        pcall(function()
            cancelTrade:Fire()
        end)
    end

    local syncWork

    local function resetOnceForm()
        autoUi.onceSent = {}
        onceFields = {}
        oncePicks.unit = {}
        oncePicks.potion = {}
        oncePicks.spin = {}
        oncePicks.gear = {}
        oncePicks.gems = {}
        oncePicks.trait_reroll = {}
        onceAmt.potion = {}
        onceAmt.spin = {}
        onceAmt.gear = {}
        onceAmt.gems = {}
        onceAmt.trait_reroll = {}
        if onceFormApi and type(onceFormApi.set) == "function" then
            pcall(onceFormApi.set, {}, true)
        end
        for _, api in pairs(oncePickApi) do
            if type(api) == "table" then
                if type(api.clear) == "function" then
                    pcall(api.clear, true)
                elseif type(api.setSelected) == "function" then
                    pcall(api.setSelected, {}, true)
                elseif type(api.set) == "function" then
                    pcall(api.set, {}, true)
                end
            end
        end
        for kind, apis in pairs(onceAmtApi) do
            if type(apis) == "table" then
                for name, rec in pairs(apis) do
                    local row = rec and (rec.row or rec.root)
                    if row then
                        pcall(function()
                            row:Destroy()
                        end)
                    end
                    apis[name] = nil
                end
            end
        end
        onceTargetId = ""
        if onceTargetApi then
            if type(onceTargetApi.clear) == "function" then
                pcall(onceTargetApi.clear, true)
            elseif type(onceTargetApi.setSelected) == "function" then
                pcall(onceTargetApi.setSelected, nil, true)
            elseif type(onceTargetApi.set) == "function" then
                pcall(onceTargetApi.set, nil, true)
            end
        end
        paintHeader()
    end

    local function finishOnce()
        onceRun = false
        if type(syncWork) == "function" then
            syncWork()
        end
    end

    local function toCooldown(reason)
        lastDone = reason or lastDone
        local planned = session and session.planned
        session = nil
        dropNext = false
        if mode == "once" or onceRun then
            if reason == "done" then
                if type(planned) == "table" then
                    if type(autoUi.onceSent) ~= "table" then
                        autoUi.onceSent = {}
                    end
                    for _, row in ipairs(planned) do
                        if type(row) == "table" and row.kind ~= "unit" and type(row.name) == "string" then
                            local key = tostring(row.kind or "") .. "|" .. row.name
                            autoUi.onceSent[key] = (tonumber(autoUi.onceSent[key]) or 0) + (tonumber(row.amount) or 0)
                        end
                    end
                end
                local left = collectOnce(scanBag(), 9999)
                if #left > 0 and playerById(onceTargetId) then
                    enter("cooldown", "Next batch", "success", tostring(#left) .. " left")
                    return
                end
                if autoUi.keep ~= true then
                    resetOnceForm()
                end
            end
            enter("idle", "Done", "success", reason or "once")
            finishOnce()
            pace(IDLE)
            return
        end
        if autoSendOn then
            enter("cooldown", "Wait", "muted", reason or ("delay " .. tostring(delaySec) .. "s"))
            return
        end
        enter("idle", "Idle", "muted", reason or "ended")
    end

    local function abort(reason, cancel)
        if cancel ~= false and inSession() then
            fireCancel()
        end
        if autoSendOn and mode == "auto" then
            toCooldown(reason or "abort")
            return
        end
        if onceRun or mode == "once" then
            enter("idle", "Idle", "muted", reason or "stopped")
            finishOnce()
            session = nil
            dropNext = false
            return
        end
        session = nil
        dropNext = false
        enter("idle", shouldRun() and "Idle" or "Off", "muted", reason or "off")
    end

    local function ensureRequests(on)
        if not nets() or not setRequests then
            return
        end
        pcall(function()
            local data = Core.data()
            local cur = data and data.TradeRequestsEnabled and data.TradeRequestsEnabled()
            if cur ~= on then
                setRequests:Fire(on == true)
            end
        end)
    end

    local function applyUpdated(payload)
        if type(payload) ~= "table" or not session then
            return
        end
        session.ownOffer = type(payload.ownOffer) == "table" and payload.ownOffer or session.ownOffer
        session.otherOffer = type(payload.otherOffer) == "table" and payload.otherOffer or session.otherOffer
        session.tradePhase = tostring(payload.phase or session.tradePhase)
        session.ownReady = payload.ownReady == true
        session.otherReady = payload.otherReady == true
        session.ownAccepted = payload.ownAccepted == true
        session.otherAccepted = payload.otherAccepted == true
        session.partner = payload.partner or session.partner
        if payload.ownReady == true or payload.ownAccepted == true then
            session.advWaitAt = nil
        end
        if session.offerWaitKey then
            local have = ownOfferAmt(session.offerWaitKey)
            if have ~= (session.offerWaitHave or 0) then
                session.offerWaitKey = nil
            end
        end
        lastOfferN = 0
        if type(session.ownOffer) == "table" then
            for _ in pairs(session.ownOffer) do
                lastOfferN = lastOfferN + 1
            end
        end
    end

    local function partnerLabel()
        local p = session and (session.partner or session.player)
        if typeof(p) == "Instance" then
            return p.DisplayName
        end
        local t = playerById(mode == "auto" and autoTargetId or onceTargetId)
        return t and t.DisplayName or "player"
    end

    local function offerCountText()
        local total = 0
        if session and type(session.planned) == "table" then
            total = #session.planned
        end
        return tostring(lastOfferN) .. "/" .. tostring(total)
    end

    local function sendLine()
        local who = partnerLabel()
        local count = offerCountText()
        if onceConfirmOpen then
            return "Confirm", "success", "check items for " .. who, "CONFIRMING…", "Confirm the popup. Sending to " .. who .. "."
        end
        if phase == "request" then
            return "Sent", "success", "wait accept from " .. who, "WAITING ACCEPT", "Request sent to " .. who .. ". Waiting for accept."
        end
        if phase == "offer" then
            return "Add items", "success", count .. " → " .. who, "ADDING ITEMS  " .. count, "Sending to " .. who .. ". Adding items " .. count .. ", then Ready."
        end
        if phase == "wait_them" then
            return "Wait", "muted", "wait ready from " .. who, "WAIT THEIR READY", "Waiting until " .. who .. " is ready, then Ready / Accept."
        end
        if phase == "ready" then
            if session and session.ownReady then
                return "Ready", "success", "wait " .. who, "READY — WAIT THEM", "Ready is on. Waiting for " .. who .. " to ready / accept."
            end
            return "Ready", "success", "set ready", "READY…", "Items are in. Setting Ready."
        end
        if phase == "confirm" then
            return "Accept", "success", "confirm with " .. who, "ACCEPTING…", "Both ready. Accepting the trade with " .. who .. "."
        end
        if phase == "wait_end" then
            return "Saving", "success", "trade finishing", "SAVING…", "Trade is saving."
        end
        if phase == "cooldown" then
            if onceRun then
                local left = #collectOnce(scanBag(), 9999)
                return "Next batch", "success", tostring(left) .. " left", "NEXT BATCH", "Waiting " .. tostring(delaySec) .. "s, then sending the next 20 to " .. who .. "."
            end
            return "Wait", "muted", "delay " .. tostring(delaySec) .. "s", "WAIT DELAY", "Waiting " .. tostring(delaySec) .. "s before the next send."
        end
        if sending() then
            return lastStatus.value, lastStatus.style, lastStatus.detail, "SENDING…", lastStatus.detail
        end
        return lastStatus.value, lastStatus.style, lastStatus.detail, "SEND TRADE", nil
    end

    paintSendControls = function()
        if stopped then
            return
        end
        local busy = sendBusyNow()
        local value, style, detail, btnText, note = sendLine()
        if busy then
            Core.paintHeader(headerApi, value, style, detail)
        elseif sending() and mode == "auto" then
            if phase == "cooldown" then
                Core.paintHeader(headerApi, value, style, detail)
            elseif lastStatus.value == "Off" or lastStatus.detail == "off" or lastStatus.detail == "turn Auto send on" then
                Core.paintHeader(headerApi, "Idle", "muted", "waiting to send")
            end
        end
        if onceBtnApi then
            if type(onceBtnApi.set) == "function" then
                pcall(onceBtnApi.set, busy and btnText or "SEND TRADE")
            end
            if type(onceBtnApi.setEnabled) == "function" then
                pcall(onceBtnApi.setEnabled, not busy)
            end
        end
        if autoSendApi then
            if type(autoSendApi.setLocked) == "function" then
                local lockToggle = onceConfirmOpen or onceRun or os.clock() < autoLockUntil
                pcall(autoSendApi.setLocked, lockToggle)
            end
            if type(autoSendApi.setLabel) == "function" then
                if mode == "auto" and autoSendOn and (busy or phase == "cooldown") then
                    pcall(autoSendApi.setLabel, btnText)
                else
                    pcall(autoSendApi.setLabel, AUTO_SEND_LABEL)
                end
            end
        end
        if sendNoteApi and type(sendNoteApi.set) == "function" then
            if busy and type(note) == "string" and note ~= "" then
                pcall(sendNoteApi.set, note)
            elseif mode == "auto" then
                pcall(sendNoteApi.set, "Auto target, min unique, give kinds, and unit rules are separate from Once. Wait until unique slots reach Min unique, then loop every 7s. Max 20 unique slots. Tickets cannot be sent.")
            else
                pcall(sendNoteApi.set, "Pick a target and items, then press Send trade. Confirm first. Over 20 unique slots: first 20 send now, the rest send automatically after each completed trade. Locked / plot / Make Unit units can be sent. Tickets cannot.")
            end
        end
    end

    local function onTradeEvent(kind, payload)
        if stopped then
            return
        end
        payload = type(payload) == "table" and payload or {}
        if kind == "RequestReceived" then
            local who = payload.player
            if not enableOn or not nets() or not respondReq then
                return
            end
            if isBusy() or pendingTrade() then
                return
            end
            if phase == "request" then
                return
            end
            local fromTarget = who and tostring(who.UserId) == tostring(mode == "auto" and autoTargetId or onceTargetId)
            local take = false
            if acceptOn then
                take = acceptAllowed(who)
            elseif sending() and fromTarget then
                take = true
            end
            if take then
                session = newSession("accept", who)
                session.awaitStart = true
                dropNext = false
                pcall(function()
                    respondReq:Fire(true)
                end)
                enter("request", "Accept", "success", who and who.DisplayName or "incoming")
            elseif acceptOn then
                pcall(function()
                    respondReq:Fire(false)
                end)
            end
            return
        end
        if kind == "RequestSent" then
            return
        end
        if kind == "RequestClosed" then
            return
        end
        if kind == "RequestExpired" then
            if session and session.ours and not session.inTrade and phase == "request" then
                toCooldown("expired")
            end
            return
        end
        if kind == "Started" then
            local partner = payload.partner
            local wantId = tostring(mode == "auto" and autoTargetId or onceTargetId)
            local gotId = partner and tostring(partner.UserId) or ""
            if not (session and session.ours) then
                if not enableOn then
                    return
                end
                if sending() and gotId ~= "" and gotId == wantId then
                    session = newSession("send", partner)
                    session.planned = collectGive(scanBag())
                elseif acceptOn and acceptAllowed(partner) then
                    session = newSession("accept", partner)
                else
                    return
                end
            elseif sending() and session.role == "send" and wantId ~= "" and gotId ~= "" and gotId ~= wantId then
                return
            end
            if dropNext or not enableOn then
                dropNext = false
                if session and session.ours then
                    session.inTrade = true
                    fireCancel()
                    clearSession()
                end
                paintHeader()
                return
            end
            session.inTrade = true
            session.partner = partner or session.player
            session.awaitStart = false
            session.ownReady = false
            session.otherReady = false
            session.ownAccepted = false
            session.otherAccepted = false
            session.tradePhase = "Offer"
            local bag = scanBag()
            if sending() then
                local nextPlan = collectGive(bag)
                if #nextPlan > 0 then
                    session.planned = nextPlan
                elseif type(session.planned) ~= "table" then
                    session.planned = {}
                end
            else
                session.planned = {}
            end
            if sending() and #(session.planned) > 0 then
                enter("offer", "Offer", "success", "0/" .. tostring(#session.planned))
                local row, need = missingOffer()
                if row then
                    putOffer(row, need)
                    setStatus("Offer", "success", "1/" .. tostring(#session.planned))
                end
            elseif session.role == "send" then
                fireCancel()
                toCooldown("nothing to send")
                return
            else
                enter("wait_them", "Wait", "muted", "wait their ready")
            end
            return
        end
        if kind == "Updated" then
            if session and session.ours and session.inTrade then
                applyUpdated(payload)
                if phase == "offer" then
                    setStatus("Offer", "success", tostring(lastOfferN) .. "/" .. tostring(#(session.planned or {})))
                elseif phase == "wait_them" then
                    if session.otherReady then
                        enter("ready", "Ready", "success", "they ready")
                    else
                        setStatus("Wait", "muted", "wait their ready")
                    end
                elseif phase == "ready" then
                    setStatus("Ready", session.ownReady and "success" or "muted", session.otherReady and "both" or "wait them")
                elseif phase == "confirm" then
                    setStatus("Confirm", "success", session.tradePhase)
                elseif phase == "wait_end" then
                    setStatus("Saving", "success", session.tradePhase)
                end
            end
            return
        end
        if kind == "Ended" then
            local reason = tostring(payload.reason or "")
            if session and session.ours then
                session.inTrade = false
                if reason == "Completed" then
                    toCooldown("done")
                elseif reason == "Cancelled" or reason == "PartnerLeft" or reason == "SaveFailed" or reason == "RecoveryRequired" then
                    toCooldown(reason)
                else
                    toCooldown(reason ~= "" and reason or "ended")
                end
            else
                if phase ~= "idle" and phase ~= "cooldown" then
                    enter("idle", "Idle", "muted", reason)
                end
            end
        end
    end

    local function startSend()
        local ok, value, detail = canTradeSelf()
        if not ok then
            setStatus(value, "warn", detail)
            pace(IDLE)
            return
        end
        if not sending() then
            setStatus("Idle", "muted", acceptOn and "waiting request" or "Send off")
            pace(IDLE)
            return
        end
        if pendingTrade() then
            setStatus("Paused", "warn", "manual trade")
            pace(IDLE)
            return
        end
        local target = playerById(mode == "auto" and autoTargetId or onceTargetId)
        if not target then
            setStatus("Need player", "warn", mode == "auto" and "pick Auto target" or "pick target")
            pace(IDLE)
            return
        end
        local bag = scanBag()
        local planned = collectGive(bag)
        if mode == "auto" then
            local stackOn = false
            local stackPicked = false
            for _, row in ipairs(STACK_KINDS) do
                if giveKinds[row.key] == true then
                    stackOn = true
                    if mapSize(autoBag.picks[row.key]) > 0 then
                        stackPicked = true
                    end
                end
            end
            local unitOn = giveKinds.unit == true
            local hasRule = #enabledRules(giveRules) > 0
            if mapSize(giveKinds) == 0 then
                setStatus("Pick kinds", "warn", "select Unit / Potion / Gear")
                pace(IDLE)
                return
            end
            if unitOn and not hasRule and not stackPicked then
                if stackOn then
                    setStatus("Pick stacks", "warn", "pick potion / gear names")
                else
                    setStatus("Add rule", "warn", "Give unit needs a rule")
                end
                pace(IDLE)
                return
            end
            if stackOn and not stackPicked and not (unitOn and hasRule) then
                setStatus("Pick stacks", "warn", "pick potion / gear names")
                pace(IDLE)
                return
            end
            if #planned == 0 then
                setStatus("No stock", "muted", "nothing to send")
                pace(IDLE)
                return
            end
            local need = clampMaxUnits(minUnique)
            if #planned < need then
                setStatus("Need " .. tostring(need) .. " items", "warn", tostring(#planned) .. "/" .. tostring(need) .. " unique")
                pace(IDLE)
                return
            end
        elseif #planned == 0 then
            local value, detail = onceEmptyReason()
            setStatus(value, "warn", detail)
            pace(IDLE)
            return
        end
        if os.clock() - lastRequestAt < delaySec then
            setStatus("Wait", "muted", "delay " .. tostring(delaySec) .. "s")
            pace(delaySec)
            return
        end
        if not nets() or not requestTrade then
            setStatus("Wait", "warn", "trade net")
            pace(IDLE)
            return
        end
        session = newSession("send", target)
        session.planned = planned
        lastRequestAt = os.clock()
        local fired = pcall(function()
            requestTrade:Fire(target)
        end)
        if not fired then
            session = nil
            setStatus("Wait", "warn", "request fail")
            pace(IDLE)
            return
        end
        enter("request", "Sent", "success", target.DisplayName)
    end

    local function canAdvance()
        return os.clock() - lastAdvanceAt >= FAST
    end

    local function fireAdvance()
        if not nets() or not advanceTrade or not canAdvance() then
            return false
        end
        if session and session.advWaitAt and os.clock() - session.advWaitAt < 1.2 then
            return false
        end
        lastAdvanceAt = os.clock()
        if session then
            session.advWaitAt = os.clock()
        end
        pcall(function()
            advanceTrade:Fire()
        end)
        return true
    end

    local function stepOffer()
        if os.clock() - phaseAt > OFFER_WAIT then
            abort("offer timeout")
            return
        end
        if not session then
            return
        end
        if session.tradePhase == "Countdown" or session.tradePhase == "Saving" then
            enter("wait_end", "Saving", "success", session.tradePhase)
            return
        end
        local row, need = missingOffer()
        if row then
            if session.offerWaitKey == row.key then
                if os.clock() - (session.offerWaitAt or 0) < 1.2 then
                    return
                end
            end
            if os.clock() - lastFireAt < FAST then
                return
            end
            putOffer(row, need)
            setStatus("Offer", "success", tostring(lastOfferN) .. "/" .. tostring(#session.planned))
            return
        end
        session.offerWaitKey = nil
        enter("ready", "Ready", "success", "offer set")
    end

    local function stepWaitThem()
        if os.clock() - phaseAt > WAIT_THEM then
            abort("wait timeout")
            return
        end
        if not session then
            return
        end
        if session.tradePhase == "Confirm" then
            enter("confirm", "Confirm", "success", "accept")
            return
        end
        if session.tradePhase == "Countdown" or session.tradePhase == "Saving" then
            enter("wait_end", "Saving", "success", session.tradePhase)
            return
        end
        if session.otherReady then
            enter("ready", "Ready", "success", "they ready")
            return
        end
        setStatus("Wait", "muted", "wait their ready")
    end

    local function stepReady()
        if os.clock() - phaseAt > READY_WAIT then
            abort("ready timeout")
            return
        end
        if not session then
            return
        end
        if session.tradePhase == "Confirm" then
            enter("confirm", "Confirm", "success", "accept")
            return
        end
        if session.tradePhase == "Countdown" or session.tradePhase == "Saving" then
            enter("wait_end", "Saving", "success", session.tradePhase)
            return
        end
        if session.role == "accept" and not session.otherReady then
            enter("wait_them", "Wait", "muted", "wait their ready")
            return
        end
        if session.role == "send" and missingOffer() then
            enter("offer", "Offer", "warn", "offer changed")
            return
        end
        if not session.ownReady then
            fireAdvance()
            setStatus("Ready", "success", "waiting")
            return
        end
        if session.tradePhase == "Offer" and session.ownReady and session.otherReady then
            return
        end
        setStatus("Ready", "success", session.otherReady and "both" or "wait them")
    end

    local function stepConfirm()
        if os.clock() - phaseAt > READY_WAIT then
            abort("confirm timeout")
            return
        end
        if not session then
            return
        end
        if session.tradePhase == "Countdown" or session.tradePhase == "Saving" then
            enter("wait_end", "Saving", "success", session.tradePhase)
            return
        end
        if session.tradePhase == "Offer" then
            enter("ready", "Ready", "warn", "reset")
            return
        end
        if not session.ownAccepted then
            fireAdvance()
            setStatus("Confirm", "success", "accept")
            return
        end
        setStatus("Confirm", "success", "wait them")
    end

    local function stepWaitEnd()
        if os.clock() - phaseAt > END_WAIT then
            abort("end timeout")
        end
    end

    local function stepOnce()
        if stopped then
            return
        end
        if not enableOn then
            pace(IDLE)
            paintHeader()
            return
        end
        if not eventConn and nets() and tradeEvent then
            eventConn = tradeEvent:Connect(onTradeEvent)
        end
        if acceptOn then
            ensureRequests(true)
        end
        if phase == "cooldown" then
            if os.clock() - phaseAt >= delaySec then
                enter("idle", "Idle", "muted", "ready")
            else
                setStatus("Wait", "muted", "delay")
            end
            return
        end
        if phase == "request" then
            if os.clock() - phaseAt > REQ_WAIT then
                dropNext = true
                toCooldown("request timeout")
            else
                setStatus(session and session.role == "accept" and "Accept" or "Sent", "success", partnerLabel())
            end
            return
        end
        if phase == "offer" then
            stepOffer()
            return
        end
        if phase == "wait_them" then
            stepWaitThem()
            return
        end
        if phase == "ready" then
            stepReady()
            return
        end
        if phase == "confirm" then
            stepConfirm()
            return
        end
        if phase == "wait_end" then
            stepWaitEnd()
            return
        end
        if pendingTrade() and not inSession() then
            setStatus("Paused", "warn", "manual trade")
            pace(IDLE)
            return
        end
        if not sending() and not acceptOn then
            setStatus("Idle", "warn", mode == "once" and "press Send trade" or "Auto send off")
            pace(IDLE)
            return
        end
        if sending() then
            startSend()
            return
        end
        paintHeader()
        pace(IDLE)
    end

    syncWork = function()
        local on = shouldRun()
        if on then
            local was = enableOn
            enableOn = true
            dropNext = false
            if workLoop then
                pcall(workLoop.setEnabled, true)
            end
            if acceptOn then
                ensureRequests(true)
            end
            if not sending() and session and session.ours and session.role == "send" then
                fireCancel()
                clearSession()
                enter("idle", "Idle", "muted", acceptOn and "waiting request" or "off")
            elseif not was and phase ~= "cooldown" and phase ~= "offer" and phase ~= "wait_them" and phase ~= "ready" and phase ~= "confirm" and phase ~= "wait_end" and phase ~= "request" then
                enter("idle", "Idle", "muted", mode)
            end
        else
            dropNext = true
            onceRun = false
            if inSession() then
                fireCancel()
            end
            clearSession()
            enableOn = false
            if workLoop then
                pcall(workLoop.setEnabled, false)
            end
            setStatus("Off", "muted", "off")
        end
        paintHeader()
    end

    local function setEnabled(on)
        autoSendOn = on == true
        autoLockUntil = os.clock() + 0.8
        if autoSendApi and type(autoSendApi.set) == "function" then
            pcall(autoSendApi.set, autoSendOn, true)
        end
        if not autoSendOn then
            onceRun = false
        end
        syncWork()
        paintHeader()
    end

    local function startOnce()
        if mode ~= "once" then
            return
        end
        if isBusy() or onceRun or onceConfirmOpen then
            return
        end
        local ok, value, detail = canTradeSelf()
        if not ok then
            setStatus(value, "warn", detail)
            return
        end
        local target = playerById(onceTargetId)
        if not target then
            setStatus("Need player", "warn", "pick Once target")
            return
        end
        autoUi.onceSent = {}
        local bag = scanBag()
        local all = collectOnce(bag, 9999)
        if #all == 0 then
            local emptyValue, emptyDetail = onceEmptyReason()
            setStatus(emptyValue, "warn", emptyDetail)
            return
        end
        local planned = {}
        for i = 1, math.min(MAX_UNIQUE, #all) do
            planned[i] = all[i]
        end
        local extra = math.max(0, #all - #planned)
        local batches = math.ceil(#all / MAX_UNIQUE)
        local function go()
            if isBusy() or onceRun then
                return
            end
            if #collectGive(scanBag()) == 0 then
                local emptyValue, emptyDetail = onceEmptyReason()
                setStatus(emptyValue, "warn", emptyDetail)
                return
            end
            onceRun = true
            syncWork()
        end
        if not (hubUi and type(hubUi.CreateConfirm) == "function") then
            go()
            return
        end
        local lines, hasLock, hasPlot = onceConfirmLines(planned, extra)
        for i = #planned + 1, #all do
            local row = all[i]
            if row and row.locked then
                hasLock = true
            end
            if row and row.plotted then
                hasPlot = true
            end
        end
        local warn = "Check the target and items. After the partner accepts, items move and cannot be undone."
        if batches > 1 then
            warn = warn .. " Game max 20 slots per trade. After each completed trade, the next batch sends automatically."
        end
        if hasLock or hasPlot then
            warn = warn .. " Locked/plot units are included and will still be sent."
        end
        onceConfirmOpen = true
        paintHeader()
        local sub = "To  "
            .. tostring(target.DisplayName)
            .. "  @"
            .. tostring(target.Name)
            .. "   ·  "
            .. tostring(#all)
            .. ((#all == 1) and " item" or " items")
        if batches > 1 then
            sub = sub .. "  ·  " .. tostring(batches) .. " trades"
        end
        hubUi:CreateConfirm({
            title = "Send trade?",
            subtitle = sub,
            warning = warn,
            lines = lines,
            confirmText = "CONTINUE SEND",
            cancelText = "CANCEL",
            onConfirm = function()
                go()
                onceConfirmOpen = false
                paintHeader()
            end,
            onCancel = function()
                onceConfirmOpen = false
                setStatus("Ready", "muted", "press Send trade")
            end,
        })
    end

    local function stop()
        stopped = true
        enableOn = false
        autoSendOn = false
        onceRun = false
        onceConfirmOpen = false
        dropNext = true
        if inSession() then
            fireCancel()
        end
        clearSession()
        if workLoop then
            pcall(workLoop.stop)
        end
        if eventConn then
            pcall(function()
                eventConn:Disconnect()
            end)
            eventConn = nil
        end
        if playerConn then
            pcall(function()
                playerConn:Disconnect()
            end)
            playerConn = nil
        end
        if acceptJoinConn then
            pcall(function()
                acceptJoinConn:Disconnect()
            end)
            acceptJoinConn = nil
        end
        G.AnimeDiceAutoTrade = nil
    end

    if nets() and tradeEvent then
        eventConn = tradeEvent:Connect(onTradeEvent)
    end
    local function refreshAcceptPlayers()
        if acceptDropApi and type(acceptDropApi.refreshItems) == "function" then
            pcall(acceptDropApi.refreshItems)
        end
    end
    playerConn = Players.PlayerRemoving:Connect(function(p)
        if session and session.ours and session.player == p and not session.inTrade then
            toCooldown("left")
        end
        refreshAcceptPlayers()
    end)
    acceptJoinConn = Players.PlayerAdded:Connect(function(p)
        if acceptPlayers[tostring(p.UserId)] == true then
            rememberPlayer(p)
            persistPlayerMeta()
        end
        refreshAcceptPlayers()
    end)

    workLoop = Core.loop("auto_trade", {
        delay = IDLE,
        step = stepOnce,
    })

    G.AnimeDiceAutoTrade = {
        busy = function()
            return onceConfirmOpen == true or onceRun == true or isBusy()
        end,
        enabled = function()
            return enableOn
        end,
        setEnabled = setEnabled,
        stop = stop,
        phase = function()
            return phase
        end,
    }

    local function paintModeVis()
        if onceGroup then
            onceGroup.Visible = mode == "once"
        end
        for _, group in ipairs(autoUi.groups) do
            if group then
                group.Visible = mode == "auto"
            end
        end
        if mode == "auto" and autoUi.form and type(autoUi.form.apply) == "function" then
            pcall(autoUi.form.apply)
        end
        if onceBtnApi and type(onceBtnApi.setVisible) == "function" then
            pcall(onceBtnApi.setVisible, mode == "once")
        end
        if autoSendApi and type(autoSendApi.setVisible) == "function" then
            pcall(autoSendApi.setVisible, mode == "auto")
        end
    end

    local function bindRuleBlock(ui, parent, spec)
        local rules = spec.list
        local draft = spec.draft
        local ruleApi
        local function persistRules()
            if ruleApi and type(ruleApi.set) == "function" then
                pcall(ruleApi.set, rules)
            end
            paintHeader()
        end
        local _, bindRules = ui:CreateRuleList(parent, {
            id = spec.id .. ".rules",
            title = spec.title,
            searchPlaceholder = "Search rules...",
            emptyText = spec.empty,
            visibleRows = 4,
            persist = true,
            getItems = function()
                return rules
            end,
            formatItem = formatRule,
            onLoad = function(list)
                local clean = setRuleList(list)
                for i = #rules, 1, -1 do
                    rules[i] = nil
                end
                for i, row in ipairs(clean) do
                    rules[i] = row
                end
            end,
            onToggle = function(rule, enabled)
                local id = type(rule) == "table" and tostring(rule.id or "") or ""
                for _, item in ipairs(rules) do
                    if tostring(item.id) == id then
                        item.enabled = enabled == true
                        break
                    end
                end
                persistRules()
            end,
            onDelete = function(rule)
                local id = type(rule) == "table" and tostring(rule.id or "") or ""
                local nextList = {}
                for _, item in ipairs(rules) do
                    if tostring(item.id) ~= id then
                        nextList[#nextList + 1] = item
                    end
                end
                for i = #rules, 1, -1 do
                    rules[i] = nil
                end
                for i, row in ipairs(nextList) do
                    rules[i] = row
                end
                persistRules()
            end,
        })
        ruleApi = bindRules

        local _, formApi = ui:CreateRuleForm(parent, {
            id = spec.id .. ".draft.modes",
            label = "Rule Fields",
            placeholder = "Pick fields...",
            hintText = spec.hint,
            persist = true,
            modes = {
                { key = "rarity", name = "Rarity" },
                { key = "mutation", name = "Mutation" },
                { key = "trait", name = "Trait" },
                { key = "grade", name = "Grade" },
                { key = "level", name = "Level" },
                { key = "earn", name = "Earn/s" },
                { key = "chance", name = "1-in" },
            },
        })

        local _, rarityApi = ui:CreateRowDropdown(parent, {
            id = spec.id .. ".draft.rarities",
            label = "Rarity",
            mode = "multi",
            placeholder = "Any rarity",
            clearable = true,
            persist = true,
            preserveItemOrder = true,
            maxLabelChars = 18,
            getItems = rarityItems,
            onChanged = function(a, b)
                draft.rarities = copyMap(dropdownValue(a, b))
            end,
        })
        local _, mutationApi = ui:CreateRowDropdown(parent, {
            id = spec.id .. ".draft.mutations",
            label = "Mutation",
            mode = "multi",
            placeholder = "Any mutation",
            clearable = true,
            persist = true,
            preserveItemOrder = true,
            maxLabelChars = 18,
            getItems = mutationItems,
            onChanged = function(a, b)
                draft.mutations = copyMap(dropdownValue(a, b))
            end,
        })
        local _, traitApi = ui:CreateRowDropdown(parent, {
            id = spec.id .. ".draft.traits",
            label = "Trait",
            mode = "multi",
            placeholder = "Any trait",
            clearable = true,
            persist = true,
            preserveItemOrder = true,
            maxLabelChars = 18,
            getItems = traitItemList,
            onChanged = function(a, b)
                draft.traits = copyMap(dropdownValue(a, b))
            end,
        })
        local _, gradeApi = ui:CreateRowDropdown(parent, {
            id = spec.id .. ".draft.grades",
            label = "Grade",
            mode = "multi",
            placeholder = "Any grade",
            clearable = true,
            persist = true,
            preserveItemOrder = true,
            maxLabelChars = 18,
            getItems = gradeItemList,
            onChanged = function(a, b)
                draft.grades = copyMap(dropdownValue(a, b))
            end,
        })
        local levelWrap = wrapFieldStack(parent)
        local _, levelModeApi = ui:CreateRowDropdown(levelWrap, {
            id = spec.id .. ".draft.levelMode",
            label = "Level mode",
            placeholder = "Mode",
            clearable = false,
            persist = true,
            preserveItemOrder = true,
            initial = "below",
            getItems = function()
                return COMPARE
            end,
            onChanged = function(a, b)
                draft.levelMode = clampMode(dropdownValue(a, b))
            end,
        })
        local _, _, commitLevel, levelApi = ui:CreateRowInput(levelWrap, {
            id = spec.id .. ".draft.levelRule",
            label = "Level",
            initial = "0",
            hintText = "Below 1 = lv1 only. 0 = any.",
            clearOnFocus = false,
            persist = true,
            onChanged = function(text)
                draft.levelRule = tostring(text or "0")
            end,
        })
        local earnWrap = wrapFieldStack(parent)
        local _, _, commitEarnMin, earnMinApi = ui:CreateRowInput(earnWrap, {
            id = spec.id .. ".draft.earnMin",
            label = "Earn/s min",
            initial = "0",
            hintText = "Example 10k. 0 = no min.",
            clearOnFocus = false,
            persist = true,
            onChanged = function(text)
                draft.earnMin = tostring(text or "0")
            end,
        })
        local _, _, commitEarnMax, earnMaxApi = ui:CreateRowInput(earnWrap, {
            id = spec.id .. ".draft.earnMax",
            label = "Earn/s max",
            initial = "0",
            hintText = "Example 100k. 0 = no max.",
            clearOnFocus = false,
            persist = true,
            onChanged = function(text)
                draft.earnMax = tostring(text or "0")
            end,
        })
        local chanceWrap = wrapFieldStack(parent)
        local _, _, commitChanceMin, chanceMinApi = ui:CreateRowInput(chanceWrap, {
            id = spec.id .. ".draft.chanceMin",
            label = "1-in min",
            initial = "0",
            hintText = "Example 100qi. 0 = no min.",
            clearOnFocus = false,
            persist = true,
            onChanged = function(text)
                draft.chanceMin = tostring(text or "0")
            end,
        })
        local _, _, commitChanceMax, chanceMaxApi = ui:CreateRowInput(chanceWrap, {
            id = spec.id .. ".draft.chanceMax",
            label = "1-in max",
            initial = "0",
            hintText = "Example 4sp. 0 = no max.",
            clearOnFocus = false,
            persist = true,
            onChanged = function(text)
                draft.chanceMax = tostring(text or "0")
            end,
        })
        if formApi and type(formApi.attach) == "function" then
            formApi.attach("rarity", rarityApi, function()
                draft.rarities = {}
                if rarityApi and type(rarityApi.clear) == "function" then
                    pcall(rarityApi.clear, true)
                end
            end)
            formApi.attach("mutation", mutationApi, function()
                draft.mutations = {}
                if mutationApi and type(mutationApi.clear) == "function" then
                    pcall(mutationApi.clear, true)
                end
            end)
            formApi.attach("trait", traitApi, function()
                draft.traits = {}
                if traitApi and type(traitApi.clear) == "function" then
                    pcall(traitApi.clear, true)
                end
            end)
            formApi.attach("grade", gradeApi, function()
                draft.grades = {}
                if gradeApi and type(gradeApi.clear) == "function" then
                    pcall(gradeApi.clear, true)
                end
            end)
            formApi.attach("level", { root = levelWrap }, function()
                draft.levelRule = "0"
                draft.levelMode = "below"
                if levelApi and type(levelApi.set) == "function" then
                    pcall(levelApi.set, "0", true)
                end
                if levelModeApi and type(levelModeApi.setSelected) == "function" then
                    pcall(levelModeApi.setSelected, "below", true)
                end
            end)
            formApi.attach("earn", { root = earnWrap }, function()
                draft.earnMin = "0"
                draft.earnMax = "0"
                if earnMinApi and type(earnMinApi.set) == "function" then
                    pcall(earnMinApi.set, "0", true)
                end
                if earnMaxApi and type(earnMaxApi.set) == "function" then
                    pcall(earnMaxApi.set, "0", true)
                end
            end)
            formApi.attach("chance", { root = chanceWrap }, function()
                draft.chanceMin = "0"
                draft.chanceMax = "0"
                if chanceMinApi and type(chanceMinApi.set) == "function" then
                    pcall(chanceMinApi.set, "0", true)
                end
                if chanceMaxApi and type(chanceMaxApi.set) == "function" then
                    pcall(chanceMaxApi.set, "0", true)
                end
            end)
            pcall(formApi.apply)
        end
        ui:CreateRowButton(parent, {
            text = spec.button,
            kind = "primary",
            onClick = function()
                local modes = formApi and formApi.getModes and formApi.getModes() or {}
                local hasMode = false
                for _, on in pairs(modes) do
                    if on == true then
                        hasMode = true
                        break
                    end
                end
                if not hasMode then
                    return
                end
                if type(commitEarnMin) == "function" then
                    pcall(commitEarnMin)
                end
                if type(commitEarnMax) == "function" then
                    pcall(commitEarnMax)
                end
                if type(commitChanceMin) == "function" then
                    pcall(commitChanceMin)
                end
                if type(commitChanceMax) == "function" then
                    pcall(commitChanceMax)
                end
                if type(commitLevel) == "function" then
                    pcall(commitLevel)
                end
                if earnMinApi and type(earnMinApi.get) == "function" then
                    draft.earnMin = tostring(earnMinApi.get() or "0")
                end
                if earnMaxApi and type(earnMaxApi.get) == "function" then
                    draft.earnMax = tostring(earnMaxApi.get() or "0")
                end
                if chanceMinApi and type(chanceMinApi.get) == "function" then
                    draft.chanceMin = tostring(chanceMinApi.get() or "0")
                end
                if chanceMaxApi and type(chanceMaxApi.get) == "function" then
                    draft.chanceMax = tostring(chanceMaxApi.get() or "0")
                end
                if levelApi and type(levelApi.get) == "function" then
                    draft.levelRule = tostring(levelApi.get() or "0")
                end
                if levelModeApi and type(levelModeApi.getSelected) == "function" then
                    draft.levelMode = clampMode(levelModeApi.getSelected())
                end
                rules[#rules + 1] = sanitizeRule({
                    enabled = true,
                    fields = modes,
                    rarities = modes.rarity and draft.rarities or {},
                    mutations = modes.mutation and draft.mutations or {},
                    traits = modes.trait and draft.traits or {},
                    grades = modes.grade and draft.grades or {},
                    levelRule = modes.level and draft.levelRule or "0",
                    levelMode = modes.level and draft.levelMode or "below",
                    earnMin = modes.earn and draft.earnMin or "0",
                    earnMax = modes.earn and draft.earnMax or "0",
                    chanceMin = modes.chance and draft.chanceMin or "0",
                    chanceMax = modes.chance and draft.chanceMax or "0",
                })
                persistRules()
            end,
        })
    end

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "trade",
        subLabel = "Trade",
        subOrder = 3,
        order = 1,
        build = function(ui)
            hubUi = ui
            local body, _, api = ui:CreateSection({
                title = "Auto Trade",
                expanded = false,
                status = {
                    id = "auto.trade.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "off",
                },
            })
            headerApi = api
            local function playerItems()
                local out = {}
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP then
                        out[#out + 1] = {
                            key = tostring(p.UserId),
                            label = p.DisplayName .. "  @" .. p.Name,
                        }
                    end
                end
                table.sort(out, function(a, b)
                    return tostring(a.label) < tostring(b.label)
                end)
                return out
            end
            local function readTargetKey(a, b)
                local v = dropdownValue(a, b)
                if type(v) == "table" then
                    v = v.key or v.id
                end
                return tostring(v or "")
            end
            local group = ui:CreateGroup(body)

            ui:CreateRowDropdown(group, {
                id = "auto.trade.mode",
                label = "Mode",
                placeholder = "Once",
                clearable = false,
                persist = true,
                preserveItemOrder = true,
                initial = mode,
                getItems = function()
                    return MODES
                end,
                onChanged = function(a, b)
                    local nextMode = clampTradeMode(dropdownValue(a, b))
                    if nextMode ~= mode then
                        if nextMode ~= "auto" then
                            autoSendOn = false
                            autoLockUntil = os.clock() + 0.8
                            if autoSendApi and type(autoSendApi.set) == "function" then
                                pcall(autoSendApi.set, false, true)
                            end
                        end
                        if nextMode ~= "once" then
                            onceRun = false
                            onceConfirmOpen = false
                        end
                        if inSession() and session and session.role == "send" then
                            fireCancel()
                            clearSession()
                            enter("idle", "Idle", "muted", nextMode == "once" and "press Send trade" or "Auto send off")
                        end
                    end
                    mode = nextMode
                    paintModeVis()
                    syncWork()
                    paintHeader()
                end,
            })

            onceGroup = ui:CreateGroup(body)
            local _, onceTgtApi = ui:CreateRowDropdown(onceGroup, {
                id = "auto.trade.once.target",
                label = "Target player",
                placeholder = "Pick player...",
                clearable = true,
                persist = false,
                maxLabelChars = 22,
                getItems = playerItems,
                onChanged = function(a, b)
                    onceTargetId = readTargetKey(a, b)
                    paintHeader()
                end,
            })
            onceTargetApi = onceTgtApi
            local _, formApi = ui:CreateRuleForm(onceGroup, {
                id = "auto.trade.once.fields",
                label = "Fields",
                placeholder = "Unit / Potion / Spin / Gear / Gems",
                hintText = "Pick kinds first. All Luck/Income/Damage sends full stock. Per item amount shows total.",
                persist = false,
                modes = ALL_KINDS,
                onChanged = function(map)
                    onceFields = copyMap(map)
                    paintHeader()
                end,
            })
            onceFormApi = formApi
            local function syncOnceAmtRows(kind, host)
                if not host then
                    return
                end
                if type(onceAmt[kind]) ~= "table" then
                    onceAmt[kind] = {}
                end
                local picks = copyMap(oncePicks[kind])
                local apis = onceAmtApi[kind]
                if type(apis) ~= "table" then
                    apis = {}
                    onceAmtApi[kind] = apis
                end
                local stock = {}
                for _, info in ipairs(scanBag()) do
                    if info.tradeKind == kind and type(info.name) == "string" then
                        stock[info.name] = (stock[info.name] or 0) + (tonumber(info.amount) or 0)
                    end
                end
                for name, rec in pairs(apis) do
                    if picks[name] ~= true or not autoUi.allHelp.needAmt(kind, name, picks) then
                        local row = rec and (rec.row or rec.root)
                        if row then
                            pcall(function()
                                row:Destroy()
                            end)
                        end
                        apis[name] = nil
                        onceAmt[kind][name] = nil
                    end
                end
                local order = 20
                for _, name in ipairs(pickedNames(picks)) do
                    if autoUi.allHelp.needAmt(kind, name, picks) then
                        order = order + 1
                        if onceAmt[kind][name] == nil then
                            onceAmt[kind][name] = 1
                        end
                        local title = autoUi.allHelp.amtLabel(name, stock[name] or 0)
                        if not apis[name] then
                            local _, _, _, amtApi = ui:CreateRowInput(host, {
                                label = title,
                                initial = tostring(onceAmt[kind][name] or 1),
                                persist = false,
                                clearOnFocus = false,
                                placeholder = "1",
                                onChanged = function(text)
                                    setAmt(onceAmt, kind, name, parseNum(text))
                                end,
                            })
                            apis[name] = amtApi
                        else
                            autoUi.allHelp.setLabel(apis[name], title)
                        end
                        local row = apis[name] and (apis[name].row or apis[name].root)
                        if row then
                            row.LayoutOrder = order
                        end
                    end
                end
            end
            local function mountOnceKind(kind, label, withAmt)
                local wrap = wrapFieldStack(onceGroup)
                local isUnit = kind == "unit"
                if withAmt then
                    onceAmtApi[kind] = onceAmtApi[kind] or {}
                end
                local _, dropApi = ui:CreateRowDropdown(wrap, {
                    id = "auto.trade.once." .. kind,
                    label = label,
                    mode = "multi",
                    placeholder = "Pick " .. string.lower(label) .. "...",
                    clearable = true,
                    persist = false,
                    preserveItemOrder = true,
                    maxLabelChars = isUnit and 22 or 28,
                    layout = "stack",
                    order = 1,
                    panelWidth = isUnit and 340 or 280,
                    panelHeight = isUnit and 320 or 260,
                    searchPlaceholder = isUnit and "Search unit..." or "Search...",
                    hintText = withAmt and "All Luck/Income/Damage sends full stock, no amount. Per item amount shows total." or nil,
                    getItems = function()
                        return bagKindItems(kind)
                    end,
                    onChanged = function(a, b)
                        oncePicks[kind] = copyMap(dropdownValue(a, b))
                        if withAmt then
                            syncOnceAmtRows(kind, wrap)
                        end
                        paintHeader()
                    end,
                })
                oncePickApi[kind] = dropApi
                onceFormApi.attach(kind, { root = wrap })
            end
            mountOnceKind("unit", "Unit", false)
            mountOnceKind("potion", "Potion", true)
            mountOnceKind("spin", "Spin", true)
            mountOnceKind("gear", "Gear", true)
            mountOnceKind("gems", "Gems", true)
            mountOnceKind("trait_reroll", "Trait Reroll", true)
            if onceFormApi.get then
                onceFields = copyMap(onceFormApi.get())
            end
            Core.bindToggle(ui, onceGroup, {
                id = "auto.trade.once.keep",
                label = "Keep",
                persist = true,
                initial = true,
                onChanged = function(on)
                    autoUi.keep = on ~= false
                end,
            })

            local autoTargetGroup = ui:CreateGroup(body)
            ui:CreateRowDropdown(autoTargetGroup, {
                id = "auto.trade.target",
                label = "Target player",
                placeholder = "Pick player...",
                clearable = true,
                persist = true,
                maxLabelChars = 22,
                getItems = playerItems,
                onChanged = function(a, b)
                    autoTargetId = readTargetKey(a, b)
                    paintHeader()
                end,
            })
            local autoGiveGroup = ui:CreateGroup(body)
            local _, giveForm = ui:CreateRuleForm(autoGiveGroup, {
                id = "auto.trade.give.kinds",
                label = "Give kinds",
                placeholder = "Unit / Potion / Spin / Gear / Gems",
                hintText = "Unit uses rules. All Luck/Income/Damage sends full stock. Per item amount shows total.",
                persist = true,
                modes = ALL_KINDS,
                onChanged = function(map)
                    giveKinds = copyMap(map)
                    paintHeader()
                end,
            })
            autoUi.form = giveForm
            ui:CreateRowSlider(autoGiveGroup, {
                id = "auto.trade.minUnique",
                label = "Min unique",
                min = 1,
                max = MAX_UNIQUE,
                step = 1,
                initial = minUnique,
                persist = true,
                onChanged = function(n)
                    minUnique = clampMaxUnits(n)
                    paintHeader()
                end,
            })
            local function syncAutoAmtRows(kind, host)
                if not host then
                    return
                end
                if type(autoBag.amt[kind]) ~= "table" then
                    autoBag.amt[kind] = {}
                end
                local picks = copyMap(autoBag.picks[kind])
                local apis = autoBag.rows[kind]
                if type(apis) ~= "table" then
                    apis = {}
                    autoBag.rows[kind] = apis
                end
                local stock = {}
                for _, info in ipairs(scanBag()) do
                    if info.tradeKind == kind and type(info.name) == "string" then
                        stock[info.name] = (stock[info.name] or 0) + (tonumber(info.amount) or 0)
                    end
                end
                for name, rec in pairs(apis) do
                    if picks[name] ~= true or not autoUi.allHelp.needAmt(kind, name, picks) then
                        local row = rec and (rec.row or rec.root)
                        if row then
                            pcall(function()
                                row:Destroy()
                            end)
                        end
                        apis[name] = nil
                    end
                end
                local order = 20
                for _, name in ipairs(pickedNames(picks)) do
                    if autoUi.allHelp.needAmt(kind, name, picks) then
                        order = order + 1
                        if autoBag.amt[kind][name] == nil then
                            autoBag.amt[kind][name] = 1
                        end
                        local title = autoUi.allHelp.amtLabel(name, stock[name] or 0)
                        if not apis[name] then
                            local _, _, _, amtApi = ui:CreateRowInput(host, {
                                id = "auto.trade.auto." .. kind .. "Amt." .. name,
                                label = title,
                                initial = tostring(autoBag.amt[kind][name] or 1),
                                persist = true,
                                clearOnFocus = false,
                                placeholder = "1",
                                onChanged = function(text)
                                    setAmt(autoBag.amt, kind, name, parseNum(text))
                                end,
                            })
                            apis[name] = amtApi
                        else
                            autoUi.allHelp.setLabel(apis[name], title)
                        end
                        local row = apis[name] and (apis[name].row or apis[name].root)
                        if row then
                            row.LayoutOrder = order
                        end
                    end
                end
            end
            local function mountAutoKind(kind, label)
                local wrap = wrapFieldStack(autoGiveGroup)
                autoBag.rows[kind] = autoBag.rows[kind] or {}
                local _, dropApi = ui:CreateRowDropdown(wrap, {
                    id = "auto.trade.auto." .. kind,
                    label = label,
                    mode = "multi",
                    placeholder = "Pick " .. string.lower(label) .. "...",
                    clearable = true,
                    persist = true,
                    preserveItemOrder = true,
                    maxLabelChars = 28,
                    layout = "stack",
                    order = 1,
                    panelWidth = 280,
                    panelHeight = 260,
                    searchPlaceholder = "Search...",
                    hintText = "All Luck/Income/Damage sends full stock, no amount. Per item amount shows total.",
                    getItems = function()
                        return bagKindItems(kind)
                    end,
                    onChanged = function(a, b)
                        autoBag.picks[kind] = copyMap(dropdownValue(a, b))
                        syncAutoAmtRows(kind, wrap)
                        paintHeader()
                    end,
                })
                if dropApi and type(dropApi.getSelected) == "function" then
                    local ok, cur = pcall(dropApi.getSelected)
                    if ok then
                        autoBag.picks[kind] = copyMap(cur)
                    end
                end
                syncAutoAmtRows(kind, wrap)
                if giveForm and type(giveForm.attach) == "function" then
                    giveForm.attach(kind, { root = wrap })
                end
            end
            mountAutoKind("potion", "Potion")
            mountAutoKind("spin", "Spin")
            mountAutoKind("gear", "Gear")
            mountAutoKind("gems", "Gems")
            mountAutoKind("trait_reroll", "Trait Reroll")
            local autoFilterGroup = ui:CreateGroup(body)
            ui:CreateRowSlider(autoFilterGroup, {
                id = "auto.trade.maxUnits",
                label = "Max units send",
                min = 1,
                max = MAX_UNIQUE,
                step = 1,
                initial = maxUnitsSend,
                persist = true,
                onChanged = function(n)
                    maxUnitsSend = clampMaxUnits(n)
                    paintHeader()
                end,
            })
            bindRuleBlock(ui, autoFilterGroup, {
                id = "auto.trade.give",
                list = giveRules,
                draft = giveDraft,
                title = "Give unit rules",
                empty = "No give rules. Unit kind sends none until you add one.",
                hint = "Filter units to send. Plot and locked included. Tickets cannot be traded. 1-in min/max need suffix (19sx not 19).",
                button = "APPLY → Add Give Rule",
            })
            if giveForm and type(giveForm.attach) == "function" then
                giveForm.attach("unit", { root = autoFilterGroup })
            end
            if giveForm and giveForm.get then
                giveKinds = copyMap(giveForm.get())
            end
            if giveForm and type(giveForm.apply) == "function" then
                pcall(giveForm.apply)
            end
            autoUi.groups = { autoTargetGroup, autoGiveGroup, autoFilterGroup }

            enableGroup = ui:CreateGroup(body)
            local _, onceApi = ui:CreateRowButton(enableGroup, {
                text = "SEND TRADE",
                kind = "primary",
                onClick = function()
                    startOnce()
                end,
            })
            onceBtnApi = onceApi
            local _, _, apiAuto = Core.bindToggle(ui, enableGroup, {
                id = "auto.trade",
                label = AUTO_SEND_LABEL,
                initial = false,
                onChanged = function(on)
                    if onceConfirmOpen or onceRun then
                        if apiAuto and type(apiAuto.set) == "function" then
                            pcall(apiAuto.set, autoSendOn, true)
                        end
                        return
                    end
                    autoSendOn = on == true
                    autoLockUntil = os.clock() + 0.8
                    if not autoSendOn then
                        onceRun = false
                    end
                    syncWork()
                    paintHeader()
                end,
            })
            autoSendApi = apiAuto
            local sendNote, _, noteApi = ui:CreateRowLabel(enableGroup, {
                text = "Pick a target and items, then press Send trade. Confirm first. Items are added, then Ready. Locked / plot / Make Unit units can be sent. Tickets cannot.",
                wrap = true,
                style = "detail",
            })
            sendNoteApi = noteApi
            if sendNote then
                local pad = Instance.new("UIPadding")
                pad.PaddingTop = UDim.new(0, 2)
                pad.PaddingBottom = UDim.new(0, 4)
                pad.Parent = sendNote
            end
            paintModeVis()
            paintHeader()
        end,
    })

    Core.section({
        main = "auto",
        mainLabel = "AUTO",
        mainOrder = 1,
        sub = "trade",
        subLabel = "Trade",
        subOrder = 3,
        order = 2,
        build = function(ui)
            local body, _, api = ui:CreateSection({
                title = "Auto Accept Trade",
                expanded = false,
                status = {
                    id = "auto.trade.accept.status",
                    persist = false,
                    value = "Off",
                    style = "muted",
                    detail = "off",
                },
            })
            acceptHeader = api
            local noteGroup = ui:CreateGroup(body)
            local note = ui:CreateRowLabel(noteGroup, {
                text = "Takes incoming trade requests. If the whitelist has names or players, only those are accepted. Empty whitelist accepts anyone. Pick from this server or paste names. Saved even if they leave. Opens trade requests on the game while this is on.",
                wrap = true,
                style = "detail",
            })
            if note then
                local pad = Instance.new("UIPadding")
                pad.PaddingTop = UDim.new(0, 2)
                pad.PaddingBottom = UDim.new(0, 4)
                pad.Parent = note
            end
            local enableAccept = ui:CreateGroup(body)
            Core.bindToggle(ui, enableAccept, {
                id = "auto.trade.accept",
                label = "Enable Auto Accept Trade",
                initial = false,
                onChanged = function(on)
                    acceptOn = on == true
                    syncWork()
                end,
            })
            local listGroup = ui:CreateGroup(body)
            do
                local snap = G.__RideAPetSavedConfig
                if type(snap) == "table" then
                    loadPlayerMeta(snap["auto.trade.accept.playerMeta"])
                    acceptPlayers = copyMap(snap["auto.trade.accept.players"])
                end
            end
            local _, dropApi = ui:CreateRowDropdown(listGroup, {
                id = "auto.trade.accept.players",
                label = "Whitelist players",
                mode = "multi",
                placeholder = "Pick players in this server...",
                clearable = true,
                persist = true,
                preserveItemOrder = true,
                maxLabelChars = 22,
                getItems = acceptPlayerItems,
                labelForKey = function(key)
                    key = tostring(key or "")
                    local p = livePlayer(key)
                    if p then
                        return playerLabel(p)
                    end
                    local meta = acceptPlayerMeta[key]
                    if type(meta) == "table" then
                        return tostring(meta.label or meta.display or meta.name or key)
                    end
                    return key
                end,
                onChanged = function(a, b)
                    setAcceptPlayers(dropdownValue(a, b))
                    paintAcceptHeader()
                end,
            })
            acceptDropApi = dropApi
            ui:CreateRowInput(listGroup, {
                id = "auto.trade.accept.whitelist",
                label = "Whitelist usernames",
                initial = "",
                persist = true,
                clearOnFocus = false,
                layout = "stack",
                multiline = true,
                inputHeight = 72,
                placeholder = "user1, user2, user3",
                hintText = "Paste extra usernames. Dropdown picks stay saved after they leave. Empty dropdown + empty box = anyone.",
                onChanged = function(text)
                    setAcceptList(text)
                    paintAcceptHeader()
                end,
            })
            paintAcceptHeader()
        end,
    })

    Core.onSync(function(values)
        mode = clampTradeMode(values["auto.trade.mode"])
        local function readSavedTarget(raw)
            if type(raw) == "table" then
                raw = raw.key or raw.id
            end
            return tostring(raw or "")
        end
        autoTargetId = readSavedTarget(values["auto.trade.target"] or autoTargetId)
        onceTargetId = readSavedTarget(values["auto.trade.once.target"] or onceTargetId)
        if values["auto.trade.once.keep"] == nil then
            autoUi.keep = true
        else
            autoUi.keep = values["auto.trade.once.keep"] ~= false
        end
        minUnique = clampMaxUnits(values["auto.trade.minUnique"] or minUnique)
        maxUnitsSend = clampMaxUnits(values["auto.trade.maxUnits"])
        giveKinds = copyMap(values["auto.trade.give.kinds"])
        for _, row in ipairs(STACK_KINDS) do
            local kind = row.key
            autoBag.picks[kind] = copyMap(values["auto.trade.auto." .. kind] or autoBag.picks[kind])
            if type(autoBag.amt[kind]) ~= "table" then
                autoBag.amt[kind] = {}
            end
            local prefix = "auto.trade.auto." .. kind .. "Amt."
            for key, val in pairs(values) do
                if type(key) == "string" and string.sub(key, 1, #prefix) == prefix then
                    local name = string.sub(key, #prefix + 1)
                    if name ~= "" then
                        autoBag.amt[kind][name] = clampStack(parseNum(val))
                    end
                end
            end
        end
        acceptOn = values["auto.trade.accept"] == true
        if type(values["auto.trade.accept.playerMeta"]) == "table" then
            loadPlayerMeta(values["auto.trade.accept.playerMeta"])
        end
        if type(values["auto.trade.accept.players"]) == "table" then
            setAcceptPlayers(values["auto.trade.accept.players"])
        end
        setAcceptList(values["auto.trade.accept.whitelist"] or acceptListText)
        autoSendOn = mode == "auto" and values["auto.trade"] == true
        if autoSendOn ~= true then
            autoSendOn = false
            if autoSendApi and type(autoSendApi.set) == "function" then
                pcall(autoSendApi.set, false, true)
            end
        end
        onceRun = false
        local function fillRules(dst, src)
            local clean = setRuleList(src)
            for i = #dst, 1, -1 do
                dst[i] = nil
            end
            for i, row in ipairs(clean) do
                dst[i] = row
            end
        end
        if type(values["auto.trade.give.rules"]) == "table" then
            fillRules(giveRules, values["auto.trade.give.rules"])
        end
        paintModeVis()
        syncWork()
        paintHeader()
    end)
end
 end, required = true, feature = true },
    { key = "InfoMakeUnit", name = "Info Make Unit", factory = function() -- INFO → Make Unit.
-- Sisa bahan, rekap spent, antrian proses, unit selesai. Baca G.AnimeDiceAutoUnit.view.

return function(Core)
    local G = Core.env()

    local remain = {}
    local recap = {}
    local processBody
    local processHead
    local processEmpty
    local processCards = {}
    local doneBody
    local doneHead
    local doneEmpty
    local doneCards = {}

    local STEP = {
        grade = { label = "Grade", hex = "#FFD300", color = Color3.fromRGB(255, 211, 0) },
        trait = { label = "Trait", hex = "#C4A0FF", color = Color3.fromRGB(196, 160, 255) },
        quirk = { label = "Quirk", hex = "#7EE8FF", color = Color3.fromRGB(126, 232, 255) },
        roll = { label = "Roll", hex = "#FFD300", color = Color3.fromRGB(255, 211, 0) },
        upgrade = { label = "Upgrade", hex = "#5CFF9A", color = Color3.fromRGB(92, 255, 154) },
        rotate = { label = "Rotate", hex = "#8EC8FF", color = Color3.fromRGB(142, 200, 255) },
        wait_gems = { label = "Wait gems", hex = "#FF9A4A", color = Color3.fromRGB(255, 154, 74) },
        wait_traits = { label = "Wait traits", hex = "#FF9A4A", color = Color3.fromRGB(255, 154, 74) },
        wait_money = { label = "Wait money", hex = "#FF9A4A", color = Color3.fromRGB(255, 154, 74) },
        wait_tower = { label = "Wait tower", hex = "#9AA0A8", color = Color3.fromRGB(154, 160, 168) },
        wait_game_roll = { label = "Wait game", hex = "#9AA0A8", color = Color3.fromRGB(154, 160, 168) },
        wait_grade_event = { label = "Wait Grade Event", hex = "#FFD300", color = Color3.fromRGB(255, 211, 0) },
        wait_trait_event = { label = "Wait Trait Event", hex = "#C4A0FF", color = Color3.fromRGB(196, 160, 255) },
        fuse = { label = "Wait fuse", hex = "#9AA0A8", color = Color3.fromRGB(154, 160, 168) },
        wait_replica = { label = "Sync", hex = "#8A8F98", color = Color3.fromRGB(138, 143, 152) },
        wait_debounce = { label = "Sync", hex = "#8A8F98", color = Color3.fromRGB(138, 143, 152) },
        done = { label = "Done", hex = "#5CFF9A", color = Color3.fromRGB(92, 255, 154) },
    }

    local function compact(n)
        return Core.compact(n)
    end

    local function corner(inst, radius)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius or 8)
        c.Parent = inst
    end

    local function gradientColor(gradient)
        if typeof(gradient) == "ColorSequence" and gradient.Keypoints[1] then
            return gradient.Keypoints[1].Value
        end
        return Color3.fromRGB(255, 211, 0)
    end

    local function escapeRich(s)
        s = tostring(s or "")
        return s:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;")
    end

    local function view()
        local auto = G.AnimeDiceAutoUnit
        if type(auto) == "table" and type(auto.view) == "table" then
            return auto.view
        end
        return nil
    end

    local function stepInfo(step)
        return STEP[tostring(step or "")] or { label = "-", hex = "#9AA0A8", color = Color3.fromRGB(154, 160, 168) }
    end

    local function clockText(sec)
        sec = math.max(0, math.floor(tonumber(sec) or 0))
        local h = math.floor(sec / 3600)
        local m = math.floor((sec % 3600) / 60)
        local s = sec % 60
        if h > 0 then
            return string.format("%d:%02d:%02d", h, m, s)
        end
        return string.format("%d:%02d", m, s)
    end

    local function panel(parent, order, title, accent, full)
        local col = Instance.new("Frame")
        col.Name = "Panel"
        col.BackgroundColor3 = Color3.fromRGB(16, 16, 18)
        col.BackgroundTransparency = 0.2
        col.BorderSizePixel = 0
        col.Size = full and UDim2.new(1, 0, 0, 44) or UDim2.new(1 / 3, -6, 0, 44)
        col.AutomaticSize = Enum.AutomaticSize.Y
        col.LayoutOrder = order
        col.Parent = parent
        corner(col, 10)
        Core.panelStroke(col, accent)

        local head = Instance.new("TextLabel")
        head.Name = "Head"
        head.BackgroundTransparency = 1
        head.Size = UDim2.new(0.58, -8, 0, 18)
        head.Position = UDim2.new(0, 8, 0, 6)
        head.Font = Enum.Font.GothamBold
        head.TextSize = 12
        head.TextXAlignment = Enum.TextXAlignment.Left
        head.TextColor3 = accent
        head.TextTruncate = Enum.TextTruncate.AtEnd
        head.Text = title
        head.Parent = col

        local detail = Instance.new("TextLabel")
        detail.Name = "HeadDetail"
        detail.BackgroundTransparency = 1
        detail.Size = UDim2.new(0.42, -8, 0, 18)
        detail.Position = UDim2.new(0.58, 0, 0, 6)
        detail.Font = Enum.Font.Gotham
        detail.TextSize = 11
        detail.TextXAlignment = Enum.TextXAlignment.Right
        detail.TextColor3 = Color3.fromRGB(150, 154, 162)
        detail.TextTruncate = Enum.TextTruncate.AtEnd
        detail.Text = ""
        detail.Parent = col

        local body = Instance.new("Frame")
        body.Name = "Body"
        body.BackgroundTransparency = 1
        body.Position = UDim2.new(0, 8, 0, 26)
        body.Size = UDim2.new(1, -16, 0, 0)
        body.AutomaticSize = Enum.AutomaticSize.Y
        body.Parent = col
        local list = Instance.new("UIListLayout")
        list.FillDirection = Enum.FillDirection.Vertical
        list.SortOrder = Enum.SortOrder.LayoutOrder
        list.Padding = UDim.new(0, 4)
        list.Parent = body
        local pad = Instance.new("UIPadding")
        pad.PaddingBottom = UDim.new(0, 8)
        pad.Parent = body
        return col, body, head, detail
    end

    local function remainCard(parent, order, title, accent)
        local col, body, head, detail = panel(parent, order, title, accent, false)

        local value = Instance.new("TextLabel")
        value.Name = "Value"
        value.BackgroundTransparency = 1
        value.Size = UDim2.new(1, 0, 0, 22)
        value.LayoutOrder = 1
        value.Font = Enum.Font.GothamBold
        value.TextSize = 18
        value.TextXAlignment = Enum.TextXAlignment.Left
        value.TextColor3 = accent
        value.TextTruncate = Enum.TextTruncate.AtEnd
        value.Text = "-"
        value.Parent = body

        local sub = Instance.new("TextLabel")
        sub.Name = "Sub"
        sub.BackgroundTransparency = 1
        sub.Size = UDim2.new(1, 0, 0, 16)
        sub.LayoutOrder = 2
        sub.Font = Enum.Font.Gotham
        sub.TextSize = 11
        sub.TextXAlignment = Enum.TextXAlignment.Left
        sub.TextColor3 = Color3.fromRGB(150, 154, 162)
        sub.TextTruncate = Enum.TextTruncate.AtEnd
        sub.RichText = true
        sub.Text = ""
        sub.Parent = body

        return {
            head = head,
            detail = detail,
            value = value,
            sub = sub,
        }
    end

    local function recapLine(parent, order, key)
        local row = Instance.new("Frame")
        row.BackgroundTransparency = 1
        row.Size = UDim2.new(1, 0, 0, 16)
        row.LayoutOrder = order
        row.Parent = parent

        local cap = Instance.new("TextLabel")
        cap.BackgroundTransparency = 1
        cap.Size = UDim2.new(0.28, 0, 1, 0)
        cap.Font = Enum.Font.Gotham
        cap.TextSize = 11
        cap.TextXAlignment = Enum.TextXAlignment.Left
        cap.TextColor3 = Color3.fromRGB(150, 154, 162)
        cap.TextTruncate = Enum.TextTruncate.AtEnd
        cap.Text = key
        cap.Parent = row

        local value = Instance.new("TextLabel")
        value.BackgroundTransparency = 1
        value.Position = UDim2.new(0.28, 0, 0, 0)
        value.Size = UDim2.new(0.72, 0, 1, 0)
        value.Font = Enum.Font.GothamMedium
        value.TextSize = 10
        value.TextXAlignment = Enum.TextXAlignment.Right
        value.TextTruncate = Enum.TextTruncate.AtEnd
        value.RichText = true
        value.Text = "-"
        value.Parent = row
        return value
    end

    local function makeUnitCard(parent, order)
        local card = Instance.new("Frame")
        card.Name = "UnitCard"
        card.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        card.BackgroundTransparency = 0.94
        card.BorderSizePixel = 0
        card.Size = UDim2.new(1, 0, 0, 28)
        card.LayoutOrder = order
        card.Parent = parent
        corner(card, 8)
        local stroke = Instance.new("UIStroke")
        stroke.Name = "Tint"
        stroke.Thickness = 1
        stroke.Transparency = 0.4
        stroke.Color = Color3.fromRGB(90, 90, 90)
        stroke.Parent = card

        local bar = Instance.new("Frame")
        bar.Name = "Bar"
        bar.BackgroundColor3 = Color3.fromRGB(90, 90, 90)
        bar.BorderSizePixel = 0
        bar.AnchorPoint = Vector2.new(0, 0.5)
        bar.Position = UDim2.new(0, 6, 0.5, 0)
        bar.Size = UDim2.new(0, 3, 1, -10)
        bar.Parent = card
        corner(bar, 2)

        local line = Instance.new("TextLabel")
        line.Name = "Line"
        line.BackgroundTransparency = 1
        line.Position = UDim2.new(0, 14, 0, 0)
        line.Size = UDim2.new(1, -20, 1, 0)
        line.Font = Enum.Font.GothamMedium
        line.TextSize = 10
        line.TextXAlignment = Enum.TextXAlignment.Left
        line.TextYAlignment = Enum.TextYAlignment.Center
        line.RichText = true
        line.TextTruncate = Enum.TextTruncate.AtEnd
        line.Text = ""
        line.Parent = card

        return {
            frame = card,
            line = line,
            bar = bar,
            stroke = stroke,
        }
    end

    local function gotText(row, step)
        if type(row) ~= "table" then
            return ""
        end
        step = step or row.step
        local done = step == nil or step == "done" or step == "none"
        local bits = {}
        local showGrade = done or step == "grade" or step == "wait_gems" or step == "roll"
        local showTrait = done or step == "trait" or step == "wait_traits" or step == "roll"
        local showQuirk = done or step == "quirk" or step == "roll"
        local showLv = done or step == "upgrade" or step == "rotate" or step == "wait_money" or step == "wait_tower"
        if showGrade then
            local g = row.grade or row.currentGrade
            if type(g) == "string" and g ~= "" and g ~= "None" then
                bits[#bits + 1] = tostring(g)
            end
        end
        if showTrait then
            local t = row.trait or row.currentTrait
            if type(t) == "string" and t ~= "" and t ~= "None" then
                bits[#bits + 1] = tostring(t)
            end
        end
        if showQuirk then
            local q = row.quirk or row.currentQuirk
            if type(q) == "string" and q ~= "" and q ~= "None" then
                bits[#bits + 1] = tostring(q)
            end
        end
        if showLv then
            local lv = tonumber(row.level or row.currentLevel)
            if lv then
                bits[#bits + 1] = "Lv " .. tostring(lv)
            end
        end
        return table.concat(bits, " · ")
    end

    local function stepCost(step)
        if step == "grade" or step == "wait_gems" then
            return "1 gem"
        end
        if step == "trait" or step == "wait_traits" then
            return "1 trait"
        end
        if step == "quirk" then
            return "cash"
        end
        if step == "roll" then
            return "parallel"
        end
        return nil
    end

    local function paintList(cards, body, empty, rows, emptyText, doneMode)
        rows = type(rows) == "table" and rows or {}
        if empty and empty.Parent then
            empty.Visible = #rows == 0
            empty.Text = #rows == 0 and emptyText or ""
        end
        for i, row in ipairs(rows) do
            local card = cards[i]
            if not card or not card.frame or not card.frame.Parent then
                if card and card.frame then
                    pcall(function()
                        card.frame:Destroy()
                    end)
                end
                card = makeUnitCard(body, i)
                cards[i] = card
            end
            card.frame.Visible = true
            card.frame.LayoutOrder = i
            local info = stepInfo(row.step)
            local tint = gradientColor(row.gradient)
            if row.current then
                tint = Color3.fromRGB(255, 211, 0)
            elseif doneMode then
                tint = Color3.fromRGB(92, 255, 154)
            end
            card.bar.BackgroundColor3 = tint
            card.stroke.Color = tint
            card.stroke.Transparency = row.current and 0.1 or 0.4
            local name = escapeRich(row.title or row.name or "-")
            if row.rule then
                name = '<font color="#8EC8FF">' .. escapeRich(row.rule) .. "</font> " .. name
            end
            local inText = row.chance and ("1 in " .. compact(row.chance)) or ""
            local nowE = compact(row.earnNow)
            local got = gotText(row, "done")
            local cost = not doneMode and stepCost(row.step) or nil
            local extra
            if doneMode then
                extra = got
            else
                extra = info.label
                if cost then
                    extra = extra .. " · " .. cost
                end
                if got ~= "" then
                    extra = extra .. " · " .. got
                end
            end
            local plotHtml = ""
            if row.onPlot == true then
                local slot = tonumber(row.slot)
                plotHtml = string.format(
                    '<font color="#8A8F98"> | </font><font color="#78DC96">%s</font>',
                    slot and ("Plot " .. tostring(slot)) or "Plot"
                )
                if not row.current then
                    card.stroke.Transparency = 0.2
                end
            end
            local earnHtml = '<font color="#8A8F98"> | </font><font color="#FFD300">' .. nowE .. "</font>"
            card.line.Text = string.format(
                '<font color="#F2F3F5">%s</font><font color="#8A8F98"> | </font><font color="%s">%s</font>%s%s%s',
                name,
                doneMode and "#5CFF9A" or info.hex,
                escapeRich(extra),
                earnHtml,
                inText ~= "" and ('<font color="#8A8F98"> | </font><font color="#8EC8FF">' .. inText .. "</font>") or "",
                plotHtml
            )
        end
        for i = #rows + 1, #cards do
            local card = cards[i]
            if card and card.frame and card.frame.Parent then
                card.frame.Visible = false
            end
        end
    end

    local function paint()
        if not Core.uiIs("info", "make") then
            return
        end
        if not remain.money or not remain.money.value or not remain.money.value.Parent then
            return
        end
        local v = view()
        local rem = v and v.remaining or {}
        local rec = v and v.recap or {}
        local on = v and v.on == true

        remain.money.value.Text = compact(rem.money)
        remain.money.sub.Text = '<font color="#9AA0A8">keep </font><font color="#78DC96">'
            .. tostring(math.floor(tonumber(rem.keepPercent) or 0))
            .. "%</font>"
        remain.gems.value.Text = Core.grouped(rem.gems)
        local gemSub = '<font color="#9AA0A8">usable </font><font color="#FFD300">'
            .. Core.grouped(rem.usableGems)
            .. "</font>"
        if rem.gradeEvent == true then
            if rem.gradeEventNow == true then
                gemSub = gemSub .. '<font color="#8A8F98"> · </font><font color="#FFD300">Grade Event</font>'
            else
                gemSub = gemSub
                    .. '<font color="#8A8F98"> · hold </font><font color="#FFD300">'
                    .. tostring(math.floor(tonumber(rem.gradeEventPct) or 0))
                    .. "%</font>"
            end
        end
        remain.gems.sub.Text = gemSub
        remain.traits.value.Text = Core.grouped(rem.traits)
        local traitSub = '<font color="#9AA0A8">usable </font><font color="#C4A0FF">'
            .. Core.grouped(rem.usableTraits)
            .. "</font>"
        if rem.traitEvent == true then
            if rem.traitEventNow == true then
                traitSub = traitSub .. '<font color="#8A8F98"> · </font><font color="#C4A0FF">Trait Event</font>'
            else
                traitSub = traitSub
                    .. '<font color="#8A8F98"> · hold </font><font color="#C4A0FF">'
                    .. tostring(math.floor(tonumber(rem.traitEventPct) or 0))
                    .. "%</font>"
            end
        end
        remain.traits.sub.Text = traitSub

        local info = stepInfo(rec.currentStep)
        if recap.detail and recap.detail.Parent then
            if on then
                recap.detail.Text = clockText(rec.elapsed)
                recap.detail.TextColor3 = Color3.fromRGB(92, 255, 154)
            else
                recap.detail.Text = "Off"
                recap.detail.TextColor3 = Color3.fromRGB(150, 154, 162)
            end
        end
        if recap.now then
            if rec.currentName then
                local got = gotText({
                    grade = rec.currentGrade,
                    trait = rec.currentTrait,
                    quirk = rec.currentQuirk,
                    level = rec.currentLevel,
                }, "done")
                local cost = rec.currentCost or stepCost(rec.currentStep)
                recap.now.Text = string.format(
                    '<font color="%s">%s</font><font color="#8A8F98"> · </font><font color="#F2F3F5">%s</font>%s%s%s',
                    info.hex,
                    escapeRich(info.label),
                    escapeRich(rec.currentName),
                    cost and ('<font color="#8A8F98"> · </font><font color="#FFD300">' .. escapeRich(tostring(cost)) .. "</font>") or "",
                    got ~= "" and ('<font color="#8A8F98"> · </font><font color="#FFD300">' .. escapeRich(got) .. "</font>") or "",
                    rec.currentOnPlot == true
                            and ('<font color="#8A8F98"> · </font><font color="#78DC96">' .. (tonumber(rec.currentSlot) and ("Plot " .. tostring(rec.currentSlot)) or "Plot") .. "</font>")
                        or '<font color="#8A8F98"> · </font><font color="#9AA0A8">bag</font>'
                )
            else
                local n = type(v.process) == "table" and #v.process or 0
                recap.now.Text = string.format('<font color="#9AA0A8">%s in queue</font>', tostring(n))
            end
        end
        if recap.spent then
            recap.spent.Text = string.format(
                '<font color="#FFD300">%s gems</font><font color="#8A8F98">  ·  </font><font color="#C4A0FF">%s traits</font><font color="#8A8F98">  ·  </font><font color="#78DC96">%s</font>',
                Core.grouped(rec.gems),
                Core.grouped(rec.traits),
                compact(rec.money)
            )
        end
        if recap.rolls then
            recap.rolls.Text = string.format(
                '<font color="#FFD300">%s grade</font><font color="#8A8F98">  ·  </font><font color="#C4A0FF">%s trait</font><font color="#8A8F98">  ·  </font><font color="#7EE8FF">%s quirk</font><font color="#8A8F98">  ·  </font><font color="#5CFF9A">%s lv</font>',
                tostring(tonumber(rec.gradeN) or 0),
                tostring(tonumber(rec.traitN) or 0),
                tostring(tonumber(rec.quirkN) or 0),
                tostring(tonumber(rec.upN) or 0)
            )
        end
        if recap.done then
            recap.done.Text = '<font color="#5CFF9A">' .. tostring(tonumber(rec.doneN) or 0) .. "</font>"
        end
        if recap.cap then
            local processN = type(v.process) == "table" and #v.process or (tonumber(rem.processN) or 0)
            local doneN = tonumber(rec.doneN) or 0
            local used = tonumber(rec.capUsed) or (doneN + processN)
            local cap = tonumber(rec.capMax) or tonumber(rem.maxUnits) or 50
            local over = used >= cap
            recap.cap.Text = string.format(
                '<font color="#5CFF9A">%s completed</font><font color="#8A8F98"> + </font><font color="#8EC8FF">%s progress</font><font color="#8A8F98"> / </font><font color="%s">%s</font>',
                tostring(doneN),
                tostring(processN),
                over and "#FFBA50" or "#F2F3F5",
                tostring(cap)
            )
        end

        local process = v and v.process or {}
        local done = v and v.done or {}
        local plotN = 0
        for i = 1, #process do
            if process[i] and process[i].onPlot == true then
                plotN = plotN + 1
            end
        end
        if processHead and processHead.Parent then
            local hotN = tonumber(rec.hotN) or 0
            local bits = { tostring(#process) }
            if hotN > 0 then
                bits[#bits + 1] = tostring(hotN) .. " rolling"
            end
            if plotN > 0 then
                bits[#bits + 1] = tostring(plotN) .. " plot"
            end
            processHead.Text = table.concat(bits, " · ")
        end
        if doneHead and doneHead.Parent then
            doneHead.Text = tostring(tonumber(rec.doneN) or #done)
        end
        paintList(processCards, processBody, processEmpty, process, on and "No units need work" or "No units match filter", false)
        paintList(doneCards, doneBody, doneEmpty, done, "No bag units match finish + filter", true)
    end

    -- Baca view yang sudah di-publish Make Unit. Bukan scan tas.
    local loop = Core.loop("info_make_unit", {
        delay = 0.15,
        step = paint,
    })
    loop.setEnabled(true)

    Core.section({
        main = "info",
        mainLabel = "INFO",
        mainOrder = 0,
        sub = "make",
        subLabel = "Make Unit",
        subOrder = 4,
        order = 1,
        build = function(ui)
            remain = {}
            recap = {}
            processCards = {}
            doneCards = {}
            processBody = nil
            doneBody = nil

            local stack = Instance.new("Frame")
            stack.Name = "MakeStack"
            stack.BackgroundTransparency = 1
            stack.BorderSizePixel = 0
            stack.Size = UDim2.new(1, 0, 0, 0)
            stack.AutomaticSize = Enum.AutomaticSize.Y
            stack.LayoutOrder = 1
            stack.Parent = ui.content
            local stackList = Instance.new("UIListLayout")
            stackList.FillDirection = Enum.FillDirection.Vertical
            stackList.SortOrder = Enum.SortOrder.LayoutOrder
            stackList.Padding = UDim.new(0, 8)
            stackList.Parent = stack

            local remainBoard = Instance.new("Frame")
            remainBoard.Name = "RemainBoard"
            remainBoard.BackgroundTransparency = 1
            remainBoard.Size = UDim2.new(1, 0, 0, 0)
            remainBoard.AutomaticSize = Enum.AutomaticSize.Y
            remainBoard.LayoutOrder = 1
            remainBoard.Parent = stack
            local remainRow = Instance.new("UIListLayout")
            remainRow.FillDirection = Enum.FillDirection.Horizontal
            remainRow.SortOrder = Enum.SortOrder.LayoutOrder
            remainRow.Padding = UDim.new(0, 8)
            remainRow.Parent = remainBoard
            remain.money = remainCard(remainBoard, 1, "MONEY", Color3.fromRGB(120, 220, 150))
            remain.gems = remainCard(remainBoard, 2, "GEMS", Color3.fromRGB(255, 211, 0))
            remain.traits = remainCard(remainBoard, 3, "TRAITS", Color3.fromRGB(196, 160, 255))

            local recapCol, recapBody, recapHead, recapDetail = panel(stack, 2, "RECAP", Color3.fromRGB(255, 154, 74), true)
            recapCol.Name = "Recap"
            recap.head = recapHead
            recap.detail = recapDetail
            recap.now = recapLine(recapBody, 1, "Now")
            recap.spent = recapLine(recapBody, 2, "Spent")
            recap.rolls = recapLine(recapBody, 3, "Rolls")
            recap.done = recapLine(recapBody, 4, "Done")
            recap.cap = recapLine(recapBody, 5, "Max total")

            local doneCol, dBody, _, dHead = panel(stack, 3, "FINISH", Color3.fromRGB(92, 255, 154), true)
            doneCol.Name = "Finish"
            doneBody = dBody
            doneHead = dHead
            doneEmpty = Instance.new("TextLabel")
            doneEmpty.Name = "Empty"
            doneEmpty.BackgroundTransparency = 1
            doneEmpty.Size = UDim2.new(1, 0, 0, 18)
            doneEmpty.LayoutOrder = 0
            doneEmpty.Font = Enum.Font.Gotham
            doneEmpty.TextSize = 12
            doneEmpty.TextXAlignment = Enum.TextXAlignment.Left
            doneEmpty.TextColor3 = Color3.fromRGB(150, 154, 162)
            doneEmpty.Text = "No bag units match finish + filter"
            doneEmpty.Parent = doneBody

            local processCol, pBody, _, pHead = panel(stack, 4, "PROCESS", Color3.fromRGB(142, 200, 255), true)
            processCol.Name = "Process"
            processBody = pBody
            processHead = pHead
            processEmpty = Instance.new("TextLabel")
            processEmpty.Name = "Empty"
            processEmpty.BackgroundTransparency = 1
            processEmpty.Size = UDim2.new(1, 0, 0, 18)
            processEmpty.LayoutOrder = 0
            processEmpty.Font = Enum.Font.Gotham
            processEmpty.TextSize = 12
            processEmpty.TextXAlignment = Enum.TextXAlignment.Left
            processEmpty.TextColor3 = Color3.fromRGB(150, 154, 162)
            processEmpty.Text = "No units need work"
            processEmpty.Parent = processBody

            paint()
            Core.kickScroll(ui.content)
        end,
    })
end
 end, required = true, feature = true },
}

local function failBoot(msg)
    G.__AnimeDiceBooting = false
    error("[" .. BOOT_NAME .. "] " .. tostring(msg), 0)
end

local function destroyHubGui()
    local hosts = {}
    local pg = LP and LP:FindFirstChild("PlayerGui")
    if pg then
        hosts[#hosts + 1] = pg
    end
    pcall(function()
        if typeof(gethui) == "function" then
            local h = gethui()
            if h then
                hosts[#hosts + 1] = h
            end
        end
    end)
    pcall(function()
        hosts[#hosts + 1] = game:GetService("CoreGui")
    end)
    for _, host in ipairs(hosts) do
        for _, name in ipairs({ "NodeHubNeonUI", "NodeHubDropdownOverlay" }) do
            local old = host:FindFirstChild(name)
            if old then
                pcall(function()
                    old:Destroy()
                end)
            end
        end
    end
end

destroyHubGui()

local function hasUnreplacedShortcode(s)
    return tostring(s or ""):find("%%%[%[%[", 1, false) ~= nil
end

local function runFactory(def)
    local ok, res = pcall(def.factory)
    if not ok then
        local err = tostring(res)
        if hasUnreplacedShortcode(err) or hasUnreplacedShortcode(def.factory) then
            return false, "shortcode belum di-stitch — pakai exec.lua / main_ui.php / boot.lua"
        end
        return false, err
    end
    if def.feature then
        if type(res) ~= "function" then
            return false, "feature bukan function"
        end
        return true, res
    end
    if type(res) ~= "table" then
        return false, "module bukan table"
    end
    return true, res
end

local Loaded = {}
for _, def in ipairs(MODULE_DEFS) do
    local ok, modOrErr = runFactory(def)
    if ok then
        Loaded[def.key] = modOrErr
    elseif def.required then
        failBoot(("required module failed: %s | %s"):format(tostring(def.name), tostring(modOrErr)))
    end
end

local MainUI = Loaded.MainUI
if type(MainUI) ~= "table" or type(MainUI.new) ~= "function" then
    failBoot("MainUI.new tidak ada")
end

local Core = Loaded.Core
if type(Core) ~= "table" or type(Core.init) ~= "function" then
    failBoot("core.lua tidak valid")
end
Core.init({
    player = LP,
    G = G,
})

if type(Loaded.PotionCatalog) == "table" then
    if type(Loaded.PotionCatalog.install) == "function" then
        Loaded.PotionCatalog.install(Core, G)
    else
        Core.potionCatalog = Loaded.PotionCatalog
        G.AnimeDicePotionCatalog = Loaded.PotionCatalog
        if type(G.AnimeDice) == "table" then
            G.AnimeDice.PotionCatalog = Loaded.PotionCatalog
        end
    end
end

if type(Loaded.GearCatalog) == "table" then
    if type(Loaded.GearCatalog.install) == "function" then
        Loaded.GearCatalog.install(Core, G)
    else
        Core.gearCatalog = Loaded.GearCatalog
        G.AnimeDiceGearCatalog = Loaded.GearCatalog
        if type(G.AnimeDice) == "table" then
            G.AnimeDice.GearCatalog = Loaded.GearCatalog
        end
    end
end

if type(Loaded.UnitEarn) == "table" then
    Core.unitEarn = Loaded.UnitEarn
    G.AnimeDiceUnitEarn = Loaded.UnitEarn
    if type(G.AnimeDice) == "table" then
        G.AnimeDice.UnitEarn = Loaded.UnitEarn
    end
end

if type(Loaded.UnitRules) == "table" then
    Core.unitRules = Loaded.UnitRules
    G.AnimeDiceUnitRules = Loaded.UnitRules
end

local function safePlayerFileName(name)
    local s = tostring(name or "player")
    s = s:gsub("[^%w%-_.]", "_")
    s = s:gsub("_+", "_")
    if s == "" or s == "_" then
        s = "player"
    end
    return s:sub(1, 48)
end

local SAVE_DIR = "nodeanimedice"
local OLD_SAVE_DIR = "animedice"
G.__AnimeDiceSaveDir = SAVE_DIR

local function playerSavePath(dir)
    return (dir or SAVE_DIR) .. "/" .. safePlayerFileName(LP and LP.Name) .. ".json"
end

local function fileExists(path)
    if type(isfile) == "function" then
        local ok, exists = pcall(isfile, path)
        if ok then
            return exists == true
        end
    end
    if type(readfile) ~= "function" then
        return false
    end
    local ok, src = pcall(readfile, path)
    return ok and type(src) == "string" and src ~= ""
end

local savePath = playerSavePath(SAVE_DIR)
local loadPath = savePath
if not fileExists(savePath) then
    local oldPath = playerSavePath(OLD_SAVE_DIR)
    if fileExists(oldPath) then
        loadPath = oldPath
    end
end
pcall(function()
    if type(makefolder) == "function" then
        makefolder(SAVE_DIR)
    end
end)

-- Tampilkan shell UI dulu. Feature ClientComm jangan nahan panel 60 detik.
local ui = MainUI.new({
    title = "| ANIME DICE | discord.gg/nodehub",
    savePath = savePath,
    autosave = true,
})

for _, def in ipairs(MODULE_DEFS) do
    if def.feature and type(Loaded[def.key]) == "function" then
        local okReg, regErr = pcall(Loaded[def.key], Core)
        if not okReg then
            if def.required then
                failBoot(("feature gagal: %s | %s"):format(tostring(def.name), tostring(regErr)))
            end
        end
    end
end

Core.mount(ui)

pcall(function()
    ui:Load(loadPath)
end)
ui._savePath = savePath
if loadPath ~= savePath then
    pcall(function()
        ui:Save(savePath)
    end)
end

local firstTab = Core.firstMainKey()
if firstTab then
    pcall(function()
        ui:SetActiveMainTab(firstTab)
    end)
end

Core.sync(ui)

G.NodeNeonUI = ui
G.MainUI = MainUI
G.AnimeDiceUI = ui
G.AnimeDice.UI = ui

G.__AnimeDiceReadyAt = os.clock()
G.__AnimeDiceBooting = false
warn(string.format("[%s] UI ready in %.1fs", BOOT_NAME, os.clock() - bootT))
return ui
